 9: 
10: class PriceListResource extends JsonResource
11: {
12:     /**
13:      * Transform the resource into an array.
14:      *
15:      * @return array<string, mixed>
16:      */
17:     public function toArray(Request $request): array
18:     {
19:         return [
20:             'id' => $this->id,
21:             'name' => $this->name,
22:             'type' => $this->type,
23:             'customer' => $this->whenLoaded('customer', fn () => $this->customer ? [
24:                 'id' => $this->customer->id, 'name' => $this->customer->name,
25:             ] : null),
26:             'customer_group' => $this->whenLoaded('customerGroup', fn () => $this->customerGroup ? [
27:                 'id' => $this->customerGroup->id, 'name' => $this->customerGroup->name, 'code' => $this->customerGroup->code,
28:             ] : null),
29:             'branch' => $this->whenLoaded('branch', fn () => $this->branch ? [
30:                 'id' => $this->branch->id, 'name' => $this->branch->name,
31:             ] : null),
32:             'currency' => $this->currency,
33:             'starts_at' => $this->starts_at,
34:             'ends_at' => $this->ends_at,
35:             'priority' => $this->priority,
36:             'is_active' => $this->is_active,
37:             'items_count' => $this->whenCounted('items'),
38:             'created_at' => $this->created_at,
39:         ];
40:     }
41: } 1: <?php
