 5: namespace Tests\Feature;
 6: 
 7: use App\Jobs\RefreshCatalogRetailPrices;
 8: use App\Models\ProductVariant;
 9: use App\Observers\CatalogRetailPriceObserver;
10: use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
11: use Illuminate\Support\Facades\Bus;
12: use Illuminate\Support\Facades\DB;
13: use RuntimeException;
14: use Tests\TestCase;
15: 
16: class CatalogPriceBatchTest extends TestCase
17: {
18:     use LazilyRefreshDatabase;
19: 
20:     public function test_failed_batch_does_not_publish_or_leak_product_ids_into_the_next_batch(): void
21:     {
22:         $discarded = ProductVariant::factory()->create();
23:         $first = ProductVariant::factory()->create();
24:         $second = ProductVariant::factory()->create();
25:         Bus::fake([RefreshCatalogRetailPrices::class]);
26:         $observer = app(CatalogRetailPriceObserver::class);
27: 
28:         try {
29:             $observer->batch(fn () => DB::transaction(function () use ($discarded): void {
30:                 $discarded->update(['retail_price' => '77.00']);
31:                 throw new RuntimeException('rollback');
32:             }));
33:             $this->fail('The batch should propagate the rollback.');
34:         } catch (RuntimeException $exception) {
35:             $this->assertSame('rollback', $exception->getMessage());
36:         }
37:         Bus::assertNothingDispatched();
38:         $this->assertNotSame('77.00', $discarded->fresh()->retail_price);
39: 
40:         $observer->batch(fn () => DB::transaction(function () use ($first, $second): void {
41:             $first->update(['retail_price' => '80.00']);
42:             $second->update(['retail_price' => '90.00']);
43:             $first->update(['retail_price' => '85.00']);
44:         }));
45:         Bus::assertDispatchedTimes(RefreshCatalogRetailPrices::class, 1);
46:         Bus::assertDispatched(RefreshCatalogRetailPrices::class, function ($job) use ($first, $second, $discarded): bool {
47:             $ids = $job->productId;
48:             $this->assertEqualsCanonicalizing([$first->product_id, $second->product_id], $ids);
49:             $this->assertNotContains($discarded->product_id, $ids);
50: 
51:             return true;
52:         });
53:     }
54: 
55:     public function test_batch_job_identity_ignores_order_and_duplicate_ids(): void
56:     {
57:         $this->assertSame(
58:             (new RefreshCatalogRetailPrices([3, 1, 3]))->uniqueId(),
59:             (new RefreshCatalogRetailPrices([1, 3]))->uniqueId(),
60:         );
61:         $this->assertNotSame(
62:             (new RefreshCatalogRetailPrices([1, 3]))->uniqueId(),
63:             (new RefreshCatalogRetailPrices([1, 4]))->uniqueId(),
64:         );
65:     }
66: 
67:     public function test_caught_nested_rollback_discards_its_ids_but_retains_committed_inner_changes(): void
68:     {
69:         $discarded = ProductVariant::factory()->create();
70:         $kept = ProductVariant::factory()->create();
71:         $other = ProductVariant::factory()->create();
72:         Bus::fake([RefreshCatalogRetailPrices::class]);
73:         $observer = app(CatalogRetailPriceObserver::class);
74: 
75:         $observer->batch(fn () => DB::transaction(function () use ($observer, $discarded, $kept, $other): void {
76:             DB::transaction(fn () => $observer->batch(fn () => $kept->update(['retail_price' => '85.00'])));
77:             try {
78:                 DB::transaction(function () use ($observer, $discarded): void {
79:                     $observer->batch(fn () => $discarded->update(['retail_price' => '77.00']));
80:                     throw new RuntimeException('rollback');
81:                 });
82:             } catch (RuntimeException) {
83:             }
84:             $other->update(['retail_price' => '95.00']);
85:         }));
86: 
87:         Bus::assertDispatchedTimes(RefreshCatalogRetailPrices::class, 1);
88:         Bus::assertDispatched(RefreshCatalogRetailPrices::class, function ($job) use ($kept, $other, $discarded): bool {
89:             $this->assertEqualsCanonicalizing([$kept->product_id, $other->product_id], $job->productId);
90:             $this->assertNotContains($discarded->product_id, $job->productId);
91: 
92:             return true;
93:         });
94:     }
95: }  1: <?php
