  5: namespace Tests\Feature;
  6: 
  7: use App\Enums\StaffRole;
  8: use App\Enums\TreasuryType;
  9: use App\Models\Branch;
 10: use App\Models\Expense;
 11: use App\Models\Treasury;
 12: use App\Models\TreasuryTransaction;
 13: use App\Models\User;
 14: use App\Services\ReportService;
 15: use Database\Seeders\FinancialPermissionSeeder;
 16: use Database\Seeders\SettingSeeder;
 17: use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
 18: use Illuminate\Support\Facades\Auth;
 19: use Illuminate\Support\Str;
 20: use PHPUnit\Framework\Attributes\DataProvider;
 21: use Spatie\Permission\Models\Permission;
 22: use Spatie\Permission\Models\Role;
 23: use Tests\TestCase;
 24: 
 25: /**
 26:  * C1: حذف المصروف صار إلغاءً (void) يعكس الحركة بدل الحذف الفعلي،
 27:  * مع مفتاح عدم تكرار إلزامي على الإنشاء.
 28:  */
 29: class ExpenseVoidTest extends TestCase
 30: {
 31:     use LazilyRefreshDatabase;
 32: 
 33:     private User $staff;
 34: 
 35:     private string $token;
 36: 
 37:     protected function setUp(): void
 38:     {
 39:         parent::setUp();
 40:         $this->seed([SettingSeeder::class, FinancialPermissionSeeder::class]);
 41:         $this->staff = User::factory()->create();
 42:         $role = Role::findOrCreate(StaffRole::SuperAdmin->value, 'staff');
 43:         $this->staff->assignRole($role);
 44:         $this->token = $this->staff->createToken('audit')->plainTextToken;
 45:     }
 46: 
 47:     private function treasury(array $attributes = []): Treasury
 48:     {
 49:         return Treasury::create([
 50:             'name' => 'Main Safe', 'code' => 'SAFE-'.Str::uuid(),
 51:             'branch_id' => Branch::factory()->create(['is_active' => true])->id,
 52:             'type' => TreasuryType::MainSafe, 'current_balance' => '1000.00', 'is_active' => true,
 53:             ...$attributes,
 54:         ]);
 55:     }
 56: 
 57:     private function payload(Treasury $treasury, array $attributes = []): array
 58:     {
 59:         return [
 60:             'branch_id' => $treasury->branch_id, 'treasury_id' => $treasury->id,
 61:             'category' => 'صيانة', 'amount' => 100, 'expense_date' => now()->toDateString(),
 62:             ...$attributes,
 63:         ];
 64:     }
 65: 
 66:     private function createExpense(Treasury $treasury): Expense
 67:     {
 68:         $id = $this->withToken($this->token)->postJson('/api/v1/admin/expenses', $this->payload($treasury), [
 69:             'Idempotency-Key' => 'expense-'.Str::uuid(),
 70:         ])->assertCreated()->json('data.id');
 71: 
 72:         return Expense::findOrFail($id);
 73:     }
 74: 
 75:     private function authenticateBranchStaff(int $branchId, array $permissions): void
 76:     {
 77:         $staff = User::factory()->create(['branch_id' => $branchId]);
 78:         foreach ($permissions as $permission) {
 79:             $staff->givePermissionTo(Permission::findOrCreate($permission, 'staff'));
 80:         }
 81:         Auth::forgetGuards();
 82:         $this->withToken($staff->createToken('branch-audit')->plainTextToken);
 83:     }
 84: 
 85:     public function test_destroy_voids_expense_and_reverses_treasury_balance(): void
 86:     {
 87:         $treasury = $this->treasury();
 88:         $payload = $this->payload($treasury);
 89: 
 90:         $create = $this->withToken($this->token)->postJson(
 91:             '/api/v1/admin/expenses',
 92:             $payload,
 93:             ['Idempotency-Key' => 'exp-key-001']
 94:         );
 95:         $create->assertCreated();
 96:         $expenseId = (int) $create->json('data.id');
 97:         $this->assertSame('900.00', number_format((float) $treasury->fresh()->current_balance, 2, '.', ''));
 98: 
 99:         // نفس المفتاح + نفس الحمولة يعيد نفس السجل بلا خصم ثانٍ
100:         $retry = $this->withToken($this->token)->postJson(
101:             '/api/v1/admin/expenses',
102:             $payload,
103:             ['Idempotency-Key' => 'exp-key-001']
104:         );
105:         $retry->assertCreated();
106:         $this->assertSame($expenseId, (int) $retry->json('data.id'));
107:         $this->assertSame('900.00', number_format((float) $treasury->fresh()->current_balance, 2, '.', ''));
108: 
109:         $this->withToken($this->token)->postJson('/api/v1/admin/expenses', [...$payload, 'amount' => 200], [
110:             'Idempotency-Key' => 'exp-key-001',
111:         ])->assertConflict();
112:         $this->assertDatabaseCount('expenses', 1);
113:         $this->assertSame('900.00', $treasury->fresh()->current_balance);
114: 
115:         $destroy = $this->withToken($this->token)->postJson("/api/v1/admin/expenses/{$expenseId}/void", [
116:             'void_reason' => 'تم تسجيل المصروف بالخطأ',
117:         ]);
118:         $destroy->assertOk();
119: 
120:         $expense = Expense::findOrFail($expenseId);
121:         $this->assertNotNull($expense->voided_at);
122:         $this->assertSame('تم تسجيل المصروف بالخطأ', $expense->void_reason);
123:         $this->assertSame($this->staff->id, $expense->voided_by);
124:         $this->assertSame('1000.00', number_format((float) $treasury->fresh()->current_balance, 2, '.', ''));
125:         $this->assertSame(2, TreasuryTransaction::where('reference_type', Expense::class)->where('reference_id', $expenseId)->count());
126:         $report = app(ReportService::class)->profitReport(now()->toDateString(), now()->toDateString(), $treasury->branch_id);
127:         $this->assertSame(0.0, $report['total_expenses']);
128: 
129:         // إلغاء مزدوج مرفوض
130:         $again = $this->withToken($this->token)->deleteJson("/api/v1/admin/expenses/{$expenseId}");
131:         $again->assertStatus(422);
132:     }
133: 
134:     public function test_store_requires_idempotency_key(): void
135:     {
136:         $treasury = $this->treasury();
137:         $this->withToken($this->token)->postJson('/api/v1/admin/expenses', $this->payload($treasury))->assertStatus(422);
138:     }
139: 
140:     public static function foreignBranchActions(): array
141:     {
142:         return [['create'], ['read'], ['update'], ['void']];
143:     }
144: 
145:     #[DataProvider('foreignBranchActions')]
146:     public function test_branch_staff_cannot_access_another_branches_expenses(string $action): void
147:     {
148:         $treasury = $this->treasury();
149:         $expense = $this->createExpense($treasury);
150:         $this->authenticateBranchStaff(Branch::factory()->create()->id, [
151:             'expenses.view', 'expenses.create', 'expenses.update', 'expenses.delete',
152:         ]);
153:         $this->getJson('/api/v1/admin/expenses')->assertOk()->assertJsonCount(0, 'data');
154: 
155:         $response = match ($action) {
156:             'create' => $this->postJson('/api/v1/admin/expenses', $this->payload($treasury), ['Idempotency-Key' => 'foreign-expense']),
157:             'read' => $this->getJson("/api/v1/admin/expenses/{$expense->id}"),
158:             'update' => $this->putJson("/api/v1/admin/expenses/{$expense->id}", ['notes' => 'Unauthorized edit']),
159:             'void' => $this->postJson("/api/v1/admin/expenses/{$expense->id}/void", ['void_reason' => 'Unauthorized void']),
160:         };
161:         $response->assertForbidden();
162:         $this->assertDatabaseCount('expenses', 1);
163:         $this->assertDatabaseHas('expenses', ['id' => $expense->id, 'notes' => null, 'voided_at' => null]);
164:         $this->assertSame('900.00', $treasury->fresh()->current_balance);
165:         $this->assertDatabaseCount('treasury_transactions', 1);
166:     }
167: 
168:     public static function invalidAdministrativeExpenses(): array
169:     {
170:         return [['inactive'], ['mismatched_branch'], ['pos_drawer'], ['excess_decimal_places']];
171:     }
172: 
173:     #[DataProvider('invalidAdministrativeExpenses')]
174:     public function test_admin_expenses_reject_invalid_treasuries_and_amount_precision(string $case): void
175:     {
176:         $treasury = $this->treasury(match ($case) {
177:             'inactive' => ['is_active' => false],
178:             'pos_drawer' => ['type' => TreasuryType::PosDrawer],
179:             default => [],
180:         });
181:         $payload = $this->payload($treasury, match ($case) {
182:             'mismatched_branch' => ['branch_id' => Branch::factory()->create()->id],
183:             'excess_decimal_places' => ['amount' => '0.015'],
184:             default => [],
185:         });
186: 
187:         $response = $this->withToken($this->token)->postJson('/api/v1/admin/expenses', $payload, [
188:             'Idempotency-Key' => 'invalid-expense',
189:         ])->assertUnprocessable();
190:         if ($case === 'excess_decimal_places') {
191:             $response->assertJsonValidationErrors('amount');
192:         }
193:         $this->assertDatabaseCount('expenses', 0);
194:         $this->assertDatabaseCount('treasury_transactions', 0);
195:         $this->assertSame('1000.00', $treasury->fresh()->current_balance);
196:     }
197: 
198:     public function test_post_void_requires_expense_delete_permission(): void
199:     {
200:         $treasury = $this->treasury();
201:         $expense = $this->createExpense($treasury);
202:         $this->authenticateBranchStaff($treasury->branch_id, ['expenses.view']);
203: 
204:         $this->postJson("/api/v1/admin/expenses/{$expense->id}/void", ['void_reason' => 'No delete permission'])
205:             ->assertForbidden();
206:         $this->assertNull($expense->fresh()->voided_at);
207:         $this->assertSame('900.00', $treasury->fresh()->current_balance);
