12: use Symfony\Component\HttpKernel\Exception\TooManyRequestsHttpException;
13: use Tests\TestCase;
14: 
15: class RemainingAuthRegressionTest extends TestCase
16: {
17:     use LazilyRefreshDatabase;
18: 
19:     public function test_valid_credentials_survive_the_daily_budget_without_resetting_failed_guess_counters(): void
20:     {
21:         config([
22:             'auth.unified_login_failures_hour' => 10,
23:             'auth.unified_login_identifier_failures_hour' => 30,
24:             'auth.unified_login_failures_day' => 2,
25:         ]);
26:         $staff = User::factory()->create(['password' => 'Good-password12']);
27:         $auth = app(UnifiedAuthService::class);
28:         $this->wrongPassword($auth, $staff->email);
29:         $this->wrongPassword($auth, $staff->email);
30: 
31:         $this->assertSame($staff->id, $auth->attempt($staff->email, 'Good-password12')->id);
32: 
33:         request()->server->set('REMOTE_ADDR', '192.0.2.44');
34:         $this->expectException(TooManyRequestsHttpException::class);
35:         $auth->attempt($staff->email, 'wrong-password');
36:     }
37: 
38:     public function test_the_hourly_identifier_guard_still_stops_hash_checks_across_rotating_ips(): void
39:     {
40:         config([
41:             'auth.unified_login_failures_hour' => 10,
42:             'auth.unified_login_identifier_failures_hour' => 2,
43:             'auth.unified_login_failures_day' => 100,
44:         ]);
45:         $staff = User::factory()->create(['password' => 'Good-password12']);
46:         $auth = app(UnifiedAuthService::class);
47:         foreach (['192.0.2.1', '192.0.2.2'] as $ip) {
48:             request()->server->set('REMOTE_ADDR', $ip);
49:             $this->wrongPassword($auth, $staff->email);
50:         }
51: 
52:         request()->server->set('REMOTE_ADDR', '192.0.2.3');
53:         Hash::shouldReceive('check')->never();
54:         $this->expectException(TooManyRequestsHttpException::class);
55:         $auth->attempt($staff->email, 'Good-password12');
56:     }
57: 
58:     private function wrongPassword(UnifiedAuthService $auth, string $identifier): void
59:     {
60:         try {
61:             $auth->attempt($identifier, 'wrong-password');
62:             $this->fail('A wrong password was accepted.');
63:         } catch (BusinessException $exception) {
64:             $this->assertSame(401, $exception->status);
65:         }
66:     }
67: } 1: # استكمال مراجعة task.txt — 2026-10-28
 2: 
 3: > أُغلقت الحالات الـ71 في المتابعة: **1055/1055 اختبارات خلفية ناجحة**. [النتيجة النهائية وتفاصيل المعالجة](remaining-suite-completion-2026-10-28.md). النتائج أدناه توثّق الجولة السابقة.
 4: 
 5: استُكملت تعديلات شجرة العمل الموجودة مع الحفاظ على عمل المستخدم. هذا التقرير يفرّق بين إصلاحات العمليات المتحققة وإخفاقات الحزمة الشاملة؛ لا يعني نجاح اختبارات العمليات أن المشروع كله جاهز للدمج.
 6: 
 7: ## الإصلاحات
 8: 
 9: | البنود | النتيجة |
10: | --- | --- |
11: | C1 | إلغاء المصروف يعكس رصيده في معاملة مقفلة، ويحفظ السند وفاعل الإلغاء وسببه. أضيف `POST /admin/expenses/{id}/void` بسبب إلزامي وصلاحية `expenses.delete`. تستبعد تقارير الأرباح ومجاميع الواجهة المصروف الملغى. يبقى DELETE القديم للإلغاء المتوافق مع العملاء السابقين. |
12: | C2، H1 | مراجعة نطاق الفروع للمصروفات والطلبات والمرتجعات والورديات والتحويلات. فرع المرتجع الصريح له الأولوية على فرع الطلب، بما يشمل تنزيل مرفقاته. اعتماد إشعار السداد يتحقق من الخزينة حتى عند اختيارها افتراضيًا داخل الخدمة. الطلب غير الموزع والخزينة المركزية يتطلبان وصولًا مركزيًا. |
13: | H2 | إنشاء المصروف والتحويل ودفعة المورد يتطلب مفتاح عدم تكرار بخزن فريد ومعاملة. نموذج التحويل يحتفظ بالمفتاح عند فشل الشبكة ويجدده بعد النجاح فقط. اعتماد التحويل وإشعار السداد محمي بقفل الحالة، فلا ينشئ اعتماد مكرر أثرًا ماليًا ثانيًا. |
14: | H3 | المسار الإداري يرفض إنشاء مصروف على `pos_drawer`. إلغاء مصروف مرتبط بوردية من هذا المسار مرفوض أيضًا، حتى لا يتجاوز إجماليات وتسوية الوردية. |
15: | H4 | منشئ التحويل لا يعتمد تحويله. أوامر الشراء لديها أصلًا فحص مستقل مع إعداد `allow_self_approve_purchases`، والوحدة متوقفة حسب قرار نشاط التصنيع. |
16: | H5 | تعديل الدفع اليدوي يحتاج ملاحظات، والانتقال إلى refunded يحتاج مرجع استرداد محفوظًا في التاريخ. المرجع توثيق لإجراء خارجي؛ لا ينفذ التحويل اليدوي دفعة أو استردادًا عبر بوابة دفع. |
17: | H6، M5 | فتح المرفقات محصور في PDF وPNG وJPEG وWebP، مع قطع `opener`. الأنواع الأخرى والنوافذ المحجوبة تنزل الاستجابة المحملة نفسها. روابط التنزيل ملحقة بالـDOM وتُلغى بعد مهلة. رفع الإيصالات يقبل الأنواع الآمنة، وتنزيل الخادم يرسل `nosniff` وattachment. |
18: | M1، M2 | تحقق صيغ التواريخ والحالات وUUID، ومدى التقارير 366 يومًا شاملًا بحد أقصى، مع إلزام طرفي الفترة وthrottle للتقارير. |
19: | M3، M4 | مواعيد البداية nullable آمنة في الخرائط. قيمة الخصم إلزامية للأنواع المالية. أهداف العرض موجودة في جدول النطاق ومحدودة بـ500 وتتحقق كمصفوفة. الرموز تُوحّد، مع فهرس UNIQUE على `upper(code)` لمنع سباق اختلاف حالة الأحرف. نوع buy_x_get_y غير المدعوم مرفوض. |
20: | M6، L5 | عدادات الطلبات من endpoint تجميعي. قراءة جميع الإشعارات بطلب واحد مع منع التكرار والتراجع الصحيح عن الفشل، بما يشمل العدد غير المحمّل. polling يضيف الجديد أولًا ويحافظ على الصفحات المحملة. |
21: | M7 | فحص الحالة بعد إعادة قراءة الطلب تحت القفل في التوزيع وفكه، بما يشمل الطلب الملغى بعد ربطه من المسار. |
22: | M8 | قيود AWB وزوج الشركة/المنطقة ورمز الخزينة موجودة في قاعدة البيانات. أضيف قيد الكوبون غير الحساس للحالة. سباق التفرد يعيد 409 مضبوطًا بدل500. |
23: | M9، M10 | اعتماد الوردية يستخدم مستخدم Sanctum الفعلي. مبالغ المصروف والتحويل ودفعة المورد وإشعار السداد محدودة بمنزلتين. تسجيل المصروف وعكسه يستخدم سلاسل عشرية وBCMath، وفحص رصيد الخزينة يستخدم bccomp. |
24: | M11 | fallback المالي معطل في إنتاج Vite حتى لو كان علم البيئة مفعّلًا، دون إسقاط التطبيق بخطأ عند تحميل الوحدة. |
25: | L1–L4، L6 | تحقق ترتيب تواريخ قوائم الأسعار وحد المدن. إلغاء دفعة المورد يستخدم POST بسبب متحقق منه وصلاحية الإلغاء على المسار الجديد. البحث يشمل العميل المسجل. الوقت غير الصالح وطريقة الدفع الغائبة لا يعرضان قيمًا مضللة. |
26: | L7 | الصفحات وروابط مجموعات العمليات وتبويبات المالية تتبع صلاحيات العرض الفعلية. الكاشير ذو الصلاحيات الإدارية لا يُحصر خطأً في POS. أُصلح تحديث الشاشة عند تغيير query التبويب وحده في الرابط. |
27: | I2، I3 | seeders الحسابات التجريبية محصورة محليًا/اختباريًا، وLocalAdminSeeder يتطلب كلمة مرور بيئية. كميتا فحص المرتجع تبدآن فارغتين ويتطلب الاستلام إدخالهما صراحة. |
28: 
29: ## التحقق
30: 
31: - الواجهة: **110/110** عبر `node --test tests/*.test.cjs`، دون تخطّي أو تعطيل. أُصلح تحميل aliases في اختبارات المتجر مع تشغيل الوحدات الفعلية وعزل الحالة بين الاختبارات. المخرجات: `test-results/operations/frontend-current.tap`.
32: - `pnpm --filter @alfarid/api-client typecheck` و`pnpm --filter @alfarid/backoffice build` ناجحان. تحذير حجم chunk الرئيسي لا يزال موجودًا.
33: - Edge على الكمبيوتر وعلى عرض390px: ناجحان. يشمل الاختبار استلام المرتجع بمدخلات فحص فارغة أولًا، إلغاء المصروف بسبب، حجب صفحة بلا صلاحية، وتعطيل أزرار التعديل لمستخدم العرض فقط. بيانات API مضبوطة في سياق معزول، ولا تمثل اختبار بوابة دفع أو جلسة Staging حية.
34: - اختبارات الخلفية المخصصة: **53/53** مع214 assertion في `ExpenseVoidTest` و`OperationsAuditCompletionTest` و`OrderStatsNotificationTest`. المخرجات: `test-results/operations/backend-focused.xml`.
35: - مجموعات الطلبات والمرتجعات والشحن والعروض والتقارير وPOS المرتبطة: **45/45** مع363 assertion. المخرجات: `test-results/operations/backend-operations.xml`.
36: - Pint وفحص whitespace على ملفات التطبيق نجحا. ملفات repomix السابقة لم تُعَد توليدها.
