52:                     ->orWhereLike('name_en', $pattern, caseSensitive: false));
53:             })
54:             ->when(isset($filters['is_active']), fn ($query) => $query->where('is_active', filter_var($filters['is_active'], FILTER_VALIDATE_BOOLEAN)))
55:             ->orderBy('sort_order')
