 5: namespace App\Http\Controllers\Api\V1\Shared;
 6: 
 7: use App\Http\Controllers\Controller;
 8: use Illuminate\Http\JsonResponse;
 9: use Illuminate\Http\Request;
10: 
11: /**
12:  * متحكم الإشعارات الموحد لكل البوابات (متجر/جملة/مورد/إدارة/Nقاط البيع):
13:  * يعمل مع أي notifiable مصادق (User/Customer/SupplierUser) عبر العلاقة
14:  * polymorphic في جدول notifications القياسي.
15:  */
16: class NotificationController extends Controller
17: {
18:     /** قائمة إشعارات المستخدم الحالي (20 لكل صفحة) + عدد غير المقروء. */
19:     public function index(Request $request): JsonResponse
20:     {
21:         $user = $request->user();
22:         $page = $user->notifications()->paginate(20);
23: 
24:         return response()->json([
25:             'data' => collect($page->items())->map(fn ($notification): array => [
26:                 'id' => $notification->id,
27:                 'type' => class_basename($notification->type),
28:                 'data' => $notification->data,
29:                 'read_at' => $notification->read_at?->toIso8601String(),
30:                 'created_at' => $notification->created_at?->toIso8601String(),
31:             ])->all(),
32:             'meta' => [
33:                 'current_page' => $page->currentPage(),
34:                 'last_page' => $page->lastPage(),
35:                 'per_page' => $page->perPage(),
36:                 'total' => $page->total(),
37:                 'unread_count' => $user->unreadNotifications()->count(),
38:             ],
39:         ]);
40:     }
41: 
42:     /** تعليم إشعار واحد كمقروء (إشعار غيره = 404). */
43:     public function markAsRead(Request $request, string $id): JsonResponse
44:     {
45:         abort_unless(\Illuminate\Support\Str::isUuid($id), 404);
46:         $notification = $request->user()->notifications()->findOrFail($id);
47:         $notification->markAsRead();
48: 
49:         return response()->json([
50:             'data' => [
51:                 'id' => $notification->id,
52:                 'read_at' => $notification->read_at?->toIso8601String(),
53:             ],
54:             'meta' => ['unread_count' => $request->user()->unreadNotifications()->count()],
55:         ]);
56:     }
57: 
58:     /** تعليم كل الإشعارات كمقروءة بتحديث واحد (M6): كان markAllRead يطلق طلبًا لكل إشعار. */
59:     public function readAll(Request $request): JsonResponse
60:     {
61:         $request->user()->unreadNotifications()->update(['read_at' => now()]);
62: 
63:         return response()->json([
64:             'data' => ['read_all' => true],
65:             'meta' => ['unread_count' => 0],
66:         ]);
67:     }
68: } 1: <?php
