 5: namespace App\Http\Resources\Admin;
 6: 
 7: use App\Models\PurchaseOrder;
 8: use Illuminate\Http\Request;
 9: use Illuminate\Http\Resources\Json\JsonResource;
10: 
11: /**
12:  * @mixin PurchaseOrder
13:  */
14: class PurchaseOrderResource extends JsonResource
15: {
16:     /**
17:      * @return array<string, mixed>
18:      */
19:     public function toArray(Request $request): array
20:     {
21:         return [
22:             'id' => $this->id,
23:             'po_number' => $this->po_number,
24:             'supplier_id' => $this->supplier_id,
25:             'supplier' => $this->whenLoaded('supplier', fn (): ?array => $this->supplier === null ? null : [
26:                 'id' => $this->supplier->id, 'code' => $this->supplier->code, 'name' => $this->supplier->name,
27:             ]),
28:             'branch_id' => $this->branch_id,
29:             'branch' => $this->whenLoaded('branch', fn (): ?array => $this->branch === null ? null : [
30:                 'id' => $this->branch->id, 'name' => $this->branch->name,
31:             ]),
32:             'purchase_request_id' => $this->purchase_request_id,
33:             'status' => $this->status,
34:             'expected_delivery_date' => $this->expected_delivery_date?->toDateString(),
35:             'supplier_change_notes' => $this->supplier_change_notes,
36:             'subtotal' => $this->subtotal,
37:             'discount_amount' => $this->discount_amount,
38:             'tax_amount' => $this->tax_amount,
39:             'grand_total' => $this->grand_total,
40:             'created_by' => $this->created_by,
