 5: export interface RemoteState<T> {
 6:   data: T | null;
 7:   loading: boolean;
 8:   error: ParsedApiError | null;
 9:   usingMock: boolean;
10:   reload: () => void;
11:   setData: React.Dispatch<React.SetStateAction<T | null>>;
12: }
13: 
14: export function useRemote<T>(
15:   fetcher: (signal: AbortSignal) => Promise<T>,
16:   deps: DependencyList,
17:   opts: { enabled?: boolean; mock?: () => T; onError?: (e: ParsedApiError) => void } = {},
18: ): RemoteState<T> {
19:   const { enabled = true, mock, onError } = opts;
20:   const [data, setData] = useState<T | null>(null);
21:   const [loading, setLoading] = useState<boolean>(enabled);
22:   const [error, setError] = useState<ParsedApiError | null>(null);
23:   const [usingMock, setUsingMock] = useState(false);
24:   const [tick, setTick] = useState(0);
25:   const onErrorRef = useRef(onError);
26:   onErrorRef.current = onError;
27: 
28:   useEffect(() => {
29:     if (!enabled) { setData(null); setError(null); setLoading(false); return; }
30:     if (USE_MOCK) { setData(mock?.() ?? null); setUsingMock(true); setError(null); setLoading(false); return; }
31:     const ctrl = new AbortController();
32:     setLoading(true);
33:     setError(null);
34:     setData(null);
35:     setUsingMock(false);
36:     fetcher(ctrl.signal)
37:       .then((d) => { if (!ctrl.signal.aborted) { setData(d); setUsingMock(false); } })
38:       .catch((e) => {
39:         if (ctrl.signal.aborted || isAxiosCancel(e)) return;
40:         const pe = parseApiError(e);
41:         setError(pe);
42:         onErrorRef.current?.(pe);
43:         if (FALLBACK_ON_ERROR && mock && (pe.status === null || pe.status >= 500)) {
44:           setData(mock()); setUsingMock(true);
45:         }
46:       })
47:       .finally(() => { if (!ctrl.signal.aborted) setLoading(false); });
48:     return () => ctrl.abort();
49:     // eslint-disable-next-line react-hooks/exhaustive-deps
50:   }, [...deps, tick, enabled]);
51: 
52:   const reload = useCallback(() => setTick((t) => t + 1), []);
53:   return { data, loading, error, usingMock, reload, setData };
54: }
