63: /** تنفيذ mutation مع حالة busy وtoast */
64: export function useAction() {
65:   const [busy, setBusy] = useState(false);
66:   const inFlight = useRef(false);
67:   const run = useCallback(async <R,>(
68:     fn: () => Promise<R>,
69:     h: { toast: (t: string, tone?: 'accent' | 'green' | 'red') => void; success?: string; onFieldErrors?: (f: Record<string, string>) => void },
70:   ): Promise<R | undefined> => {
71:     if (USE_MOCK) { h.toast('وضع تجريبي — لم يتم الحفظ', 'accent'); return undefined; }
72:     if (inFlight.current) return undefined;
73:     inFlight.current = true;
74:     setBusy(true);
75:     try {
76:       const r = await fn();
77:       if (h.success) h.toast(h.success, 'green');
78:       return r;
79:     } catch (e) {
80:       const pe = parseApiError(e);
81:       if (pe.status === 422 && Object.keys(pe.fieldErrors).length && h.onFieldErrors) h.onFieldErrors(pe.fieldErrors);
82:       h.toast(pe.message, 'red');
83:       return undefined;
84:     } finally {
85:       inFlight.current = false;
86:       setBusy(false);
87:     }
88:   }, []);
89:   return { busy, run };
