 740: export function GroupForm({ row, onClose, onSaved }: { row: CustomerGroup | null; onClose: () => void; onSaved: () => void }) {
 741:   const toast = useToast();
 742:   const { busy, run } = useAction();
 743:   const f = useFormState({ name: row?.name ?? '', code: row?.code ?? '', desc: row?.desc ?? '', disc: row?.disc ?? 0, active: row?.active ?? true });
 744:   const save = async () => {
 745:     if (!f.v.name.trim() || !f.v.code.trim()) return toast('الاسم والكود مطلوبان', 'red');
 746:     if (f.v.code.length > 64) return toast('الكود حتى 64 حرفًا', 'red');
 747:     const body = { name: f.v.name, code: f.v.code, description: (f.v.desc as string) || null, discount_percentage: Number(f.v.disc || 0), is_active: !!f.v.active };
 748:     const r = await run(() => (row ? customerGroupsApi.update(row.id, body) : customerGroupsApi.create(body)),
 749:       { toast, success: 'تم الحفظ', onFieldErrors: (e) => f.setErrors(mapErrors(e, { name: 'name', code: 'code', description: 'desc', discount_percentage: 'disc' })) });
 750:     if (r) { onSaved(); onClose(); }
 751:   };
 752:   return (
 753:     <Modal open onClose={onClose} title={row ? 'تعديل مجموعة عملاء' : 'مجموعة عملاء جديدة'} icon="users"
 754:       footer={<><button className="btn btn-soft" onClick={onClose}>إلغاء</button><button className="btn btn-dark" disabled={busy} onClick={save}>حفظ</button></>}>
 755:       <div className="space-y-4">
 756:         <div className="grid grid-cols-2 gap-3">
 757:           <Field label="الاسم" req err={f.errors.name}><input className="inp" value={f.v.name} onChange={f.on('name')} /></Field>
 758:           <Field label="الكود" req hint="فريد" err={f.errors.code}><input className="inp num" dir="ltr" value={f.v.code} onChange={f.on('code')} /></Field>
 759:         </div>
 760:         <TextArea label="الوصف" value={f.v.desc} onChange={(v) => f.set('desc', v)} />
 761:         <Field label="نسبة الخصم" hint="من 0 إلى 100" err={f.errors.disc}>
 762:           <div className="relative"><input className="inp num" type="number" min="0" max="100" step="0.01" value={f.v.disc} onChange={f.on('disc' as any)} /><span className="absolute top-1/2 -translate-y-1/2 tx3 text-[12px]" style={{ insetInlineEnd: 14 }}>%</span></div>
 763:         </Field>
 764:         <ToggleRow label="مفعّلة" on={f.v.active} onChange={(v) => f.set('active', v)} />
 765:       </div>
 766:     </Modal>
 767:   );
 768: }
