 770: export function PriceListForm({ row, onClose, onSaved }: { row: (PriceListRow & { raw?: any }) | null; onClose: () => void; onSaved?: () => void }) {
 771:   const toast = useToast();
 772:   const { busy, run } = useAction();
 773:   const [type, setType] = useState(row?.type || 'retail');
 774:   const f = useFormState({
 775:     name: row?.name ?? '', customerId: String(row?.raw?.customer?.id ?? ''), groupId: String(row?.raw?.customer_group?.id ?? ''), branchId: String(row?.raw?.branch?.id ?? ''),
 776:     from: row?.from ?? '', to: (row?.to ?? '') as string, prio: row?.prio ?? 0, active: row?.active ?? true,
 777:   });
 778:   const [prio, setPrio] = useState(row?.prio ?? 0);
 779:   const prErr = prio < -10000 || prio > 10000 ? 'الأولوية من ‎-10000 إلى 10000' : null;
 780:   const groups = useRemote((s) => customerGroupsApi.all(s).then((rows) => rows.map(mapCustomerGroup)), [], { mock: () => CUSTOMER_GROUPS });
 781:   const branchesList = useRemote((s) => branchesApi.list({}, s).then((r) => r.data), []);
 782:   const customers = useRemote((s) => commerceLookupsApi.customers(s), []);
 783:   const toBackendType = (t: string): PriceListType => (t === 'group' ? 'customer_group' : t === 'customer' ? 'customer_specific' : t) as PriceListType;
 784:   const save = async () => {
 785:     if (!f.v.name.trim()) return toast('اسم القائمة مطلوب', 'red');
 786:     if (prErr) return;
 787:     const raw = (row as any)?.raw;
 788:     const body: any = {
 789:       name: f.v.name, type: toBackendType(type),
 790:       customer_id: type === 'customer' ? (f.v.customerId ? Number(f.v.customerId) : (raw?.customer?.id ?? null)) : null,
 791:       customer_group_id: type === 'group' ? (f.v.groupId ? Number(f.v.groupId) : (raw?.customer_group?.id ?? null)) : null,
 792:       branch_id: f.v.branchId ? Number(f.v.branchId) : null,
 793:       currency: 'EGP', starts_at: f.v.from || null, ends_at: f.v.to || null,
 794:       priority: prio, is_active: f.v.active,
 795:     };
 796:     const r = await run(() => (row && (row as any).id ? priceListsApi.update((row as any).id, body) : priceListsApi.create(body)),
 797:       { toast, success: 'تم الحفظ', onFieldErrors: (e) => f.setErrors(mapErrors(e, { starts_at: 'from', ends_at: 'to', priority: 'prio', customer_id: 'customerId', customer_group_id: 'groupId', branch_id: 'branchId' })) });
 798:     if (r) { onSaved?.(); onClose(); }
 799:   };
 800: 
 801:   return (
 802:     <Modal
 803:       open
 804:       onClose={onClose}
 805:       title={row ? 'تعديل قائمة أسعار' : 'قائمة أسعار جديدة'}
 806:       icon="tag"
 807:       width={620}
 808:       footer={
 809:         <>
 810:           <button className="btn btn-soft" onClick={onClose}>
 811:             إلغاء
 812:           </button>
 813:           <button
 814:             className="btn btn-dark"
 815:             disabled={!!prErr || busy}
 816:             onClick={save}
 817:           >
 818:             حفظ
 819:           </button>
 820:         </>
 821:       }
 822:     >
 823:       <div className="space-y-4">
 824:         <Field label="الاسم" req err={f.errors.name}>
 825:           <input className="inp" value={f.v.name} onChange={f.on('name')} />
 826:         </Field>
 827:         <Field label="النوع" req>
 828:           <div className="flex flex-wrap gap-1.5">
 829:             {Object.entries(PL_TYPES).map(([k, l]) => (
 830:               <button
 831:                 key={k}
 832:                 type="button"
 833:                 onClick={() => setType(k)}
 834:                 className={'pill-inp font-medium ' + (type === k ? 'on' : '')}
 835:               >
 836:                 {l}
 837:               </button>
 838:             ))}
 839:           </div>
 840:         </Field>
 841:         {type === 'customer' && (
 842:           <Field label="العميل" req err={f.errors.customerId}>
 843:             <select className="inp" value={f.v.customerId} onChange={f.on('customerId' as any)}>
 844:               <option value="">اختر العميل</option>
 845:               {(customers.data ?? []).map((w: { id: number; name: string }) => (
 846:                 <option key={w.id} value={String(w.id)}>{w.name}</option>
 847:               ))}
 848:             </select>
 849:           </Field>
 850:         )}
 851:         {type === 'group' && (
 852:           <Field label="مجموعة العملاء" req err={f.errors.groupId}>
 853:             <select className="inp" value={f.v.groupId} onChange={f.on('groupId' as any)}>
 854:               <option value="">اختر المجموعة</option>
 855:               {(groups.data ?? []).map((g: CustomerGroup) => (
 856:                 <option key={g.id} value={String(g.id)}>{g.name}</option>
 857:               ))}
 858:             </select>
 859:           </Field>
 860:         )}
 861:         <div className="grid grid-cols-2 gap-3">
 862:           <Field label="الفرع" hint="اتركه فارغًا لكل الفروع" err={f.errors.branchId}>
 863:             <select className="inp" value={f.v.branchId} onChange={f.on('branchId' as any)}>
 864:               <option value="">كل الفروع</option>
 865:               {(branchesList.data ?? []).map((b: { id: number; name: string }) => (
 866:                 <option key={b.id} value={String(b.id)}>{b.name}</option>
 867:               ))}
 868:             </select>
 869:           </Field>
 870:           <Field label="العملة">
 871:             <input className="inp num" value="EGP" readOnly dir="ltr" />
 872:           </Field>
 873:           <Field label="بداية السريان" err={f.errors.from}>
 874:             <input type="date" className="inp" value={f.v.from} onChange={f.on('from' as any)} />
 875:           </Field>
 876:           <Field label="نهاية السريان" err={f.errors.to}>
 877:             <input type="date" className="inp" value={f.v.to} onChange={f.on('to' as any)} />
 878:           </Field>
 879:         </div>
 880:         <Field label="الأولوية" err={prErr ?? f.errors.prio} hint="الأعلى يُطبَّق أولًا عند تعارض القوائم · من ‎-10000 إلى 10000">
 881:           <input
 882:             type="number"
 883:             className={'inp num ' + (prErr ? 'err' : '')}
 884:             value={prio}
 885:             onChange={(e) => setPrio(Number(e.target.value))}
 886:           />
 887:         </Field>
 888:         <ToggleRow label="مفعّلة" on={f.v.active} onChange={(v) => f.set('active', v)} />
 889:       </div>
 890:     </Modal>
 891:   );
 892: }
