 894: export function AddPriceItemModal({ priceListId, onClose, onSaved }: { priceListId: number; onClose: () => void; onSaved: () => void }) {
 895:   const toast = useToast();
 896:   const { busy, run } = useAction();
 897:   const f = useFormState({ variantId: '', min: 1, price: '' as any, from: '', to: '' });
 898:   const variants = useRemote((signal) => commerceLookupsApi.variants(signal), []);
 899:   const variantOptions = variants.data ?? [];
 900:   const save = async () => {
 901:     if (!f.v.variantId) return toast('اختر متغير المنتج', 'red');
 902:     if (!f.v.price && f.v.price !== 0) return toast('أدخل السعر', 'red');
 903:     const r = await run(() => priceListItemsApi(priceListId).create({
 904:       product_variant_id: Number(f.v.variantId), min_qty: Number(f.v.min || 1), price: Number(f.v.price),
 905:       starts_at: (f.v.from as string) || null, ends_at: (f.v.to as string) || null,
 906:     }), { toast, success: 'تمت الإضافة', onFieldErrors: (e) => f.setErrors(e as any) });
 907:     if (r) { onSaved(); onClose(); }
 908:   };
 909:   return (
 910:     <Modal open onClose={onClose} title="إضافة بند للقائمة" icon="tag" width={560}
 911:       footer={<><button className="btn btn-soft" onClick={onClose}>إلغاء</button><button className="btn btn-dark" disabled={busy} onClick={save}>إضافة</button></>}>
 912:       <div className="space-y-4">
 913:         <RemoteFeedback state={variants} />
 914:         <Field label="متغير المنتج" req err={f.errors.product_variant_id}>
 915:           <select className="inp" value={f.v.variantId} onChange={f.on('variantId' as any)}>
 916:             <option value="">اختر المتغير</option>
 917:             {variantOptions.map((v) => (<option key={v.id} value={String(v.id)}>{v.label}</option>))}
 918:           </select>
 919:         </Field>
 920:         <div className="grid grid-cols-2 gap-3">
 921:           <Field label="أقل كمية لتطبيق السعر" req hint="1 أو أكثر" err={f.errors.min_qty}><input type="number" min="1" className="inp num" value={f.v.min} onChange={f.on('min' as any)} /></Field>
 922:           <Field label="السعر (EGP)" req hint="حتى 4 منازل عشرية" err={f.errors.price}><input type="number" step="0.0001" min="0" className="inp num" value={f.v.price} onChange={f.on('price' as any)} /></Field>
 923:         </div>
 924:         <div className="grid grid-cols-2 gap-3">
 925:           <Field label="بداية سريان البند" hint="اختياري"><input type="date" className="inp" value={f.v.from} onChange={f.on('from' as any)} /></Field>
 926:           <Field label="نهاية سريان البند" hint="اختياري"><input type="date" className="inp" value={f.v.to} onChange={f.on('to' as any)} /></Field>
 927:         </div>
 928:       </div>
 929:     </Modal>
 930:   );
 931: }
