 933: export function PriceListDetail({ id, go }: { id: number; go: (r: { m: string; id?: any; sub?: any }) => void }) {
 934:   const toast = useToast();
 935:   const { busy, run } = useAction();
 936:   const pl = useRemote((s) => priceListsApi.show(id, s).then(mapPriceList), [id], { mock: () => (PRICE_LISTS.find((row) => row.id === id) ?? PRICE_LISTS[0]) as any, onError: (e) => toast(e.message, 'red') });
 937:   const p = pl.data;
 938:   const itemsApi = useMemo(() => priceListItemsApi(id), [id]);
 939:   const [search, setSearch] = useState('');
 940:   const dsearch = useDebounced(search);
 941:   const remoteItems = useRemote((s) => itemsApi.all(s), [id], { mock: () => [] });
 942:   const [items, setItems] = useState<any[]>([]);
 943:   useEffect(() => {
 944:     setItems((remoteItems.data ?? []).map((it) => ({
 945:       id: it.id, v: { name: it.variant?.product_name_ar ?? `#${it.product_variant_id}`, sku: it.variant?.sku ?? '' },
 946:       variantId: it.product_variant_id, min: it.min_qty, price: it.price, from: it.starts_at?.slice(0, 10) ?? '', to: it.ends_at?.slice(0, 10) ?? '',
 947:     })));
 948:   }, [remoteItems.data]);
 949:   const [editRow, setEditRow] = useState<any>(null);
 950:   const [form, setForm] = useState(false);
 951:   const [pct, setPct] = useState('');
 952:   const [imp, setImp] = useState(false);
 953:   const upd = (rowId: number, k: string, v: any) =>
 954:     setItems(items.map((it) => (it.id === rowId ? { ...it, [k]: v } : it)));
 955:   const saveRow = async (r: any) => {
 956:     await run(() => itemsApi.update(r.id, { product_variant_id: r.variantId, min_qty: Number(r.min), price: Number(r.price), starts_at: r.from || null, ends_at: r.to || null }),
 957:       { toast, success: 'تم حفظ البند' });
 958:   };
 959:   const deleteRow = async (r: any) => {
 960:     const ok = await run(() => itemsApi.remove(r.id), { toast, success: 'تم حذف البند' });
 961:     if (ok) setItems(items.filter((x) => x.id !== r.id));
 962:   };
 963:   const applyPercent = async (pctVal: number) => {
 964:     if (pctVal < -100) return toast('النسبة لا تقل عن -100%', 'red');
 965:     const result = await run(async () => {
 966:       for (const r of items) {
 967:         const price = Number((Number(r.price) * (1 + pctVal / 100)).toFixed(4));
 968:         await itemsApi.update(r.id, { product_variant_id: r.variantId, min_qty: Number(r.min), price, starts_at: r.from || null, ends_at: r.to || null });
 969:       }
 970:       return true;
 971:     }, { toast, success: 'تم تطبيق التعديل' });
 972:     remoteItems.reload();
 973:     if (result) setPct('');
 974:   };
 975:   if (!p) return <RemoteFeedback state={pl} />;
 976: 
 977:   return (
 978:     <div className="space-y-5">
 979:       <PageHead
 980:         back={{ label: 'قوائم الأسعار', onClick: () => go({ m: 'pricing' }) }}
 981:         title={p.name}
 982:         sub={
 983:           <span className="flex flex-wrap items-center gap-2">
 984:             <Badge dot={false} tone="violet">
 985:               {PL_TYPES[p.type] || p.type}
 986:             </Badge>
 987:             {p.target && <span>{p.target} ·</span>}
 988:             <span>{p.branch || 'كل الفروع'}</span>·
 989:             <span className="num ltr">
 990:               {p.from} → {p.to || '∞'}
 991:             </span>
 992:             ·
 993:             <span>
 994:               أولوية <Num>{p.prio}</Num>
 995:             </span>
 996:           </span>
 997:         }
 998:         actions={
 999:           <>
1000:             <button className="btn btn-soft" disabled={pl.usingMock} onClick={() => setForm(true)}>
1001:               <Icon name="edit" size={14} />
1002:               تعديل القائمة
1003:             </button>
1004:             <button className="btn btn-soft" disabled={busy || pl.usingMock || remoteItems.usingMock} onClick={() => run(() => priceListsApi.exportCsv(id, p.name), { toast, success: 'تم تصدير CSV' })}>
1005:               <Icon name="download" size={14} />
1006:               تصدير CSV
1007:             </button>
1008:             <button className="btn btn-soft" disabled={pl.usingMock} onClick={() => setImp(true)}><Icon name="upload" size={14} />استيراد أسعار</button>
1009:             <button className="btn btn-dark" disabled={pl.usingMock || remoteItems.usingMock} onClick={() => setEditRow({})}>
1010:               <Icon name="plus" size={14} />
1011:               إضافة بند
1012:             </button>
1013:           </>
1014:         }
1015:       />
1016:       <RemoteFeedback state={pl} />
1017:       <RemoteFeedback state={remoteItems} />
1018:       <Card stg={2}>
1019:         <div className="flex flex-wrap items-center justify-between gap-3 mb-4">
1020:           <div className="flex items-center gap-2">
1021:             <SearchPill value={search} onChange={setSearch} placeholder="بحث بالاسم أو SKU" />
1022:             <span className="text-[11.5px] tx3">
1023:               <Num>{items.length}</Num> بند مسجّل
1024:             </span>
1025:           </div>
1026:           <div className="flex items-center gap-2">
1027:             <span className="text-[12px] tx2">تعديل نسبة مئوية جماعي:</span>
1028:             <input type="number" step="0.5" placeholder="+5%" className="inp inp-sm num w-20" value={pct} onChange={(e) => setPct(e.target.value)} />
1029:             <button className="btn btn-soft btn-sm" disabled={busy || pl.usingMock || remoteItems.usingMock || !pct} onClick={() => { const v = Number(pct); if (!Number.isFinite(v)) return toast('أدخل نسبة صحيحة', 'red'); void applyPercent(v); }}>
1030:               تطبيق
1031:             </button>
1032:           </div>
1033:         </div>
1034:         <DataTable
1035:           rows={items.filter((row) => !dsearch || (row.v.name + ' ' + row.v.sku).toLowerCase().includes(dsearch.toLowerCase()))}
1036:           cols={[
1037:             {
1038:               h: 'المنتج / المتغير',
1039:               r: (r: any) => (
1040:                 <div className="leading-tight">
1041:                   <div className="font-medium tx1">{r.v.name}</div>
1042:                   <div className="text-[11px] tx3 num">{r.v.sku}</div>
1043:                 </div>
1044:               ),
1045:             },
1046:             {
1047:               h: 'أقل كمية',
1048:               align: 'center',
1049:               r: (r: any) => (
1050:                 <input
1051:                   type="number"
1052:                   min="1"
1053:                   className="inp inp-sm num !w-20 text-center"
1054:                   disabled={pl.usingMock || remoteItems.usingMock}
1055:                   value={r.min}
1056:                   onChange={(e) => upd(r.id, 'min', e.target.value)}
1057:                   onBlur={() => saveRow(r)}
1058:                 />
1059:               ),
1060:             },
1061:             {
1062:               h: 'السعر (حتى 4 منازل)',
1063:               r: (r: any) => (
1064:                 <div className="flex items-center gap-1.5">
1065:                   <input
1066:                     type="number"
1067:                     step="0.0001"
1068:                     className="inp inp-sm num !w-28 text-end"
1069:                     value={r.price}
1070:                     onChange={(e) => upd(r.id, 'price', e.target.value)}
1071:                     onBlur={() => saveRow(r)}
1072:                   />
1073:                   <span className="text-[11px] tx3">EGP</span>
1074:                 </div>
1075:               ),
1076:             },
1077:             {
1078:               h: 'فترة سريان البند',
1079:               r: (r: any) => (
1080:                 <div className="flex items-center gap-1 num text-[11px]">
1081:                   <input
1082:                     type="date"
1083:                     className="inp inp-sm text-[11px] !py-0.5"
1084:                     value={r.from}
1085:                     onChange={(e) => upd(r.id, 'from', e.target.value)}
1086:                     onBlur={() => saveRow(r)}
1087:                   />
1088:                   <span className="tx3">→</span>
1089:                   <input
1090:                     type="date"
1091:                     className="inp inp-sm text-[11px] !py-0.5"
1092:                     value={r.to}
1093:                     onChange={(e) => upd(r.id, 'to', e.target.value)}
1094:                     onBlur={() => saveRow(r)}
1095:                   />
1096:                 </div>
1097:               ),
1098:             },
1099:             {
1100:               h: '',
1101:               r: (r: any) => (
1102:                 <RowActions>
1103:                   <button className="icon-btn !w-7 !h-7" disabled={busy} onClick={() => deleteRow(r)}>
1104:                     <Icon name="trash" size={13} />
1105:                   </button>
1106:                 </RowActions>
1107:               ),
1108:             },
1109:           ]}
1110:         />
1111:       </Card>
1112:       <PriceImportModal open={imp} priceListId={id} onClose={() => setImp(false)} onSaved={() => { remoteItems.reload(); pl.reload(); }} />
1113:       {editRow && (
1114:         <AddPriceItemModal priceListId={id} onClose={() => setEditRow(null)} onSaved={() => { remoteItems.reload(); pl.reload(); }} />
1115:       )}
1116:       {form && <PriceListForm row={p as any} onClose={() => setForm(false)} onSaved={() => pl.reload()} />}
1117:     </div>
1118:   );
1119: }
