1121: /* ---------------- PROMOS & COUPONS ---------------- */
1122: export function PromosPage() {
1123:   const toast = useToast();
1124:   const { run } = useAction();
1125:   const [tab, setTab] = useState<'promos' | 'coupons'>('promos');
1126:   const [pf, setPf] = useState<PromoRow | null>(null);
1127:   const [cf, setCf] = useState<CouponRow | null>(null);
1128:   const [newPromo, setNewPromo] = useState(false);
1129:   const [newCoupon, setNewCoupon] = useState(false);
1130:   const promos = useRemote((s) => promotionsApi.all(s).then((rows) => rows.map((p) => ({ ...mapPromo(p), targetIds: p.target_ids ?? [], targets: (p.target_ids ?? []).map(String) }))), [], { mock: () => PROMOS });
1131:   const coupons = useRemote((s) => couponsApi.all(s).then((rows) => rows.map(mapCoupon)), [], { mock: () => COUPONS });
1132: 
1133:   const promoVal = (p: PromoRow) =>
1134:     p.type === 'percent' ? (
1135:       <Num className="font-semibold">{p.value}%</Num>
1136:     ) : p.type === 'amount' ? (
1137:       <span className="font-semibold">{fmtMoney(p.value || 0, 0)}</span>
1138:     ) : (
1139:       <span className="tx3">—</span>
1140:     );
1141: 
1142:   return (
1143:     <div className="space-y-5">
1144:       <PageHead
1145:         title="العروض والكوبونات"
1146:         sub="العروض تُطبق على نطاق محدد، والكوبونات بأكواد يُدخلها العميل."
1147:         actions={
1148:           <button className="btn btn-dark" onClick={() => (promos.usingMock || coupons.usingMock) ? toast('البيانات تجريبية — لا يمكن الحفظ', 'red') : (tab === 'promos' ? setNewPromo(true) : setNewCoupon(true))}>
1149:             <Icon name="plus" size={14} />
1150:             {tab === 'promos' ? 'عرض ترويجي' : 'كوبون جديد'}
1151:           </button>
1152:         }
1153:       />
1154:       <RemoteFeedback state={tab === 'promos' ? promos : coupons} />
1155:       <Note>العروض مسجلة للإدارة ولا يطبقها الخادم تلقائيًا عند الشراء.</Note>
1156:       <TabsBar
1157:         value={tab}
1158:         onChange={(v: any) => setTab(v)}
1159:         tabs={[
1160:           { value: 'promos', label: 'العروض الترويجية', icon: 'ticket', count: (promos.data ?? []).length },
1161:           { value: 'coupons', label: 'كوبونات الخصم', icon: 'tag', count: (coupons.data ?? []).length },
1162:         ]}
1163:       />
1164:       {tab === 'promos' && (
1165:         <Card stg={3}>
1166:           <DataTable
1167:             rows={promos.data ?? []}
1168:             onRow={(p: PromoRow) => promos.usingMock ? toast('البيانات تجريبية — لا يمكن التعديل', 'red') : setPf(p)}
1169:             cols={[
1170:               { h: 'اسم العرض', r: (p: PromoRow) => <span className="font-semibold tx1">{p.name}</span> },
1171:               {
1172:                 h: 'النوع',
1173:                 r: (p: PromoRow) => (
1174:                   <Badge
1175:                     dot={false}
1176:                     tone={
1177:                       ({
1178:                         percent: 'orange',
1179:                         amount: 'blue',
1180:                         free_ship: 'green',
1181:                         bxgy: 'violet',
1182:                       } as const)[p.type as 'percent'] || 'gray'
1183:                     }
1184:                   >
1185:                     {PROMO_TYPES[p.type] || p.type}
1186:                   </Badge>
1187:                 ),
1188:               },
1189:               { h: 'القيمة', r: promoVal },
1190:               {
1191:                 h: 'الحد الأدنى',
1192:                 r: (p: PromoRow) =>
1193:                   p.min ? <span className="tx2 font-medium">{fmtMoney(p.min, 0)}</span> : <span className="tx3">—</span>,
1194:               },
1195:               {
1196:                 h: 'النطاق والمستهدفات',
1197:                 r: (p: PromoRow) => (
1198:                   <div className="leading-tight">
1199:                     <span className="text-[12px] font-medium">{SCOPES[p.scope]}</span>
1200:                     {p.targets?.length > 0 && (
1201:                       <div className="text-[11px] tx3 clamp1 mt-0.5">{p.targets.join('، ')}</div>
1202:                     )}
1203:                   </div>
1204:                 ),
1205:               },
1206:               {
1207:                 h: 'السريان',
1208:                 r: (p: PromoRow) => (
1209:                   <span className="num text-[11.5px] tx2 ltr">
1210:                     {p.from} → {p.to || '∞'}
1211:                   </span>
1212:                 ),
1213:               },
1214:               { h: 'التفعيل', r: (p: PromoRow) => <ActiveDot on={p.active} /> },
1215:               {
1216:                 h: '',
1217:                 r: (p: PromoRow) => (
1218:                   <RowActions>
1219:                     <button className="icon-btn !w-7 !h-7" onClick={() => promos.usingMock ? toast('البيانات تجريبية — لا يمكن التعديل', 'red') : setPf(p)}>
1220:                       <Icon name="edit" size={13} />
1221:                     </button>
1222:                   </RowActions>
1223:                 ),
1224:               },
1225:             ]}
1226:           />
1227:         </Card>
1228:       )}
1229:       {tab === 'coupons' && (
1230:         <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
1231:           {(coupons.data ?? []).map((c, i) => {
1232:             const pct = c.total ? Math.min(100, (c.used / c.total) * 100) : null;
1233:             return (
1234:               <div
1235:                 key={c.id}
1236:                 className={'v-card p-5 stg stg-' + (2 + i) + ' cursor-pointer hover:shadow-sm transition'}
1237:                 onClick={() => coupons.usingMock ? toast('البيانات تجريبية — لا يمكن التعديل', 'red') : setCf(c)}
1238:               >
1239:                 <div className="flex items-start justify-between gap-3">
1240:                   <div>
1241:                     <div className="font-display text-[22px] font-bold num tracking-[.06em] tx1 ltr">{c.code}</div>
1242:                     <div className="flex items-center gap-2 mt-1.5">
1243:                       <Badge dot={false} tone="orange">
1244:                         {COUPON_TYPES[c.type]}
1245:                       </Badge>
1246:                       {c.value && (
1247:                         <span className="font-semibold text-[13px]">
1248:                           {c.type === 'percent' ? <Num>{c.value}%</Num> : fmtMoney(c.value, 0)}
1249:                         </span>
1250:                       )}
1251:                       {c.maxDisc && (
1252:                         <span className="text-[11.5px] tx3">حد أقصى {fmtMoney(c.maxDisc, 0)}</span>
1253:                       )}
1254:                     </div>
1255:                   </div>
1256:                   <ActiveDot on={c.active} />
1257:                 </div>
1258:                 <div className="mt-4">
1259:                   <div className="flex items-center justify-between text-[12px] mb-1.5">
1260:                     <span>
1261:                       <b className="num tx1">{fmtInt(c.used)}</b> <span className="tx3">مرة استخدام</span>
1262:                     </span>
1263:                     <span className="tx2">{c.total ? <>من <Num>{fmtInt(c.total)}</Num></> : 'غير محدود'}</span>
1264:                   </div>
1265:                   {pct != null ? <HatchBar pct={pct} h={12} /> : <div className="h-3 rounded-full hatch-track"></div>}
1266:                 </div>
1267:                 <div className="grid grid-cols-3 gap-2 mt-4">
1268:                   <div className="v-sub px-3 py-2">
1269:                     <div className="text-[10.5px] tx3">الحد الأدنى</div>
1270:                     <div className="text-[12px] font-semibold">{fmtMoney(c.min, 0)}</div>
1271:                   </div>
1272:                   <div className="v-sub px-3 py-2">
1273:                     <div className="text-[10.5px] tx3">لكل عميل</div>
1274:                     <div className="text-[12px] font-semibold">{c.perCust ? <Num>{c.perCust}</Num> : '∞'}</div>
1275:                   </div>
1276:                   <div className="v-sub px-3 py-2">
1277:                     <div className="text-[10.5px] tx3">السريان</div>
1278:                     <div className="text-[11px] font-semibold num ltr">{c.to ? c.to.slice(5) : '∞'}</div>
1279:                   </div>
1280:                 </div>
1281:               </div>
1282:             );
1283:           })}
1284:         </div>
1285:       )}
1286:       {(pf || newPromo) && <PromoForm row={pf} onClose={() => { setPf(null); setNewPromo(false); }} onSaved={() => promos.reload()} />}
1287:       {(cf || newCoupon) && <CouponForm row={cf} onClose={() => { setCf(null); setNewCoupon(false); }} onSaved={() => coupons.reload()} />}
1288:     </div>
1289:   );
1290: }
