1292: export function PromoForm({ row, onClose, onSaved }: { row: PromoRow | null; onClose: () => void; onSaved?: () => void }) {
1293:   const toast = useToast();
1294:   const { busy, run } = useAction();
1295:   const [deleting, setDeleting] = useState(false);
1296:   const [type, setType] = useState(row?.type || 'percent');
1297:   const [scope, setScope] = useState(row?.scope || 'all');
1298:   const [targets, setTargets] = useState<number[]>((row as PromoRow & { targetIds?: number[] } | null)?.targetIds ?? []);
1299:   const options = useRemote((signal) => scope === 'categories' ? commerceLookupsApi.categories(signal) : scope === 'brands' ? commerceLookupsApi.brands(signal) : commerceLookupsApi.variants(signal), [scope], { enabled: scope !== 'all' && scope !== 'brands' });
1300:   const f = useFormState({ name: row?.name ?? '', value: (row?.value ?? '') as any, min: (row?.min ?? '') as any, from: row?.from ?? '', to: (row?.to ?? '') as string, active: row?.active ?? true });
1301:   const save = async () => {
1302:     if (!f.v.name.trim()) return toast('اسم العرض مطلوب', 'red');
1303:     const body: any = {
1304:       name: f.v.name, type: promoToBackend(type),
1305:       value: type === 'percent' || type === 'amount' ? (f.v.value === '' ? undefined : Number(f.v.value)) : undefined,
1306:       min_order_amount: f.v.min === '' ? null : Number(f.v.min),
1307:       applies_to: scope, target_ids: scope === 'all' ? [] : targets,
1308:       starts_at: f.v.from || null, ends_at: (f.v.to as string) || null, is_active: !!f.v.active,
1309:     };
1310:     const r = await run(() => (row ? promotionsApi.update(row.id, body) : promotionsApi.create(body)),
1311:       { toast, success: 'تم الحفظ', onFieldErrors: (e) => f.setErrors(mapErrors(e, { min_order_amount: 'min', applies_to: 'scope', target_ids: 'targets', starts_at: 'from', ends_at: 'to' })) });
1312:     if (r) { onSaved?.(); onClose(); }
1313:   };
1314: 
1315:   const opts = options.data ?? [];
1316:   const on = (id: number) => setTargets(targets.includes(id) ? targets.filter((target) => target !== id) : [...targets, id]);
1317: 
1318:   return (
1319:     <Modal
1320:       open
1321:       onClose={onClose}
1322:       title={row ? 'تعديل عرض ترويجي' : 'عرض ترويجي جديد'}
1323:       icon="ticket"
1324:       width={640}
1325:       footer={
1326:         <>
1327:           {row && <button className="btn btn-danger" disabled={busy} onClick={() => setDeleting(true)}>حذف</button>}
1328:           <button className="btn btn-soft" onClick={onClose}>
1329:             إلغاء
1330:           </button>
1331:           <button
1332:             className="btn btn-dark"
1333:             disabled={busy}
1334:             onClick={save}
1335:           >
1336:             حفظ
1337:           </button>
1338:         </>
1339:       }
1340:     >
1341:       <div className="space-y-4">
1342:         {scope !== 'all' && <RemoteFeedback state={options} />}
1343:         <Field label="اسم العرض" req err={f.errors.name}>
1344:           <input className="inp" value={f.v.name} onChange={f.on('name')} />
1345:         </Field>
1346:         <Field label="النوع" req>
1347:           <div className="flex flex-wrap gap-1.5">
1348:             {Object.entries(PROMO_TYPES).map(([k, l]) => (
1349:               <button
1350:                 key={k}
1351:                 type="button"
1352:                 onClick={() => setType(k as any)}
1353:                 className={'pill-inp font-medium ' + (type === k ? 'on' : '')}
1354:               >
1355:                 {l}
1356:               </button>
1357:             ))}
1358:           </div>
1359:         </Field>
1360:         <div className="grid grid-cols-2 gap-3">
1361:           {type !== 'free_ship' && type !== 'bxgy' && (
1362:             <Field label={type === 'percent' ? 'نسبة الخصم %' : 'مبلغ الخصم (EGP)'} req err={f.errors.value}>
1363:               <input type="number" step="0.01" min="0" className="inp num" value={f.v.value} onChange={f.on('value' as any)} />
1364:             </Field>
1365:           )}
1366:           {type === 'bxgy' && (
1367:             <>
1368:               <Field label="اشترِ (كمية X)" hint="الخادم لا يدعم حفظ كميات X/Y حاليًا">
1369:                 <input type="number" min="1" className="inp num" value="2" readOnly disabled />
1370:               </Field>
1371:               <Field label="واحصل على (كمية Y)" hint="العرض يُحفظ للإدارة فقط ولا يُطبق تلقائيًا">
1372:                 <input type="number" min="1" className="inp num" value="1" readOnly disabled />
1373:               </Field>
1374:             </>
1375:           )}
1376:           <Field label="الحد الأدنى لقيمة الطلب" hint="اختياري" err={f.errors.min}>
1377:             <input type="number" step="0.01" min="0" className="inp num" value={f.v.min} onChange={f.on('min' as any)} />
1378:           </Field>
1379:         </div>
1380:         <Field label="نطاق التطبيق" req err={f.errors.scope}>
1381:           <div className="flex flex-wrap gap-1.5">
1382:             {Object.entries(SCOPES).map(([k, l]) => (
1383:               <button
1384:                 key={k}
1385:                 type="button"
1386:                 onClick={() => {
1387:                   setScope(k as any);
1388:                   setTargets([]);
1389:                 }}
1390:                 className={'pill-inp font-medium ' + (scope === k ? 'on' : '')}
1391:               >
1392:                 {l}
1393:               </button>
1394:             ))}
1395:           </div>
1396:         </Field>
1397:         {f.errors.targets && <Note tone="red">{f.errors.targets}</Note>}
1398:         {scope !== 'all' && (
1399:           <div>
1400:             <div className="flex items-center justify-between mb-2">
1401:               <span className="lbl">المستهدفات المشمولة</span>
1402:               <span className="text-[11px] tx3">
1403:                 <Num>{targets.length}</Num> مختارة
1404:               </span>
