1409:                   key={o.id}
1410:                   type="button"
1411:                   onClick={() => on(o.id)}
1412:                   className={'pill-inp text-[12px] ' + (targets.includes(o.id) ? 'on' : '')}
1413:                 >
1414:                   {o.label}
1415:                 </button>
1416:               ))}
1417:             </div>
1418:           </div>
1419:         )}
1420:         <div className="grid grid-cols-2 gap-3">
1421:           <Field label="بداية السريان" req err={f.errors.from}>
1422:             <input type="date" className="inp" value={f.v.from} onChange={f.on('from' as any)} />
1423:           </Field>
1424:           <Field label="نهاية السريان" hint="اتركه فارغًا لمستمر" err={f.errors.to}>
1425:             <input type="date" className="inp" value={f.v.to} onChange={f.on('to' as any)} />
1426:           </Field>
1427:         </div>
1428:         <ToggleRow label="مفعّل" on={f.v.active} onChange={(v) => f.set('active', v)} />
1429:       </div>
1430:       <ConfirmModal open={deleting} danger title="حذف العرض" text="سيُحذف السجل نهائيًا." cta="حذف" onClose={() => setDeleting(false)} onConfirm={async () => {
1431:         if (!row || busy) return false;
1432:         const deleted = await run(() => promotionsApi.remove(row.id), { toast, success: 'تم الحذف' });
1433:         if (deleted) { onSaved?.(); onClose(); }
1434:         return !!deleted;
1435:       }} />
1436:     </Modal>
1437:   );
1438: }
