1440: export function CouponForm({ row, onClose, onSaved }: { row: CouponRow | null; onClose: () => void; onSaved?: () => void }) {
1441:   const toast = useToast();
1442:   const { busy, run } = useAction();
1443:   const [deleting, setDeleting] = useState(false);
1444:   const [code, setCode] = useState(row?.code || '');
1445:   const [type, setType] = useState(row?.type || 'percent');
1446:   const f = useFormState({
1447:     value: (row?.value ?? '') as any, maxDisc: (row?.maxDisc ?? '') as any, min: (row?.min ?? '') as any,
1448:     total: (row?.total ?? '') as any, perCust: (row?.perCust ?? '') as any,
1449:     from: row?.from ?? '', to: (row?.to ?? '') as string, active: row?.active ?? true,
1450:   });
1451:   const save = async () => {
1452:     if (!code.trim()) return toast('كود الكوبون مطلوب', 'red');
1453:     const body: any = {
1454:       code: code.toUpperCase().replace(/\s/g, ''), type: couponToBackend(type),
1455:       value: type === 'free_ship' ? undefined : Number(f.v.value || 0),
1456:       max_discount_amount: (f.v.maxDisc as string) === '' ? null : Number(f.v.maxDisc || 0),
1457:       min_order_amount: Number(f.v.min || 0),
1458:       usage_limit: (f.v.total as string) === '' ? null : Number(f.v.total),
1459:       usage_limit_per_customer: (f.v.perCust as string) === '' ? 0 : Number(f.v.perCust),
1460:       starts_at: f.v.from, ends_at: (f.v.to as string) || null, is_active: !!f.v.active,
1461:     };
1462:     const r = await run(() => (row ? couponsApi.update(row.id, body) : couponsApi.create(body)),
1463:       { toast, success: 'تم الحفظ', onFieldErrors: (e) => f.setErrors(mapErrors(e, { max_discount_amount: 'maxDisc', min_order_amount: 'min', usage_limit: 'total', usage_limit_per_customer: 'perCust', starts_at: 'from', ends_at: 'to' })) });
1464:     if (r) { onSaved?.(); onClose(); }
1465:   };
1466:   return (
1467:     <Modal
1468:       open
1469:       onClose={onClose}
1470:       title={row ? 'تعديل كوبون' : 'كوبون جديد'}
1471:       icon="ticket"
1472:       width={600}
1473:       footer={
1474:         <>
1475:           {row && <button className="btn btn-danger" disabled={busy} onClick={() => setDeleting(true)}>حذف</button>}
1476:           <button className="btn btn-soft" onClick={onClose}>
1477:             إلغاء
1478:           </button>
1479:           <button
1480:             className="btn btn-dark"
1481:             disabled={!code || busy}
1482:             onClick={save}
1483:           >
1484:             حفظ
1485:           </button>
1486:         </>
1487:       }
1488:     >
1489:       <div className="space-y-4">
1490:         <Field label="الكود" req count={`${code.length} / 50`} hint="فريد · يُحوَّل تلقائيًا لحروف كبيرة" err={f.errors.code}>
1491:           <input
1492:             className="inp num font-bold tracking-[.08em]"
1493:             dir="ltr"
1494:             maxLength={50}
1495:             value={code}
1496:             onChange={(e) => setCode(e.target.value.toUpperCase().replace(/\s/g, ''))}
1497:             placeholder="SUMMER25"
1498:           />
1499:         </Field>
1500:         <Field label="النوع" req>
1501:           <Seg
1502:             value={type}
1503:             onChange={(v: any) => setType(v)}
1504:             options={Object.entries(COUPON_TYPES).map(([v, l]) => ({ value: v, label: l }))}
1505:           />
1506:         </Field>
1507:         <div className="grid grid-cols-2 gap-3">
1508:           {type !== 'free_ship' && (
1509:             <Field label="قيمة الخصم" req err={f.errors.value}>
1510:               <div className="relative">
1511:                 <input className="inp num" type="number" value={f.v.value} onChange={f.on('value' as any)} />
1512:                 <span
1513:                   className="absolute top-1/2 -translate-y-1/2 tx3 text-[12px]"
1514:                   style={{ insetInlineEnd: 14 }}
1515:                 >
1516:                   {type === 'percent' ? '%' : 'EGP'}
1517:                 </span>
1518:               </div>
1519:             </Field>
1520:           )}
1521:           {type === 'percent' && (
1522:             <Field label="أقصى مبلغ خصم" err={f.errors.maxDisc}>
1523:               <input className="inp num" type="number" value={f.v.maxDisc} onChange={f.on('maxDisc' as any)} placeholder="بدون حد" />
1524:             </Field>
1525:           )}
1526:           <Field label="الحد الأدنى للطلب" err={f.errors.min}>
1527:             <input className="inp num" type="number" value={f.v.min} onChange={f.on('min' as any)} />
1528:           </Field>
1529:           <Field label="الحد الإجمالي للاستخدام" err={f.errors.total}>
1530:             <input className="inp num" type="number" value={f.v.total} onChange={f.on('total' as any)} placeholder="غير محدود" />
1531:           </Field>
1532:           <Field label="حد الاستخدام لكل عميل" err={f.errors.perCust}>
1533:             <input className="inp num" type="number" value={f.v.perCust} onChange={f.on('perCust' as any)} placeholder="غير محدود" />
1534:           </Field>
1535:         </div>
1536:         <div className="grid grid-cols-2 gap-3">
1537:           <Field label="بداية السريان" err={f.errors.from}>
1538:             <input type="date" className="inp" value={f.v.from} onChange={f.on('from' as any)} />
1539:           </Field>
1540:           <Field label="نهاية السريان" err={f.errors.to}>
1541:             <input type="date" className="inp" value={f.v.to} onChange={f.on('to' as any)} />
1542:           </Field>
1543:         </div>
1544:         <ToggleRow label="مفعّل" on={f.v.active} onChange={(v) => f.set('active', v)} />
1545:       </div>
1546:       <ConfirmModal open={deleting} danger title="حذف الكوبون" text="سيُحذف السجل نهائيًا." cta="حذف" onClose={() => setDeleting(false)} onConfirm={async () => {
1547:         if (!row || busy) return false;
1548:         const deleted = await run(() => couponsApi.remove(row.id), { toast, success: 'تم الحذف' });
1549:         if (deleted) { onSaved?.(); onClose(); }
1550:         return !!deleted;
1551:       }} />
1552:     </Modal>
1553:   );
1554: }
