1557: export function BrandForm({ row, onClose, onSaved }: { row: BrandRow | null; onClose: () => void; onSaved: () => void }) {
1558:   const toast = useToast();
1559:   const { busy, run } = useAction();
1560:   const f = useFormState({
1561:     ar: row?.ar ?? '', en: row?.en ?? '', slug: row?.slug ?? '', sort: row?.sort ?? 0,
1562:     active: row?.active ?? true, descAr: (row as BrandRow & { descAr?: string } | null)?.descAr ?? '', descEn: (row as BrandRow & { descEn?: string } | null)?.descEn ?? '',
1563:   });
1564:   const [logoFile, setLogoFile] = useState<File | null>(null);
1565:   const [removeLogo, setRemoveLogo] = useState(false);
1566:   useEffect(() => {
1567:     if (!logoFile) return;
1568:     const url = URL.createObjectURL(logoFile);
1569:     setLogoPreview(url);
1570:     return () => URL.revokeObjectURL(url);
1571:   }, [logoFile]);
1572:   const [logoPreview, setLogoPreview] = useState<string | null>(typeof row?.logo === 'string' && /^(https?:\/\/|\/)/.test(row.logo) ? row.logo : null);
1573:   const onFile = (file: File | null) => {
1574:     if (!file) return;
1575:     if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type)) return toast('نوع الملف غير مدعوم', 'red');
1576:     if (file.size > 4 * 1024 * 1024) return toast('الملف أكبر من 4MB', 'red');
1577:     setLogoFile(file);
1578:     setRemoveLogo(false);
1579:   };
1580:   const save = async () => {
1581:     if (!f.v.ar.trim() || !f.v.en.trim()) return toast('الاسم العربي والإنجليزي مطلوبان', 'red');
1582:     const body: any = {
1583:       name_ar: f.v.ar, name_en: f.v.en, slug: (f.v.slug as string) || null,
1584:       description_ar: (f.v.descAr as string) || null, description_en: (f.v.descEn as string) || null,
1585:       sort_order: Number(f.v.sort || 0), is_active: !!f.v.active, logo: logoFile, remove_logo: removeLogo,
1586:     };
1587:     const r = await run(() => row ? brandsApi.update(row.id, body) : brandsApi.create(body), { toast, success: 'تم الحفظ', onFieldErrors: (e) => f.setErrors(mapErrors(e, { name_ar: 'ar', name_en: 'en', sort_order: 'sort' })) });
1588:     if (r) { onSaved(); onClose(); }
1589:   };
1590:   return (
1591:     <Modal open onClose={onClose} title={row ? 'تعديل براند' : 'براند جديد'} icon="star" width={620}
1592:       footer={<><button className="btn btn-soft" onClick={onClose}>إلغاء</button><button className="btn btn-dark" disabled={busy} onClick={save}>حفظ</button></>}>
1593:       <div className="space-y-4">
1594:         <div className="flex items-start gap-4">
1595:           <div className="shrink-0 text-center">
1596:             {logoPreview ? (
1597:               <div className="relative">
1598:                 <img src={logoPreview ?? String(row?.logo)} alt="" className="w-[88px] h-[88px] rounded-[20px] object-cover" />
1599:                 <button className="btn btn-danger btn-xs mt-2 w-full" onClick={() => { setLogoFile(null); setLogoPreview(null); setRemoveLogo(true); }}>
1600:                   <Icon name="trash" size={11} /> إزالة الشعار
1601:                 </button>
1602:               </div>
1603:             ) : (
1604:               <label className="w-[88px] h-[88px] rounded-[20px] drop !p-0 flex flex-col items-center justify-center gap-1 cursor-pointer">
1605:                 <input type="file" accept="image/jpeg,image/png,image/webp" className="hidden" onChange={(e) => onFile(e.target.files?.[0] ?? null)} />
1606:                 <Icon name="upload" size={18} className="tx3" />
1607:                 <span className="text-[10.5px] tx3">رفع شعار</span>
1608:               </label>
1609:             )}
1610:             <div className="text-[10px] tx3 mt-1.5 leading-tight num">JPG · PNG · WebP<br />حتى 4MB</div>
1611:           </div>
1612:           <div className="flex-1 grid grid-cols-1 gap-3">
1613:             <Field label="الاسم العربي" req hint="حتى 150 حرفًا" err={f.errors.ar}><input className="inp" maxLength={150} value={f.v.ar} onChange={f.on('ar')} /></Field>
1614:             <Field label="الاسم الإنجليزي" req hint="حتى 150 حرفًا" err={f.errors.en}><input className="inp num" dir="ltr" maxLength={150} value={f.v.en} onChange={f.on('en' as any)} /></Field>
1615:           </div>
1616:         </div>
1617:         <div className="grid grid-cols-2 gap-3">
1618:           <Field label="slug" hint="اختياري" err={f.errors.slug}><input className="inp num" dir="ltr" value={f.v.slug} onChange={f.on('slug' as any)} placeholder="auto-generated" /></Field>
1619:           <Field label="ترتيب العرض" err={f.errors.sort}><input className="inp num" type="number" value={f.v.sort} onChange={f.on('sort' as any)} /></Field>
1620:         </div>
1621:         <div className="grid grid-cols-2 gap-3">
1622:           <TextArea label="الوصف العربي" value={f.v.descAr} onChange={(v) => f.set('descAr', v)} />
1623:           <Field label="الوصف الإنجليزي"><textarea className="inp num" dir="ltr" value={f.v.descEn} onChange={f.on('descEn' as any)} /></Field>
1624:         </div>
1625:         <ToggleRow label="مفعّل" on={f.v.active} onChange={(v) => f.set('active', v)} />
1626:       </div>
1627:     </Modal>
1628:   );
1629: }
