1631: export function BrandsPage() {
1632:   const toast = useToast();
1633:   const { run } = useAction();
1634:   const [page, setPage] = useState(1);
1635:   const [form, setForm] = useState<BrandRow | { id?: any; logo?: any; ar?: string; en?: string; slug?: string; sort?: number; active?: boolean; products?: number } | null>(null);
1636:   const [del, setDel] = useState<BrandRow | null>(null);
1637:   const [blocked, setBlocked] = useState<BrandRow | null>(null);
1638:   const [brandTotal, setBrandTotal] = useState(0);
1639:   const list = useRemote((s) => brandsApi.list({ per_page: 20, page }, s).then((p) => { setBrandTotal(p.meta?.total ?? p.data.length); return p.data.map((b: any) => ({
1640:     id: b.id, ar: b.name_ar, en: b.name_en, slug: b.slug, logo: b.logo_url, sort: b.sort_order, active: b.is_active, products: b.all_products_count ?? b.products_count ?? 0, descAr: b.description_ar ?? '', descEn: b.description_en ?? '',
1641:   }) as BrandRow); }), [page], { mock: () => BRANDS });
1642: 
1643:   return (
1644:     <div className="space-y-5">
1645:       <PageHead
1646:         title="البراندات"
1647:         sub="العلامات التجارية المعروضة في المتجر وترتيب ظهورها."
1648:         actions={
1649:           <button className="btn btn-dark" onClick={() => list.usingMock ? toast('البيانات تجريبية — لا يمكن الحفظ', 'red') : setForm({})}>
1650:             <Icon name="plus" size={14} />
1651:             براند جديد
1652:           </button>
1653:         }
1654:       />
1655:       <RemoteFeedback state={list} />
1656:       {blocked && (
1657:         <Note tone="red" icon="ban" className="stg stg-2">
1658:           لا يمكن حذف «{blocked.ar}» لأنه مرتبط بـ <Num>{blocked.products}</Num> منتجًا. انقل المنتجات لبراند آخر أو عطّل البراند بدلًا من حذفه.
1659:         </Note>
1660:       )}
1661:       <Card stg={2}>
1662:         <DataTable
1663:           rows={list.data ?? []}
1664:           foot={<Pager total={list.usingMock ? BRANDS.length : brandTotal} per={20} page={page} onPage={setPage} />}
1665:           onRow={(row) => list.usingMock ? toast('البيانات تجريبية — لا يمكن التعديل', 'red') : setForm(row)}
1666:           cols={[
1667:             {
1668:               h: 'الشعار',
1669:               w: 64,
1670:               r: (b: BrandRow) =>
1671:                 b.logo ? (
1672:                   <span
1673:                     className="w-10 h-10 rounded-[12px] flex items-center justify-center text-white font-display font-bold"
1674:                     style={{ background: /^(https?:\/\/|\/)/.test(b.logo) ? `url("${b.logo}") center / cover` : b.logo }}
1675:                   >
1676:                     {!/^(https?:\/\/|\/)/.test(b.logo) && b.en[0]}
1677:                   </span>
1678:                 ) : (
1679:                   <span className="w-10 h-10 rounded-[12px] v-sub flex items-center justify-center tx3">
1680:                     <Icon name="image" size={15} />
1681:                   </span>
1682:                 ),
1683:             },
1684:             { h: 'الاسم العربي', r: (b: BrandRow) => <span className="font-semibold tx1">{b.ar}</span> },
1685:             { h: 'الاسم الإنجليزي', r: (b: BrandRow) => <span className="num tx2 ltr">{b.en}</span> },
1686:             {
1687:               h: 'الرابط المختصر',
1688:               r: (b: BrandRow) =>
1689:                 b.slug ? (
1690:                   <span className="num text-[11.5px] v-sub px-2 py-1 rounded-md tx2 ltr">/{b.slug}</span>
1691:                 ) : (
1692:                   <span className="tx3 text-[11.5px]">يُولّد تلقائيًا</span>
1693:                 ),
1694:             },
1695:             {
1696:               h: 'الترتيب',
1697:               align: 'center',
1698:               r: (b: BrandRow) => <Num className="font-semibold">{b.sort}</Num>,
1699:             },
1700:             { h: 'التفعيل', r: (b: BrandRow) => <ActiveDot on={b.active} /> },
1701:             {
1702:               h: '',
1703:               r: (b: BrandRow) => (
1704:                 <RowActions>
1705:                   <button className="icon-btn !w-7 !h-7" onClick={() => list.usingMock ? toast('البيانات تجريبية — لا يمكن التعديل', 'red') : setForm(b)}>
1706:                     <Icon name="edit" size={13} />
1707:                   </button>
1708:                   <button className="icon-btn !w-7 !h-7" onClick={() => list.usingMock ? toast('البيانات تجريبية — لا يمكن الحذف', 'red') : setDel(b)}>
1709:                     <Icon name="trash" size={13} />
1710:                   </button>
1711:                 </RowActions>
1712:               ),
1713:             },
1714:           ]}
1715:         />
1716:       </Card>
1717:       {form && (
1718:         <BrandForm row={form.id ? (form as BrandRow) : null} onClose={() => setForm(null)} onSaved={() => list.reload()} />
1719:       )}
1720:       <ConfirmModal
1721:         open={!!del}
1722:         onClose={() => setDel(null)}
1723:         danger
1724:         title={'حذف «' + (del?.ar || '') + '»'}
1725:         cta="حذف"
1726:         text="سيُحذف البراند نهائيًا. سيرفض النظام الحذف إن كان مرتبطًا بمنتجات."
1727:         onConfirm={async () => {
1728:           if (!del) return false;
1729:           const r = await run(async () => {
1730:             try { return await brandsApi.remove(del.id); }
1731:             catch (error) {
1732:               const parsed = parseApiError(error);
1733:               if (/منتج|product/i.test(parsed.message)) setBlocked(del);
1734:               throw error;
1735:             }
1736:           }, { toast, success: 'تم الحذف' });
1737:           if (r) { setDel(null); list.reload(); }
1738:           return !!r;
1739:         }}
1740:       />
1741:     </div>
1742:   );
1743: }  1: /* ============ Status maps + mock data (Vortix Admin) ============ */
