  63: export const mapShift = (s: PosShift): ShiftRow => ({ id: s.id, no: s.shift_number, cashier: s.cashier?.name ?? '', branch: s.branch?.name ?? '', tr: s.treasury_id, open: s.opened_at, close: s.closed_at, status: s.status === 'closed_pending_approval' ? 'closed' : s.status, exp: s.expected_closing_cash === null ? null : num(s.expected_closing_cash), act: s.actual_closing_cash === null ? null : num(s.actual_closing_cash) });
  64: const quoteStatus = (s: string) => s === 'priced_by_admin' ? 'priced' : s === 'converted_to_order' ? 'converted' : s;
  65: export const mapQuote = (q: Quotation): QuoteRow => ({ id: q.id, no: q.quotation_number, company: q.customer?.company_name || q.customer?.name || '—', cust: q.customer?.name ?? '', status: quoteStatus(q.status), total: q.status === 'draft' || q.status === 'requested' ? null : num(q.grand_total), valid: q.valid_until, date: q.created_at.slice(0, 10), order: q.converted_order_id ? `#${q.converted_order_id}` : undefined });
  66: export const mapNotice = (n: PaymentNotice): PaymentNoticeRow => ({ id: n.id, no: n.notice_number, company: n.customer?.company_name || n.customer?.name || '—', cust: n.customer?.name ?? '', amount: num(n.amount), method: n.payment_method === 'bank_transfer' ? 'bank' : n.payment_method, status: n.status === 'pending_review' ? 'pending' : n.status, date: n.transfer_date ?? n.created_at.slice(0, 10), bank: n.bank_name ?? '', ref: n.reference_number ?? '', file: n.has_receipt, order: n.order_number ?? null, tr: n.treasury_id ?? undefined, review: n.admin_notes ?? undefined });
  67: 
  68: async function allPages<T>(request: (page: number) => Promise<Paginated<T>>): Promise<T[]> {
  69:   const first = await request(1);
  70:   const rows = [...first.data];
  71:   for (let page = 2; page <= first.meta.last_page; page++) rows.push(...(await request(page)).data);
  72:   return rows;
  73: }
  74: 
  75: function RemoteNote({ remote }: { remote: { loading: boolean; error: { message: string } | null; usingMock: boolean; reload: () => void } }) {
  76:   if (remote.usingMock && !USE_MOCK) return <Note tone="red">تعذّر الاتصال بالخادم؛ البيانات المعروضة تجريبية.</Note>;
  77:   if (remote.error) return <><Empty icon="alert" title={remote.error.message} /><button className="btn btn-soft" onClick={remote.reload}>إعادة المحاولة</button></>;
  78:   if (remote.loading) return <Note>جارٍ التحميل…</Note>;
  79:   return null;
  80: }
