  82: /* ---------------- FINANCE PAGE ---------------- */
  83: export function FinancePage({ sub = 'tr', can = () => true }: { sub?: string; can?: (permission: string) => boolean }) {
  84:   const [tab, setTab] = useState(sub);
  85:   useEffect(() => setTab(sub), [sub]);
  86:   const tabs = [
  87:     { value: 'tr', label: 'الخزائن', icon: 'vault', permission: 'treasuries.view' },
  88:     { value: 'exp', label: 'المصروفات', icon: 'receipt', permission: 'expenses.view' },
  89:     { value: 'trf', label: 'تحويلات الخزائن', icon: 'swap', permission: 'treasury_transfers.view' },
  90:   ].filter(t => can(t.permission));
  91:   const activeTab = tabs.some(t => t.value === tab) ? tab : tabs[0]?.value;
  92: 
  93:   return (
  94:     <div className="space-y-5">
  95:       <PageHead title="المالية" sub="الخزائن والمصروفات وتحويلات النقدية بين الخزائن." />
  96:       <TabsBar
  97:         value={activeTab}
  98:         onChange={(v: any) => setTab(v)}
  99:         tabs={tabs}
 100:       />
 101:       {activeTab === 'tr' && <TreasuriesTab />}
 102:       {activeTab === 'exp' && <ExpensesTab can={can} />}
 103:       {activeTab === 'trf' && <TransfersTab />}
 104:     </div>
 105:   );
 106: }
