 108: export function ExpenseForm({ onClose, onSaved }: { onClose: () => void; onSaved: () => void }) {
 109:   const toast = useToast();
 110:   const { busy, run } = useAction();
 111:   const f = useFormState({ branchId: '', treasuryId: '', category: '', amount: '', date: today(), notes: '' });
 112:   const [idemKey, setIdemKey] = useState(() => newIdempotencyKey());
 113:   const treasures = useRemote((s) => allPages((page) => treasuriesApi.list({ page, per_page: 100, is_active: true }, s)), []);
 114:   const branches = useRemote((s) => allPages((page) => opsApi.get('/api/v1/admin/branches', { params: { page, per_page: 100 }, signal: s }).then((r) => asPage<{ id: number; name: string }>(r))), []);
 115:   const selectedTreasury = treasures.data?.find((t) => t.id === Number(f.v.treasuryId));
 116:   const categories = ['نظافة', 'صيانة', 'نقل وتحميل', 'إيجار', 'ضيافة', 'أدوات مكتبية', 'أخرى'];
 117:   const save = async () => {
 118:     if (!f.v.branchId || !f.v.treasuryId || !f.v.category || !f.v.amount) return toast('أكمل الحقول المطلوبة', 'red');
 119:     const r = await run(() => expensesApi.create({
 120:       branch_id: Number(f.v.branchId),
 121:       treasury_id: Number(f.v.treasuryId), category: f.v.category, amount: Number(f.v.amount),
 122:       expense_date: f.v.date, notes: f.v.notes || null,
 123:     }, idemKey), { toast, success: 'تم تسجيل سند الصرف', onFieldErrors: (e) => f.setErrors(e as any) });
 124:     if (r) { setIdemKey(newIdempotencyKey()); onSaved(); onClose(); }
 125:   };
 126:   return (
 127:     <Modal open onClose={onClose} title="سند صرف مصروفات" icon="receipt" width={560}
 128:       footer={<><button className="btn btn-soft" onClick={onClose}>إلغاء</button><button className="btn btn-dark" disabled={busy} onClick={save}>تسجيل الصرف</button></>}>
 129:       <div className="space-y-4">
 130:         <RemoteNote remote={treasures} />
 131:         <RemoteNote remote={branches} />
 132:         <div className="grid grid-cols-2 gap-3">
 133:           <Field label="الفرع" req err={f.errors.branch_id}>
 134:             <select className="inp" value={f.v.branchId} onChange={f.on('branchId')}>
 135:               <option value="">اختر الفرع</option>
 136:               {(branches.data ?? []).map((b) => <option key={b.id} value={b.id}>{b.name}</option>)}
 137:             </select>
 138:           </Field>
 139:           <Field label="الخزينة المنصرف منها" req err={f.errors.treasury_id}>
 140:             <select className="inp" value={f.v.treasuryId} onChange={f.on('treasuryId' as any)}>
 141:               <option value="">اختر الخزينة</option>
 142:               {(treasures.data ?? []).map((t: { id: number; name: string }) => (<option key={t.id} value={String(t.id)}>{t.name}</option>))}
 143:             </select>
 144:           </Field>
 145:           <Field label="تصنيف المصروف" req err={f.errors.category}>
 146:             <select className="inp" value={f.v.category} onChange={f.on('category' as any)}>
 147:               <option value="">اختر التصنيف</option>
 148:               {categories.map((c) => (<option key={c} value={c}>{c}</option>))}
 149:             </select>
 150:           </Field>
 151:           <Field label="المبلغ (EGP)" req err={f.errors.amount} hint={selectedTreasury && Number(f.v.amount) > num(selectedTreasury.current_balance) ? 'المبلغ أكبر من رصيد الخزينة' : undefined}>
 152:             <input type="number" step="0.01" min="0.01" className="inp num" value={f.v.amount} onChange={f.on('amount' as any)} />
 153:           </Field>
 154:         </div>
 155:         <Field label="التاريخ" req err={f.errors.expense_date}>
 156:           <input type="date" className="inp" value={f.v.date} onChange={f.on('date' as any)} />
 157:         </Field>
 158:         <TextArea label="البيان / الملاحظات" req value={f.v.notes} onChange={(v) => f.set('notes', v)} />
 159:       </div>
 160:     </Modal>
 161:   );
 162: }
