 164: const treasuryToUI = (t: string): TreasuryRow['type'] => t === 'main_safe' ? 'main' : t === 'pos_drawer' ? 'drawer' : t === 'bank_account' ? 'bank' : 'main';
 165: const treasuryToBackend = (t: string): TreasuryType => (t === 'main' ? 'main_safe' : t === 'drawer' ? 'pos_drawer' : t === 'bank' ? 'bank_account' : t) as TreasuryType;
