 167: export function TreasuryForm({ row, onClose, onSaved }: { row: any; onClose: () => void; onSaved: () => void }) {
 168:   const toast = useToast();
 169:   const { busy, run } = useAction();
 170:   const f = useFormState({ name: row?.name ?? '', code: row?.code ?? '', type: row?.type ?? 'main', branchId: String(row?.branchId ?? ''), active: row?.active ?? true });
 171:   const branches = useRemote((s) => allPages((page) => opsApi.get('/api/v1/admin/branches', { params: { page, per_page: 100 }, signal: s }).then((r) => asPage<{ id: number; name: string }>(r))), []);
 172:   const save = async () => {
 173:     if (!f.v.name.trim()) return toast('اسم الخزينة مطلوب', 'red');
 174:     const body: any = {
 175:       name: f.v.name, code: f.v.code, type: treasuryToBackend(f.v.type),
 176:       branch_id: (f.v.branchId as string) ? Number(f.v.branchId) : null,
 177:       is_active: !!f.v.active,
 178:     };
 179:     const r = await run(() => (row ? treasuriesApi.update(row.id, body) : treasuriesApi.create(body)),
 180:       { toast, success: 'تم الحفظ', onFieldErrors: (e) => f.setErrors(mapErrors(e, { branch_id: 'branchId' })) });
 181:     if (r) { onSaved(); onClose(); }
 182:   };
 183:   return (
 184:     <Modal open onClose={onClose} title={row ? 'تعديل خزينة' : 'خزينة جديدة'} icon="vault" width={600}
 185:       footer={<><button className="btn btn-soft" onClick={onClose}>إلغاء</button><button className="btn btn-dark" disabled={busy} onClick={save}>حفظ</button></>}>
 186:       <div className="space-y-4">
 187:         <div className="grid grid-cols-2 gap-3">
 188:           <Field label="اسم الخزينة" req err={f.errors.name}><input className="inp" value={f.v.name} onChange={f.on('name')} /></Field>
 189:           <Field label="الكود" req err={f.errors.code}><input className="inp" value={f.v.code} onChange={f.on('code')} /></Field>
 190:           <Field label="النوع" req err={f.errors.type}>
 191:             <select className="inp" disabled={!!row} value={f.v.type} onChange={f.on('type' as any)}>
 192:               {Object.entries(TREASURY_TYPES).map(([k, l]) => (<option key={k} value={k}>{l as string}</option>))}
 193:             </select>
 194:           </Field>
 195:         </div>
 196:         <Field label="الفرع" hint="فارغ للخزائن المركزية" err={f.errors.branchId}>
 197:           <select className="inp" value={f.v.branchId} onChange={f.on('branchId' as any)}>
 198:             <option value="">خزينة مركزية</option>
 199:             {(branches.data ?? []).map((b: { id: number; name: string }) => (<option key={b.id} value={String(b.id)}>{b.name}</option>))}
 200:           </select>
 201:         </Field>
 202:         {!row && (<Field label="الرصيد الافتتاحي" hint="يُسجَّل الرصيد عبر تحويل أو إيراد"><input type="number" step="0.01" className="inp num" value={0} readOnly /></Field>)}
 203:         <ToggleRow label="مفعّلة" on={f.v.active} onChange={(v) => f.set('active', v)} />
 204:       </div>
 205:     </Modal>
 206:   );
 207: }
