 382:   const [voidReason, setVoidReason] = useState('');
 383: 
 384:   const categories = ['نظافة', 'صيانة', 'نقل وتحميل', 'إيجار', 'ضيافة', 'أدوات مكتبية', 'أخرى'];
 385:   const [page, setPage] = useState(1);
 386:   useEffect(() => setPage(1), [br, tr, cat]);
 387:   const list = useRemote((s) => expensesApi.list({ page, per_page: 20, branch_id: br || undefined, treasury_id: tr || undefined, category: cat || undefined }, s).then((p) => ({ ...p, data: p.data.map(mapExpense) })), [page, br, tr, cat], { mock: () => mockPage(EXPENSES) });
 388:   const treasures = useRemote((s) => allPages((page) => treasuriesApi.list({ page, per_page: 100 }, s)), []);
 389:   const branches = useRemote((s) => allPages((page) => opsApi.get('/api/v1/admin/branches', { params: { page, per_page: 100 }, signal: s }).then((r) => asPage<{ id: number; name: string }>(r))), []);
 390:   const rows = list.data?.data ?? [];
 391:   const activeRows = rows.filter(e => !e.voidedAt);
 392:   const largest = [...activeRows].sort((a, b) => b.amount - a.amount)[0];
 393:   const nameOf = (id: number) => treasures.data?.find((t) => t.id === id)?.name ?? (USE_MOCK ? trName(id) : `#${id}`);
 394:   const total = activeRows.reduce((a, e) => a + e.amount, 0);
 395: 
 396:   return (
