 403:           value={<span className="ltr">{fmtNum(total, 0)}</span>}
 404:           small
 405:           foot="EGP"
 406:         />
 407:         <KPI label="عدد سندات الصرف" icon="file" value={rows.length} foot="سند مسجّل" />
 408:         <KPI label="أعلى بند صرف" icon="tag" value={largest?.cat ?? '—'} foot={largest ? fmtMoney(largest.amount) : '—'} />
 409:       </div>
 410:       <Card stg={3}>
 411:         <div className="flex flex-wrap items-center justify-between gap-2 mb-4">
 412:           <div className="flex flex-wrap gap-2">
 413:             <FSelect value={br} onChange={setBr} placeholder="الفرع" options={(branches.data ?? []).map((b: { id: number; name: string }) => ({ value: String(b.id), label: b.name }))} />
 414:             <FSelect
 415:               value={tr}
 416:               onChange={setTr}
 417:               placeholder="الخزينة"
 418:               options={(treasures.data ?? []).map((t: { id: number; name: string }) => ({ value: String(t.id), label: t.name }))}
 419:             />
 420:             <FSelect value={cat} onChange={setCat} placeholder="التصنيف" options={categories} />
 421:           </div>
 422:           <button className="btn btn-dark btn-sm" onClick={() => setForm(true)}>
 423:             <Icon name="plus" size={13} />
 424:             سند صرف
