 432:             { h: 'الحالة', r: (e: ExpenseRow) => <Badge tone={e.voidedAt ? 'red' : 'green'}>{e.voidedAt ? 'ملغى' : 'مسجّل'}</Badge> },
 433:             { h: 'الفرع', r: (e: ExpenseRow) => <span className="tx2">{e.branch}</span> },
 434:             { h: 'الخزينة', r: (e: ExpenseRow) => <span className="text-[12px]">{nameOf(e.tr)}</span> },
 435:             {
 436:               h: 'التصنيف',
 437:               r: (e: ExpenseRow) => (
 438:                 <Badge dot={false} tone="gray">
 439:                   {e.cat}
 440:                 </Badge>
 441:               ),
 442:             },
 443:             {
 444:               h: 'المبلغ',
 445:               r: (e: ExpenseRow) => <span className="font-semibold c-red">{fmtMoney(e.amount)}</span>,
 446:             },
 447:             { h: 'التاريخ', r: (e: ExpenseRow) => <Num className="tx2">{e.date}</Num> },
 448:             {
 449:               h: 'بواسطة',
 450:               r: (e: ExpenseRow) => (
 451:                 <div className="flex items-center gap-1.5 text-[12px]">
 452:                   <Avatar name={e.by} tone={e.id} size={22} />
 453:                   <span>{e.by}</span>
 454:                 </div>
 455:               ),
 456:             },
 457:             {
 458:               h: 'الوردية',
 459:               r: (e: ExpenseRow) => (e.shift ? <Num className="tx3 text-[11px]">{e.shift}</Num> : <span className="tx3">—</span>),
 460:             },
 461:             {
 462:               h: 'ملاحظات',
 463:               r: (e: ExpenseRow) => <span className="text-[11.5px] tx2 clamp1">{e.voidReason || e.notes || '—'}</span>,
 464:             },
 465:             { h: '', r: (e: ExpenseRow) => !e.voidedAt && !e.shift && can('expenses.delete') ? <button className="btn btn-soft btn-sm" onClick={() => { setVoiding(e); setVoidReason(''); }}>إلغاء المصروف</button> : null },
 466:           ]}
 467:         />
 468:         <Pager total={list.data?.meta.total ?? 0} page={page} per={20} onPage={setPage} />
 469:       </Card>
 470:       {form && (
 471:         <ExpenseForm onClose={() => setForm(false)} onSaved={() => { list.reload(); treasures.reload(); }} />
 472:       )}
 473:       {voiding && <Modal open title={`إلغاء المصروف ${voiding.no}`} onClose={() => { if (!busy) setVoiding(null); }}
 474:         footer={<button className="btn btn-dark" disabled={busy || !voidReason.trim()} onClick={async () => {
 475:           if (list.usingMock) return toast('البيانات المعروضة تجريبية — لم يتم الحفظ', 'red');
 476:           const result = await run(() => expensesApi.void(voiding.id, voidReason.trim()), { toast, success: 'تم إلغاء المصروف وعكس أثره على الخزينة' });
 477:           if (result) { setVoiding(null); list.reload(); treasures.reload(); }
 478:         }}>تأكيد الإلغاء</button>}>
 479:         <Note>يُحفظ السند في سجل التدقيق ويُعاد المبلغ إلى الخزينة.</Note>
 480:         <TextArea label="سبب الإلغاء" req value={voidReason} onChange={setVoidReason} />
 481:       </Modal>}
 482:     </>
 483:   );
 484: }
