 486: export function TransfersTab() {
 487:   const toast = useToast();
 488:   const { busy, run } = useAction();
 489:   const [st, setSt] = useState('');
 490:   const [tr, setTr] = useState('');
 491:   const [view, setView] = useState<any>(null);
 492:   const [form, setForm] = useState(false);
 493:   const [src, setSrc] = useState('');
 494:   const [idemKey, setIdemKey] = useState(() => newIdempotencyKey());
 495:   const [dst, setDst] = useState('');
 496:   const [amount, setAmount] = useState('');
 497:   const [notes, setNotes] = useState('');
 498:   const [errors, setErrors] = useState<Record<string, string>>({});
 499: 
 500:   const [page, setPage] = useState(1);
 501:   useEffect(() => setPage(1), [st, tr]);
 502:   const list = useRemote(async (s) => {
 503:     // The server supports separate source/destination filters, not an OR filter.
 504:     const result = tr
 505:       ? mockPage((await allPages((page) => treasuryTransfersApi.list({ page, per_page: 100, status: st || undefined }, s))).filter((x) => String(x.from_treasury_id) === tr || String(x.to_treasury_id) === tr), page)
 506:       : await treasuryTransfersApi.list({ page, per_page: 20, status: st || undefined }, s);
 507:     return { ...result, data: result.data.map((x): TreasuryTransfer => ({
 508:       id: x.id, from: x.from_treasury_id, to: x.to_treasury_id, amount: num(x.amount),
 509:       status: x.status, date: (x.created_at ?? '').slice(0, 10), by: x.creator?.name ?? '', appr: x.approver?.name ?? null, notes: x.notes,
 510:     })) };
 511:   }, [page, st, tr], { mock: () => mockPage(TRANSFERS.filter((x) => (!st || x.status === st) && (!tr || String(x.from) === tr || String(x.to) === tr)), page) });
 512:   const treasures = useRemote((s) => allPages((page) => treasuriesApi.list({ page, per_page: 100 }, s)), []);
 513:   const nameOf = (id: number) => (treasures.data ?? []).find((t) => t.id === id)?.name ?? (USE_MOCK ? trName(id) : `#${id}`);
 514:   const rows = (list.data?.data ?? []).filter(
 515:     (x) => (!st || x.status === st) && (!tr || String(x.from) === tr || String(x.to) === tr)
 516:   );
 517:   const approve = async (id: number) => {
 518:     if (list.usingMock) return toast('البيانات المعروضة تجريبية — لم يتم الحفظ', 'red');
 519:     const r = await run(() => treasuryTransfersApi.approve(id), { toast, success: 'تم اعتماد التحويل' });
 520:     if (r) { setView(null); list.reload(); treasures.reload(); }
 521:   };
 522:   const reject = async (id: number) => {
 523:     if (list.usingMock) return toast('البيانات المعروضة تجريبية — لم يتم الحفظ', 'red');
 524:     const r = await run(() => treasuryTransfersApi.reject(id), { toast, success: 'تم رفض التحويل' });
 525:     if (r) { setView(null); list.reload(); treasures.reload(); }
 526:   };
 527:   const create = async () => {
 528:     if (!src || !dst || src === dst) return toast('اختر مصدرًا ووجهة مختلفين', 'red');
 529:     if (!amount || Number(amount) <= 0) return toast('أدخل مبلغًا صحيحًا', 'red');
 530:     const r = await run(() => treasuryTransfersApi.create({
 531:       from_treasury_id: Number(src), to_treasury_id: Number(dst), amount: Number(amount), notes: notes || null,
 532:     }, idemKey), { toast, success: 'أُرسل طلب التحويل', onFieldErrors: setErrors });
 533:     if (r) { setIdemKey(newIdempotencyKey()); setForm(false); setSrc(''); setDst(''); setAmount(''); setNotes(''); list.reload(); treasures.reload(); }
 534:   };
 535: 
 536:   return (
 537:     <>
 538:       <Card stg={3}>
 539:         <div className="flex flex-wrap items-center justify-between gap-2 mb-4">
 540:           <div className="flex flex-wrap gap-2">
 541:             <FSelect
 542:               value={st}
 543:               onChange={setSt}
 544:               placeholder="الحالة"
 545:               options={Object.entries(TRANSFER_STATUS).map(([v, s]) => ({ value: v, label: s.label }))}
 546:             />
 547:             <FSelect
 548:               value={tr}
 549:               onChange={setTr}
 550:               placeholder="الخزينة (مصدر أو وجهة)"
 551:               options={(treasures.data ?? []).map((t: { id: number; name: string }) => ({ value: String(t.id), label: t.name }))}
 552:             />
 553:           </div>
 554:           <button className="btn btn-dark btn-sm" onClick={() => setForm(true)}>
 555:             <Icon name="plus" size={13} />
 556:             طلب تحويل
 557:           </button>
 558:         </div>
 559:         <RemoteNote remote={list} />
 560:         <DataTable
 561:           rows={rows}
 562:           onRow={list.usingMock ? undefined : setView}
 563:           cols={[
 564:             {
 565:               h: 'المصدر',
 566:               r: (x: TreasuryTransfer) => <span className="font-semibold tx1">{nameOf(x.from)}</span>,
 567:             },
 568:             {
 569:               h: 'الوجهة',
 570:               r: (x: TreasuryTransfer) => <span className="font-semibold tx1">{nameOf(x.to)}</span>,
 571:             },
 572:             {
 573:               h: 'المبلغ',
 574:               r: (x: TreasuryTransfer) => <span className="font-display font-bold text-[14px]">{fmtMoney(x.amount)}</span>,
 575:             },
 576:             { h: 'الحالة', r: (x: TreasuryTransfer) => <StatusBadge map={TRANSFER_STATUS} value={x.status} /> },
 577:             { h: 'التاريخ', r: (x: TreasuryTransfer) => <Num className="tx2">{x.date}</Num> },
 578:             { h: 'المنشئ', r: (x: TreasuryTransfer) => <span className="text-[12px] tx2">{x.by}</span> },
 579:             {
 580:               h: 'المعتمد',
 581:               r: (x: TreasuryTransfer) => (x.appr ? <span className="text-[12px] tx2">{x.appr}</span> : <span className="tx3">—</span>),
 582:             },
 583:             {
 584:               h: '',
 585:               r: (x: TreasuryTransfer) =>
 586:                 x.status === 'pending' && (
 587:                   <RowActions>
 588:                     <button className="btn btn-danger btn-xs" disabled={busy} onClick={() => reject(x.id)}>
 589:                       رفض
 590:                     </button>
 591:                     <button className="btn btn-success btn-xs" disabled={busy} onClick={() => approve(x.id)}>
 592:                       اعتماد
 593:                     </button>
 594:                   </RowActions>
 595:                 ),
 596:             },
 597:           ]}
 598:         />
 599:         <Pager total={list.data?.meta.total ?? 0} page={page} per={20} onPage={setPage} />
 600:       </Card>
 601:       {view && (
 602:         <Modal
 603:           open
 604:           onClose={() => setView(null)}
 605:           title="طلب تحويل"
 606:           icon="swap"
 607:           width={520}
 608:           footer={
 609:             view.status === 'pending' && (
 610:               <>
 611:                 <button
 612:                   className="btn btn-danger"
 613:                   disabled={busy}
 614:                   onClick={() => reject(view.id)}
 615:                 >
 616:                   رفض
 617:                 </button>
 618:                 <button
 619:                   className="btn btn-dark"
 620:                   disabled={busy}
 621:                   onClick={() => approve(view.id)}
 622:                 >
 623:                   اعتماد
 624:                 </button>
 625:               </>
 626:             )
 627:           }
 628:         >
 629:           <div className="space-y-4 pb-2">
 630:             <div className="grid grid-cols-[1fr_auto_1fr] items-center gap-3">
 631:               <div className="v-sub p-3 text-center">
 632:                 <div className="text-[11px] tx3 mb-1">من</div>
 633:                 <div className="font-semibold text-[12.5px]">{nameOf(view.from)}</div>
 634:               </div>
 635:               <span className="w-9 h-9 rounded-full btn-accent flex items-center justify-center">
 636:                 <Icon name="arrowL" size={15} />
 637:               </span>
 638:               <div className="v-sub p-3 text-center">
 639:                 <div className="text-[11px] tx3 mb-1">إلى</div>
 640:                 <div className="font-semibold text-[12.5px]">{nameOf(view.to)}</div>
 641:               </div>
 642:             </div>
 643:             <div className="text-center">
 644:               <div className="font-display text-[28px] font-bold">{fmtMoney(view.amount)}</div>
 645:               <div className="mt-1">
 646:                 <StatusBadge map={TRANSFER_STATUS} value={view.status} />
 647:               </div>
 648:             </div>
 649:             <KV
 650:               items={[
 651:                 ['المنشئ', view.by],
 652:                 ['المعتمد', view.appr],
 653:                 ['التاريخ', <Num>{view.date}</Num>],
 654:                 ['ملاحظات', view.notes],
 655:               ]}
 656:             />
 657:           </div>
 658:         </Modal>
 659:       )}
 660:       <Modal
 661:         open={form}
 662:         onClose={() => setForm(false)}
 663:         title="طلب تحويل بين خزائن"
 664:         icon="swap"
 665:         width={520}
 666:         sub="يُنشأ بحالة «بانتظار الاعتماد» ولا يمكن تعديله بعد ذلك."
 667:         footer={
 668:           <>
 669:             <button className="btn btn-soft" onClick={() => setForm(false)}>
 670:               إلغاء
 671:             </button>
 672:             <button
 673:               className="btn btn-dark"
 674:               disabled={!src || !dst || src === dst || busy}
 675:               onClick={create}
 676:             >
 677:               إنشاء الطلب
 678:             </button>
 679:           </>
 680:         }
 681:       >
 682:         <div className="space-y-4">
 683:           <div className="grid grid-cols-2 gap-3">
 684:             <Field label="الخزينة المصدر" req err={errors.from_treasury_id}>
 685:               <select className="inp" value={src} onChange={(e) => setSrc(e.target.value)}>
 686:                 <option value="">اختر</option>
 687:                 {(treasures.data ?? []).map((x: { id: number; name: string }) => (
 688:                   <option key={x.id} value={x.id}>
 689:                     {x.name}
 690:                   </option>
 691:                 ))}
 692:               </select>
 693:             </Field>
 694:             <Field label="الخزينة الوجهة" req err={errors.to_treasury_id || (src && src === dst ? 'يجب أن تختلف عن المصدر' : null)}>
 695:               <select
 696:                 className={'inp ' + (src && src === dst ? 'err' : '')}
 697:                 value={dst}
 698:                 onChange={(e) => setDst(e.target.value)}
 699:               >
 700:                 <option value="">اختر</option>
 701:                 {(treasures.data ?? []).map((x: { id: number; name: string }) => (
 702:                   <option key={x.id} value={x.id} disabled={String(x.id) === src}>
 703:                     {x.name}
 704:                   </option>
 705:                 ))}
 706:               </select>
 707:             </Field>
 708:           </div>
 709:           <Field label="المبلغ" req err={errors.amount}>
 710:             <input type="number" step="0.01" min="0.01" className="inp num" value={amount} onChange={(e) => setAmount(e.target.value)} />
 711:           </Field>
 712:           <TextArea label="ملاحظات" value={notes} onChange={setNotes} />
 713:         </div>
 714:       </Modal>
 715:     </>
 716:   );
 717: }
