 720: export function DiffCell({ s }: { s: ShiftRow }) {
 721:   if (s.exp == null) return <span className="tx3">—</span>;
 722:   const d = (s.act ?? 0) - s.exp;
 723:   if (d === 0) return <Badge tone="green" dot={false}>مطابق</Badge>;
 724:   return (
 725:     <span className={'font-semibold ' + (d < 0 ? 'c-red' : 'c-amber')}>
 726:       {d < 0 ? 'عجز ' : 'زيادة '}
 727:       <span className="num ltr">{fmtNum(Math.abs(d))}</span>
 728:     </span>
 729:   );
 730: }
