 732: export function ShiftsPage() {
 733:   const toast = useToast();
 734:   const { busy, run } = useAction();
 735:   const [br, setBr] = useState('');
 736:   const [ca, setCa] = useState('');
 737:   const [st, setSt] = useState('');
 738:   const [from, setFrom] = useState('');
 739:   const [to, setTo] = useState('');
 740:   const [view, setView] = useState<ShiftRow | null>(null);
 741: 
 742:   const [page, setPage] = useState(1);
 743:   useEffect(() => setPage(1), [br, ca, st, from, to]);
 744:   const list = useRemote((s) => shiftsApi.list({ page, per_page: 20, branch_id: br || undefined, user_id: ca || undefined, status: st === 'closed' ? 'closed_pending_approval' : st || undefined, from_date: from || undefined, to_date: to || undefined }, s).then((p) => ({ ...p, data: p.data.map(mapShift) })), [page, br, ca, st, from, to], { mock: () => mockPage(SHIFTS) });
 745:   const branches = useRemote((s) => allPages((page) => opsApi.get('/api/v1/admin/branches', { params: { page, per_page: 100 }, signal: s }).then((r) => asPage<{ id: number; name: string }>(r))), []);
 746:   const cashiers = useRemote((s) => allPages((page) => opsApi.get('/api/v1/admin/users', { params: { page, per_page: 100 }, signal: s }).then((r) => asPage<{id: number; name: string}>(r))), []);
 747:   const treasures = useRemote((s) => allPages((page) => treasuriesApi.list({ page, per_page: 100 }, s)), []);
 748:   const nameOf = (id: number) => treasures.data?.find((t) => t.id === id)?.name ?? (USE_MOCK ? trName(id) : `#${id}`);
 749:   const rows = list.data?.data ?? [];
 750:   const approveShift = async (id: number) => {
 751:     if (list.usingMock) return toast('البيانات المعروضة تجريبية — لم يتم الحفظ', 'red');
 752:     const r = await run(() => shiftsApi.approve(id), { toast, success: 'تم اعتماد الوردية' });
 753:     if (r) { setView(null); list.reload(); }
 754:   };
 755: 
 756:   return (
 757:     <div className="space-y-5">
 758:       <PageHead title="مراجعة الورديات" sub="مطابقة النقدية المتوقعة مع الفعلية واعتماد الورديات المغلقة." />
 759:       <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 stg stg-2">
 760:         <KPI
 761:           hero
 762:           label="بانتظار الاعتماد"
 763:           icon="clock"
 764:           value={rows.filter((s) => s.status === 'closed').length}
 765:           foot="ورديات مغلقة"
 766:         />
 767:         <KPI
 768:           label="ورديات بها فروق"
 769:           icon="alert"
 770:           value={rows.filter((s) => s.exp != null && s.act !== s.exp).length}
 771:           foot="عجز أو زيادة"
 772:         />
 773:         <KPI label="إجمالي الورديات المسجلة" icon="calendar" value={list.data?.meta.total ?? 0} foot="وردية" />
 774:       </div>
 775:       <Card stg={3}>
 776:         <div className="flex flex-wrap gap-2 mb-4">
 777:           <FSelect value={br} onChange={setBr} placeholder="الفرع" options={(branches.data ?? []).map((b) => ({ value: String(b.id), label: b.name }))} />
 778:           <FSelect value={ca} onChange={setCa} placeholder="الكاشير" options={(cashiers.data ?? []).map((c) => ({ value: String(c.id), label: c.name }))} />
 779:           <FSelect
 780:             value={st}
 781:             onChange={setSt}
 782:             placeholder="الحالة"
 783:             options={Object.entries(SHIFT_STATUS).map(([v, s]) => ({ value: v, label: s.label }))}
 784:           />
 785:           <FDate label="من" value={from} onChange={setFrom} />
 786:           <FDate label="إلى" value={to} onChange={setTo} />
 787:         </div>
 788:         <RemoteNote remote={list} />
 789:         <DataTable
 790:           rows={rows}
 791:           onRow={setView}
 792:           cols={[
 793:             { h: 'رقم الوردية', r: (s: ShiftRow) => <span className="num font-semibold tx1">{s.no}</span> },
 794:             {
 795:               h: 'الكاشير / الفرع',
 796:               r: (s: ShiftRow) => (
 797:                 <div className="flex items-center gap-2">
 798:                   <Avatar name={s.cashier} tone={s.id} size={28} />
 799:                   <div className="leading-tight">
 800:                     <div className="font-medium tx1">{s.cashier}</div>
 801:                     <div className="text-[11px] tx3">{s.branch}</div>
 802:                   </div>
 803:                 </div>
 804:               ),
 805:             },
 806:             { h: 'الخزينة', r: (s: ShiftRow) => <span className="text-[12px] tx2">{nameOf(s.tr)}</span> },
 807:             {
 808:               h: 'الفتح / الإغلاق',
 809:               r: (s: ShiftRow) => (
 810:                 <div className="leading-tight num text-[11.5px]">
 811:                   <div className="tx1">{s.open}</div>
 812:                   <div className="tx3">{s.close || '—'}</div>
 813:                 </div>
 814:               ),
 815:             },
 816:             { h: 'الحالة', r: (s: ShiftRow) => <StatusBadge map={SHIFT_STATUS} value={s.status} /> },
 817:             {
 818:               h: 'المتوقعة',
 819:               r: (s: ShiftRow) => (s.exp != null ? fmtMoney(s.exp) : <span className="tx3">—</span>),
 820:             },
 821:             {
 822:               h: 'الفعلية',
 823:               r: (s: ShiftRow) => (s.act != null ? fmtMoney(s.act) : <span className="tx3">—</span>),
 824:             },
 825:             { h: 'الفرق', r: (s: ShiftRow) => <DiffCell s={s} /> },
 826:           ]}
 827:         />
 828:         <Pager total={list.data?.meta.total ?? 0} page={page} per={20} onPage={setPage} />
 829:       </Card>
 830:       {view && (
 831:         <ShiftModal
 832:           s={view}
 833:           onClose={() => setView(null)}
 834:           onApprove={() => approveShift(view.id)}
 835:         />
 836:       )}
 837:     </div>
 838:   );
 839: }
 840: 
 841: export function ShiftModal({ s: initial, onClose, onApprove }: { s: ShiftRow; onClose: () => void; onApprove: () => void }) {
 842:   const detail = useRemote((signal) => shiftsApi.show(initial.id, signal), [initial.id]);
 843:   const s = detail.data ? mapShift(detail.data) : initial;
 844:   const opening = num(detail.data?.opening_cash);
 845:   const cashSales = num(detail.data?.cash_sales_total);
 846:   const cardSales = num(detail.data?.card_sales_total);
 847:   const cashRet = num(detail.data?.cash_returns_total);
 848:   const cashExp = num(detail.data?.cash_expenses_total);
 849:   const exp = s.exp ?? opening + cashSales - cashRet - cashExp;
 850:   const d = s.act != null ? s.act - exp : null;
 851: 
 852:   return (
 853:     <Modal
 854:       open
 855:       onClose={onClose}
 856:       width={680}
 857:       icon="clock"
 858:       title={
 859:         <span className="flex items-center gap-2">
 860:           <span className="num">{s.no}</span>
 861:           <StatusBadge map={SHIFT_STATUS} value={s.status} />
 862:         </span>
 863:       }
 864:       sub={
 865:         <>
 866:           {s.cashier} · {s.branch} · {detail.data?.treasury?.name ?? `#${s.tr}`}
 867:         </>
 868:       }
 869:       footer={
 870:         detail.data?.status === 'closed_pending_approval' ? (
 871:           <>
 872:             <button className="btn btn-soft" onClick={onClose}>
 873:               إغلاق
 874:             </button>
 875:             <button className="btn btn-dark" onClick={onApprove}>
 876:               <Icon name="check" size={14} />
 877:               اعتماد الوردية
 878:             </button>
 879:           </>
 880:         ) : null
 881:       }
 882:     >
 883:       <div className="space-y-4 pb-2">
 884:         <RemoteNote remote={detail} />
 885:         {s.status === 'open' && (
 886:           <Note tone="blue" icon="info">
 887:             الوردية ما زالت مفتوحة — الأرقام حتى اللحظة، والاعتماد متاح بعد إغلاقها من نقطة البيع.
 888:           </Note>
 889:         )}
 890:         <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
 891:           <div className="v-sub p-4 space-y-2.5 text-[12.5px]">
 892:             {[
