 897:             ].map(([l, v, c]) => (
 898:               <div key={l as string} className="flex items-center justify-between">
 899:                 <span className="tx2">{l}</span>
 900:                 <span className={'font-semibold ' + (c as string)}>{fmtMoney(v as number)}</span>
 901:               </div>
 902:             ))}
 903:             <div className="flex items-center justify-between v-bt pt-2.5">
 904:               <span className="font-semibold tx1">النقدية المتوقعة</span>
 905:               <span className="font-display font-bold">{fmtMoney(exp)}</span>
 906:             </div>
 907:             <div className="flex items-center justify-between text-[11.5px] tx3">
 908:               <span>مبيعات البطاقات (خارج الدرج)</span>
 909:               <span>{fmtMoney(cardSales)}</span>
 910:             </div>
 911:           </div>
 912:           <div
 913:             className={
 914:               'rounded-[18px] p-4 flex flex-col justify-between ' +
 915:               (d == null ? 'v-sub' : d === 0 ? 't-green' : d < 0 ? 't-red' : 't-amber')
 916:             }
 917:           >
 918:             <div>
 919:               <div className="text-[12px] font-medium opacity-90">النقدية الفعلية</div>
 920:               <div className="font-display text-[26px] font-bold num ltr mt-1">
 921:                 {s.act != null ? fmtNum(s.act) : '—'}
 922:               </div>
 923:             </div>
 924:             <div className="mt-4">
 925:               <div className="text-[12px] font-medium opacity-90">الفرق</div>
 926:               <div className="font-display text-[20px] font-bold mt-0.5">
 927:                 {d == null ? (
 928:                   '—'
 929:                 ) : d === 0 ? (
 930:                   'مطابق'
 931:                 ) : (
 932:                   <>
 933:                     {d < 0 ? 'عجز' : 'زيادة'} <span className="num ltr">{fmtNum(Math.abs(d))}</span>
 934:                   </>
 935:                 )}
 936:               </div>
 937:             </div>
 938:           </div>
 939:         </div>
 940:         <div>
 941:           <div className="lbl mb-2">مصروفات الوردية</div>
 942:           <DataTable
 943:             compact
 944:             rows={(detail.data?.expenses ?? []).map(mapExpense)}
 945:             cols={[
 946:               { h: 'رقم السند', r: (e: ExpenseRow) => <span className="num">{e.no}</span> },
 947:               { h: 'التصنيف', r: (e: ExpenseRow) => e.cat },
 948:               { h: 'المبلغ', r: (e: ExpenseRow) => fmtMoney(e.amount) },
 949:               { h: 'البيان', r: (e: ExpenseRow) => e.notes || '—' },
 950:             ]}
 951:             empty="لا توجد مصروفات مسجلة على هذه الوردية"
 952:           />
 953:         </div>
 954:       </div>
 955:     </Modal>
 956:   );
