 988: export function QuotesTab() {
 989:   const toast = useToast();
 990:   const { busy, run } = useAction();
 991:   const [st, setSt] = useState('');
 992:   const [cu, setCu] = useState('');
 993:   const [page, setPage] = useState(1);
 994:   const [view, setView] = useState<QuoteRow | null>(null);
 995:   const [price, setPrice] = useState(false);
 996:   const [expire, setExpire] = useState(false);
 997:   const [prices, setPrices] = useState<Record<number, string>>({});
 998:   const [validUntil, setValidUntil] = useState('');
 999:   const [adminNotes, setAdminNotes] = useState('');
1000:   const [errors, setErrors] = useState<Record<string, string>>({});
1001:   useEffect(() => setPage(1), [st, cu]);
1002:   const status = st === 'priced' ? 'priced_by_admin' : st === 'converted' || st === 'ordered' ? 'converted_to_order' : st;
1003:   const list = useRemote((s) => quotationsApi.list({ page, per_page: 20, status: status || undefined, customer_id: cu || undefined }, s).then((p) => ({ ...p, data: p.data.map(mapQuote) })), [page, st, cu], { mock: () => mockPage(QUOTES) });
1004:   const customers = useRemote((s) => allPages((page) => opsApi.get('/api/v1/admin/customers', { params: { page, type: 'wholesale', per_page: 100 }, signal: s }).then((r) => asPage<{ id: number; name: string; company_name?: string }>(r))), []);
1005:   const detail = useRemote((s) => quotationsApi.show(view!.id, s), [view?.id], { enabled: !!view });
1006:   useEffect(() => {
