1019:     if (lines.some((line) => prices[line.id] == null || prices[line.id] === '' || !Number.isFinite(Number(prices[line.id])) || Number(prices[line.id]) < 0)) return toast('أدخل سعراً صحيحاً لكل بند', 'red');
1020:     const result = await run(() => quotationsApi.price(detail.data!.id, { items: lines.map((line) => ({ id: line.id, offered_unit_price: Number(prices[line.id]) })), valid_until: validUntil, admin_notes: adminNotes || null }), { toast, success: 'أُرسل التسعير للعميل', onFieldErrors: setErrors });
1021:     if (result) { detail.setData(result); setView(mapQuote(result)); setPrice(false); list.reload(); }
1022:   };
1023:   const expireQuote = async () => {
1024:     if (!view || list.usingMock || !detail.data) return;
1025:     const result = await run(() => quotationsApi.expire(view.id), { toast, success: 'تم إنهاء صلاحية العرض' });
1026:     if (result) { setExpire(false); setView(mapQuote(result)); detail.setData(result); list.reload(); }
