1049:               r: (q: QuoteRow) => (
1050:                 <div className="flex items-center gap-2">
1051:                   <Avatar name={q.company} tone={q.id} size={28} />
1052:                   <div className="leading-tight">
1053:                     <div className="font-medium tx1">{q.company}</div>
1054:                     <div className="text-[11px] tx3">{q.cust}</div>
1055:                   </div>
1056:                 </div>
1057:               ),
1058:             },
1059:             { h: 'الحالة', r: (q: QuoteRow) => <StatusBadge map={QUOTE_STATUS} value={q.status} /> },
1060:             {
