1263: export function NoticesTab() {
1264:   const toast = useToast();
1265:   const { busy, run } = useAction();
1266:   const [st, setSt] = useState('');
1267:   const [cu, setCu] = useState('');
1268:   const [page, setPage] = useState(1);
1269:   const [selected, setSelected] = useState<PaymentNoticeRow | null>(null);
1270:   const [mode, setMode] = useState<'approve' | 'reject' | null>(null);
1271:   const [treasuryId, setTreasuryId] = useState('');
1272:   const [notes, setNotes] = useState('');
1273:   const [errors, setErrors] = useState<Record<string, string>>({});
1274:   useEffect(() => { setPage(1); setSelected(null); }, [st, cu]);
1275:   useEffect(() => { setNotes(''); setTreasuryId(''); setErrors({}); }, [mode, selected?.id]);
1276:   const list = useRemote((s) => paymentNoticesApi.list({ page, per_page: 20, status: st === 'pending' ? 'pending_review' : st || undefined, customer_id: cu || undefined }, s).then((p) => ({ ...p, data: p.data.map(mapNotice) })), [page, st, cu], { mock: () => mockPage(NOTICES) });
1277:   const detail = useRemote((s) => paymentNoticesApi.show(selected!.id, s), [selected?.id], { enabled: !!selected });
1278:   const treasures = useRemote((s) => allPages((page) => treasuriesApi.list({ page, per_page: 100, is_active: true }, s)), []);
1279:   const customers = useRemote((s) => allPages((page) => opsApi.get('/api/v1/admin/customers', { params: { page, type: 'wholesale', per_page: 100 }, signal: s }).then((r) => asPage<{ id: number; name: string; company_name?: string }>(r))), []);
1280:   const nameOf = (id: number) => treasures.data?.find((t) => t.id === id)?.name ?? (USE_MOCK ? trName(id) : '#' + id);
1281:   const rows = list.data?.data ?? [];
1282:   const sel = detail.data && detail.data.id === selected?.id ? mapNotice(detail.data) : selected;
1283:   const setSel = setSelected;
1284:   useEffect(() => { if (!selected && rows.length) setSelected(rows[0]); }, [list.data, selected]);
1285:   const review = async (approve: boolean) => {
1286:     if (!sel || list.usingMock || !detail.data) return;
1287:     if (!approve && !notes.trim()) return toast('سبب الرفض مطلوب', 'red');
1288:     const result = await run(() => approve ? paymentNoticesApi.approve(sel.id, { treasury_id: treasuryId ? Number(treasuryId) : null, admin_notes: notes || null }) : paymentNoticesApi.reject(sel.id, notes), { toast, success: approve ? 'تم اعتماد إشعار الدفع' : 'تم رفض الإشعار', onFieldErrors: setErrors });
1289:     if (result) { detail.setData(result); setSelected(mapNotice(result)); setMode(null); list.reload(); treasures.reload(); }
1290:   };
1291: 
1292:   return (
1293:     <div className="grid grid-cols-1 lg:grid-cols-12 gap-5">
1294:       <Card stg={3} className="lg:col-span-5 space-y-3">
1295:         <div className="flex flex-wrap gap-2">
1296:           <FSelect
1297:             value={st}
1298:             onChange={setSt}
1299:             placeholder="كل الحالات"
1300:             options={Object.entries(NOTICE_STATUS).map(([v, s]) => ({ value: v, label: s.label }))}
1301:           />
1302:           <FSelect value={cu} onChange={setCu} placeholder="العميل" options={(customers.data ?? []).map((c) => ({ value: String(c.id), label: c.company_name || c.name }))} />
1303:         </div>
1304:         <RemoteNote remote={list} />
1305:         <div className="space-y-2">
1306:           {rows.length === 0 && <Empty icon="bank" title="لا توجد إشعارات" />}
1307:           {(rows as PaymentNoticeRow[]).map((n: PaymentNoticeRow) => (
1308:             <button
1309:               key={n.id}
1310:               disabled={list.usingMock} onClick={() => setSel(n)}
1311:               className="w-full text-start v-sub p-3.5 transition flex items-start gap-3 rounded-[14px]"
