  59:       <div className={'text-[11px] mt-0.5 font-semibold c-' + (PAY_STATUS[o.payStatus]?.tone || 'gray')}>
  60:         {PAY_STATUS[o.payStatus]?.label || o.payStatus}
  61:       </div>
  62:     </div>
  63:   );
  64: }
  65: 
  66: export function OrderFlags({ o }: { o: OrderRow }) {
  67:   return (
  68:     <div className="flex flex-col gap-1 items-start">
  69:       {o.followUp && (
  70:         <span className="badge t-amber !py-[2px] !text-[10.5px]">
  71:           <Icon name="flag" size={10} sw={2.4} />
  72:           يحتاج متابعة
  73:         </span>
  74:       )}
  75:       {o.needRefund && (
  76:         <span className="badge t-red !py-[2px] !text-[10.5px]">
  77:           <Icon name="returns" size={10} sw={2.4} />
  78:           يتطلب استرداد مبلغ
  79:         </span>
  80:       )}
  81:     </div>
  82:   );
  83: }
  84: 
  85: /* ---------- Orders list ---------- */
  86: export function OrdersList({ go }: { go: (route: { m: string; id?: number | string }) => void }) {
  87:   const [q, setQ] = useState('');
  88:   const [st, setSt] = useState('');
  89:   const [br, setBr] = useState('');
  90:   const [pm, setPm] = useState('');
  91:   const [from, setFrom] = useState('');
  92:   const [to, setTo] = useState('');
  93:   const [fu, setFu] = useState(false);
  94:   const [rf, setRf] = useState(false);
  95:   const toast = useToast();
  96:   const [page, setPage] = useState(1);
  97:   const dq = useDebounced(q);
  98: 
  99:   // ارجع للصفحة 1 عند تغيير أي فلتر
 100:   useEffect(() => { setPage(1); }, [dq, st, br, pm, from, to, fu, rf]);
 101: 
 102:   const params: AdminOrderListParams = {
 103:     page,
 104:     status: (st || undefined) as OrderStatus | undefined,
 105:     search: dq || undefined,
 106:     allocated_branch_id: br ? Number(br) : undefined,
 107:     payment_method: (pm === 'bank' ? 'bank_transfer' : pm || undefined) as AdminOrderListParams['payment_method'],
 108:     date_from: from || undefined,
 109:     date_to: to || undefined,
 110:     needs_attention: fu ? true : undefined,
 111:     requires_refund: rf ? true : undefined,
 112:   };
 113: 
 114:   const { data, loading, error, reload, usingMock } = useRemote(
 115:     (signal) => adminOrdersApi.list(params, signal),
 116:     [page, st, dq, br, pm, from, to, fu, rf],
 117:     {
 118:       mock: () => ({ data: [], meta: { current_page: 1, last_page: 1, per_page: 20, total: ORDERS.length, from: 1, to: ORDERS.length } } as any),
 119:       onError: (e) => toast(e.message, 'red'),
 120:     },
 121:   );
 122:   const rows = useMemo(
 123:     () => (usingMock ? ORDERS : (data?.data ?? []).map(mapOrder)),
 124:     [data, usingMock],
 125:   );
 126:   const branches = useRemote((s) => branchesApi.list({}, s).then((r) => r.data), []);
 127:   const branchOpts = useMemo(() => branchOptions(branches.data ?? []), [branches.data]);
 128:   const kpi = useRemote(async (signal) => {
 129:     const s = await adminOrdersApi.stats(signal);
 130:     return { pending: s.pending, processing: s.processing, follow: s.needs_attention, refund: s.requires_refund };
 131:   }, []);
 132: 
 133:   const anyFilter = q || st || br || pm || from || to || fu || rf;
 134:   const reset = () => {
 135:     setQ('');
 136:     setSt('');
 137:     setBr('');
 138:     setPm('');
 139:     setFrom('');
 140:     setTo('');
 141:     setFu(false);
 142:     setRf(false);
 143:   };
 144: 
 145:   const cols: ColumnDef<OrderRow>[] = [
 146:     { h: 'رقم الطلب', r: (o) => <span className="num font-semibold tx2">{o.no}</span> },
 147:     {
 148:       h: 'العميل',
 149:       r: (o) => (
 150:         <div className="flex items-center gap-2.5">
 151:           <Avatar name={o.customer} tone={o.id} size={28} />
 152:           <div className="leading-tight">
 153:             <div className="font-semibold tx1 flex items-center gap-1.5">
 154:               {o.customer}
 155:               {o.guest && <span className="badge t-gray !py-0 !px-1.5 !text-[10px]">زائر</span>}
 156:             </div>
 157:             <div className="text-[11px] tx3 num ltr mt-0.5">{o.phone}</div>
 158:           </div>
 159:         </div>
 160:       ),
 161:     },
 162:     {
 163:       h: 'القناة',
 164:       r: (o) => (
 165:         <span className="v-sub px-2.5 py-1 rounded-full text-[11px] tx2 whitespace-nowrap">
 166:           {o.channel}
 167:         </span>
 168:       ),
 169:     },
 170:     { h: 'الحالة', r: (o) => <StatusBadge map={ORDER_STATUS} value={o.status} /> },
 171:     { h: 'الدفع', r: (o) => <PayCell o={o} /> },
 172:     {
 173:       h: 'الفرع المخصص',
 174:       r: (o) =>
 175:         o.branch ? (
 176:           <span className="tx2 whitespace-nowrap">{o.branch}</span>
 177:         ) : (
 178:           <span className="tx3 text-[11.5px]">غير مخصص</span>
 179:         ),
 180:     },
 181:     {
 182:       h: 'الإجمالي',
 183:       r: (o) => <span className="font-semibold tx1 whitespace-nowrap">{fmtMoney(o.total)}</span>,
 184:     },
 185:     {
 186:       h: 'تاريخ الإنشاء',
 187:       r: (o) => (
 188:         <div className="leading-tight tx2">
 189:           <Num>{o.date}</Num>
 190:           <div className="text-[11px] tx3 num">{o.time}</div>
 191:         </div>
 192:       ),
 193:     },
 194:     { h: 'تنبيهات', r: (o) => <OrderFlags o={o} /> },
 195:     {
 196:       h: '',
 197:       r: (o) => (
 198:         <RowActions>
 199:           <button className="btn btn-soft btn-xs" onClick={() => go({ m: 'orders', id: o.id })}>
 200:             عرض التفاصيل
 201:           </button>
 202:         </RowActions>
 203:       ),
 204:     },
 205:   ];
 206: 
 207:   return (
 208:     <div className="space-y-5">
 209:       <RemoteFeedback state={{ loading: false, error: null, usingMock, reload }} />
 210:       <PageHead title="الطلبات" sub="متابعة طلبات كل القنوات، وتحديث حالتها ودفعها وتخصيص مخزونها." />
 211:       <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 stg stg-2">
 212:         <KPI
 213:           hero
 214:           label="طلبات قيد المراجعة"
 215:           icon="clock"
 216:           value={kpi.data?.pending ?? '—'}
 217:           foot="تحتاج تأكيدًا أو إلغاء"
 218:         />
 219:         <KPI
 220:           label="يحتاج متابعة"
 221:           icon="flag"
 222:           value={kpi.data?.follow ?? '—'}
 223:           foot="معلَّمة للمتابعة"
 224:         />
 225:         <KPI
 226:           label="يتطلب استرداد مبلغ"
 227:           icon="returns"
 228:           value={kpi.data?.refund ?? '—'}
 229:           foot="ملغاة أو مرتجعة ومدفوعة"
 230:         />
 231:         <KPI
 232:           label="قيد التجهيز"
 233:           icon="store"
 234:           value={kpi.data?.processing ?? '—'}
 235:           foot="بانتظار تخصيص المخزون"
 236:         />
 237:       </div>
 238:       <Card stg={3}>
 239:         <div className="flex flex-wrap items-center gap-2 mb-4">
 240:           <SearchPill value={q} onChange={setQ} placeholder="رقم الطلب، العميل، الهاتف" w="w-48" />
 241:           <FSelect
 242:             value={st}
 243:             onChange={setSt}
 244:             placeholder="كل الحالات"
 245:             options={Object.entries(ORDER_STATUS).map(([v, s]) => ({ value: v, label: s.label }))}
 246:           />
 247:           <FSelect value={br} onChange={setBr} placeholder="كل الفروع" options={branchOpts.length ? branchOpts : []} />
 248:           <FSelect
 249:             value={pm}
 250:             onChange={setPm}
 251:             placeholder="طريقة الدفع"
 252:             options={Object.entries(PAY_METHODS).map(([v, l]) => ({ value: v, label: l }))}
 253:           />
 254:           <FDate label="من" value={from} onChange={setFrom} />
 255:           <FDate label="إلى" value={to} onChange={setTo} />
 256:           <FChip on={fu} onClick={() => setFu(!fu)} icon="flag">
 257:             يحتاج متابعة
 258:           </FChip>
 259:           <FChip on={rf} onClick={() => setRf(!rf)} icon="returns">
 260:             يتطلب استرداد
 261:           </FChip>
 262:           {anyFilter && (
 263:             <button className="btn btn-ghost btn-xs" onClick={reset}>
 264:               <Icon name="x" size={12} />
 265:               مسح الفلاتر
 266:             </button>
 267:           )}
 268:         </div>
 269:         <DataTable
 270:           rows={loading ? [] : rows}
 271:           empty={loading ? 'جارٍ التحميل…' : error && !usingMock
 272:             ? <Empty icon="alert" title="تعذّر تحميل الطلبات" text={error.message}
 273:                 action={<button className="btn btn-soft btn-sm" onClick={reload}>إعادة المحاولة</button>} />
 274:             : undefined}
 275:           onRow={(o: OrderRow) => go({ m: 'orders', id: o.id })}
 276:           cols={cols}
 277:         />
 278:         <Pager total={data?.meta.total ?? rows.length} per={data?.meta.per_page ?? 20} page={page} onPage={setPage} />
 279:       </Card>
 280:     </div>
 281:   );
 282: }
 283: 
 284: /* ---------- Order detail ---------- */
 285: export function OrderDetail({
 286:   id,
 287:   go,
 288: }: {
 289:   id: number | string;
 290:   go: (route: { m: string; id?: number | string }) => void;
 291: }) {
 292:   const toast = useToast();
 293:   const mayUpdate = useCan('orders.update');
 294:   const mayPay = useCan('orders.payment');
 295:   const mayAllocate = useCan('orders.allocate');
 296:   const { busy, run } = useAction();
 297:   const numId = Number(id);
 298:   const remote = useRemote(
 299:     (s) => adminOrdersApi.show(numId, s), [numId], { mock: () => mockOrder(numId), onError: (e) => toast(e.message, 'red') },
 300:   );
 301:   const { data: order, loading, setData: setOrder } = remote;
 302:   const shipCos = useRemote((s) => shippingCompaniesApi.list({ is_active: true }, s).then((p) => p.data), []);
 303:   const branchesList = useRemote((s) => branchesApi.list({}, s).then((r) => r.data), []);
 304:   const [statusNotes, setStatusNotes] = useState('');
 305:   const [payNotes, setPayNotes] = useState('');
 306:   const [refundRef, setRefundRef] = useState('');
 307:   const [modal, setModal] = useState<string | null>(null);
 308:   const [newSt, setNewSt] = useState('');
 309:   const [newPay, setNewPay] = useState('');
 310:   const [allocBranch, setAllocBranch] = useState('');
 311:   const [carrier, setCarrier] = useState('');
 312:   const [awb, setAwb] = useState('');
 313:   useEffect(() => { if (order) setNewPay(mapOrder(order).payStatus); }, [order]);
 314: 
 315:   if (loading || !order) return <><RemoteFeedback state={remote} />{!loading && !remote.error && <Empty title="الطلب غير موجود" />}</>;
 316:   const o = mapOrder(order);
 317: 
 318:   const saveStatus = async (status: OrderStatus, notes: string) => {
 319:     if (remote.usingMock) return toast('البيانات المعروضة تجريبية — لم يتم الحفظ', 'red');
 320:     const r = await run(() => adminOrdersApi.updateStatus(order.id, { status: status as any, notes: notes || undefined }),
 321:       { toast, success: 'تم تحديث حالة الطلب' });
 322:     if (r) { setOrder(r); setModal(null); }
 323:   };
 324: 
 325:   const savePayment = async (payment_status: PaymentStatus, notes: string) => {
 326:     if (remote.usingMock) return toast('البيانات المعروضة تجريبية — لم يتم الحفظ', 'red');
 327:     if (!notes.trim()) return toast('الملاحظات إلزامية للتعديل اليدوي على الدفع', 'red');
 328:     if (payment_status === 'refunded' && !refundRef.trim()) return toast('مرجع الاسترداد إلزامي عند التحويل إلى مسترد', 'red');
 329:     const r = await run(() => adminOrdersApi.updatePayment(order.id, {
 330:       payment_status,
 331:       notes,
 332:       ...(payment_status === 'refunded' ? { refund_reference: refundRef.trim() } : {}),
 333:     }),
 334:       { toast, success: 'تم تحديث حالة الدفع' });
 335:     if (r) { setOrder(r); setModal(null); setRefundRef(''); }
 336:   };
 337: 
 338:   const saveAlloc = async (branchId: string) => {
 339:     if (remote.usingMock) return toast('البيانات المعروضة تجريبية — لم يتم الحفظ', 'red');
 340:     const r = await run(() => adminOrdersApi.allocate(order.id, branchId ? Number(branchId) : null),
 341:       { toast, success: 'تم تخصيص الطلب' });
 342:     if (r) { setOrder(r); setModal(null); }
 343:   };
 344:   const deAlloc = async () => {
 345:     if (remote.usingMock) return toast('البيانات المعروضة تجريبية — لم يتم الحفظ', 'red');
 346:     const r = await run(() => adminOrdersApi.deallocate(order.id), { toast, success: 'تم إلغاء التخصيص' });
 347:     if (r) setOrder(r);
 348:   };
 349:   const saveShipment = async (companyId: string, awbNum: string) => {
 350:     if (remote.usingMock) return toast('البيانات المعروضة تجريبية — لم يتم الحفظ', 'red');
 351:     const r = await run(() => adminOrdersApi.createShipment(order.id, { shipping_company_id: Number(companyId), awb_number: awbNum || null }),
 352:       { toast, success: 'تم إنشاء الشحنة' });
 353:     if (r) { setModal(null); remote.reload(); }
 354:   };
 355: 
 356:   const items = (order.items ?? []).map((it) => ({
 357:     v: { name: it.product_name, sku: it.sku, price: num(it.unit_price) },
 358:     qty: it.qty,
 359:     disc: num(it.discount_amount),
 360:     tax: num(it.tax_amount),
 361:     branch: o.branch,
 362:     line: num(it.line_total),
 363:   }));
 364:   const displayItems = items;
 365:   const lineTotal = (it: any) => it.line;
 366:   const subtotal = order.subtotal != null ? num(order.subtotal) : displayItems.reduce((s: number, it: any) => s + (it.v.price ?? 0) * it.qty, 0);
 367:   const disc = order.discount_amount != null ? num(order.discount_amount) : displayItems.reduce((s: number, it: any) => s + (it.disc ?? 0), 0);
 368:   const ship = order.shipping_cost != null ? num(order.shipping_cost) : 0;
 369:   const codFee = num(order.cod_fee);
 370:   const tax = order.tax_amount != null ? num(order.tax_amount) : 0;
 371:   const total = order.grand_total != null ? num(order.grand_total) : subtotal - disc + ship + codFee + tax;
 372:   const statusOpts = (ORDER_NEXT[o.status] || []).filter((s) => s !== 'shipped');
 373:   const next = ORDER_NEXT[o.status] || [];
 374:   const canShip = next.includes('shipped');
 375:   const terminal = next.length === 0;
 376:   const canAllocate = ['confirmed', 'processing'].includes(order.status);
 377: 
 378:   const timeline = (order.status_history ?? []).map((h) => ({
 379:     title: (ORDER_STATUS as any)[h.to_status]?.label ?? h.to_status,
 380:     date: `${toDate(h.at)} ${toTime(h.at)}`,
 381:     note: h.notes ?? undefined,
 382:     from: h.from_status,
 383:     to: h.to_status,
 384:   }));
 385:   const history = timeline.map(t => ({ from: t.from, to: t.to, note: t.note, by: '', at: t.date }));
 386: 
 387:   return (
 388:     <div className="space-y-5">
 389:       <RemoteFeedback state={remote} />
 390:       <PageHead
 391:         back={{ label: 'كل الطلبات', onClick: () => go({ m: 'orders' }) }}
 392:         title={
 393:           <span className="flex items-center gap-3 flex-wrap">
 394:             <span className="num">{o.no}</span>
 395:             <StatusBadge map={ORDER_STATUS} value={o.status} />
 396:           </span>
 397:         }
 398:         sub={
 399:           <span>
 400:             أُنشئ <Num>{o.date} · {o.time}</Num> عبر {o.channel}
 401:           </span>
 402:         }
 403:         actions={
 404:           <>
 405:             <button
 406:               className="btn btn-soft"
 407:               disabled={!mayUpdate || remote.usingMock || terminal}
 408:               onClick={() => {
 409:                 setNewSt('');
 410:                 setModal('status');
 411:               }}
 412:             >
 413:               <Icon name="refresh" size={14} />
 414:               تغيير الحالة
 415:             </button>
 416:             <button className="btn btn-soft" disabled={!mayPay || remote.usingMock} onClick={() => setModal('pay')}>
 417:               <Icon name="card" size={14} />
 418:               تحديث الدفع
 419:             </button>
 420:             {o.branch ? (
 421:               <button
 422:                 className="btn btn-soft"
 423:                 disabled={!mayAllocate || remote.usingMock || busy || !canAllocate}
 424:                 onClick={deAlloc}
 425:               >
 426:                 <Icon name="layers" size={14} />
 427:                 فك التخصيص
 428:               </button>
 429:             ) : (
 430:               <button className="btn btn-soft" disabled={!mayAllocate || remote.usingMock || busy || !canAllocate} onClick={() => setModal('alloc')}>
 431:                 <Icon name="layers" size={14} />
 432:                 تخصيص المخزون
 433:               </button>
 434:             )}
 435:             <button
 436:               className="btn btn-dark"
 437:               disabled={!mayUpdate || remote.usingMock || busy || !canShip}
 438:               onClick={() => setModal('ship')}
 439:             >
 440:               <Icon name="truck" size={14} />
 441:               إنشاء شحنة
 442:             </button>
 443:           </>
 444:         }
 445:       />
 446: 
 447:       {(o.followUp || o.needRefund) && (
 448:         <div className="flex flex-wrap gap-2 stg stg-2">
 449:           {o.followUp && (
 450:             <Note tone="amber" icon="flag">
 451:               هذا الطلب معلَّم <b>«يحتاج متابعة»</b>.
 452:             </Note>
 453:           )}
 454:           {o.needRefund && (
 455:             <Note tone="red" icon="returns">
 456:               هذا الطلب <b>«يتطلب استرداد مبلغ»</b> — أنشئ مرتجعًا أو حدّث حالة الدفع إلى مسترد.
 457:             </Note>
 458:           )}
 459:         </div>
 460:       )}
 461: 
 462:       <div className="grid grid-cols-1 lg:grid-cols-12 gap-5">
 463:         <div className="lg:col-span-8 space-y-5">
 464:           <Card stg={2}>
 465:             <CardHead
 466:               title="المنتجات"
 467:               sub="بيانات المنتج كما كانت وقت الطلب"
 468:               right={
 469:                 <span className="text-[11.5px] tx3">
 470:                   <Num>{items.length}</Num> بنود
 471:                 </span>
 472:               }
 473:             />
 474:             <DataTable
 475:               compact
 476:               cols={[
 477:                 {
 478:                   h: 'المنتج',
 479:                   r: (it) => (
 480:                     <div className="flex items-center gap-2.5">
 481:                       <span className="w-9 h-9 rounded-[10px] v-sub flex items-center justify-center tx3">
 482:                         <Icon name="box" size={15} />
 483:                       </span>
 484:                       <div className="leading-tight">
 485:                         <div className="font-semibold tx1">{it.v.name}</div>
 486:                         <div className="text-[11px] tx3 num ltr mt-0.5">{it.v.sku}</div>
 487:                       </div>
 488:                     </div>
 489:                   ),
 490:                 },
 491:                 { h: 'الكمية', align: 'center', r: (it) => <Num className="font-semibold">{it.qty}</Num> },
 492:                 { h: 'سعر الوحدة', r: (it) => fmtMoney(it.v.price) },
 493:                 {
 494:                   h: 'الخصم',
 495:                   r: (it) =>
 496:                     it.disc ? <span className="c-red">{fmtMoney(-it.disc)}</span> : <span className="tx3">—</span>,
 497:                 },
 498:                 { h: 'الضريبة', r: (it) => <span className="tx2">{fmtMoney(it.tax)}</span> },
 499:                 { h: 'إجمالي البند', r: (it) => <span className="font-semibold">{fmtMoney(lineTotal(it))}</span> },
 500:                 {
 501:                   h: 'فرع البند',
 502:                   r: (it) =>
 503:                     it.branch ? (
 504:                       <span className="text-[11.5px] tx2">{it.branch}</span>
 505:                     ) : (
 506:                       <span className="text-[11.5px] tx3">غير مخصص</span>
 507:                     ),
 508:                 },
 509:               ]}
 510:               rows={displayItems}
 511:             />
 512:           </Card>
 513: 
 514:           <Card stg={3}>
 515:             <CardHead title="سجل التغييرات" sub="كل تغيير في حالة الطلب ومن قام به" />
 516:             <Timeline
 517:               items={history.map((h) => ({
 518:                 icon: h.to === 'pending' ? 'plus' : 'refresh',
 519:                 body: (
 520:                   <div>
 521:                     <div className="flex items-center gap-2 flex-wrap">
 522:                       {h.from && (
 523:                         <>
 524:                           <StatusBadge map={ORDER_STATUS} value={h.from} />
 525:                           <Icon name="arrowL" size={13} className="tx3" />
 526:                         </>
 527:                       )}
 528:                       <StatusBadge map={ORDER_STATUS} value={h.to} />
 529:                     </div>
 530:                     {h.note && <div className="text-[12.5px] tx1 mt-2">{h.note}</div>}
 531:                     <div className="text-[11px] tx3 mt-1 flex items-center gap-2">
 532:                       <span>{h.by}</span>
 533:                       <span>·</span>
 534:                       <Num>{h.at}</Num>
 535:                     </div>
 536:                   </div>
 537:                 ),
 538:               }))}
 539:             />
 540:           </Card>
 541:         </div>
 542: 
 543:         <div className="lg:col-span-4 space-y-5">
 544:           <div className="v-card p-4 stg stg-2">
 545:             <div className="v-orange rounded-[18px] p-4">
 546:               <div className="flex items-center justify-between text-[12.5px] text-white/90">
 547:                 <span>إجمالي الطلب</span>
 548:                 <span className="px-2 py-0.5 rounded-full text-[10.5px] font-semibold bg-white/20">
 549:                   {PAY_METHODS[o.pay]}
