 554:               </div>
 555:               <div className="text-[11.5px] text-white/85">
 556:                 حالة الدفع: <b>{PAY_STATUS[o.payStatus]?.label || o.payStatus}</b>
 557:               </div>
 558:             </div>
 559:             <div className="px-1 pt-4">
 560:               <KV
 561:                 items={[
