 762:       {/* allocate modal */}
 763:       <Modal
 764:         open={modal === 'alloc'}
 765:         onClose={() => setModal(null)}
 766:         title="تخصيص المخزون"
 767:         icon="layers"
 768:         width={460}
 769:         footer={
 770:           <>
 771:             <button className="btn btn-soft" onClick={() => setModal(null)}>
 772:               إلغاء
 773:             </button>
 774:             <button
 775:               className="btn btn-dark"
 776:               disabled={busy}
 777:               onClick={() => saveAlloc(allocBranch)}
 778:             >
 779:               {allocBranch ? 'تخصيص' : 'تخصيص تلقائي'}
