 783:       >
 784:         <div className="space-y-4 pb-2">
 785:           <Field label="الفرع" hint="اترك الحقل فارغًا ليختار النظام الفرع المناسب تلقائيًا.">
 786:             <select className="inp" value={allocBranch} onChange={(e) => setAllocBranch(e.target.value)}>
 787:               <option value="">— تخصيص تلقائي —</option>
 788:               {(branchesList.data ?? []).map((b: { id: number; name: string }) => (
 789:                 <option key={b.id} value={String(b.id)}>{b.name}</option>
 790:               ))}
