 796:       {/* shipping modal */}
 797:       <Modal
 798:         open={modal === 'ship'}
 799:         onClose={() => setModal(null)}
 800:         title="إنشاء شحنة"
 801:         icon="truck"
 802:         width={520}
 803:         footer={
 804:           <>
 805:             <button className="btn btn-soft" onClick={() => setModal(null)}>
 806:               إلغاء
 807:             </button>
 808:             <button
 809:               className="btn btn-dark"
 810:               disabled={!carrier || busy}
 811:               onClick={() => saveShipment(carrier, awb)}
 812:             >
 813:               إنشاء الشحنة
 814:             </button>
 815:           </>
 816:         }
 817:       >
 818:         <div className="space-y-4">
 819:           <Field label="شركة الشحن" req>
 820:             <select className="inp" value={carrier} onChange={(e) => setCarrier(e.target.value)}>
 821:               <option value="">اختر الشركة</option>
 822:               {(shipCos.data ?? []).map((c: { id: number; name: string }) => (
 823:                 <option key={c.id} value={String(c.id)}>
 824:                   {c.name}
 825:                 </option>
 826:               ))}
 827:             </select>
 828:           </Field>
 829:           <Field
 830:             label="رقم البوليصة (AWB)"
 831:             count={`${awb.length} / 100`}
 832:             hint="اختياري — يمكن تركه إن كانت الشركة تُصدره تلقائيًا."
 833:           >
 834:             <input
 835:               className="inp num"
 836:               dir="ltr"
 837:               maxLength={100}
 838:               value={awb}
 839:               onChange={(e) => setAwb(e.target.value)}
 840:               placeholder="e.g. 7731 4402 9918"
 841:             />
 842:           </Field>
 843:           {!o.branch && (
 844:             <Note tone="amber" icon="alert">
 845:               لم يتم تخصيص مخزون لهذا الطلب بعد — قد يرفض النظام إنشاء الشحنة.
 846:             </Note>
 847:           )}
 848:         </div>
 849:       </Modal>
 850:     </div>
 851:   );
 852: }
