 854: /* ================= RETURNS ================= */
 855: export function ReturnsList({ go }: { go: (route: { m: string; id?: number | string }) => void }) {
 856:   const [st, setSt] = useState('');
 857:   const [q, setQ] = useState('');
 858:   const [create, setCreate] = useState(false);
 859:   const toast = useToast();
 860:   const [page, setPage] = useState(1);
 861:   const dq = useDebounced(q);
 862:   useEffect(() => { setPage(1); }, [dq, st]);
 863:   const { data, loading, error, reload, usingMock } = useRemote(
 864:     (signal) => adminReturnsApi.list({ page, search: dq || undefined, status: (st === '' ? undefined : st) as ReturnStatus | undefined }, signal),
 865:     [page, dq, st],
 866:     {
 867:       mock: () => ({ data: [], meta: { current_page: 1, last_page: 1, per_page: 20, total: RETURNS.length, from: 1, to: RETURNS.length } } as any),
 868:       onError: (e) => toast(e.message, 'red'),
 869:     },
 870:   );
 871:   const branches = useRemote((s) => branchesApi.list({}, s).then((r) => r.data), []);
 872:   const branchMap = useMemo(() => new Map((branches.data ?? []).map((b: { id: number; name: string }) => [b.id, b.name] as const)), [branches.data]);
 873:   const rows = useMemo(
 874:     () => (usingMock ? RETURNS.filter((r) => (!st || r.status === st) && (!dq || (r.no + r.order + r.customer).includes(dq))) : (data?.data ?? []).map((r: any) => mapReturn(r, (id: number | null) => (id == null ? null : branchMap.get(id) ?? `#${id}`)))),
 875:     [data, usingMock, st, dq, branchMap],
 876:   );
 877:   const counts = useRemote(async (signal) => {
 878:     const qq = (status?: ReturnStatus) => adminReturnsApi.list({ status, page: 1 }, signal).then((r) => r.meta.total);
 879:     const entries = await Promise.all(Object.keys(RETURN_STATUS).map(async (k) => [k, await qq(k as ReturnStatus)] as const));
 880:     const total = await qq(undefined);
 881:     return { total, byStatus: Object.fromEntries(entries) as Record<string, number> };
 882:   }, []);
 883: 
 884:   return (
 885:     <div className="space-y-5">
 886:       <RemoteFeedback state={{ loading: false, error: null, usingMock, reload }} />
 887:       <PageHead
 888:         title="المرتجعات"
 889:         sub="الموافقة والاستلام ورد المبلغ تتم كخطوات منفصلة لكل مرتجع."
 890:         actions={
 891:           <button className="btn btn-dark" onClick={() => setCreate(true)}>
 892:             <Icon name="plus" size={14} />
 893:             إنشاء مرتجع
 894:           </button>
 895:         }
 896:       />
 897:       <Card stg={2} pad="p-4">
 898:         <div className="flex gap-2 overflow-x-auto">
 899:           <button
 900:             onClick={() => setSt('')}
 901:             className={'v-sub px-4 py-3 rounded-[14px] text-start min-w-[120px] transition ' + (!st ? 'ring-2' : '')}
 902:             style={!st ? { '--tw-ring-color': 'var(--accent)' } as any : {}}
 903:           >
 904:             <div className="text-[11.5px] tx2">الكل</div>
 905:             <div className="font-display text-[22px] font-bold num tx1">{counts.data?.total ?? '—'}</div>
 906:           </button>
 907:           {Object.entries(RETURN_STATUS).map(([k, s]) => (
 908:             <button
 909:               key={k}
 910:               onClick={() => setSt(k)}
 911:               className={'v-sub px-4 py-3 rounded-[14px] text-start min-w-[120px] transition ' + (st === k ? 'ring-2' : '')}
 912:               style={st === k ? { '--tw-ring-color': 'var(--accent)' } as any : {}}
 913:             >
 914:               <div className={'text-[11.5px] font-medium c-' + s.tone}>{s.label}</div>
 915:               <div className="font-display text-[22px] font-bold num tx1">
 916:                 {counts.data?.byStatus[k] ?? '—'}
 917:               </div>
 918:             </button>
 919:           ))}
 920:         </div>
 921:       </Card>
 922:       <Card stg={3}>
 923:         <div className="flex flex-wrap items-center gap-2 mb-4">
 924:           <SearchPill value={q} onChange={setQ} placeholder="رقم المرتجع أو الطلب" />
 925:         </div>
 926:         <DataTable
 927:           onRow={(r: ReturnRow) => go({ m: 'returns', id: r.id })}
 928:           rows={loading ? [] : rows}
 929:           empty={loading ? 'جارٍ التحميل…' : error && !usingMock
 930:             ? <Empty icon="alert" title="تعذّر تحميل المرتجعات" text={error.message}
 931:                 action={<button className="btn btn-soft btn-sm" onClick={reload}>إعادة المحاولة</button>} />
 932:             : undefined}
 933:           cols={[
 934:             { h: 'رقم المرتجع', r: (r) => <span className="num font-semibold tx1">{r.no}</span> },
 935:             {
 936:               h: 'الطلب الأصلي',
 937:               r: (r) => (
 938:                 <span className="num tx2 underline decoration-dotted underline-offset-4">{r.order}</span>
 939:               ),
 940:             },
 941:             {
 942:               h: 'العميل',
 943:               r: (r) => (
 944:                 <div className="flex items-center gap-2">
 945:                   <Avatar name={r.customer} tone={r.id} size={26} />
 946:                   <span className="font-medium tx1">{r.customer}</span>
 947:                 </div>
 948:               ),
 949:             },
 950:             {
 951:               h: 'الفرع',
 952:               r: (r) =>
 953:                 r.branch ? <span className="tx2">{r.branch}</span> : <span className="tx3 text-[11.5px]">يحدد عند الموافقة</span>,
 954:             },
 955:             { h: 'الحالة', r: (r) => <StatusBadge map={RETURN_STATUS} value={r.status} /> },
 956:             {
 957:               h: 'طريقة الرد',
 958:               r: (r) =>
 959:                 r.method ? (
 960:                   <span className="tx2">{REFUND_METHODS[r.method] || r.method}</span>
 961:                 ) : (
 962:                   <span className="tx3">—</span>
 963:                 ),
 964:             },
 965:             { h: 'إجمالي الاسترداد', r: (r) => <span className="font-semibold">{fmtMoney(r.total)}</span> },
 966:             { h: 'تاريخ الإنشاء', r: (r) => <Num className="tx2">{r.date}</Num> },
 967:           ]}
 968:         />
 969:         <Pager total={data?.meta.total ?? rows.length} per={data?.meta.per_page ?? 20} page={page} onPage={setPage} />
 970:       </Card>
 971:       <CreateReturnModal open={create} onClose={() => setCreate(false)} onSaved={() => { reload(); counts.reload(); }} />
 972:     </div>
 973:   );
 974: }
