 976: export function CreateReturnModal({ open, onClose, onSaved }: { open: boolean; onClose: () => void; onSaved?: () => void }) {
 977:   const toast = useToast();
 978:   const { busy, run } = useAction();
 979:   const f = useFormState({ reason: '', refund_method: '' });
 980:   const [orderId, setOrderId] = useState('');
 981:   const [orderQuery, setOrderQuery] = useState('');
 982:   const dqOrder = useDebounced(orderQuery);
 983:   const [lines, setLines] = useState([{ item: '', qty: 1, reason: '' }]);
 984:   const set = (i: number, k: string, v: any) =>
 985:     setLines(lines.map((l, j) => (j === i ? { ...l, [k]: v } : l)));
 986: 
 987:   const deliveredOrders = useRemote(
 988:     (signal) => adminOrdersApi.list({ search: dqOrder || undefined, status: 'delivered' as OrderStatus }, signal).then((r) => r.data),
 989:     [dqOrder],
 990:     { enabled: open, mock: () => ORDERS.filter((o) => o.status === 'delivered').map((o) => ({ id: o.id, order_number: o.no } as any)) },
 991:   );
 992:   const selectedOrder = useRemote(
 993:     (signal) => (orderId ? adminOrdersApi.show(Number(orderId), signal) : Promise.resolve(null as any)),
 994:     [orderId],
 995:     { enabled: open && !!orderId, mock: () => mockOrder(Number(orderId)) },
 996:   );
 997:   const orderItems = (selectedOrder.data as any)?.items ?? [];
 998:   useEffect(() => { setLines([{ item: '', qty: 1, reason: '' }]); }, [orderId]);
 999: 
1000:   const submit = async () => {
1001:     if (selectedOrder.usingMock || deliveredOrders.usingMock) return toast('البيانات المعروضة تجريبية — لم يتم الحفظ', 'red');
1002:     if (!orderId) return toast('اختر الطلب الأصلي', 'red');
1003:     if (!f.v.reason.trim()) { f.setErrors({ reason: 'سبب الإرجاع مطلوب' } as any); return toast('سبب الإرجاع مطلوب', 'red'); }
1004:     const items = lines
1005:       .filter((l) => l.item && Number(l.qty) > 0)
1006:       .map((l) => ({ order_item_id: Number(l.item), requested_qty: Number(l.qty), item_reason: l.reason || undefined }));
1007:     if (!items.length) return toast('أضف بندًا واحدًا على الأقل بكمية صحيحة', 'red');
1008:     const r = await run(() => adminReturnsApi.create({
1009:       order_id: Number(orderId),
1010:       reason: f.v.reason,
1011:       refund_method: (f.v.refund_method === 'bank' ? 'bank_transfer' : f.v.refund_method === 'original' ? 'original_payment' : f.v.refund_method || undefined) as RefundMethod | undefined,
1012:       items,
1013:     }), { toast, success: 'تم إنشاء طلب المرتجع', onFieldErrors: (e) => f.setErrors(e as any) });
1014:     if (r) { onSaved?.(); onClose(); toast(`تم إنشاء المرتجع ${(r as any).return_number ?? ''}`, 'green'); }
1015:   };
1016: 
1017:   return (
1018:     <Modal
