1050:               ))}
1051:             </select>
1052:           </Field>
1053:           <Field label="طريقة الاسترداد" hint="اختيارية — يمكن تحديدها عند رد المبلغ." err={(f.errors as any).refund_method}>
1054:             <select className="inp" value={f.v.refund_method} onChange={f.on('refund_method' as any)}>
1055:               <option value="">لم تُحدد</option>
1056:               {Object.entries(REFUND_METHODS).map(([k, l]) => (
