1059:                 </option>
1060:               ))}
1061:             </select>
1062:           </Field>
1063:         </div>
1064:         <Field label="سبب الإرجاع" req err={(f.errors as any).reason}>
1065:           <TextArea label="" req max={2000} placeholder="اشرح سبب الإرجاع" value={f.v.reason} onChange={(v) => f.set('reason' as any, v)} />
1066:         </Field>
1067:         <div>
1068:           <div className="flex items-center justify-between mb-2">
1069:             <span className="lbl">
1070:               البنود <span className="accent">*</span>
1071:             </span>
1072:             <span className="text-[11px] tx3">
1073:               من بند واحد حتى <Num>50</Num> بندًا · <Num>{lines.length}</Num>/50
1074:             </span>
1075:           </div>
1076:           <div className="v-sub p-2 space-y-2">
1077:             <div className="grid grid-cols-12 gap-2 px-2 pt-1 text-[11px] tx3">
1078:               <span className="col-span-5">بند الطلب</span>
1079:               <span className="col-span-2">الكمية</span>
1080:               <span className="col-span-4">سبب البند</span>
1081:             </div>
1082:             {lines.map((l, i) => (
1083:               <div key={i} className="grid grid-cols-12 gap-2 items-center">
1084:                 <select
1085:                   className="inp inp-sm col-span-5 !bg-[var(--bg-card)]"
1086:                   disabled={!orderId}
1087:                   value={l.item}
1088:                   onChange={(e) => set(i, 'item', e.target.value)}
1089:                 >
1090:                   <option value="">{orderId ? 'اختر بندًا' : 'اختر الطلب أولًا'}</option>
1091:                   {orderItems.map((it: any) => (
1092:                     <option key={String(it.product_variant_id ?? it.id)} value={String(it.id ?? it.product_variant_id)}>
1093:                       {it.product_name ?? it.name} · {it.sku}
1094:                     </option>
1095:                   ))}
1096:                 </select>
1097:                 <input
1098:                   type="number"
