1137: export function ReturnDetail({
1138:   id,
1139:   go,
1140: }: {
1141:   id: number | string;
1142:   go: (route: { m: string; id?: number | string }) => void;
1143: }) {
1144:   const toast = useToast();
1145:   const mayApprove = useCan('returns.approve');
1146:   const mayReceive = useCan('returns.receive');
1147:   const mayRefund = useCan('returns.refund');
1148:   const mayUpdate = useCan('returns.update');
1149:   const { busy, run } = useAction();
1150:   const numId = Number(id);
1151:   const remote = useRemote((s) => adminReturnsApi.show(numId, s), [numId], { mock: () => mockReturn(numId), onError: (e) => toast(e.message, 'red') });
1152:   const { data: ret, setData: setRet, loading } = remote;
1153:   const branches = useRemote((s) => branchesApi.list({}, s).then((r) => r.data), []);
1154:   const branchMap = useMemo(() => new Map((branches.data ?? []).map((b: { id: number; name: string }) => [b.id, b.name] as const)), [branches.data]);
1155:   const fb = useMemo(() => (ret ? mapReturn(ret, (bid) => (bid == null ? null : branchMap.get(bid) ?? `#${bid}`)) : null), [ret, branchMap]);
1156:   const base = RETURNS.find((r) => r.id === numId) || RETURNS[0];
1157:   const r = useMemo(() => fb ?? base, [fb, base]);
1158:   const [modal, setModal] = useState<string | null>(null);
1159:   const [approveBranch, setApproveBranch] = useState('');
1160:   const [rejectMode, setRejectMode] = useState('rejected');
1161:   const [approveQtys, setApproveQtys] = useState<Record<number, number>>({});
1162:   const [goodQtys, setGoodQtys] = useState<Record<number, number | undefined>>({});
1163:   const [damagedQtys, setDamagedQtys] = useState<Record<number, number | undefined>>({});
1164:   const [refundMethod, setRefundMethod] = useState('');
1165:   const [refundRef, setRefundRef] = useState('');
1166:   const [rejectNotes, setRejectNotes] = useState('');
1167:   const [approveNotes, setApproveNotes] = useState('');
1168:   useEffect(() => { if (ret) setApproveBranch(ret.branch_id ? String(ret.branch_id) : ''); }, [ret]);
1169: 
1170:   const approve = async () => {
1171:     if (!ret || remote.usingMock) return;
1172:     if (!approveBranch) return toast('اختر الفرع المستلم', 'red');
1173:     const items = (ret.items ?? []).map((it) => ({ id: it.id, approved_qty: approveQtys[it.id] ?? it.requested_qty }));
1174:     const res = await run(() => adminReturnsApi.approve(ret.id, {
1175:       branch_id: Number(approveBranch),
1176:       items,
1177:       admin_notes: approveNotes || undefined,
1178:     }), { toast, success: 'تمت الموافقة على المرتجع' });
1179:     if (res) { setRet(res); setModal(null); }
1180:   };
1181: 
1182:   const receive = async () => {
1183:     if (!ret || remote.usingMock) return;
1184:     const missing = (ret.items ?? []).filter((it) => goodQtys[it.id] === undefined || damagedQtys[it.id] === undefined);
1185:     if (missing.length > 0) return toast('أدخل الكمية السليمة والتالفة لكل بند بعد الفحص الفعلي', 'red');
1186:     const items = (ret.items ?? []).map((it) => ({ id: it.id, received_good_qty: goodQtys[it.id] ?? 0, received_damaged_qty: damagedQtys[it.id] ?? 0 }));
1187:     const res = await run(() => adminReturnsApi.receive(ret.id, { items }), { toast, success: 'تم استلام المرتجع وفحصه' });
1188:     if (res) { setRet(res); setModal(null); }
1189:   };
1190: 
1191:   const refund = async () => {
1192:     if (!ret || remote.usingMock) return;
1193:     const res = await run(() => adminReturnsApi.refund(ret.id, { refund_method: (refundMethod === 'bank' ? 'bank_transfer' : refundMethod === 'original' ? 'original_payment' : refundMethod || ret.refund_method || undefined) as RefundMethod | undefined, refund_reference: refundRef || undefined }), { toast, success: 'تم تنفيذ الاسترداد' });
1194:     if (res) { setRet(res); setModal(null); }
1195:   };
1196: 
1197:   const rejectOrCancel = async () => {
1198:     if (!ret || remote.usingMock) return;
1199:     const res = await run(() => adminReturnsApi.update(ret.id, { status: rejectMode as 'rejected' | 'cancelled', admin_notes: rejectNotes || undefined }), { toast, success: 'تم التحديث' });
1200:     if (res) { setRet(res); setModal(null); }
1201: 
1202:   };
1203: 
1204:   if (loading || !ret) return <><RemoteFeedback state={remote} />{!loading && !remote.error && <Empty title="المرتجع غير موجود" />}</>;
1205: 
1206:   const lines = (ret?.items ?? []).map((it) => ({
1207:     v: { name: it.product_name ?? `#${it.order_item_id}`, sku: it.sku ?? '' },
1208:     req: it.requested_qty,
1209:     appr: it.approved_qty,
1210:     good: it.received_good_qty,
1211:     dmg: it.received_damaged_qty,
1212:     price: num(it.unit_refund_price),
1213:     reason: it.item_reason ?? '',
1214:     files: 0,
1215:     id: it.id,
1216:   }));
1217:   const displayLines = lines;
1218:   const steps = [
1219:     { k: 'pending', l: 'طلب الإرجاع' },
1220:     { k: 'approved', l: 'الموافقة' },
1221:     { k: 'received', l: 'الاستلام والفحص' },
1222:     { k: 'refunded', l: 'رد المبلغ' },
1223:   ];
1224:   const order = ['pending', 'approved', 'received', 'refunded'];
1225:   const idx = order.indexOf(r.status);
1226:   const closed = ['rejected', 'cancelled'].includes(r.status);
1227: 
1228:   return (
1229:     <div className="space-y-5">
1230:       <RemoteFeedback state={remote} />
1231:       <PageHead
1232:         back={{ label: 'كل المرتجعات', onClick: () => go({ m: 'returns' }) }}
1233:         title={
1234:           <span className="flex items-center gap-3">
1235:             <span className="num">{r.no}</span>
1236:             <StatusBadge map={RETURN_STATUS} value={r.status} />
1237:           </span>
1238:         }
1239:         sub={
1240:           <span>
1241:             عن الطلب <span className="num font-semibold tx1">{r.order}</span> · {r.customer}
1242:           </span>
1243:         }
1244:         actions={
1245:           <>
1246:             {r.status === 'pending' && (
1247:               <>
1248:                 <button className="btn btn-danger" disabled={!mayUpdate || remote.usingMock || busy} onClick={() => setModal('reject')}>
1249:                   رفض / إلغاء
1250:                 </button>
1251:                 <button className="btn btn-dark" disabled={!mayApprove || remote.usingMock || busy} onClick={() => setModal('approve')}>
1252:                   <Icon name="check" size={14} />
1253:                   الموافقة
1254:                 </button>
1255:               </>
1256:             )}
1257:             {r.status === 'approved' && (
1258:               <>
1259:                 <button
1260:                   className="btn btn-soft"
1261:                   onClick={() => {
1262:                     setRejectMode('cancelled');
1263:                     setModal('reject');
1264:                   }}
1265:                 >
1266:                   إلغاء
1267:                 </button>
1268:                 <button className="btn btn-dark" disabled={!mayReceive || remote.usingMock || busy} onClick={() => setModal('receive')}>
1269:                   <Icon name="box" size={14} />
1270:                   الاستلام والفحص
1271:                 </button>
1272:               </>
1273:             )}
1274:             {r.status === 'received' && (
1275:               <button className="btn btn-accent" disabled={!mayRefund || remote.usingMock || busy} onClick={() => setModal('refund')}>
1276:                 <Icon name="wallet" size={14} />
1277:                 رد المبلغ
1278:               </button>
1279:             )}
1280:           </>
1281:         }
1282:       />
1283: 
1284:       <Card stg={2} pad="p-5">
1285:         {closed ? (
1286:           <Note tone={r.status === 'rejected' ? 'red' : 'gray'} icon="ban">
1287:             هذا المرتجع {RETURN_STATUS[r.status]?.label || r.status} — لا توجد خطوات إضافية.
1288:           </Note>
1289:         ) : (
1290:           <div className="grid grid-cols-4 gap-2">
1291:             {steps.map((s, i) => {
1292:               const done = i <= idx,
1293:                 cur = i === idx + 1;
1294:               return (
1295:                 <div key={s.k} className="flex flex-col gap-2">
1296:                   <div
1297:                     className="h-2 rounded-full overflow-hidden"
1298:                     style={{ background: done ? 'var(--accent)' : 'transparent' }}
1299:                   >
1300:                     {!done && <div className="h-full hatch-track" />}
1301:                   </div>
1302:                   <div className="flex items-center gap-2">
1303:                     <span
1304:                       className={
1305:                         'w-5 h-5 rounded-full flex items-center justify-center text-[10px] font-bold num ' +
1306:                         (done ? 'btn-accent' : cur ? 'btn-dark' : 'v-well')
1307:                       }
1308:                     >
1309:                       {done ? <Icon name="check" size={10} sw={3} /> : i + 1}
1310:                     </span>
1311:                     <span className={'text-[12.5px] font-medium ' + (done || cur ? 'tx1' : 'tx3')}>
1312:                       {s.l}
1313:                     </span>
1314:                   </div>
1315:                 </div>
1316:               );
1317:             })}
1318:           </div>
1319:         )}
1320:       </Card>
1321: 
1322:       <div className="grid grid-cols-1 lg:grid-cols-12 gap-5">
1323:         <Card stg={3} className="lg:col-span-8">
1324:           <CardHead title="بنود المرتجع" />
1325:           <DataTable
1326:             compact
1327:             rows={displayLines}
1328:             cols={[
1329:               {
1330:                 h: 'المنتج',
1331:                 r: (l) => (
1332:                   <div className="leading-tight">
1333:                     <div className="font-semibold tx1">{l.v.name}</div>
1334:                     <div className="text-[11px] tx3 num ltr">{l.v.sku}</div>
1335:                   </div>
1336:                 ),
1337:               },
1338:               { h: 'مطلوب', align: 'center', r: (l) => <Num>{l.req}</Num> },
1339:               {
1340:                 h: 'موافق عليه',
1341:                 align: 'center',
1342:                 r: (l) => (l.appr == null ? <span className="tx3">—</span> : <Num className="font-semibold">{l.appr}</Num>),
1343:               },
1344:               {
1345:                 h: 'سليم',
1346:                 align: 'center',
1347:                 r: (l) => (l.good == null ? <span className="tx3">—</span> : <Num className="c-green font-semibold">{l.good}</Num>),
1348:               },
1349:               {
1350:                 h: 'تالف',
1351:                 align: 'center',
1352:                 r: (l) => (l.dmg == null ? <span className="tx3">—</span> : <Num className="c-red font-semibold">{l.dmg}</Num>),
1353:               },
1354:               { h: 'سعر الاسترداد', r: (l) => fmtMoney(l.price) },
1355:               {
1356:                 h: 'السبب والمرفقات',
1357:                 r: (l) => (
1358:                   <div className="leading-tight">
1359:                     <div className="text-[12px] tx1">{l.reason}</div>
1360:                     {l.files > 0 && (
1361:                       <div className="flex gap-1 mt-1.5">
1362:                         {Array.from({ length: l.files }).map((_, i) => (
1363:                           <span
1364:                             key={i}
1365:                             className="w-7 h-7 rounded-lg v-sub flex items-center justify-center tx3"
1366:                           >
1367:                             <Icon name="image" size={12} />
1368:                           </span>
1369:                         ))}
1370:                       </div>
1371:                     )}
1372:                   </div>
1373:                 ),
1374:               },
1375:             ]}
1376:           />
1377:           <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 mt-5">
1378:             <div className="v-sub p-4">
1379:               <div className="lbl mb-1.5">سبب الإرجاع</div>
1380:               <div className="text-[12.5px] tx1 leading-relaxed">
1381:                 {ret.reason ?? '—'}
1382:               </div>
1383:             </div>
1384:             <div className="v-sub p-4">
1385:               <div className="lbl mb-1.5">ملاحظات الإدارة</div>
1386:               <div className="text-[12.5px] tx1 leading-relaxed">
1387:                 {ret.admin_notes ?? '—'}
1388:               </div>
1389:             </div>
1390:           </div>
1391:         </Card>
1392:         <div className="lg:col-span-4 space-y-5">
1393:           <div className="v-card p-4 stg stg-3">
1394:             <div className="v-orange rounded-[18px] p-4">
1395:               <div className="text-[12.5px] text-white/90">إجمالي الاسترداد</div>
1396:               <div className="font-display text-[28px] font-bold num my-1.5 ltr">
1397:                 {fmtNum(r.total)} <span className="text-[13px] opacity-80">EGP</span>
1398:               </div>
1399:               <div className="text-[11px] text-white/80">محسوب من النظام حسب الكميات المعتمدة</div>
1400:             </div>
1401:             <div className="p-2 pt-4">
1402:               <KV
1403:                 items={[
1404:                   ['الفرع', r.branch],
1405:                   ['طريقة الاسترداد', r.method && (REFUND_METHODS[r.method] || r.method)],
1406:                   ['مرجع الاسترداد', r.status === 'refunded' ? <span className="num">{ret.refund_reference ?? '—'}</span> : null],
1407:                 ]}
1408:               />
1409:             </div>
1410:           </div>
1411:           <Card stg={4}>
1412:             <CardHead title="السجل" className="mb-4" />
1413:             <Timeline
1414:               items={[
1415:                 r.status === 'refunded' && {
1416:                   icon: 'wallet',
1417:                   body: (
1418:                     <div>
