1420:                       <div className="text-[11px] tx3">
1421:                         <Num>{toDate(ret.refunded_at)} {toTime(ret.refunded_at)}</Num>
1422:                       </div>
1423:                     </div>
1424:                   ),
1425:                 },
1426:                 idx >= 2 && {
1427:                   icon: 'box',
1428:                   body: (
1429:                     <div>
1430:                       <div className="text-[12.5px] font-medium tx1">تم الاستلام والفحص</div>
1431:                       <div className="text-[11px] tx3">
1432:                         <Num>{toDate(ret.received_at)} {toTime(ret.received_at)}</Num>
1433:                       </div>
1434:                     </div>
1435:                   ),
1436:                 },
1437:                 idx >= 1 && {
1438:                   icon: 'check',
1439:                   body: (
