1442:                       <div className="text-[11px] tx3">
1443:                         <Num>{toDate(ret.approved_at)} {toTime(ret.approved_at)}</Num>
1444:                       </div>
1445:                     </div>
1446:                   ),
1447:                 },
1448:                 {
1449:                   icon: 'plus',
1450:                   body: (
1451:                     <div>
1452:                       <div className="text-[12.5px] font-medium tx1">تم إنشاء المرتجع</div>
1453:                       <div className="text-[11px] tx3">
1454:                         {r.customer} · <Num>{r.date} {toTime(ret.created_at)}</Num>
1455:                       </div>
1456:                     </div>
1457:                   ),
1458:                 },
1459:               ].filter(Boolean) as any}
1460:             />
1461:           </Card>
1462:         </div>
1463:       </div>
1464: 
1465:       {/* approve modal */}
1466:       <Modal
1467:         open={modal === 'approve'}
1468:         onClose={() => setModal(null)}
1469:         title="الموافقة على المرتجع"
1470:         icon="check"
1471:         width={620}
1472:         footer={
1473:           <>
1474:             <button className="btn btn-soft" onClick={() => setModal(null)}>
1475:               إلغاء
1476:             </button>
1477:             <button
1478:               className="btn btn-dark"
1479:               disabled={remote.usingMock || !approveBranch || busy}
1480:               onClick={approve}
1481:             >
1482:               موافقة
1483:             </button>
1484:           </>
1485:         }
1486:       >
1487:         <div className="space-y-4">
1488:           <Field label="الفرع المستلم" req>
1489:             <select
1490:               className="inp"
1491:               value={approveBranch}
1492:               onChange={(e) => setApproveBranch(e.target.value)}
1493:             >
