 42: export function BarsChart({
 43:   data,
 44:   h = 210,
 45:   keyA,
 46:   keyB,
 47:   labelA,
 48:   labelB,
 49:   fmt = (v: any) => v,
 50: }: {
 51:   data: any[];
 52:   h?: number;
 53:   keyA: string;
 54:   keyB?: string;
 55:   labelA?: string;
 56:   labelB?: string;
 57:   fmt?: (v: any) => any;
 58: }) {
 59:   const max = Math.max(0, ...data.map((d) => (d[keyA] || 0) + (keyB ? d[keyB] || 0 : 0))) * 1.1 || 1;
 60:   const ticks = [1, 0.8, 0.6, 0.4, 0.2, 0].map((t) => max * t);
 61: 
 62:   return (
 63:     <div>
 64:       {labelA && (
 65:         <div className="flex items-center gap-4 text-[11px] mb-3 justify-end">
 66:           <span className="flex items-center gap-1.5 tx2 font-medium">
 67:             <span className="w-2.5 h-2.5 rounded-sm hatch-orange inline-block"></span>
 68:             {labelA}
 69:           </span>
 70:           {labelB && (
 71:             <span className="flex items-center gap-1.5 tx2 font-medium">
 72:               <span className="w-2.5 h-2.5 rounded-sm inline-block" style={{ background: 'var(--bar-loss)' }}></span>
 73:               {labelB}
 74:             </span>
 75:           )}
 76:         </div>
 77:       )}
 78:       <div className="flex gap-2.5" style={{ height: h }}>
 79:         <div className="flex flex-col justify-between text-[10px] tx3 pb-5 shrink-0 num text-end w-9">
 80:           {ticks.map((t, i) => (
 81:             <span key={i}>{t >= 1000 ? (t / 1000).toFixed(0) + 'k' : t.toFixed(0)}</span>
 82:           ))}
 83:         </div>
 84:         <div className="relative flex-1 pb-5">
 85:           <div className="absolute inset-x-0 top-0 bottom-5 flex flex-col justify-between pointer-events-none">
 86:             {ticks.map((_, i) => (
 87:               <div
 88:                 key={i}
 89:                 className="v-bb w-full"
 90:                 style={{ borderBottomStyle: i === ticks.length - 1 ? 'solid' : 'dashed' }}
 91:               ></div>
 92:             ))}
 93:           </div>
 94:           <div className="relative z-10 h-full flex items-end justify-between gap-1.5 px-1" dir="ltr">
 95:             {data.map((d, i) => (
 96:               <div key={i} className="group relative flex-1 h-full flex flex-col items-center justify-end">
 97:                 <div
 98:                   className="opacity-0 group-hover:opacity-100 pointer-events-none transition absolute -top-2 -translate-y-full z-20 px-2 py-1 rounded-md text-[10px] font-semibold whitespace-nowrap shadow-md num"
 99:                   style={{ background: 'var(--pill-active-bg)', color: 'var(--pill-active-text)' }}
100:                 >
101:                   {fmt(d[keyA])}
102:                   {keyB && ' · ' + fmt(d[keyB])}
103:                 </div>
104:                 <div className="w-full max-w-[28px] flex flex-col justify-end gap-[3px]" style={{ height: 'calc(100% - 0px)' }}>
105:                   <div
106:                     className="w-full rounded-[6px] hatch-orange transition-all duration-500"
107:                     style={{ height: (d[keyA] / max) * 100 + '%' }}
108:                   ></div>
109:                   {keyB && (
110:                     <div
111:                       className="w-full rounded-[6px] transition-all duration-500"
112:                       style={{ height: (d[keyB] / max) * 100 + '%', background: 'var(--bar-loss)' }}
113:                     ></div>
114:                   )}
115:                 </div>
116:                 <span
117:                   className="absolute -bottom-0 text-[10px] tx3 font-medium num translate-y-0"
118:                   style={{ bottom: -2 }}
119:                 >
120:                   {d.l}
121:                 </span>
122:               </div>
123:             ))}
124:           </div>
125:         </div>
126:       </div>
127:     </div>
128:   );
129: }
