131: const today = () => toDate(new Date().toISOString());
132: type PeriodProps = { from: string; to: string; setFrom: (v: string) => void; setTo: (v: string) => void };
133: export function ReportsPage() {
134:   const [from, setFrom] = useState(() => today().slice(0, 8) + '01');
135:   const [to, setTo] = useState(today);
136:   const period = { from, to, setFrom, setTo };
137:   const [tab, setTab] = useState<'sales' | 'inv' | 'profit' | 'sup' | 'shifts'>('sales');
138: 
139:   return (
140:     <div className="space-y-5">
141:       <PageHead title="التقارير" sub="أقصى فترة لأي تقرير 366 يومًا." />
142:       <TabsBar
143:         value={tab}
144:         onChange={(v: any) => setTab(v)}
145:         tabs={[
146:           { value: 'sales', label: 'المبيعات', icon: 'chart' },
147:           { value: 'inv', label: 'المخزون', icon: 'box' },
148:           { value: 'profit', label: 'الأرباح', icon: 'percent' },
149:           { value: 'shifts', label: 'الورديات', icon: 'clock' },
150:         ]}
151:       />
152:       {tab === 'sales' && <SalesReport {...period} />}
153:       {tab === 'inv' && <InventoryReport />}
154:       {tab === 'profit' && <ProfitReport {...period} />}
155:       {tab === 'sup' && <SupplierReport />}
156:       {tab === 'shifts' && <ShiftReport {...period} />}
157:     </div>
158:   );
159: }
