161: export function DateRange({
162:   from,
163:   to,
164:   setFrom,
165:   setTo,
166: }: {
167:   from: string;
168:   to: string;
169:   setFrom: (v: string) => void;
170:   setTo: (v: string) => void;
171: }) {
172:   const periodError = validatePeriod(from, to);
173: 
174:   return (
175:     <>
176:       <FDate label="من" value={from} onChange={setFrom} />
177:       <FDate label="إلى" value={to} onChange={setTo} />
178:       {periodError && (
179:         <span className="badge t-red">
180:           <Icon name="alert" size={11} />
181:           {periodError}
182:         </span>
183:       )}
184:     </>
185:   );
186: }
