188: export function SalesReport({ from, to, setFrom, setTo }: PeriodProps) {
189:   const [grp, setGrp] = useState<'day' | 'month'>('month');
190:   const [by, setBy] = useState('');
191:   const periodErr = validatePeriod(from, to);
192:   const live = useRemote(signal => reportsApi.sales({ from, to, granularity: grp === 'month' ? 'monthly' : 'daily', group_by: (by || undefined) as 'branch' | 'channel' | undefined }, signal), [from, to, grp, by], { enabled: !periodErr, mock: mockSales });
193:   const data = (live.data?.rows ?? []).map(r => ({ l: [r.period, r.group_label].filter(Boolean).join(' · '), gross: num(r.gross_sales), disc: num(r.discounts), tax: num(r.tax), ship: num(r.shipping), orders: num(r.orders_count), net: num(r.net_sales) }));
194:   const tot = (k: 'gross' | 'disc' | 'tax' | 'ship' | 'orders' | 'net') => data.reduce((a, d) => a + d[k], 0);
195: 
196:   return (
197:     <>
198:       <RemoteFeedback state={live} />
199:       <Card stg={3} pad="p-4">
200:         <div className="flex flex-wrap items-center gap-2">
201:           <DateRange {...{ from, to, setFrom, setTo }} />
202:           <Seg
203:             value={grp}
204:             onChange={(v: any) => setGrp(v)}
205:             options={[
206:               { value: 'day', label: 'يومي' },
207:               { value: 'month', label: 'شهري' },
208:             ]}
209:           />
210:           <FSelect
211:             value={by}
212:             onChange={setBy}
213:             placeholder="بدون تقسيم"
214:             options={[
215:               { value: 'branch', label: 'حسب الفرع' },
216:               { value: 'channel', label: 'حسب القناة' },
217:             ]}
218:           />
219:         </div>
220:       </Card>
221:       <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 stg stg-3">
222:         <KPI
223:           hero
224:           label="إجمالي المبيعات"
225:           icon="chart"
226:           value={<span className="ltr">{(tot('gross') / 1e6).toFixed(2)}M</span>}
227:           foot="EGP شامل الضرائب"
228:         />
229:         <KPI
230:           label="صافي المبيعات"
231:           icon="wallet"
232:           value={<span className="ltr">{(tot('net') / 1e6).toFixed(2)}M</span>}
233:           foot="بعد الخصومات"
234:         />
235:         <KPI label="الطلبات المكتملة" icon="orders" value={fmtInt(tot('orders'))} />
236:         <KPI
237:           label="متوسط قيمة الطلب"
238:           icon="tag"
239:           value={<span className="ltr">{fmtNum((tot('orders') ? tot('gross') / tot('orders') : 0), 0)}</span>}
240:           foot="EGP"
241:         />
242:       </div>
243:       <Card stg={4}>
244:         <CardHead title="حركة المبيعات" sub="مقارنة إجمالي المبيعات بالصافي بعد الخصومات" />
245:         <BarsChart
246:           data={data}
247:           keyA="gross"
248:           keyB="disc"
249:           labelA="إجمالي المبيعات"
250:           labelB="الخصومات"
251:           fmt={(v) => fmtMoney(v, 0)}
252:         />
253:       </Card>
254:       <Card stg={4}>
255:         <DataTable
256:           rows={data}
257:           cols={[
258:             { h: 'الفترة', r: (d) => <b className="num tx1">{d.l}</b> },
259:             { h: 'الطلبات', align: 'center', r: (d) => <Num>{fmtInt(d.orders)}</Num> },
260:             { h: 'إجمالي المبيعات', r: (d) => fmtMoney(d.gross, 0) },
261:             {
262:               h: 'الخصومات',
263:               r: (d) => <span className="c-red">−{fmtMoney(d.disc, 0)}</span>,
264:             },
265:             { h: 'الضرائب', r: (d) => fmtMoney(d.tax, 0) },
266:             { h: 'الشحن', r: (d) => fmtMoney(d.ship, 0) },
267:             { h: 'صافي المبيعات', r: (d) => <b>{fmtMoney(d.net, 0)}</b> },
268:           ]}
269:         />
270:       </Card>
271:     </>
272:   );
273: }
