275: export function InventoryReport() {
276:   const [days, setDays] = useState(90);
277:   const validDays = Number.isInteger(days) && days >= 1 && days <= 3650;
278:   const live = useRemote(signal => reportsApi.inventory({ dead_days: days }, signal), [days], { enabled: validDays, mock: mockInventory });
279:   const br = (live.data?.valuation ?? []).map(r => ({ b: r.branch_name, variants: r.variants_count, qty: num(r.total_qty), value: num(r.total_value) }));
280:   const totV = br.reduce((a, x) => a + x.value, 0);
281: 
282:   return (
283:     <>
284:       <RemoteFeedback state={live} />
285:       {!validDays && <Note tone="red">عدد الأيام يجب أن يكون من 1 إلى 3650.</Note>}
286:       <Card stg={3} pad="p-4">
287:         <div className="flex flex-wrap items-center gap-3">
288:           <span className="text-[12px] tx2">اعتبار الصنف راكدًا بعد</span>
289:           <div className="flex items-center gap-2">
290:             <input
291:               type="number"
292:               min="1"
293:               className="pill-inp w-20 num text-center"
294:               value={days}
295:               onChange={(e) => setDays(Number(e.target.value))}
296:             />
297:             <span className="text-[12px] tx2">يومًا بدون حركة</span>
298:           </div>
299:           {days !== 90 && (
300:             <button className="btn btn-ghost btn-xs" onClick={() => setDays(90)}>
301:               الافتراضي 90
302:             </button>
303:           )}
304:         </div>
305:       </Card>
306:       <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 stg stg-3">
307:         <KPI
308:           hero
309:           label="القيمة الإجمالية"
310:           icon="box"
311:           value={<span className="ltr">{totV >= 1e6 ? (totV / 1e6).toFixed(2) + 'M' : fmtInt(totV)}</span>}
312:           foot="EGP بسعر التكلفة"
313:         />
314:         <KPI label="عدد المتغيرات بالفروع" value={fmtInt(br.reduce((a, x) => a + x.variants, 0))} />
315:         <KPI label="إجمالي الكميات" value={fmtInt(br.reduce((a, x) => a + x.qty, 0))} />
316:         <KPI
317:           label="أصناف راكدة"
318:           value={live.data?.dead_stock.length ?? 0}
319:           foot={
320:             <>
321:               بدون حركة منذ <Num>{days}</Num> يومًا
322:             </>
323:           }
324:         />
325:       </div>
326:       <div className="grid grid-cols-1 lg:grid-cols-12 gap-5">
327:         <Card stg={4} className="lg:col-span-6">
328:           <CardHead title="قيمة المخزون حسب الفرع" />
329:           <div className="space-y-3.5">
330:             {br.map((x) => (
331:               <div key={x.b}>
332:                 <div className="flex items-center justify-between text-[12px] mb-1.5">
333:                   <span className="font-medium tx1">{x.b}</span>
334:                   <span>{fmtMoney(x.value, 0)}</span>
335:                 </div>
336:                 <HatchBar pct={(totV ? x.value / totV : 0) * 100} h={12} />
337:                 <div className="flex gap-4 text-[11px] tx3 mt-1">
338:                   <span>
339:                     <Num>{x.variants}</Num> متغير
340:                   </span>
341:                   <span>
342:                     <Num>{fmtInt(x.qty)}</Num> وحدة
343:                   </span>
344:                 </div>
345:               </div>
346:             ))}
347:           </div>
348:         </Card>
349:         <Card
350:           stg={4}
351:           className="lg:col-span-6"
352:         >
353:           <CardHead
354:             title="الأصناف الراكدة"
