395: export function ProfitReport({ from, to, setFrom, setTo }: PeriodProps) {
396:   const periodErr = validatePeriod(from, to);
397:   const live = useRemote(signal => reportsApi.profit({ from, to }, signal), [from, to], { enabled: !periodErr, mock: mockProfit });
398:   const rev = num(live.data?.net_sales_revenue), cogs = num(live.data?.cogs), gross = num(live.data?.gross_profit), exp = num(live.data?.total_expenses), net = num(live.data?.net_profit);
399:   const steps: [string, number, string][] = [
400:     ['صافي إيراد المبيعات', rev, 'a'],
401:     ['تكلفة البضاعة', -cogs, 'b'],
402:     ['مجمل الربح', gross, 'a'],
403:     ['المصروفات', -exp, 'b'],
404:     ['صافي الربح', net, 'hero'],
405:   ];
406: 
407:   return (
408:     <>
409:       <RemoteFeedback state={live} />
410:       <Card stg={3} pad="p-4">
411:         <div className="flex flex-wrap items-center gap-2">
412:           <DateRange {...{ from, to, setFrom, setTo }} />
413:         </div>
414:       </Card>
415:       <div className="grid grid-cols-1 lg:grid-cols-12 gap-5">
416:         <Card stg={4} className="lg:col-span-7">
417:           <CardHead title="من الإيراد إلى صافي الربح" />
418:           <div className="space-y-3">
419:             {steps.map(([l, v, k]) => (
420:               <div key={l} className={'rounded-[16px] p-4 ' + (k === 'hero' ? 'v-orange' : 'v-sub')}>
421:                 <div className="flex items-center justify-between mb-2">
422:                   <span className={'text-[13px] font-medium ' + (k === 'hero' ? 'text-white' : 'tx1')}>{l}</span>
423:                   <span
424:                     className={
425:                       'font-display font-bold text-[16px] num ltr ' +
426:                       (k === 'hero' ? 'text-white' : v < 0 ? 'c-red' : 'tx1')
427:                     }
428:                   >
429:                     {fmtNum(v, 0)}
430:                   </span>
431:                 </div>
432:                 <div
433:                   className="h-2.5 rounded-full overflow-hidden"
434:                   style={{ background: k === 'hero' ? 'rgba(255,255,255,.2)' : 'transparent' }}
435:                 >
436:                   <div
437:                     className={'h-full rounded-full ' + (k === 'hero' ? 'bg-white' : k === 'a' ? 'hatch-orange' : '')}
438:                     style={{
439:                       width: (rev ? Math.abs(v) / Math.abs(rev) : 0) * 100 + '%',
440:                       background: k === 'b' ? 'var(--bar-loss)' : undefined,
441:                     }}
442:                   ></div>
443:                 </div>
444:               </div>
445:             ))}
446:           </div>
447:         </Card>
448:         <Card stg={4} className="lg:col-span-5">
449:           <CardHead title="الهوامش" />
450:           <div className="grid grid-cols-2 gap-3">
451:             <KPI hero label="هامش مجمل الربح" value={<Num>{(rev ? (gross / rev) * 100 : 0).toFixed(1)}%</Num>} />
452:             <KPI label="هامش صافي الربح" value={<Num>{(rev ? (net / rev) * 100 : 0).toFixed(1)}%</Num>} />
453:             <KPI label="تكلفة البضاعة" value={<Num>{(rev ? (cogs / rev) * 100 : 0).toFixed(1)}%</Num>} foot="من الإيراد" />
454:             <KPI label="المصروفات" value={<Num>{(rev ? (exp / rev) * 100 : 0).toFixed(1)}%</Num>} foot="من الإيراد" />
455:           </div>
456:         </Card>
457:       </div>
458:     </>
459:   );
460: }
