462: export function SupplierReport() {
463:   const live = useRemote(signal => reportsApi.suppliers(signal), [], { mock: mockSuppliers });
464:   const rows = live.data ?? [];
465:   const keys = ['not_due', 'overdue_1_30', 'overdue_31_60', 'overdue_61_90', 'overdue_90_plus'] as const;
466:   const aging: [string, number][] = ['غير مستحق', '1–30', '31–60', '61–90', '+90'].map((label, index) => [label, rows.reduce((sum, r) => sum + num(r.aging[keys[index]]), 0)]);
467:   if (live.error?.status === 403) return <Card><Empty title="هذا التقرير متاح للإدارة المركزية فقط" /></Card>;
468:   const tot = aging.reduce((a, x) => a + x[1], 0);
469: 
470:   return (
471:     <>
472:       <RemoteFeedback state={live} />
473:       <Note icon="lock" className="stg stg-3">
474:         يعرض البيانات الحالية بدون فلتر فترة، ويتطلب صلاحية وصول مركزي.
475:       </Note>
476:       <Card stg={3}>
477:         <CardHead
478:           title="أعمار مديونية الموردين"
479:           sub="إجمالي المستحق موزّعًا على فترات التأخير"
480:           right={<span className="font-display font-bold text-[18px]">{fmtMoney(tot, 0)}</span>}
481:         />
482:         <div className="flex h-10 rounded-full overflow-hidden gap-1 p-1 v-sub">
483:           {aging.map(([l, v], i) => (
484:             <div
485:               key={l}
486:               className="h-full rounded-full flex items-center justify-center text-[10.5px] font-semibold"
487:               style={{
488:                 width: (tot ? v / tot : 0) * 100 + '%',
489:                 background: ['#22c55e33', 'var(--accent-light)', '#e0491f99', '#e0491f', 'var(--bar-loss)'][i],
490:                 color: i >= 2 ? '#fff' : 'var(--text-primary)',
491:               }}
492:             >
493:               {(tot ? v / tot : 0) > 0.08 && <Num>{((v / tot) * 100).toFixed(0)}%</Num>}
494:             </div>
495:           ))}
496:         </div>
497:         <div className="grid grid-cols-5 gap-2 mt-4">
498:           {aging.map(([l, v], i) => (
499:             <div key={l} className="v-sub p-3">
500:               <div className="text-[11px] tx2">
501:                 {i === 0 ? (
502:                   l
503:                 ) : (
504:                   <>
505:                     متأخر <Num>{l}</Num> يوم
506:                   </>
507:                 )}
508:               </div>
509:               <div className="font-semibold text-[13px] mt-1">{fmtMoney(v, 0)}</div>
510:             </div>
511:           ))}
512:         </div>
513:       </Card>
514:       <Card stg={4}>
515:         <DataTable
516:           rows={rows}
517:           cols={[
518:             {
519:               h: 'المورد',
520:               r: (s) => (
521:                 <div className="flex items-center gap-2">
522:                   <Avatar name={s.supplier_name} tone={s.supplier_id} size={26} />
523:                   <span className="font-medium tx1">{s.supplier_name}</span>
524:                 </div>
525:               ),
526:             },
527:             {
528:               h: 'الرصيد',
529:               r: (s) => <b className={num(s.current_balance) < 0 ? 'c-green' : ''}>{fmtMoney(num(s.current_balance), 0)}</b>,
530:             },
531:             { h: 'إجمالي المشتريات', r: (s) => fmtMoney(num(s.total_purchases), 0) },
532:             { h: 'غير مستحق', r: (s) => fmtMoney(num(s.aging.not_due), 0) },
533:             { h: '1–30', r: (s) => fmtMoney(num(s.aging.overdue_1_30), 0) },
534:             { h: '31–60', r: (s) => fmtMoney(num(s.aging.overdue_31_60), 0) },
535:             { h: '61–90', r: (s) => fmtMoney(num(s.aging.overdue_61_90), 0) },
536:             {
537:               h: '+90',
538:               r: (s) => (
539:                 <span className={num(s.aging.overdue_90_plus) > 1000 ? 'c-red font-semibold' : ''}>
540:                   {fmtMoney(num(s.aging.overdue_90_plus), 0)}
541:                 </span>
542:               ),
543:             },
544:           ]}
545:         />
546:       </Card>
547:     </>
548:   );
