551: export function ShiftReport({ from, to, setFrom, setTo }: PeriodProps) {
552:   const [diffOnly, setDiffOnly] = useState(false);
553:   const periodErr = validatePeriod(from, to);
554:   const live = useRemote(signal => reportsApi.shifts({ from, to, only_differences: diffOnly }, signal), [from, to, diffOnly], { enabled: !periodErr, mock: mockShifts });
555:   const rows = (live.data?.rows ?? []).map(s => ({ ...s, no: s.shift_number, cashier: s.cashier_name, exp: num(s.expected_closing_cash), act: s.actual_closing_cash === null ? null : num(s.actual_closing_cash) }));
556:   const returnsExpenses = rows.reduce((sum, s) => sum + num(s.cash_returns_total) + num(s.cash_expenses_total), 0);
557:   const difference = rows.reduce((sum, s) => sum + num(s.cash_difference), 0);
558:   return (
559:     <>
560:       <RemoteFeedback state={live} />
561:       <Card stg={3} pad="p-4">
562:         <div className="flex flex-wrap items-center gap-2">
563:           <DateRange {...{ from, to, setFrom, setTo }} />
564:           <FChip on={diffOnly} onClick={() => setDiffOnly(!diffOnly)} icon="alert">
565:             الورديات ذات الفروق فقط
566:           </FChip>
567:         </div>
568:       </Card>
569:       <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 stg stg-3">
570:         <KPI hero label="المبيعات النقدية" value={<span className="ltr">{fmtNum(num(live.data?.totals.cash_sales))}</span>} foot="EGP" />
571:         <KPI label="مبيعات البطاقات" value={<span className="ltr">{fmtNum(num(live.data?.totals.card_sales))}</span>} foot="EGP" />
572:         <KPI label="المرتجعات والمصروفات" value={<span className="ltr">{fmtNum(returnsExpenses)}</span>} foot="للورديات المعروضة" />
573:         <KPI label="صافي الفروق" value={<span className="ltr c-red">{fmtNum(difference)}</span>} foot="صافي فرق الورديات المعروضة" />
574:       </div>
575:       <Card stg={4}>
576:         <DataTable
577:           rows={rows}
578:           cols={[
579:             { h: 'الوردية', r: (s) => <Num className="font-semibold">{s.no}</Num> },
580:             { h: 'الكاشير', r: (s) => s.cashier },
581:             { h: 'نقدي', r: (s) => fmtMoney(num(s.cash_sales_total), 0) },
582:             { h: 'بطاقات', r: (s) => fmtMoney(num(s.card_sales_total), 0) },
583:             { h: 'مرتجعات ومصروفات', r: (s) => fmtMoney(num(s.cash_returns_total) + num(s.cash_expenses_total), 0) },
584:             { h: 'المتوقعة', r: (s) => (s.exp != null ? fmtMoney(s.exp) : '—') },
585:             { h: 'الفعلية', r: (s) => (s.act != null ? fmtMoney(s.act) : '—') },
586:             { h: 'الفرق', r: (s) => <DiffCellR s={s} /> },
587:           ]}
588:         />
589:       </Card>
590:     </>
591:   );
592: }
593: 
594: export function DiffCellR({ s }: { s: any }) {
595:   if (s.act == null || s.exp == null) return <span>—</span>;
596:   const d = s.act - s.exp;
597:   return d === 0 ? (
598:     <Badge tone="green" dot={false}>
599:       مطابق
600:     </Badge>
601:   ) : (
602:     <span className={'font-semibold ' + (d < 0 ? 'c-red' : 'c-amber')}>
603:       {d < 0 ? 'عجز ' : 'زيادة '}
604:       <Num>{fmtNum(Math.abs(d))}</Num>
605:     </span>
606:   );
607: }
