613:   switch (n.type) {
614:     case 'order.created':
615:       return {
616:         icon: 'orders',
617:         tone: 'orange',
618:         text: (
619:           <>
620:             طلب جديد <b className="num">{d.order_no}</b> بقيمة {fmtMoney(d.total, 0)} من {d.channel}
621:           </>
622:         ),
623:       };
624:     case 'return.requested':
625:       return {
626:         icon: 'returns',
627:         tone: 'amber',
628:         text: (
629:           <>
630:             طلب إرجاع <b className="num">{d.return_no}</b> على الطلب <span className="num">{d.order_no}</span>
631:           </>
632:         ),
633:       };
634:     case 'payment_notice.submitted':
635:       return {
636:         icon: 'bank',
637:         tone: 'blue',
638:         text: (
639:           <>
640:             إشعار سداد <b className="num">{d.notice_no}</b> من {d.company} بمبلغ {fmtMoney(d.amount, 0)}
641:           </>
642:         ),
643:       };
644:     case 'shift.closed':
645:       return {
646:         icon: 'clock',
647:         tone: d.difference ? 'red' : 'green',
648:         text: (
649:           <>
650:             أُغلقت الوردية <b className="num">{d.shift_no}</b> — {d.cashier}
651:             {d.difference ? (
652:               <>
653:                 {' '}
654:                 · عجز <Num>{Math.abs(d.difference)}</Num>
655:               </>
656:             ) : (
657:               ''
658:             )}
659:           </>
660:         ),
661:       };
662:     case 'purchase_order.revision_requested':
663:       return {
664:         icon: 'cart',
665:         tone: 'violet',
666:         text: (
667:           <>
668:             {d.supplier} طلب تعديل أمر الشراء <b className="num">{d.po_no}</b>
669:           </>
670:         ),
671:       };
672:     case 'quotation.requested':
673:       return {
674:         icon: 'quote',
675:         tone: 'orange',
676:         text: (
677:           <>
678:             عرض أسعار <b className="num">{d.quote_no}</b> بانتظار التسعير — {d.company}
679:           </>
680:         ),
681:       };
682:     case 'stock.low':
683:       return {
684:         icon: 'box',
685:         tone: 'amber',
686:         text: (
687:           <>
688:             مخزون منخفض: <span className="num">{d.sku}</span> في {d.branch} (<Num>{d.qty}</Num> متبقي)
689:           </>
690:         ),
691:       };
692:     default:
693:       return {
694:         icon: 'bell',
695:         tone: 'gray',
696:         text: d.message || <span className="tx3 num">{n.type}</span>,
697:       };
698:   }
699: }
