756: export function NotifDrawer({
757:   open,
758:   onClose,
759:   items,
760:   onRead,
761:   go,
762:   container,
763: }: {
764:   open: boolean;
765:   onClose: () => void;
766:   items: NotificationItem[];
767:   onRead: (id: string) => void;
768:   go: (r: { m: string; id?: any; sub?: any }) => void;
769:   container?: Element | DocumentFragment | null;
770: }) {
771:   if (!open) return null;
772:   const unread = items.filter((n) => !n.read_at).length;
