783:             </div>
784:           </div>
785:           <button className="icon-btn" onClick={onClose}>
786:             <Icon name="x" size={14} />
787:           </button>
788:         </div>
789:         <div className="flex-1 overflow-y-auto px-3 space-y-1">
790:           {items.slice(0, 6).map((n) => (
791:             <NotifItem
792:               compact
793:               key={n.id}
794:               n={n}
795:               onRead={onRead}
796:               onOpen={(x) => {
797:                 onRead(x.id);
798:                 onClose();
799:                 const target = notificationTarget(x);
800:                 if (target) go(target);
801:               }}
802:             />
803:           ))}
804:         </div>
805:         <div className="p-4 v-bt">
806:           <button
807:             className="btn btn-dark w-full"
808:             onClick={() => {
809:               onClose();
810:               go({ m: 'notifications' });
811:             }}
812:           >
813:             عرض كل الإشعارات
814:           </button>
815:         </div>
816:       </div>
817:     </>
818:   );
819: 
820:   return container ? createPortal(content, container) : content;
821: }
