  52: const mapSupplier = (x: SupplierApi) => ({ demo: !!(x as any).__demo, id: x.id, code: x.code, name: x.name, company: x.company_name, phone: x.phone ?? '', email: x.email, terms: x.payment_terms_days, balance: num(x.current_balance), active: x.is_active, raw: x });
  53: const mapPR = (x: PRApi) => ({ demo: !!(x as any).__demo, id: x.id, no: x.request_number, branch: x.branch?.name ?? '', branchId: x.branch_id, status: x.status, by: x.requested_by ? `#${x.requested_by}` : '—', date: toDate(x.created_at), items: x.items?.length ?? 0, raw: x });
  54: const poStatus: Record<string, string> = { sent_to_supplier: 'sent', supplier_accepted: 'accepted', change_requested: 'revision', partially_received: 'partial' };
  55: const toPOStatus = (v: string) => Object.entries(poStatus).find(([, ui]) => ui === v)?.[0] ?? v;
  56: const mapPO = (x: POApi) => ({ demo: !!(x as any).__demo, id: x.id, no: x.po_number, sup: x.supplier_id, branch: x.branch?.name ?? '', branchId: x.branch_id, status: poStatus[x.status] ?? x.status, eta: x.expected_delivery_date, total: num(x.grand_total), raw: x });
  57: const mapInvoice = (x: InvoiceApi) => ({ demo: !!(x as any).__demo, id: x.id, sys: x.invoice_number, supNo: x.supplier_invoice_no ?? '', sup: x.supplier_id, po: x.purchase_order?.po_number ?? null, poId: x.purchase_order_id, issue: x.issue_date ?? '', due: x.due_date, subtotal: num(x.subtotal), tax: num(x.tax_amount), paid: num(x.paid_amount), remaining: num(x.remaining_amount), status: x.status === 'partially_paid' ? 'partial' : x.status, file: !!x.attachment_url, raw: x });
  58: const paymentMethod = (m: string): 'cash' | 'bank_transfer' | 'check' => m === 'bank' ? 'bank_transfer' : m === 'cheque' ? 'check' : 'cash';
  59: const mapPayment = (x: SupplierPaymentApi) => ({ demo: !!(x as any).__demo, id: x.id, no: x.payment_number, sup: x.supplier_id, inv: x.invoice?.invoice_number ?? null, invId: x.supplier_invoice_id, amount: num(x.amount), method: x.payment_method === 'bank_transfer' ? 'bank' : x.payment_method === 'check' ? 'cheque' : 'cash', ref: x.reference_no, date: x.payment_date, notes: x.notes, void: x.voided_at ? { reason: x.void_reason ?? '', by: x.voided_by ? `#${x.voided_by}` : '—', at: x.voided_at } : null });
  60: async function allPages<T>(loadPage: (page: number) => Promise<{ data: T[]; meta: { last_page: number } }>): Promise<T[]> {
  61:   const first = await loadPage(1), rows = [...first.data];
  62:   for (let page = 2; page <= first.meta.last_page; page++) rows.push(...(await loadPage(page)).data);
  63:   return rows;
  64: }
  65: const mockSuppliers = SUPPLIERS.map(s => ({ id: s.id, code: s.code, name: s.name, company_name: s.company, email: s.email, phone: s.phone, payment_terms_days: s.terms, opening_balance: '0', current_balance: String(s.balance), is_active: s.active, tax_number: null, commercial_register: null, address: null, users: [] } as SupplierApi)).map(row => Object.assign(row, { __demo: true }) as SupplierApi);
  66: const mockPRs = PRS.map(p => ({ id: p.id, request_number: p.no, branch_id: 0, branch: { id: 0, name: p.branch }, requested_by: null, status: p.status, notes: null, items: [], created_at: p.date } as PRApi)).map(row => Object.assign(row, { __demo: true }) as PRApi);
  67: const mockPOs = POS.map(p => ({ id: p.id, po_number: p.no, supplier_id: p.sup, branch_id: 0, branch: { id: 0, name: p.branch }, purchase_request_id: null, status: toPOStatus(p.status), expected_delivery_date: p.eta, grand_total: String(p.total), approved_by: null, supplier_change_notes: null, subtotal: String(p.total), tax_amount: '0', discount_amount: '0', items: [], deliveries: [] } as POApi)).map(row => Object.assign(row, { __demo: true }) as POApi);
  68: const mockInvoices = INVOICES.map(i => ({ id: i.id, invoice_number: i.sys, supplier_invoice_no: i.supNo, supplier_id: i.sup, purchase_order_id: null, issue_date: i.issue, due_date: i.due, subtotal: String(i.subtotal), tax_amount: String(i.tax), total_amount: String(i.subtotal + i.tax), paid_amount: String(i.paid), remaining_amount: String(i.subtotal + i.tax - i.paid), status: i.status === 'partial' ? 'partially_paid' : i.status, attachment_url: null } as InvoiceApi)).map(row => Object.assign(row, { __demo: true }) as InvoiceApi);
  69: const mockPayments = SPAYMENTS.map(p => ({ id: p.id, payment_number: p.no, supplier_id: p.sup, supplier_invoice_id: null, invoice: p.inv ? { id: 0, invoice_number: p.inv, supplier_invoice_no: null } : null, amount: String(p.amount), payment_method: paymentMethod(p.method), reference_no: p.ref, payment_date: p.date, notes: p.notes, voided_at: p.void?.at ?? null, void_reason: p.void?.reason ?? null, voided_by: null } as SupplierPaymentApi)).map(row => Object.assign(row, { __demo: true }) as SupplierPaymentApi);
  70: const pageOf = <T,>(data: T[]) => ({ data, meta: { current_page: 1, last_page: 1, per_page: 20, total: data.length, from: data.length ? 1 : null, to: data.length || null } });
  71: function useSupplierLookup() {
