  73: }
  74: function useVariants() {
  75:   return useRemote(signal => commerceLookupsApi.variants(signal).then(rows => rows.map(v => ({ id: v.id, name: v.label, sku: '' }))), [], { mock: () => VARIANTS.map((v, id) => ({ id: id + 1, name: v.name, sku: v.sku })) });
  76: }
