 100: export function ItemsEditor({
 101:   cols,
 102:   max = 50,
 103:   init = 1,
 104:   extra,
 105:   items, onItemsChange,
 106: }: {
 107:   cols: { h: string; fr: string; el: (ri: number) => React.ReactNode }[];
 108:   max?: number;
 109:   init?: number;
 110:   extra?: React.ReactNode;
 111:   items?: any[]; onItemsChange?: (items: any[]) => void;
 112: }) {
 113:   const [localRows, setRows] = useState(Array.from({ length: init }).map((_, i) => ({ k: i })));
 114:   const rows = items ? items.map((_, k) => ({ k })) : localRows;
 115:   return (
 116:     <div>
 117:       <div className="flex items-center justify-between mb-2">
 118:         <span className="lbl">
 119:           البنود <span className="accent">*</span>
 120:         </span>
 121:         <span className="text-[11px] tx3">
 122:           <Num>{rows.length}</Num> / <Num>{max}</Num>
 123:         </span>
 124:       </div>
 125:       <div className="v-sub p-2 space-y-2">
 126:         <div
 127:           className="grid gap-2 px-1 text-[11px] tx3"
 128:           style={{ gridTemplateColumns: cols.map((c) => c.fr).join(' ') + ' 32px' }}
 129:         >
 130:           {cols.map((c, i) => (
 131:             <span key={i}>{c.h}</span>
 132:           ))}
 133:           <span></span>
 134:         </div>
 135:         {rows.map((r, ri) => (
 136:           <div
 137:             key={r.k}
 138:             className="grid gap-2 items-center"
 139:             style={{ gridTemplateColumns: cols.map((c) => c.fr).join(' ') + ' 32px' }}
 140:           >
 141:             {cols.map((c, i) => (
 142:               <Fragment key={i}>{c.el(ri)}</Fragment>
 143:             ))}
 144:             <button
 145:               className="icon-btn !w-7 !h-7"
 146:               disabled={rows.length === 1}
 147:               onClick={() => items && onItemsChange ? onItemsChange(items.filter((_, i) => i !== ri)) : setRows(rows.filter((x) => x.k !== r.k))}
 148:             >
 149:               <Icon name="trash" size={12} />
 150:             </button>
 151:           </div>
 152:         ))}
 153:         <button
 154:           className="btn btn-ghost btn-sm w-full"
 155:           disabled={rows.length >= max}
 156:           onClick={() => items && onItemsChange ? onItemsChange([...items, blankItem()]) : setRows([...rows, { k: Date.now() }])}
 157:         >
 158:           <Icon name="plus" size={13} />
 159:           إضافة بند
 160:         </button>
 161:       </div>
 162:       {extra}
 163:     </div>
 164:   );
 165: }
