 168: export function SuppliersList({ go }: { go: (r: { m: string; id?: any; sub?: any }) => void }) {
 169:   const toast = useToast();
 170:   const [q, setQ] = useState('');
 171:   const [form, setForm] = useState<SupplierRow | { id?: any } | null>(null);
 172:   const dq = useDebounced(q);
 173:   const [page, setPage] = useState(1);
 174:   useEffect(() => setPage(1), [dq]);
 175:   const list = useRemote((signal) => suppliersApi.list({ page, search: dq || undefined }, signal), [page, dq], { mock: () => pageOf(mockSuppliers.filter(s => !dq || (s.name + s.code + s.company_name).includes(dq))) });
 176:   const rows = (list.data?.data ?? []).map(mapSupplier);
 177:   const invoices = useRemote(signal => supplierInvoicesApi.list({}, signal), [], { mock: () => pageOf(mockInvoices) });
 178:   const orders = useRemote(signal => purchaseOrdersApi.list({}, signal), [], { mock: () => pageOf(mockPOs) });
 179:   const totalDue = rows.reduce((a, s) => a + Math.max(0, s.balance), 0);
 180: 
 181:   return (
 182:     <div className="space-y-5">
 183:       <PageHead
 184:         title="الموردون"
 185:         sub="بيانات الموردين وأرصدتهم وحسابات موظفيهم على بوابة الموردين."
 186:         actions={
 187:           <button className="btn btn-dark" onClick={() => setForm({})}>
 188:             <Icon name="plus" size={14} />
 189:             مورد جديد
 190:           </button>
 191:         }
 192:       />
 193:       <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 stg stg-2">
 194:         <KPI
 195:           hero
 196:           label="المستحق في الصفحة الحالية"
 197:           icon="wallet"
 198:           value={<span className="ltr">{fmtNum(totalDue, 0)}</span>}
 199:           small
 200:           foot="EGP · الأرصدة الدائنة"
 201:         />
 202:         <KPI
 203:           label="المفعّلون في الصفحة الحالية"
 204:           icon="factory"
 205:           value={rows.filter((s) => s.active).length}
 206:           foot={<>من أصل <Num>{list.data?.meta.total ?? 0}</Num></>}
 207:         />
 208:         <KPI
 209:           label="فواتير غير مسددة"
 210:           icon="receipt"
 211:           value={invoices.data?.data.filter((i) => ['posted', 'partially_paid'].includes(i.status)).length ?? 0}
 212:           foot="في الصفحة المحمّلة"
 213:         />
 214:         <KPI
 215:           label="أوامر شراء مفتوحة"
 216:           icon="cart"
 217:           value={orders.data?.data.filter((p) => ['sent_to_supplier', 'supplier_accepted', 'partially_received', 'change_requested'].includes(p.status)).length ?? 0}
 218:           foot="في الصفحة المحمّلة"
 219:         />
 220:       </div>
 221:       <Card stg={3}>
 222:         <div className="flex flex-wrap items-center justify-between gap-3 mb-4">
 223:           <SearchPill value={q} onChange={setQ} placeholder="اسم المورد، الشركة، أو الكود" />
 224:           <span className="text-[12px] tx3">
 225:             <Num>{rows.length}</Num> مورد
 226:           </span>
 227:         </div>
 228:         <RemoteFeedback state={list} />
 229:         <DataTable
 230:           rows={rows}
 231:           onRow={(s: SupplierRow) => go({ m: 'suppliers', id: s.id })}
 232:           cols={[
 233:             {
 234:               h: 'المورد',
 235:               r: (s: SupplierRow) => (
 236:                 <div className="flex items-center gap-2.5">
 237:                   <Avatar name={s.company || s.name} tone={s.id} size={32} />
 238:                   <div>
 239:                     <div className="font-semibold tx1">{s.company || s.name}</div>
 240:                     {s.company && <div className="text-[11.5px] tx3">{s.name}</div>}
 241:                   </div>
 242:                 </div>
 243:               ),
 244:             },
 245:             {
 246:               h: 'الكود',
 247:               r: (s: SupplierRow) => (
 248:                 <span className="num text-[11.5px] font-semibold v-sub px-2 py-1 rounded-md tx2">{s.code}</span>
 249:               ),
 250:             },
 251:             {
 252:               h: 'الهاتف',
 253:               r: (s: SupplierRow) => (
 254:                 <span className="num text-[12px] tx2 ltr" dir="ltr">
 255:                   {s.phone}
 256:                 </span>
 257:               ),
 258:             },
 259:             {
 260:               h: 'مدة السداد',
 261:               align: 'center',
 262:               r: (s: SupplierRow) => (
 263:                 <span className="text-[12px] tx2">
 264:                   <Num>{s.terms}</Num> يوم
 265:                 </span>
 266:               ),
 267:             },
 268:             {
 269:               h: 'الرصيد',
 270:               r: (s: SupplierRow) => (
 271:                 <div className="leading-tight">
 272:                   <div className={'font-semibold ' + (s.balance > 0 ? 'c-red' : s.balance < 0 ? 'c-green' : 'tx3')}>
 273:                     {fmtMoney(Math.abs(s.balance))}
 274:                   </div>
 275:                   <div className="text-[10.5px] tx3">
 276:                     {s.balance > 0 ? 'له علينا' : s.balance < 0 ? 'لنا عنده' : 'خالص'}
 277:                   </div>
 278:                 </div>
 279:               ),
 280:             },
 281:             { h: 'التفعيل', r: (s: SupplierRow) => <ActiveDot on={s.active} /> },
 282:             {
 283:               h: '',
 284:               r: (s: SupplierRow) => (
 285:                 <RowActions>
 286:                   <button className="icon-btn !w-7 !h-7" onClick={() => setForm(s)}>
 287:                     <Icon name="edit" size={13} />
 288:                   </button>
 289:                   <button
 290:                     className="icon-btn !w-7 !h-7"
 291:                     title="كشف حساب"
 292:                     onClick={() => go({ m: 'suppliers', id: s.id })}
 293:                   >
 294:                     <Icon name="file" size={13} />
 295:                   </button>
 296:                 </RowActions>
 297:               ),
 298:             },
 299:           ]}
 300:         />
 301:       </Card>
 302:       <Pager total={list.data?.meta.total ?? 0} per={20} page={page} onPage={setPage} />
 303:       {form && <SupplierForm blocked={list.usingMock} row={form.id ? (form as SupplierRow) : null} onClose={() => setForm(null)} onSaved={() => list.reload()} />}
 304:     </div>
 305:   );
 306: }
