 308: export function SupplierForm({ row, onClose, onSaved, blocked }: { row: SupplierRow | null; onClose: () => void; onSaved?: () => void; blocked?: boolean }) {
 309:   const toast = useToast();
 310:   const { busy, run } = useAction();
 311:   const f = useFormState({
 312:     name: row?.name ?? '', company: row?.company ?? '', phone: row?.phone ?? '', email: (row as any)?.email ?? '',
 313:     tax: (row as any)?.raw?.tax_number ?? '', cr: (row as any)?.raw?.commercial_register ?? '', terms: row?.terms ?? 30, opening: 0, address: (row as any)?.raw?.address ?? '', active: row?.active ?? true, code: (row as any)?.code ?? '',
 314:   });
 315:   const save = async () => {
 316:     if (blocked || (row as any)?.demo) return toast('البيانات المعروضة تجريبية؛ الحفظ غير متاح', 'red');
 317:     if (!f.v.name.trim() || !f.v.code.trim()) return toast('اسم المورد والكود مطلوبان', 'red');
 318:     const body: any = {
 319:       code: f.v.code,
 320:       name: f.v.name, company_name: (f.v.company as string) || null, email: (f.v.email as string) || null,
 321:       phone: (f.v.phone as string) || null, tax_number: (f.v.tax as string) || null, commercial_register: (f.v.cr as string) || null,
 322:       address: (f.v.address as string) || null, payment_terms_days: Number(f.v.terms || 0),
 323:       opening_balance: row ? undefined : Number(f.v.opening || 0), is_active: !!f.v.active,
 324:     };
 325:     const r = await run(() => (row ? suppliersApi.update((row as any).id, body) : suppliersApi.create(body)),
 326:       { toast, success: 'تم الحفظ', onFieldErrors: (e) => f.setErrors(mapErrors(e, { company_name: 'company', payment_terms_days: 'terms', opening_balance: 'opening', tax_number: 'tax', commercial_register: 'cr', is_active: 'active' })) });
 327:     if (r) { onSaved?.(); onClose(); }
 328:   };
 329:   return (
 330:     <Modal
 331:       open
 332:       onClose={onClose}
 333:       title={row ? 'تعديل مورد' : 'مورد جديد'}
 334:       icon="factory"
 335:       width={640}
 336:       footer={
 337:         <>
 338:           <button className="btn btn-soft" onClick={onClose}>
 339:             إلغاء
 340:           </button>
 341:           <button
 342:             className="btn btn-dark"
 343:             disabled={busy}
 344:             onClick={save}
 345:           >
 346:             حفظ
 347:           </button>
 348:         </>
 349:       }
 350:     >
 351:       <div className="space-y-4">
 352:         <div className="grid grid-cols-2 gap-3">
 353:           <Field label="الكود" req hint="فريد" err={f.errors.code}>
 354:             <input className="inp num" dir="ltr" value={f.v.code} onChange={f.on('code' as any)} placeholder="SUP-0001" />
 355:           </Field>
 356:           <Field label="اسم جهة الاتصال" req err={f.errors.name}>
 357:             <input className="inp" value={f.v.name} onChange={f.on('name')} />
 358:           </Field>
 359:           <Field label="اسم الشركة / المؤسسة" err={f.errors.company}>
 360:             <input className="inp" value={f.v.company} onChange={f.on('company' as any)} />
 361:           </Field>
 362:           <Field label="الهاتف" req err={f.errors.phone}>
 363:             <input className="inp num" dir="ltr" value={f.v.phone} onChange={f.on('phone' as any)} />
 364:           </Field>
 365:           <Field label="البريد الإلكتروني" err={f.errors.email}>
 366:             <input className="inp num" dir="ltr" type="email" value={f.v.email} onChange={f.on('email' as any)} />
 367:           </Field>
 368:           <Field label="الرقم الضريبي" err={f.errors.tax}>
 369:             <input className="inp num" dir="ltr" value={f.v.tax} onChange={f.on('tax' as any)} />
 370:           </Field>
 371:           <Field label="السجل التجاري" err={f.errors.cr}>
 372:             <input className="inp num" dir="ltr" value={f.v.cr} onChange={f.on('cr' as any)} />
 373:           </Field>
 374:           <Field label="مدة السداد الافتراضية (أيام)" req err={f.errors.terms}>
 375:             <input type="number" min="0" className="inp num" value={f.v.terms} onChange={f.on('terms' as any)} />
 376:           </Field>
 377:           {!row && (
 378:             <Field label="الرصيد الافتتاحي" err={f.errors.opening}>
 379:               <input type="number" step="0.01" className="inp num" value={f.v.opening} onChange={f.on('opening' as any)} />
 380:             </Field>
 381:           )}
 382:         </div>
 383:         <Field label="العنوان" err={f.errors.address}>
 384:           <input className="inp" value={f.v.address} onChange={f.on('address' as any)} />
 385:         </Field>
 386:         <ToggleRow label="مفعّل" on={f.v.active} onChange={(v) => f.set('active', v)} />
 387:       </div>
 388:     </Modal>
 389:   );
 390: }
