 392: export function SupplierDetail({ id, go }: { id: number; go: (r: { m: string; id?: any; sub?: any }) => void }) {
 393:   const toast = useToast();
 394:   const { busy, run } = useAction();
 395:   const sup = useRemote(signal => suppliersApi.show(id, signal).then(mapSupplier), [id], { mock: () => mapSupplier(mockSuppliers.find(s => s.id === id) ?? mockSuppliers[0]) });
 396:   const usersRemote = useRemote(signal => suppliersApi.users(id, signal), [id], { mock: () => [] });
 397:   const posRemote = useRemote(signal => allPages(page => purchaseOrdersApi.list({ page, supplier_id: id }, signal)).then(p => p.map(mapPO)), [id], { mock: () => mockPOs.filter(p => p.supplier_id === id).map(mapPO) });
 398:   const invRemote = useRemote(signal => allPages(page => supplierInvoicesApi.list({ page, supplier_id: id }, signal)).then(p => p.map(mapInvoice)), [id], { mock: () => mockInvoices.filter(p => p.supplier_id === id).map(mapInvoice) });
 399:   const payRemote = useRemote(signal => allPages(page => supplierPaymentsApi.list({ page, supplier_id: id }, signal)).then(p => p.map(mapPayment)), [id], { mock: () => mockPayments.filter(p => p.supplier_id === id).map(mapPayment) });
 400:   const [tab, setTab] = useState<'info' | 'users' | 'pos' | 'invs' | 'pays'>('info');
 401:   const [uform, setUform] = useState<any>(null);
 402:   const [udel, setUdel] = useState<any>(null);
