 407:   const pos = posRemote.data ?? [], invs = invRemote.data ?? [], pays = payRemote.data ?? [];
 408:   const saveUser = async () => {
 409:     if (sup.usingMock || usersRemote.usingMock) return toast('البيانات المعروضة تجريبية؛ الحفظ غير متاح', 'red');
 410:     const body = { name: uform.name ?? '', email: uform.email ?? '', phone: uform.phone || null, is_active: uform.active ?? true, ...(uform.password ? { password: uform.password } : {}) };
 411:     const result = await run(() => uform.id ? suppliersApi.updateUser(id, uform.id, body) : suppliersApi.createUser(id, body), { toast, success: uform.id ? 'تم الحفظ؛ تغيير البريد أو كلمة المرور أو التعطيل يسجّل خروج المستخدم من كل الأجهزة' : 'تم إنشاء الحساب', onFieldErrors: setUserErrors });
 412:     if (result) { setUform(null); usersRemote.reload(); }
 413:   };
 414:   const s = sup.data;
 415:   if (!s) return <Card><RemoteFeedback state={sup} /></Card>;
 416:   return (
 417:     <div className="space-y-5">
 418:       <PageHead
 419:         back={{ label: 'الموردون', onClick: () => go({ m: 'suppliers' }) }}
 420:         title={
 421:           <span className="flex items-center gap-3">
 422:             {s.company || s.name}
 423:             <ActiveDot on={s.active} />
 424:           </span>
 425:         }
 426:         sub={
 427:           <span>
 428:             <span className="num">{s.code}</span> · {s.name}
 429:           </span>
 430:         }
 431:         actions={
 432:           <><button className="btn btn-soft" onClick={() => setEdit(true)}>
 433:             <Icon name="edit" size={14} />
 434:             تعديل
 435:           </button><button className="btn btn-danger" disabled={busy || sup.usingMock} onClick={() => setDeleteSupplier(true)}><Icon name="trash" size={13} />حذف</button></>
 436:         }
 437:       />
 438:       <div className="grid grid-cols-1 lg:grid-cols-12 gap-5">
 439:         <div className="lg:col-span-4 v-card p-4 stg stg-2 self-start">
 440:           <div className="v-orange rounded-[18px] p-4">
