 442:             <div className="font-display text-[28px] font-bold num my-1.5 ltr">
 443:               {fmtNum(s.balance)} <span className="text-[13px] opacity-80">EGP</span>
 444:             </div>
 445:             <div className="text-[11px] text-white/80">
 446:               {s.balance > 0 ? 'مستحق للمورد' : s.balance < 0 ? 'رصيد مدين لصالحنا' : 'لا يوجد رصيد'}
 447:             </div>
 448:           </div>
 449:           <div className="grid grid-cols-3 gap-2 mt-3">
 450:             <div className="v-sub p-3 text-center">
 451:               <div className="text-[10.5px] tx3">أوامر</div>
 452:               <Num className="font-display text-[18px] font-bold">{pos.length}</Num>
 453:             </div>
 454:             <div className="v-sub p-3 text-center">
 455:               <div className="text-[10.5px] tx3">فواتير</div>
 456:               <Num className="font-display text-[18px] font-bold">{invs.length}</Num>
 457:             </div>
 458:             <div className="v-sub p-3 text-center">
