 460:               <Num className="font-display text-[18px] font-bold">{pays.length}</Num>
 461:             </div>
 462:           </div>
 463:         </div>
 464:         <div className="lg:col-span-8 space-y-4">
 465:           <TabsBar
 466:             value={tab}
 467:             onChange={(v: any) => setTab(v)}
 468:             tabs={[
 469:               { value: 'info', label: 'البيانات الأساسية' },
 470:               { value: 'users', label: 'حسابات الموظفين', count: users.length },
 471:               { value: 'pos', label: 'أوامر الشراء', count: pos.length },
 472:               { value: 'invs', label: 'الفواتير', count: invs.length },
