 482:                     ['الاسم', s.name],
 483:                     ['اسم الشركة', s.company || '—'],
 484:                     ['الهاتف', <Num>{s.phone}</Num>],
 485:                     ['البريد', s.email ? <Num>{s.email}</Num> : null],
