 513:                     <Icon name="plus" size={13} />
 514:                     حساب جديد
 515:                   </button>
 516:                 }
 517:               />
 518:               <DataTable
 519:                 rows={users}
 520:                 cols={[
 521:                   {
 522:                     h: 'الموظف',
 523:                     r: (u: any) => (
 524:                       <div className="flex items-center gap-2.5">
 525:                         <Avatar name={u.name} tone={u.id + 2} size={28} />
 526:                         <span className="font-semibold tx1">{u.name}</span>
 527:                       </div>
 528:                     ),
 529:                   },
 530:                   { h: 'البريد', r: (u: any) => <Num className="tx2 text-[12px]">{u.email}</Num> },
 531:                   {
 532:                     h: 'الهاتف',
 533:                     r: (u: any) => (u.phone ? <Num className="tx2 text-[12px]">{u.phone}</Num> : <span className="tx3">—</span>),
 534:                   },
 535:                   { h: 'التفعيل', r: (u: any) => <ActiveDot on={u.active} /> },
 536:                   {
 537:                     h: '',
 538:                     r: (u: any) => (
 539:                       <RowActions>
 540:                         <button className="icon-btn !w-7 !h-7" onClick={() => { setUserErrors({}); setUform(u); }}>
 541:                           <Icon name="edit" size={13} />
 542:                         </button>
 543:                         <button className="icon-btn !w-7 !h-7" onClick={() => setUdel(u)}>
 544:                           <Icon name="trash" size={13} />
 545:                         </button>
 546:                       </RowActions>
 547:                     ),
 548:                   },
 549:                 ]}
 550:               />
 551:             </Card>
 552:           )}
 553:           {tab === 'pos' && (
 554:             <Card stg={3}>
 555:               <RemoteFeedback state={posRemote} />
 556:               <DataTable
 557:                 rows={pos}
 558:                 onRow={() => go({ m: 'purchasing', sub: 'po' })}
 559:                 cols={[
 560:                   { h: 'رقم الأمر', r: (p: any) => <span className="num font-semibold">{p.no}</span> },
 561:                   { h: 'الفرع', r: (p: any) => <span className="tx2">{p.branch}</span> },
 562:                   { h: 'الحالة', r: (p: any) => <StatusBadge map={PO_STATUS} value={p.status} /> },
 563:                   { h: 'الإجمالي', r: (p: any) => fmtMoney(p.total) },
 564:                 ]}
 565:                 empty="لا توجد أوامر شراء لهذا المورد"
 566:               />
 567:             </Card>
 568:           )}
 569:           {tab === 'invs' && (
 570:             <Card stg={3}>
 571:               <RemoteFeedback state={invRemote} />
 572:               <DataTable
 573:                 rows={invs}
 574:                 cols={[
 575:                   { h: 'رقم النظام', r: (i: any) => <span className="num font-semibold">{i.sys}</span> },
 576:                   { h: 'رقم المورد', r: (i: any) => <Num className="tx2">{i.supNo}</Num> },
 577:                   { h: 'الإجمالي', r: (i: any) => fmtMoney(i.subtotal + i.tax) },
 578:                   {
 579:                     h: 'المتبقي',
 580:                     r: (i: any) => fmtMoney(i.subtotal + i.tax - i.paid),
 581:                   },
 582:                   { h: 'الحالة', r: (i: any) => <StatusBadge map={INV_STATUS} value={i.status} /> },
 583:                 ]}
 584:                 empty="لا توجد فواتير"
 585:               />
 586:             </Card>
 587:           )}
 588:           {tab === 'pays' && (
 589:             <Card stg={3}>
 590:               <RemoteFeedback state={payRemote} />
 591:               <DataTable
 592:                 rows={pays}
 593:                 cols={[
 594:                   { h: 'رقم الدفعة', r: (p: any) => <span className="num font-semibold">{p.no}</span> },
 595:                   { h: 'الوسيلة', r: (p: any) => SP_METHODS[p.method as keyof typeof SP_METHODS] },
 596:                   { h: 'المبلغ', r: (p: any) => fmtMoney(p.amount) },
 597:                   { h: 'التاريخ', r: (p: any) => <Num className="tx2">{p.date}</Num> },
 598:                 ]}
 599:                 empty="لا توجد مدفوعات"
 600:               />
 601:             </Card>
 602:           )}
 603:         </div>
 604:       </div>
 605:       <ConfirmModal open={deleteSupplier} onClose={() => setDeleteSupplier(false)} danger title="حذف المورد" text="لا يمكن حذف مورد مرتبط بأوامر أو فواتير أو دفعات أو مستخدمين." cta="حذف" onConfirm={async () => { if (sup.usingMock) return; const result = await run(() => suppliersApi.remove(id), { toast, success: 'تم حذف المورد' }); if (result) { go({ m: 'suppliers' }); return true; } return false; }} />
 606:       <RemoteFeedback state={sup} />
 607:       {edit && <SupplierForm blocked={sup.usingMock} row={s} onClose={() => setEdit(false)} onSaved={sup.reload} />}
 608:       {uform && (
 609:         <Modal
 610:           open
 611:           onClose={() => setUform(null)}
 612:           title={uform.id ? 'تعديل حساب موظف' : 'حساب موظف جديد'}
 613:           icon="user"
 614:           width={480}
 615:           footer={
 616:             <>
 617:               <button className="btn btn-soft" onClick={() => setUform(null)}>
 618:                 إلغاء
 619:               </button>
 620:               <button
 621:                 className="btn btn-dark"
 622:                 disabled={busy} onClick={saveUser}
 623:               >
 624:                 حفظ
 625:               </button>
 626:             </>
 627:           }
 628:         >
 629:           <div className="space-y-4">
 630:             <Field label="الاسم" req err={userErrors.name}>
 631:               <input className="inp" value={uform.name ?? ''} onChange={e => setUform({ ...uform, name: e.target.value })} />
 632:             </Field>
 633:             <Field label="البريد الإلكتروني" req err={userErrors.email}>
 634:               <input className="inp num" dir="ltr" value={uform.email ?? ''} onChange={e => setUform({ ...uform, email: e.target.value })} />
 635:             </Field>
 636:             <Field label="الهاتف">
 637:               <input className="inp num" dir="ltr" value={uform.phone ?? ''} onChange={e => setUform({ ...uform, phone: e.target.value })} />
 638:             </Field>
 639:             <Field label="كلمة المرور" req={!uform.id} err={userErrors.password}><input type="password" className="inp" value={uform.password ?? ''} onChange={e => setUform({ ...uform, password: e.target.value })} autoComplete="new-password" /></Field>
 640:             <ToggleRow label="مفعّل" on={uform.active ?? true} onChange={active => setUform({ ...uform, active })} />
 641:           </div>
 642:         </Modal>
 643:       )}
 644:       <ConfirmModal
 645:         open={!!udel}
 646:         onClose={() => setUdel(null)}
 647:         danger
 648:         title={'حذف حساب «' + (udel?.name || '') + '»'}
 649:         cta="حذف الحساب"
 650:         text="لن يتمكن الموظف من الدخول إلى بوابة الموردين بعد الحذف."
 651:         onConfirm={async () => { if (sup.usingMock || usersRemote.usingMock) return; const result = await run(() => suppliersApi.removeUser(id, udel.id), { toast, success: 'تم حذف الحساب وتسجيل الخروج من الأجهزة' }); if (result) { setUdel(null); usersRemote.reload(); return true; } return false; }}
 652:       />
 653:     </div>
 654:   );
 655: }
