 657: /* ---------------- PURCHASING PAGE ---------------- */
 658: export function PurchasingPage({ sub = 'pr' }: { sub?: string }) {
 659:   const [tab, setTab] = useState(sub);
 660:   const [paymentInvoice, setPaymentInvoice] = useState<any>(null);
 661:   useEffect(() => setTab(sub), [sub]);
 662: 
 663:   return (
 664:     <div className="space-y-5">
 665:       <PageHead title="المشتريات" sub="أربع وحدات مترابطة: من طلب الشراء حتى سداد فاتورة المورد." />
 666:       <div className="flex items-center gap-2 flex-wrap stg stg-2">
 667:         {[
 668:           ['pr', 'طلبات الشراء', 'file'],
 669:           ['po', 'أوامر الشراء', 'cart'],
 670:           ['inv', 'فواتير الموردين', 'receipt'],
 671:           ['pay', 'مدفوعات الموردين', 'cash'],
 672:         ].map(([k, l, ic], i) => (
 673:           <Fragment key={k}>
 674:             {i > 0 && <Icon name="chevL" size={14} className="tx3" />}
 675:             <button
 676:               onClick={() => setTab(k)}
 677:               className={'v-pill px-4 py-2 flex items-center gap-2 text-[13px] font-medium transition'}
 678:               style={
 679:                 tab === k
 680:                   ? { background: 'var(--pill-active-bg)', color: 'var(--pill-active-text)', borderColor: 'transparent' }
 681:                   : { color: 'var(--text-secondary)' }
 682:               }
 683:             >
 684:               <span className={'w-6 h-6 rounded-full flex items-center justify-center ' + (tab === k ? 'bg-white/15' : 'v-well')}>
 685:                 <Icon name={ic} size={12} />
 686:               </span>
 687:               {l}
 688:             </button>
 689:           </Fragment>
 690:         ))}
 691:       </div>
 692:       {tab === 'pr' && <PRModule />}
 693:       {tab === 'po' && <POModule />}
 694:       {tab === 'inv' && <InvModule onPayment={invoice => { setPaymentInvoice(invoice); setTab('pay'); }} />}
 695:       {tab === 'pay' && <PayModule initialInvoice={paymentInvoice} />}
 696:     </div>
 697:   );
 698: }
