 700: export function PRModule() {
 701:   const canApprove = useCan('purchase_requests.approve');
 702:   const toast = useToast();
 703:   const { busy, run } = useAction();
 704:   const [st, setSt] = useState('');
 705:   const [br, setBr] = useState('');
 706:   const [form, setForm] = useState<any>(null);
 707:   const [view, setView] = useState<any>(null);
 708: 
 709:   const [page, setPage] = useState(1);
 710:   const [errors, setErrors] = useState<Record<string, string>>({});
 711:   useEffect(() => setPage(1), [st, br]);
 712:   const list = useRemote(signal => purchaseRequestsApi.list({ page, status: st ? st as any : undefined, branch_id: br ? Number(br) : undefined }, signal), [page, st, br], { mock: () => pageOf(mockPRs.filter(p => !st || p.status === st)) });
 713:   const branches = useRemote((signal) => branchesApi.list({}, signal).then(r => r.data), []);
 714:   const variants = useVariants();
 715:   const rows = (list.data?.data ?? []).map(mapPR);
 716:   const detail = useRemote(signal => purchaseRequestsApi.show(view.id, signal), [view?.id], { enabled: !!view, mock: () => mockPRs.find(p => p.id === view.id)! });
 717:   const openForm = (pr?: any) => { setErrors({}); setForm({ demo: list.usingMock || pr?.demo, id: pr?.id, no: pr?.no, branchId: pr?.raw?.branch_id ?? '', notes: pr?.raw?.notes ?? '', items: pr?.raw?.items?.map((it: any) => ({ product_variant_id: it.product_variant_id, qty: it.requested_qty, notes: it.notes ?? '' })) ?? [blankItem()] }); };
 718:   const setItem = (index: number, key: string, value: string) => setForm({ ...form, items: form.items.map((it: any, i: number) => i === index ? { ...it, [key]: value } : it) });
 719:   const doAction = async (id: number, fn: (id: number) => Promise<unknown>, msg: string) => {
 720:     if ((fn === purchaseRequestsApi.approve || fn === purchaseRequestsApi.reject) && !canApprove) return toast('ليست لديك صلاحية اعتماد طلبات الشراء', 'red');
 721:     if (list.usingMock || view?.demo) return toast('البيانات المعروضة تجريبية؛ الحفظ غير متاح', 'red');
 722:     const r = await run(() => fn(id), { toast, success: msg });
 723:     if (r) { list.reload(); setView(null); }
 724:   };
 725:   const save = async (submit = false) => {
 726:     if (form.demo || list.usingMock || variants.usingMock || branches.usingMock) return toast('البيانات المعروضة تجريبية؛ الحفظ غير متاح', 'red');
 727:     if (!form.branchId || !form.items.length || form.items.some((it: any) => !it.product_variant_id || !Number.isInteger(Number(it.qty)) || Number(it.qty) <= 0)) return toast('اختر الفرع وأدخل متغيرات وكميات صحيحة', 'red');
 728:     const body = { branch_id: Number(form.branchId), notes: form.notes || null, items: form.items.map((it: any) => ({ product_variant_id: Number(it.product_variant_id), requested_qty: Number(it.qty), notes: it.notes || null })) };
 729:     const r = await run(() => form.id ? purchaseRequestsApi.update(form.id, body) : purchaseRequestsApi.create(body), { toast, onFieldErrors: setErrors, success: 'تم حفظ المسودة' });
 730:     if (!r) return;
 731:     if (submit) { const sent = await run(() => purchaseRequestsApi.submit(r.id), { toast, success: 'أُرسل للاعتماد' }); if (!sent) { setForm({ ...form, id: r.id }); list.reload(); return; } }
 732:     setForm(null); list.reload();
 733:   };
 734: 
 735:   return (
 736:     <>
 737:       <Card stg={3}>
 738:         <div className="flex flex-wrap items-center justify-between gap-2 mb-4">
 739:           <div className="flex flex-wrap gap-2">
 740:             <FSelect
 741:               value={st}
 742:               onChange={setSt}
 743:               placeholder="كل الحالات"
 744:               options={Object.entries(PR_STATUS).map(([v, s]) => ({ value: v, label: s.label }))}
 745:             />
 746:             <FSelect value={br} onChange={setBr} placeholder="كل الفروع" options={(branches.data ?? []).map((b: { id: number; name: string }) => ({ value: String(b.id), label: b.name }))} />
 747:           </div>
 748:           <button className="btn btn-dark btn-sm" onClick={() => openForm()}>
 749:             <Icon name="plus" size={13} />
 750:             طلب شراء
 751:           </button>
 752:         </div>
 753:         <RemoteFeedback state={list} />
 754:         <DataTable
 755:           rows={rows}
 756:           onRow={setView}
 757:           cols={[
 758:             { h: 'رقم الطلب', r: (p: PurchaseRequest) => <span className="num font-semibold tx1">{p.no}</span> },
 759:             { h: 'الفرع', r: (p: PurchaseRequest) => <span className="tx2">{p.branch}</span> },
 760:             { h: 'الحالة', r: (p: PurchaseRequest) => <StatusBadge map={PR_STATUS} value={p.status} /> },
 761:             {
 762:               h: 'مقدم الطلب',
 763:               r: (p: PurchaseRequest) => (
 764:                 <div className="flex items-center gap-2">
 765:                   <Avatar name={p.by} tone={p.id} size={24} />
 766:                   <span className="text-[12px]">{p.by}</span>
 767:                 </div>
 768:               ),
 769:             },
 770:             {
 771:               h: 'البنود',
 772:               align: 'center',
 773:               r: (p: PurchaseRequest) => <Num>{p.items}</Num>,
 774:             },
 775:             { h: 'التاريخ', r: (p: PurchaseRequest) => <Num className="tx2">{p.date}</Num> },
 776:             {
 777:               h: '',
 778:               r: (p: PurchaseRequest) => (
 779:                 <RowActions>
 780:                   {p.status === 'draft' && (
 781:                     <>
 782:                       <button className="btn btn-soft btn-xs" onClick={() => openForm(p)}>
 783:                         تعديل
 784:                       </button>
 785:                       <button className="btn btn-dark btn-xs" disabled={busy} onClick={() => doAction(p.id, purchaseRequestsApi.submit, 'أُرسل للاعتماد')}>
 786:                         إرسال للاعتماد
 787:                       </button>
 788:                       <button className="icon-btn !w-7 !h-7" disabled={busy} onClick={() => doAction(p.id, purchaseRequestsApi.remove, 'تم حذف المسودة')}>
 789:                         <Icon name="trash" size={12} />
 790:                       </button>
 791:                     </>
 792:                   )}
