 946: export function ReceivePOModal({ open, po, lines, onClose, onSaved, blocked }: { open: boolean; po: any; lines: any[]; onClose: () => void; onSaved: () => void; blocked?: boolean }) {
 947:   const toast = useToast();
 948:   const { busy, run } = useAction();
 949:   const [qtys, setQtys] = useState<Record<number, number>>({});
 950:   const [idemKey] = useState(newIdempotencyKey);
 951:   const [deliveryId, setDeliveryId] = useState('');
 952:   if (!open) return null;
 953:   const save = async () => {
 954:     if (!po || po.demo || blocked) return toast('البيانات المعروضة تجريبية؛ الحفظ غير متاح', 'red');
 955:     if (lines.some((l: any, i: number) => !Number.isInteger(Number(qtys[i] ?? 0)) || Number(qtys[i] ?? 0) < 0 || Number(qtys[i] ?? 0) > l.ord - l.rec)) return toast('الكمية المستلمة يجب ألا تتجاوز المتبقي', 'red');
 956:     const items = lines.map((l: any, i: number) => ({ purchase_order_item_id: l.id, qty: Number(qtys[i] ?? 0) })).filter((x) => x.qty > 0);
 957:     if (!items.length) return toast('أدخل كمية مستلمة واحدة على الأقل', 'red');
 958:     const r = await run(() => purchaseOrdersApi.receive(po.id, { items, supplier_delivery_id: deliveryId ? Number(deliveryId) : null }, idemKey), { toast, success: 'تم تسجيل الاستلام' });
 959:     if (r) onSaved();
 960:   };
 961:   return (
 962:     <Modal open onClose={onClose} title={'استلام ' + (po?.no || '')} icon="box" width={620}
 963:       footer={<><button className="btn btn-soft" onClick={onClose}>إلغاء</button><button className="btn btn-accent" disabled={busy} onClick={save}>تأكيد الاستلام</button></>}>
 964:       <div className="space-y-4">
 965:         <Field label="إشعار التوريد" hint="حدد الإشعار عند وجود توريد معلق"><select className="inp" value={deliveryId} onChange={e => setDeliveryId(e.target.value)}><option value="">بدون</option>{(po?.raw?.deliveries ?? []).filter((d: any) => d.status === 'pending_receipt').map((d: any) => <option key={d.id} value={d.id}>{d.delivery_number}</option>)}</select></Field>
 966:         <div className="v-sub p-2">
 967:           <div className="grid grid-cols-12 gap-2 px-2 py-1 text-[11px] tx3">
 968:             <span className="col-span-6">البند</span>
 969:             <span className="col-span-2 text-center">مطلوب</span>
 970:             <span className="col-span-2 text-center">سابق</span>
 971:             <span className="col-span-2 text-center">الآن</span>
 972:           </div>
 973:           {lines.map((l: any, i: number) => (
 974:             <div key={i} className="grid grid-cols-12 gap-2 items-center px-2 py-1.5">
 975:               <span className="col-span-6 text-[12.5px] font-medium clamp1">{l.v.name}</span>
 976:               <Num className="col-span-2 text-center">{l.ord}</Num>
 977:               <Num className="col-span-2 text-center tx3">{l.rec}</Num>
 978:               <input type="number" min="0" max={l.ord - l.rec}
 979:                 value={qtys[i] ?? 0}
 980:                 onChange={(e) => setQtys({ ...qtys, [i]: Number(e.target.value) })}
 981:                 className="inp inp-sm col-span-2 num text-center !bg-[var(--bg-card)]" />
 982:             </div>
 983:           ))}
 984:         </div>
 985:       </div>
 986:     </Modal>
 987:   );
 988: }
