 990: export function POModule() {
 991:   const canApprove = useCan('purchases.approve');
 992:   const canReceive = useCan('purchases.receive');
 993:   const toast = useToast();
 994:   const { busy, run } = useAction();
 995:   const [q, setQ] = useState('');
 996:   const [st, setSt] = useState('');
 997:   const [sp, setSp] = useState('');
 998:   const [br, setBr] = useState('');
 999:   const [form, setForm] = useState<any>(null);
1000:   const [view, setView] = useState<any>(null);
1001:   const [recv, setRecv] = useState(false);
1002:   const [closeConfirm, setCloseConfirm] = useState(false);
1003:   const [fromPR, setFromPR] = useState('');
1004:   const dq = useDebounced(q);
1005: 
1006:   const [page, setPage] = useState(1);
1007:   const [errors, setErrors] = useState<Record<string, string>>({});
1008:   useEffect(() => setPage(1), [dq, st, sp, br]);
1009:   const list = useRemote(signal => purchaseOrdersApi.list({ page, search: dq || undefined, status: st ? toPOStatus(st) as any : undefined, supplier_id: sp ? Number(sp) : undefined, branch_id: br ? Number(br) : undefined }, signal), [page, dq, st, sp, br], { mock: () => pageOf(mockPOs.filter(p => (!st || p.status === toPOStatus(st)) && (!sp || p.supplier_id === Number(sp)))) });
1010:   const suppliers = useSupplierLookup();
1011:   const branches = useRemote((signal) => branchesApi.list({}, signal).then(r => r.data), []);
1012:   const approvedPRs = useRemote(signal => allPages(page => purchaseRequestsApi.list({ page, status: 'approved' }, signal)), []);
1013:   const variants = useVariants();
1014:   const rows = (list.data?.data ?? []).map(mapPO);
1015:   const detail = useRemote(signal => purchaseOrdersApi.show(view.id, signal), [view?.id], { enabled: !!view, mock: () => mockPOs.find(p => p.id === view.id)! });
1016:   const supName = (id: number) => suppliers.data?.find(x => x.id === id)?.company || suppliers.data?.find(x => x.id === id)?.name || `#${id}`;
1017:   const openForm = (po?: any) => { const raw = po?.raw; setErrors({}); setFromPR(raw?.purchase_request_id ? String(raw.purchase_request_id) : ''); setForm({ demo: list.usingMock || po?.demo, id: po?.id, sup: raw?.supplier_id ?? '', branch: raw?.branch_id ?? '', eta: raw?.expected_delivery_date ?? '', discount: num(raw?.discount_amount), items: raw?.items?.map((it: any) => ({ product_variant_id: it.product_variant_id, qty: it.ordered_qty, cost: it.unit_cost, tax: it.tax_rate })) ?? [blankItem()] }); };
1018:   const setItem = (index: number, key: string, value: string) => setForm({ ...form, items: form.items.map((it: any, i: number) => i === index ? { ...it, [key]: value } : it) });
1019:   const act = async (id: number, fn: (id: number) => Promise<unknown>, msg: string) => { if (list.usingMock || view?.demo) return toast('البيانات المعروضة تجريبية؛ الحفظ غير متاح', 'red'); const result = await run(() => fn(id), { toast, success: msg }); if (result) { setView(null); list.reload(); return true; } return false; };
1020:   const actionsFor = (p: any): string[] => {
1021:     if (['draft', 'revision'].includes(p.status)) return ['edit', ...(p.raw?.approved_by ? ['send'] : canApprove ? ['approve'] : []), ...(p.status === 'draft' ? ['delete'] : []), 'cancel'];
1022:     return (({ accepted: ['receive', 'cancel'], sent: ['receive', 'cancel'], partial: ['receive', 'close'] } as Record<string, string[]>)[p.status] ?? []).filter(action => canReceive || !['receive', 'close'].includes(action));
1023:   };
1024:   const lines = (detail.data?.items ?? []).map(it => ({ id: it.id, v: { name: it.variant?.sku ?? `#${it.product_variant_id}`, sku: it.variant?.sku ?? '' }, ord: num(it.ordered_qty), rec: num(it.received_qty), cost: num(it.unit_cost), tax: num(it.tax_rate) }));
1025:   const save = async () => {
1026:     if (form.demo || list.usingMock || suppliers.usingMock || variants.usingMock) return toast('البيانات المعروضة تجريبية؛ الحفظ غير متاح', 'red');
1027:     if (!form.sup || !form.branch || form.items.some((it: any) => !it.product_variant_id || !Number.isInteger(Number(it.qty)) || Number(it.qty) <= 0)) return toast('أكمل المورد والفرع والبنود بكميات صحيحة', 'red');
1028:     const body = { supplier_id: Number(form.sup), ...(form.id ? {} : { purchase_request_id: fromPR ? Number(fromPR) : null }), branch_id: Number(form.branch), items: form.items.map((it: any) => ({ product_variant_id: Number(it.product_variant_id), ordered_qty: Number(it.qty), unit_cost: Number(it.cost), tax_rate: Number(it.tax) })), expected_delivery_date: form.eta || null, discount_amount: Number(form.discount || 0) };
1029:     const result = await run(() => form.id ? purchaseOrdersApi.update(form.id, body) : purchaseOrdersApi.create(body), { toast, success: 'تم حفظ الأمر كمسودة', onFieldErrors: setErrors });
1030:     if (result) { setForm(null); list.reload(); }
1031:   };
1032: 
1033:   return (
1034:     <>
