1050:             />
1051:             <FSelect value={br} onChange={setBr} placeholder="الفرع" options={(branches.data ?? []).map((b: { id: number; name: string }) => ({ value: String(b.id), label: b.name }))} />
1052:           </div>
1053:           <button className="btn btn-dark btn-sm" onClick={() => openForm()}>
1054:             <Icon name="plus" size={13} />
