1238:       {recv && <ReceivePOModal blocked={list.usingMock || detail.usingMock} key={view?.id} open={recv} po={detail.data ? mapPO(detail.data) : view} lines={lines} onClose={() => setRecv(false)} onSaved={() => { setRecv(false); setView(null); list.reload(); }} />}
