1361:             { h: 'رقم فاتورة المورد', r: (i: SupplierInvoice) => <Num className="tx2">{i.supNo}</Num> },
1362:             { h: 'المورد', r: (i: SupplierInvoice) => <span className="font-medium">{supName(i.sup)}</span> },
1363:             {
