1564: export function PayModule({ initialInvoice }: { initialInvoice?: any }) {
1565:   const toast = useToast();
1566:   const { busy, run } = useAction();
1567:   const [form, setForm] = useState<any>(null);
1568:   const [view, setView] = useState<any>(null);
1569:   const [voidM, setVoidM] = useState(false);
1570:   const [method, setMethod] = useState<'bank' | 'cash' | 'cheque'>('bank');
1571:   const [page, setPage] = useState(1);
1572:   const [errors, setErrors] = useState<Record<string, string>>({});
1573:   const [idemKey, setIdemKey] = useState(newIdempotencyKey);
1574:   const [voidReason, setVoidReason] = useState('');
1575:   const [allocateOpen, setAllocateOpen] = useState(false);
1576:   const [allocateId, setAllocateId] = useState('');
1577:   const suppliers = useSupplierLookup();
1578:   const invoices = useRemote(signal => allPages(page => supplierInvoicesApi.list({ page, supplier_id: Number(form?.sup || view?.sup) || undefined }, signal)).then(r => r.filter(i => ['posted', 'partially_paid'].includes(i.status)).map(mapInvoice)), [form?.sup, view?.sup]);
1579:   const list = useRemote(signal => supplierPaymentsApi.list({ page }, signal), [page], { mock: () => pageOf(mockPayments) });
1580:   const rows = (list.data?.data ?? []).map(mapPayment);
1581:   const supName = (id: number) => suppliers.data?.find(x => x.id === id)?.company || suppliers.data?.find(x => x.id === id)?.name || `#${id}`;
1582:   const openForm = (payment?: any) => { setErrors({}); setIdemKey(newIdempotencyKey()); setMethod(payment?.method ?? 'bank'); setForm({ ...payment, demo: list.usingMock || payment?.demo, sup: payment?.sup ?? '', invId: payment?.invId ?? '', amount: payment?.amount ?? '', date: payment?.date ?? new Date().toISOString().slice(0, 10), ref: payment?.ref ?? '', notes: payment?.notes ?? '' }); };
1583:   useEffect(() => { if (initialInvoice) openForm({ demo: initialInvoice.demo, sup: initialInvoice.sup, invId: initialInvoice.id, amount: initialInvoice.remaining }); }, [initialInvoice?.id]);
1584:   const save = async () => {
1585:     if (form.demo || list.usingMock || suppliers.usingMock) return toast('البيانات المعروضة تجريبية؛ الحفظ غير متاح', 'red');
1586:     const common = { payment_method: paymentMethod(method), reference_no: form.ref || null, notes: form.notes || null };
1587:     const r = await run(() => form.id ? supplierPaymentsApi.update(form.id, common) : supplierPaymentsApi.create({ ...common, supplier_id: Number(form.sup), supplier_invoice_id: form.invId ? Number(form.invId) : null, amount: Number(form.amount), payment_date: form.date }, idemKey), { toast, success: 'تم حفظ الدفعة', onFieldErrors: setErrors });
1588:     if (r) { setForm(null); list.reload(); invoices.reload(); suppliers.reload(); }
1589:   };
1590:   const voidPayment = async () => {
