 902: export function Modal({
 903:   open,
 904:   onClose,
 905:   title,
 906:   sub,
 907:   children,
 908:   footer,
 909:   width = 520,
 910:   icon,
 911:   tone,
 912: }: {
 913:   open: boolean;
 914:   onClose: () => void;
 915:   title: ReactNode;
 916:   sub?: ReactNode;
 917:   children: ReactNode;
 918:   footer?: ReactNode;
 919:   width?: number | string;
 920:   icon?: string;
 921:   tone?: string;
 922: }) {
 923:   useEffect(() => {
 924:     if (!open) return;
 925:     const h = (e: KeyboardEvent) => e.key === 'Escape' && onClose();
 926:     window.addEventListener('keydown', h);
 927:     return () => window.removeEventListener('keydown', h);
 928:   }, [open, onClose]);
 929: 
 930:   if (!open) return null;
 931: 
 932:   return (
 933:     <div className="modal-bd" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
 934:       <div className="modal" style={{ maxWidth: width }} dir="rtl">
 935:         <div className="flex items-start justify-between gap-4 p-6 pb-4">
 936:           <div className="flex items-start gap-3">
 937:             {icon && (
 938:               <span
 939:                 className={`w-10 h-10 rounded-full flex items-center justify-center shrink-0 t-${tone || 'orange'}`}
 940:               >
 941:                 <Icon name={icon} size={17} />
 942:               </span>
 943:             )}
 944:             <div>
 945:               <h3 className="font-display text-[18px] font-semibold tx1">{title}</h3>
 946:               {sub && <p className="text-[12px] tx2 mt-1 pretty">{sub}</p>}
 947:             </div>
 948:           </div>
 949:           <button className="icon-btn shrink-0" onClick={onClose}>
 950:             <Icon name="x" size={14} />
 951:           </button>
 952:         </div>
 953:         <div className="modal-body">{children}</div>
 954:         {footer && <div className="flex items-center justify-end gap-2 p-5 pt-4 mt-2 v-bt">{footer}</div>}
 955:       </div>
 956:     </div>
 957:   );
 958: }
