 960: export function ConfirmModal({
 961:   open,
 962:   onClose,
 963:   onConfirm,
 964:   title,
 965:   text,
 966:   cta = 'تأكيد',
 967:   danger,
 968: }: {
 969:   open: boolean;
 970:   onClose: () => void;
 971:   onConfirm?: () => void | boolean | Promise<void | boolean>;
 972:   title: string;
 973:   text: string;
 974:   cta?: string;
 975:   danger?: boolean;
 976: }) {
 977:   const [confirming, setConfirming] = useState(false);
 978:   const confirmingRef = useRef(false);
 979:   const toast = useToast();
 980:   return (
 981:     <Modal
 982:       open={open}
 983:       onClose={() => { if (!confirmingRef.current) onClose(); }}
 984:       title={title}
 985:       icon={danger ? 'alert' : 'info'}
 986:       tone={danger ? 'red' : 'orange'}
 987:       width={440}
 988:       footer={
 989:         <>
 990:           <button className="btn btn-soft" disabled={confirming} onClick={onClose}>
 991:             تراجع
 992:           </button>
 993:           <button
 994:             className={'btn ' + (danger ? 'btn-danger' : 'btn-dark')}
 995:             disabled={confirming}
 996:             onClick={async () => {
 997:               if (confirmingRef.current) return;
 998:               confirmingRef.current = true;
 999:               setConfirming(true);
1000:               try {
1001:                 if (await onConfirm?.() !== false) onClose();
1002:               } catch {
1003:                 toast('تعذّر تنفيذ الإجراء، حاول مرة أخرى', 'red');
1004:               } finally {
1005:                 confirmingRef.current = false;
1006:                 setConfirming(false);
1007:               }
1008:             }}
1009:           >
1010:             {cta}
1011:           </button>
1012:         </>
1013:       }
1014:     >
1015:       <p className="text-[13px] tx2 leading-relaxed pretty pb-2">{text}</p>
1016:     </Modal>
1017:   );
1018: }
