  8: /** شكل Laravel paginate() القياسي */
  9: export interface PageMeta {
 10:   current_page: number;
 11:   last_page: number;
 12:   per_page: number;
 13:   total: number;
 14:   from: number | null;
 15:   to: number | null;
 16: }
 17: export interface Paginated<T> {
 18:   data: T[];
 19:   links?: Record<string, string | null>;
 20:   meta: PageMeta;
 21: }
 22: 
 23: /** يحوّل أي استجابة قائمة (paginated أو مصفوفة) إلى Paginated موحّد */
 24: export function asPage<T>(r: AxiosResponse<any>): Paginated<T> {
 25:   const body = r.data;
 26:   if (body && Array.isArray(body.data) && body.meta) return body as Paginated<T>;
 27:   if (body && Array.isArray(body.data) && typeof body.current_page === 'number') {
 28:     return { data: body.data, meta: {
 29:       current_page: body.current_page, last_page: body.last_page, per_page: body.per_page,
 30:       total: body.total, from: body.from ?? null, to: body.to ?? null,
 31:     } };
 32:   }
 33:   const arr: T[] = Array.isArray(body) ? body : Array.isArray(body?.data) ? body.data : [];
 34:   return { data: arr, meta: { current_page: 1, last_page: 1, per_page: arr.length || 20, total: arr.length, from: arr.length ? 1 : null, to: arr.length || null } };
 35: }
 36: 
 37: /** يفك { data: T } */
 38: export function one<T>(r: AxiosResponse<any>): T {
 39:   return (r.data && 'data' in r.data ? r.data.data : r.data) as T;
 40: }
 41: 
 42: /** يحذف القيم الفارغة، ويحوّل boolean إلى 1/0 لأن Laravel `boolean` يرفض "true" */
 43: export function cleanParams(params: object = {}): Record<string, string | number> {
 44:   const out: Record<string, string | number> = {};
 45:   for (const [k, v] of Object.entries(params)) {
 46:     if (v === undefined || v === null || v === '') continue;
 47:     out[k] = typeof v === 'boolean' ? (v ? 1 : 0) : (v as any);
 48:   }
 49:   return out;
 50: }
 51: 
 52: /** FormData لرفع الملفات. spoofPut=true عند التعديل لأن PHP لا يقرأ multipart مع PUT */
 53: export function toFormData(obj: Record<string, unknown>, spoofPut = false): FormData {
 54:   const fd = new FormData();
 55:   if (spoofPut) fd.append('_method', 'PUT');
 56:   const put = (key: string, v: unknown) => {
 57:     if (v === undefined) return;
 58:     if (v === null) return fd.append(key, '');
 59:     if (typeof v === 'boolean') return fd.append(key, v ? '1' : '0');
 60:     if (v instanceof Blob) return fd.append(key, v);
 61:     if (Array.isArray(v)) {
 62:       v.forEach((item, i) => {
 63:         if (item !== null && typeof item === 'object' && !(item instanceof Blob)) {
 64:           Object.entries(item).forEach(([ik, iv]) => put(`${key}[${i}][${ik}]`, iv));
 65:         } else put(`${key}[${i}]`, item);
 66:       });
 67:       return;
 68:     }
 69:     fd.append(key, String(v));
 70:   };
 71:   Object.entries(obj).forEach(([k, v]) => put(k, v));
 72:   return fd;
 73: }
 74: export const MULTIPART = { headers: { 'Content-Type': 'multipart/form-data' } };
