 76: /** CRUD عام لموارد apiResource */
 77: export function crud<T, P extends object, Q extends object = Record<string, unknown>>(path: string) {
 78:   return {
 79:     list: (params?: Q, signal?: AbortSignal) =>
 80:       api.get(path, { params: cleanParams(params), signal }).then((r) => asPage<T>(r)),
 81:     show: (id: Id, signal?: AbortSignal) => api.get(`${path}/${id}`, { signal }).then((r) => one<T>(r)),
 82:     create: (body: P) => api.post(path, body).then((r) => one<T>(r)),
 83:     update: (id: Id, body: Partial<P>) => api.put(`${path}/${id}`, body).then((r) => one<T>(r)),
 84:     remove: (id: Id) => api.delete<{ message: string }>(`${path}/${id}`).then((r) => r.data),
 85:   };
 86: }
