 88: const SAFE_INLINE = new Set(['application/pdf', 'image/png', 'image/jpeg', 'image/webp']);
 89: 
 90: /** تحميل مرفق محمي (يحتاج Bearer) وفتحه في تبويب جديد */
 91: export async function openProtectedFile(url: string): Promise<void> {
 92:   const w = window.open('', '_blank');
 93:   if (w) w.opener = null;
 94:   try {
 95:     const r = await api.get(url, { responseType: 'blob' });
 96:     const type = String(r.headers?.['content-type'] ?? '').split(';')[0].trim().toLowerCase();
 97:     if (!SAFE_INLINE.has(type) || !w) {
 98:       if (w) w.close();
 99:       saveBlob(r.data as Blob, 'attachment');
100:       return;
101:     }
102:     const blob = new Blob([r.data], { type });
103:     const blobUrl = URL.createObjectURL(blob);
104:     w.location.href = blobUrl;
105:     setTimeout(() => URL.revokeObjectURL(blobUrl), 60_000);
106:   } catch (e) {
107:     if (w) w.close();
108:     throw e;
109:   }
110: }
111: 
112: /** تنزيل ملف (CSV) */
113: export async function downloadFile(url: string, filename: string, params?: object): Promise<void> {
114:   const r = await api.get(url, { responseType: 'blob', params: cleanParams(params) });
115:   saveBlob(r.data as Blob, filename);
116: }
117: 
118: function saveBlob(blob: Blob, filename: string): void {
119:   const a = document.createElement('a');
120:   const href = URL.createObjectURL(blob);
121:   a.href = href;
122:   a.download = filename;
123:   document.body.appendChild(a);
124:   a.click();
125:   setTimeout(() => {
126:     URL.revokeObjectURL(href);
127:     a.remove();
128:   }, 30_000);
129: }
