135: /** ===== معالجة الأخطاء ===== */
136: export interface ParsedApiError {
137:   status: number | null;
138:   message: string;
139:   fieldErrors: Record<string, string>; // أول رسالة لكل حقل
140: }
141: export function parseApiError(e: unknown): ParsedApiError {
142:   const err = e as any;
143:   const status: number | null = err?.response?.status ?? null;
144:   const body = err?.response?.data ?? {};
145:   const fieldErrors: Record<string, string> = {};
146:   if (body.errors && typeof body.errors === 'object') {
147:     for (const [k, v] of Object.entries(body.errors)) fieldErrors[k] = Array.isArray(v) ? String(v[0]) : String(v);
148:   }
149:   let message = body.message as string | undefined;
150:   if (!message) {
151:     if (status === null) message = 'تعذّر الاتصال بالخادم';
152:     else if (status === 403) message = 'ليست لديك صلاحية لتنفيذ هذا الإجراء';
153:     else if (status === 404) message = 'السجل غير موجود';
154:     else if (status >= 500) message = 'حدث خطأ في الخادم، حاول لاحقاً';
155:     else message = 'تعذّر تنفيذ الطلب';
156:   }
157:   return { status, message, fieldErrors };
