28: export const MAX_REPORT_DAYS = 366;
29: export function validatePeriod(from?: string, to?: string): string | null {
30:   if (!from && !to) return null;
31:   if (!from || !to) return 'اختر تاريخ البداية والنهاية';
32:   const date = (value: string) => {
33:     if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return NaN;
34:     const stamp = Date.parse(value + 'T00:00:00Z');
35:     return Number.isFinite(stamp) && new Date(stamp).toISOString().slice(0, 10) === value ? stamp : NaN;
36:   };
37:   const a = date(from), b = date(to);
38:   if (!Number.isFinite(a) || !Number.isFinite(b)) return 'صيغة التاريخ غير صحيحة';
39:   if (b < a) return 'تاريخ النهاية يجب أن يكون بعد تاريخ البداية';
40:   // ReportService uses an inclusive period (difference <= 365 days).
41:   if ((b - a) / 86_400_000 + 1 > MAX_REPORT_DAYS) return `أقصى مدى للتقرير ${MAX_REPORT_DAYS} يوماً`;
42:   return null;
43: }
