29: test('protected files isolate the new tab and use the fetched bytes for blocked or unsafe previews', async () => {
30:   const previous = { window: global.window, document: global.document, setTimeout: global.setTimeout,
31:     createObjectURL: URL.createObjectURL, revokeObjectURL: URL.revokeObjectURL };
32:   let requests = 0, clicks = 0, closes = 0, opened, fetched;
33:   const tab = { opener: { location: 'admin' }, location: { href: '' }, close() { closes++; } };
34:   global.window = { open() { opened = tab; return tab; } };
35:   global.document = { body: { appendChild() {} }, createElement: () => ({ click() { clicks++; }, remove() {} }) };
36:   global.setTimeout = () => 1;
37:   URL.createObjectURL = blob => { fetched = blob; return 'blob:safe'; };
38:   URL.revokeObjectURL = () => {};
39:   let type = 'application/pdf';
40:   const files = load(base + 'http.ts', { '../../axios-instance': { defaultApiClient: { get: async () => {
41:     requests++; return { data: new Blob(['contents'], { type }), headers: { 'content-type': type } };
42:   } } } });
43:   try {
44:     await files.openProtectedFile('/receipt');
45:     assert.equal(opened.opener, null);
46:     assert.equal(opened.location.href, 'blob:safe');
47:     assert.equal(fetched.type, 'application/pdf');
48:     type = 'text/html';
49:     await files.openProtectedFile('/unsafe');
50:     assert.equal(requests, 2, 'unsafe files must download the existing response without another fetch');
51:     assert.equal(clicks, 1); assert.equal(closes, 1);
52:     global.window.open = () => null;
53:     type = 'image/png';
54:     await files.openProtectedFile('/blocked');
55:     assert.equal(clicks, 2, 'blocked popups must fall back to downloading');
56:     assert.equal(requests, 3);
57:   } finally {
58:     Object.assign(global, { window: previous.window, document: previous.document, setTimeout: previous.setTimeout });
59:     URL.createObjectURL = previous.createObjectURL; URL.revokeObjectURL = previous.revokeObjectURL;
60:   }
61: });
