  8: function finance() {
  9:   const calls = [];
 10:   const api = Object.fromEntries(['get', 'post', 'put', 'delete'].map(method => [method, async (url, body, config) => {
 11:     calls.push({ method, url, body, config });
 12:     return { data: { data: { id: 7, current_balance: '750.00' } } };
 13:   }]));
 14:   const filename = path.resolve(__dirname, '../packages/api-client/src/endpoints/operations/finance.ts');
 15:   const compiled = new Module(filename, module);
 16:   compiled.require = name => name === './http' ? {
 17:     ADMIN: '/api/v1/admin', api,
 18:     cleanParams: p => Object.fromEntries(Object.entries(p ?? {}).filter(([, v]) => v !== undefined && v !== '').map(([k, v]) => [k, typeof v === 'boolean' ? Number(v) : v])),
 19:     one: r => r.data.data, asPage: r => r.data,
 20:     crud: base => ({ list: (p, signal) => api.get(base, { params: p, signal }), create: body => api.post(base, body), update: (id, body) => api.put(`${base}/${id}`, body) }),
 21:     newIdempotencyKey: () => 'finance-key', openProtectedFile: url => { calls.push({ method: 'file', url }); },
 22:     downloadFile: (url, filename) => { calls.push({ method: 'download', url, filename }); },
 23:   } : Module.prototype.require.call(compiled, name);
 24:   compiled._compile(ts.transpileModule(fs.readFileSync(filename, 'utf8'), { compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022 } }).outputText, filename);
 25:   return { ...compiled.exports, calls };
 26: }
