 49:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
 50:         ]);
 51: 
 52:         $branch = app(BranchAccess::class)->restrictedBranch($request->user());
 53:         if ($branch !== null && isset($filters['branch_id']) && (int) $filters['branch_id'] !== $branch) {
 54:             throw new BusinessException('لا تملك صلاحية الوصول إلى هذا الفرع.');
 55:         }
