 62:             ->when($filters['shift_id'] ?? null, fn ($q, $v) => $q->where('shift_id', $v))
 63:             ->when($filters['category'] ?? null, fn ($q, $v) => $q->whereLike('category', SearchTerm::pattern($v), caseSensitive: false))
 64:             ->when($filters['from_date'] ?? null, fn ($q, $v) => $q->where('expense_date', '>=', $v))
 65:             ->when($filters['to_date'] ?? null, fn ($q, $v) => $q->where('expense_date', '<=', $v))
 66:             ->orderByDesc('id')
 67:             ->paginate($filters['per_page'] ?? 15);
 68: 
 69:         return response()->json($expenses);
 70:     }
 71: 
 72:     public function store(Request $request): JsonResponse
 73:     {
 74:         $data = $request->validate([
 75:             'branch_id' => ['required', 'integer', 'min:1', 'exists:branches,id'],
 76:             'treasury_id' => ['required', 'integer', 'min:1', 'exists:treasuries,id'],
 77:             'category' => ['required', 'string', 'max:191'],
 78:             'amount' => ['required', 'numeric', 'min:0.01', 'max:99999999', 'decimal:0,2'],
 79:             'expense_date' => ['required', 'date_format:Y-m-d'],
 80:             'notes' => ['nullable', 'string', 'max:500'],
 81:         ]);
 82: 
 83:         $treasury = Treasury::query()->findOrFail($data['treasury_id']);
 84:         app(BranchAccess::class)->assertBranch($request->user()->id, (int) $data['branch_id']);
 85:         app(BranchAccess::class)->assertTreasury($request->user()->id, $treasury);
 86:         if (! $treasury->is_active || ($treasury->branch_id !== null && (int) $treasury->branch_id !== (int) $data['branch_id'])) {
 87:             throw new BusinessException('الخزينة غير مفعّلة أو لا تتبع الفرع المحدد.');
 88:         }
 89:         if ($treasury->type->value === 'pos_drawer') {
 90:             throw new BusinessException('مصروفات أدراج نقطة البيع تُسجل من مسار نقطة البيع فقط.');
 91:         }
 92: 
 93:         $expense = app(OperationIdempotencyService::class)->run(
 94:             'expense',
 95:             $request->user(),
 96:             $request->header('Idempotency-Key'),
 97:             $data,
 98:             fn () => DB::transaction(function () use ($data, $request): Expense {
 99:                 $lockedTreasury = Treasury::query()->lockForUpdate()->findOrFail($data['treasury_id']);
100:                 app(BranchAccess::class)->assertTreasury($request->user()->id, $lockedTreasury);
101:                 if ($lockedTreasury->type->value === 'pos_drawer'
102:                     || ($lockedTreasury->branch_id !== null && (int) $lockedTreasury->branch_id !== (int) $data['branch_id'])) {
103:                     throw new BusinessException('الخزينة لا تقبل مصروفات هذا الفرع من المسار الإداري.');
104:                 }
105:                 $expenseNumber = $this->settings->generateNextNumber('expense');
106: 
107:                 $expense = Expense::create([
108:                     ...$data,
109:                     'amount' => bcadd((string) $data['amount'], '0', 2),
110:                     'expense_number' => $expenseNumber,
111:                     'created_by' => $request->user()->id,
112:                 ]);
113: 
114:                 // خصم من الخزينة
115:                 $this->treasury->record([
116:                     'treasury_id' => $data['treasury_id'],
117:                     'type' => TreasuryTransactionType::Expense,
118:                     'amount' => bcsub('0', (string) $data['amount'], 2),
119:                     'reference_type' => Expense::class,
120:                     'reference_id' => $expense->id,
121:                     'created_by' => $request->user()->id,
122:                     'notes' => "مصروف إداري: {$data['category']} #{$expenseNumber}",
123:                 ]);
124: 
125:                 return $expense;
126:             })
127:         );
128: 
129:         return response()->json([
130:             'message' => 'تم تسجيل المصروف بنجاح.',
131:             'data' => $expense->load(['branch', 'treasury', 'creator']),
132:         ], 201);
133:     }
134: 
135:     public function show(Request $request, Expense $expense): JsonResponse
136:     {
137:         app(BranchAccess::class)->assertBranch($request->user()->id, $expense->branch_id);
138:         app(BranchAccess::class)->assertTreasury($request->user()->id, $expense->treasury);
139: 
140:         return response()->json(['data' => $expense->load(['branch', 'treasury', 'shift', 'creator'])]);
141:     }
142: 
143:     public function update(Request $request, Expense $expense): JsonResponse
144:     {
145:         app(BranchAccess::class)->assertBranch($request->user()->id, $expense->branch_id);
146:         app(BranchAccess::class)->assertTreasury($request->user()->id, $expense->treasury);
147: 
148:         if ($expense->voided_at !== null) {
149:             throw new BusinessException('لا يمكن تعديل مصروف ملغى.');
150:         }
151: 
152:         $data = $request->validate([
153:             'category' => ['sometimes', 'string', 'max:191'],
154:             'notes' => ['nullable', 'string', 'max:500'],
155:         ]);
156: 
157:         $expense->update($data);
158: 
159:         return response()->json(['message' => 'تم تحديث المصروف.', 'data' => $expense]);
160:     }
161: 
162:     /**
163:      * إلغاء (void) المصروف بدل الحذف الفعلي: يعكس الحركة المالية
164:      * ذريًا داخل نفس المعاملة مع قفل يمنع الإلغاء المزدوج.
165:      */
166:     public function destroy(Request $request, Expense $expense): JsonResponse
167:     {
168:         $data = $request->validate([
169:             'void_reason' => ['nullable', 'string', 'max:500'],
170:         ]);
171: 
172:         app(BranchAccess::class)->assertBranch($request->user()->id, $expense->branch_id);
173:         app(BranchAccess::class)->assertTreasury($request->user()->id, $expense->treasury);
174: 
175:         $expense = DB::transaction(function () use ($expense, $request, $data): Expense {
176:             $locked = Expense::query()->lockForUpdate()->findOrFail($expense->id);
177:             if ($locked->voided_at !== null) {
178:                 throw new BusinessException('هذا المصروف ملغى سابقًا.');
179:             }
180:             if ($locked->shift_id !== null) {
181:                 throw new BusinessException('لا يمكن إلغاء مصروف مرتبط بوردية من المسار الإداري.');
182:             }
183: 
184:             $this->treasury->record([
185:                 'treasury_id' => $locked->treasury_id,
186:                 'type' => TreasuryTransactionType::Expense,
187:                 'amount' => (string) $locked->amount,
188:                 'reference_type' => Expense::class,
189:                 'reference_id' => $locked->id,
190:                 'created_by' => $request->user()->id,
191:                 'notes' => "إلغاء مصروف #{$locked->expense_number}",
192:             ]);
193: 
194:             $locked->update([
195:                 'voided_at' => now(),
196:                 'voided_by' => $request->user()->id,
197:                 'void_reason' => $data['void_reason'] ?? null,
198:             ]);
199: 
200:             return $locked->fresh();
201:         });
202: 
203:         return response()->json(['message' => 'تم إلغاء المصروف وعكس أثره على الخزينة.', 'data' => $expense]);
204:     }
205: 
206:     public function void(Request $request, Expense $expense): JsonResponse
207:     {
208:         $request->validate(['void_reason' => ['required', 'string', 'max:500']]);
209: 
210:         return $this->destroy($request, $expense);
211:     }
212: } 1: <?php
