 45:             ->with(['supplier:id,code,name', 'branch:id,name'])
 46:             ->when($request->query('status'), fn ($q, $status) => $q->where('status', $status))
 47:             ->when($request->query('supplier_id'), fn ($q, $id) => $q->where('supplier_id', (int) $id))
 48:             ->when($request->query('branch_id'), fn ($q, $id) => $q->where('branch_id', (int) $id))
 49:             ->when($search !== '', fn ($q) => $q->where('po_number', 'ilike', SearchTerm::pattern($search)))
