15: use Illuminate\Routing\Controllers\HasMiddleware;
16: use Illuminate\Routing\Controllers\Middleware;
17: 
18: /**
19:  * فواتير الموردين: تسجيل مسودة ثم اعتماد (post) يثبت الاستحقاق
20:  * في رصيد المورد — الآثار المالية كلها في SupplierFinanceService.
21:  */
22: class SupplierInvoiceController extends Controller implements HasMiddleware
23: {
24:     public static function middleware(): array
25:     {
26:         return [
27:             new Middleware('can:purchases.view', only: ['index', 'show']),
28:             new Middleware('can:purchases.create', only: ['store']),
29:             new Middleware('can:purchases.update', only: ['update']),
30:             new Middleware('can:supplier_invoices.post', only: ['post']),
31:             new Middleware('can:supplier_invoices.cancel', only: ['cancel']),
32:             new Middleware('can:purchases.delete', only: ['destroy']),
33:         ];
34:     }
35: 
36:     public function __construct(protected SupplierFinanceService $finance) {}
37: 
38:     public function index(Request $request): AnonymousResourceCollection
39:     {
40:         $filters = $request->validate([
41:             'status' => ['nullable', \Illuminate\Validation\Rule::in(array_column(\App\Enums\SupplierInvoiceStatus::cases(), 'value'))],
42:             'supplier_id' => ['nullable', 'integer', 'min:1'],
43:             'purchase_order_id' => ['nullable', 'integer', 'min:1'],
44:         ]);
45:         $invoices = SupplierInvoice::query()
46:             ->with(['supplier:id,code,name', 'purchaseOrder:id,po_number'])
47:             ->when($filters['status'] ?? null, fn ($q, $status) => $q->where('status', $status))
48:             ->when($filters['supplier_id'] ?? null, fn ($q, $id) => $q->where('supplier_id', (int) $id))
49:             ->when($filters['purchase_order_id'] ?? null, fn ($q, $id) => $q->where('purchase_order_id', (int) $id))
50:             ->latest('id')
51:             ->paginate(20);
52: 
53:         return SupplierInvoiceResource::collection($invoices);
54:     }
55: 
56:     public function store(SupplierInvoiceRequest $request): JsonResponse
57:     {
58:         $data = $request->safe()->except('attachment');
59:         $invoice = $this->finance->createInvoice($data, $request->file('attachment'));
60:         $invoice->load(['supplier:id,code,name', 'purchaseOrder:id,po_number']);
61: 
62:         return SupplierInvoiceResource::make($invoice)->response()->setStatusCode(201);
63:     }
64: 
65:     public function show(SupplierInvoice $supplierInvoice): SupplierInvoiceResource
66:     {
67:         return SupplierInvoiceResource::make($supplierInvoice->load(['supplier:id,code,name', 'purchaseOrder:id,po_number']));
68:     }
69: 
70:     public function update(SupplierInvoiceRequest $request, SupplierInvoice $supplierInvoice): SupplierInvoiceResource
71:     {
72:         $data = $request->safe()->except('attachment');
73:         $invoice = $this->finance->updateInvoice($supplierInvoice, $data, $request->file('attachment'));
74:         $invoice->load(['supplier:id,code,name', 'purchaseOrder:id,po_number']);
75: 
76:         return SupplierInvoiceResource::make($invoice);
77:     }
78: 
79:     public function post(SupplierInvoice $supplierInvoice): SupplierInvoiceResource
80:     {
81:         return SupplierInvoiceResource::make($this->finance->postInvoice($supplierInvoice));
82:     }
83: 
84:     public function cancel(SupplierInvoice $supplierInvoice): SupplierInvoiceResource
85:     {
86:         return SupplierInvoiceResource::make($this->finance->cancelInvoice($supplierInvoice));
87:     }
88: 
89:     public function destroy(SupplierInvoice $supplierInvoice): JsonResponse
90:     {
91:         $this->finance->deleteInvoice($supplierInvoice);
92: 
93:         return response()->json(['message' => 'تم حذف فاتورة المورد.']);
94:     }
