181:     public function approve(WholesalePaymentNotice $notice, int $adminId, ?int $treasuryId = null, ?string $adminNotes = null): WholesalePaymentNotice
182:     {
183:         return DB::transaction(function () use ($notice, $adminId, $treasuryId, $adminNotes): WholesalePaymentNotice {
184:             $notice = WholesalePaymentNotice::query()->lockForUpdate()->findOrFail($notice->id);
185:             $customer = Customer::query()->lockForUpdate()->findOrFail($notice->customer_id);
186: 
187:             if ($notice->status !== WholesalePaymentNoticeStatus::PendingReview) {
188:                 throw new BusinessException('إشعار السداد هذا تمت مراجعته من قبل.');
189:             }
190: 
191:             if ((float) $notice->amount > $this->outstandingBalance($customer)) {
192:                 throw new BusinessException('مبلغ الإشعار أكبر من المديونية الآجلة الحالية للتاجر.');
193:             }
194: 
195:             $treasury = $this->resolveTreasury($treasuryId);
196:             app(BranchAccess::class)->assertTreasury($adminId, $treasury);
197: 
198:             $transaction = $this->treasury->record([
199:                 'treasury_id' => $treasury->id,
200:                 'type' => TreasuryTransactionType::CustomerReceipt,
201:                 'amount' => (string) $notice->amount,
202:                 'reference_type' => 'wholesale_payment_notice',
203:                 'reference_id' => $notice->id,
204:                 'created_by' => $adminId,
205:                 'notes' => "اعتماد إشعار سداد جملة {$notice->notice_number}",
206:             ]);
207: 
208:             $notice->update([
209:                 'status' => WholesalePaymentNoticeStatus::Approved,
210:                 'reviewed_by' => $adminId,
211:                 'admin_notes' => $adminNotes ?? $notice->admin_notes,
212:                 'treasury_id' => $treasury->id,
213:                 'treasury_transaction_id' => $transaction->id,
214:             ]);
215: 
216:             if ($notice->order_id !== null) {
217:                 $this->settleOrderIfCovered((int) $notice->order_id);
218:             }
219: 
220:             return $notice->load(['customer', 'order', 'treasury', 'treasuryTransaction']);
221:         });
222:     }
223: 
224:     public function reject(WholesalePaymentNotice $notice, int $adminId, ?string $adminNotes = null): WholesalePaymentNotice
225:     {
226:         return DB::transaction(function () use ($notice, $adminId, $adminNotes): WholesalePaymentNotice {
227:             $notice = WholesalePaymentNotice::query()->lockForUpdate()->findOrFail($notice->id);
228: 
229:             if ($notice->status !== WholesalePaymentNoticeStatus::PendingReview) {
230:                 throw new BusinessException('إشعار السداد هذا تمت مراجعته من قبل.');
231:             }
232: 
233:             $notice->update([
234:                 'status' => WholesalePaymentNoticeStatus::Rejected,
235:                 'reviewed_by' => $adminId,
236:                 'admin_notes' => $adminNotes ?? $notice->admin_notes,
237:             ]);
238: 
239:             return $notice->load(['customer', 'order']);
240:         });
241:     }
