243:     private function assertCreditableOrder(Customer $customer, int $orderId): Order
244:     {
245:         $order = Order::query()->where('customer_id', $customer->id)->find($orderId);
246: 
247:         if ($order === null) {
248:             throw new BusinessException('الطلب المرتبط غير موجود أو لا يخص هذا التاجر.', [], 404);
249:         }
250: 
251:         if ($order->payment_method !== 'credit' || $order->payment_status !== 'unpaid'
252:             || $order->status === OrderStatus::Cancelled) {
253:             throw new BusinessException('الطلب المرتبط ليس طلب آجل غير مسدد.');
254:         }
255: 
256:         return $order;
257:     }
