259:     /** مجموع المعتمد + قيد المراجعة على الطلب نفسه لا يتجاوز إجماليه. */
260:     private function assertOrderCapacity(Order $order, float $newAmount): void
261:     {
262:         $committed = (float) WholesalePaymentNotice::query()
263:             ->where('order_id', $order->id)
264:             ->whereIn('status', [
265:                 WholesalePaymentNoticeStatus::PendingReview->value,
266:                 WholesalePaymentNoticeStatus::Approved->value,
267:             ])
268:             ->sum('amount');
269: 
270:         if ($committed + $newAmount > (float) $order->grand_total) {
271:             throw new BusinessException('مبلغ الإشعار يتجاوز المتبقي غير المسدد من هذا الطلب.');
272:         }
273:     }
274: 
275:     private function settleOrderIfCovered(int $orderId): void
276:     {
277:         $order = Order::query()->lockForUpdate()->find($orderId);
278: 
279:         if ($order === null || $order->payment_status !== 'unpaid') {
280:             return;
281:         }
282: 
283:         $approved = (float) WholesalePaymentNotice::query()
284:             ->where('order_id', $order->id)
285:             ->where('status', WholesalePaymentNoticeStatus::Approved->value)
286:             ->sum('amount');
287: 
288:         if ($approved >= (float) $order->grand_total) {
289:             $order->update(['payment_status' => 'paid']);
290:         }
291:     }
292: 
293:     private function resolveTreasury(?int $treasuryId): Treasury
294:     {
295:         if ($treasuryId !== null) {
296:             return Treasury::query()->findOrFail($treasuryId);
297:         }
298: 
299:         $treasury = Treasury::query()->where('is_active', true)
300:             ->where('type', TreasuryType::BankAccount->value)
301:             ->orderBy('id')
302:             ->first()
303:             ?? Treasury::query()->where('is_active', true)
304:                 ->where('type', TreasuryType::MainSafe->value)
305:                 ->orderBy('id')
306:                 ->first();
307: 
308:         if ($treasury === null) {
309:             throw new BusinessException('لا توجد خزينة بنكية أو رئيسية نشطة لتسجيل القبض.');
310:         }
311: 
312:         return $treasury;
313:     }
