237:     private function orderFromCart(ProductVariant $variant, float|int $qty, ?int $cityId): Order
238:     {
239:         $cart = Cart::create([]);
240:         $cart->items()->create(['product_variant_id' => $variant->id, 'qty' => $qty]);
241: 
242:         return app(OrderService::class)->createFromCart($cart, [
243:             'recipient_name' => 'عميل', 'recipient_phone' => '01012345678',
244:             'city_id' => $cityId, 'shipping_address_line' => 'عنوان',
245:             'payment_method' => 'cod',
246:         ]);
247:     }
