249:     private function purchasableVariant(float $price): ProductVariant
250:     {
251:         $product = Product::factory()->create(['status' => 'published']);
252: 
253:         return ProductVariant::factory()->create([
254:             'product_id' => $product->id,
255:             'retail_price' => $price,
256:         ]);
257:     }
