259:     private function giveStock(ProductVariant $variant, float|int $qty): void
260:     {
261:         app(InventoryService::class)->recordMovement([
262:             'product_variant_id' => $variant->id,
263:             'branch_id' => $this->branch->id,
264:             'type' => StockMovementType::AdjustmentIn,
265:             'affected_bucket' => StockBucket::OnHand,
266:             'quantity' => $qty,
267:             'created_by' => $this->admin->id,
268:         ]);
269:     }
270: 
271:     private function level(int $variantId): StockLevel
272:     {
273:         return StockLevel::query()
274:             ->where('product_variant_id', $variantId)
275:             ->where('branch_id', $this->branch->id)
276:             ->whereNull('location_id')
277:             ->firstOrFail();
278:     }
