280:     private function staffWithPermissions(array $permissions): User
281:     {
282:         foreach ($permissions as $permission) {
283:             Permission::findOrCreate($permission, 'staff');
284:         }
285:         $staff = User::factory()->create();
286:         $staff->givePermissionTo($permissions);
287: 
288:         return $staff;
289:     }
