32:     public function __construct(private readonly PosService $pos) {}
33: 
34:     /**
35:      * GET /admin/shifts — قائمة الورديات للمراجعة الإدارية.
36:      */
37:     public function index(Request $request): JsonResponse
38:     {
39:         $filters = $request->validate([
40:             'branch_id' => ['nullable', 'integer', 'min:1'],
41:             'user_id' => ['nullable', 'integer', 'min:1'],
42:             'status' => ['nullable', Rule::in(array_column(PosShiftStatus::cases(), 'value'))],
43:             'from_date' => ['nullable', 'date_format:Y-m-d'],
44:             'to_date' => ['nullable', 'date_format:Y-m-d'],
45:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
46:         ]);
47: 
48:         $branch = app(BranchAccess::class)->restrictedBranch($request->user());
49:         $shifts = PosShift::query()->when($branch !== null, fn ($q) => $q->where('branch_id', $branch))
50:             ->with(['cashier', 'treasury', 'branch', 'approver'])
51:             ->when($filters['branch_id'] ?? null, fn ($q, $v) => $q->where('branch_id', $v))
52:             ->when($filters['user_id'] ?? null, fn ($q, $v) => $q->where('user_id', $v))
53:             ->when($filters['status'] ?? null, fn ($q, $v) => $q->where('status', $v))
54:             ->when($filters['from_date'] ?? null, fn ($q, $v) => $q->where('opened_at', '>=', $v))
55:             ->when($filters['to_date'] ?? null, fn ($q, $v) => $q->where('opened_at', '<=', $v.' 23:59:59'))
56:             ->orderByDesc('id')
57:             ->paginate($filters['per_page'] ?? 15);
58: 
59:         return response()->json($shifts);
60:     }
61: 
