 20: /**
 21:  * دفعات الموردين: إنشاؤها يخفض رصيد المورد ويحدّث فاتورتها، وحذفها
 22:  * يعكس الأثر كاملًا — عبر SupplierFinanceService فقط.
 23:  */
 24: class SupplierPaymentController extends Controller implements HasMiddleware
 25: {
 26:     public static function middleware(): array
 27:     {
 28:         return [
 29:             new Middleware('can:purchases.view', only: ['index', 'show']),
 30:             new Middleware('can:supplier_payments.create', only: ['store']),
 31:             new Middleware('can:supplier_payments.update', only: ['update', 'allocate']),
 32:             new Middleware('can:supplier_payments.delete', only: ['destroy', 'void']),
 33:         ];
 34:     }
 35: 
 36:     public function __construct(protected SupplierFinanceService $finance) {}
 37: 
 38:     public function index(Request $request): AnonymousResourceCollection
 39:     {
 40:         $filters = $request->validate([
 41:             'supplier_id' => ['nullable', 'integer', 'min:1'],
 42:             'supplier_invoice_id' => ['nullable', 'integer', 'min:1'],
 43:             'from_date' => ['nullable', 'date_format:Y-m-d'],
 44:             'to_date' => ['nullable', 'date_format:Y-m-d', 'after_or_equal:from_date'],
 45:         ]);
 46:         $payments = SupplierPayment::query()
 47:             ->with(['invoice:id,invoice_number,supplier_invoice_no'])
 48:             ->when($filters['supplier_id'] ?? null, fn ($q, $id) => $q->where('supplier_id', (int) $id))
 49:             ->when($filters['supplier_invoice_id'] ?? null, fn ($q, $id) => $q->where('supplier_invoice_id', (int) $id))
 50:             ->when($filters['from_date'] ?? null, fn ($q, $date) => $q->where('payment_date', '>=', $date))
 51:             ->when($filters['to_date'] ?? null, fn ($q, $date) => $q->where('payment_date', '<=', $date))
 52:             ->latest('id')
 53:             ->paginate(20);
 54: 
 55:         return SupplierPaymentResource::collection($payments);
 56:     }
 57: 
 58:     public function store(SupplierPaymentRequest $request): JsonResponse
 59:     {
 60:         /** @var User $admin */
 61:         $admin = $request->user();
 62:         $payment = $this->finance->createPayment($request->validated(), $admin, $request->header('Idempotency-Key'));
 63:         $payment->load(['invoice:id,invoice_number,supplier_invoice_no']);
 64: 
 65:         return SupplierPaymentResource::make($payment)->response()->setStatusCode(201);
 66:     }
 67: 
 68:     public function show(SupplierPayment $supplierPayment): SupplierPaymentResource
 69:     {
 70:         return SupplierPaymentResource::make($supplierPayment->load(['invoice:id,invoice_number,supplier_invoice_no']));
 71:     }
 72: 
 73:     public function update(UpdateSupplierPaymentRequest $request, SupplierPayment $supplierPayment): SupplierPaymentResource
 74:     {
 75:         $supplierPayment = $this->finance->updatePayment($supplierPayment, $request->validated());
 76: 
 77:         return SupplierPaymentResource::make($supplierPayment->fresh(['invoice:id,invoice_number,supplier_invoice_no']));
 78:     }
 79: 
 80:     public function destroy(Request $request, SupplierPayment $supplierPayment): JsonResponse
 81:     {
 82:         $validated = $request->validate([
 83:             'void_reason' => ['required', 'string', 'max:500'],
 84:         ]);
 85:         /** @var User $admin */
 86:         $admin = $request->user();
 87:         $this->finance->voidPayment($supplierPayment, $admin, $validated['void_reason']);
 88: 
 89:         return response()->json(['message' => 'تم إلغاء الدفعة وعكس أثرها على الرصيد والفاتورة.']);
 90:     }
 91: 
 92:     public function void(Request $request, SupplierPayment $supplierPayment): JsonResponse
 93:     {
 94:         $validated = $request->validate([
 95:             'void_reason' => ['required', 'string', 'max:500'],
 96:         ]);
 97:         /** @var User $admin */
 98:         $admin = $request->user();
 99:         $this->finance->voidPayment($supplierPayment, $admin, $validated['void_reason']);
100: 
101:         return response()->json(['message' => 'تم إلغاء الدفعة وعكس أثرها على الرصيد والفاتورة.']);
102:     }
103: 
104:     public function allocate(Request $request, SupplierPayment $supplierPayment): SupplierPaymentResource
105:     {
106:         $data = $request->validate([
107:             'supplier_invoice_id' => ['required', 'integer', 'exists:supplier_invoices,id'],
108:         ]);
109:         $payment = $this->finance->allocatePayment($supplierPayment, (int) $data['supplier_invoice_id']);
110: 
111:         return SupplierPaymentResource::make($payment->load(['invoice:id,invoice_number,supplier_invoice_no']));
