 5: namespace App\Http\Requests\Admin\Promotion;
 6: 
 7: use App\Models\Coupon;
 8: use Illuminate\Foundation\Http\FormRequest;
 9: use Illuminate\Validation\Rule;
10: use Illuminate\Validation\Validator;
11: 
12: class CouponRequest extends FormRequest
13: {
14:     public function authorize(): bool
15:     {
16:         return true;
17:     }
18: 
19:     /** @return array<string, mixed> */
20:     public function rules(): array
21:     {
22:         $coupon = $this->route('coupon');
23: 
24:         return [
25:             'code' => ['required', 'string', 'max:50', Rule::unique('coupons', 'code')->ignore($coupon),
26:                 function (string $attribute, mixed $value, \Closure $fail) use ($coupon): void {
27:                     if (is_string($value) && Coupon::query()
28:                         ->whereRaw('upper(code) = ?', [strtoupper($value)])
29:                         ->when($coupon, fn ($query) => $query->whereKeyNot($coupon->getKey()))
30:                         ->exists()) {
31:                         $fail('رمز الكوبون مستخدم بالفعل.');
32:                     }
33:                 },
34:             ],
35:             'type' => ['required', Rule::in(['percentage', 'fixed', 'free_shipping'])],
36:             // كوبون نسبي فوق 100% يعني خصمًا كاملًا وأكثر — ممنوع (M18)
37:             'value' => ['required_unless:type,free_shipping', 'nullable', 'numeric', 'min:0', 'decimal:0,2', Rule::when($this->input('type') === 'percentage', ['max:100'])],
38:             'max_discount_amount' => ['nullable', 'numeric', 'min:0', 'decimal:0,2'],
39:             'min_order_amount' => ['nullable', 'numeric', 'min:0', 'decimal:0,2'],
40:             'usage_limit' => ['nullable', 'integer', 'min:1', 'max:1000000'],
41:             'usage_limit_per_customer' => ['nullable', 'integer', 'min:0', 'max:1000000'],
42:             'starts_at' => ['nullable', 'date'],
43:             'ends_at' => ['nullable', 'date', 'after_or_equal:starts_at'],
44:             'is_active' => ['nullable', 'boolean'],
45:         ];
46:     }
47: 
48:     /**
49:      * (M1) فحص القيمة «الفعّالة» بعد الدمج مع الكوبون الحالي: قاعدة max:100
50:      * أعلاه تعتمد على النوع المُرسل، فطلب تعديل يغيّر النوع إلى percentage
51:      * دون إرسال value كان يترك قيمة قديمة (>100) تمرّ دون فحص.
52:      *
53:      * @return list<callable(Validator): void>
54:      */
55:     public function after(): array
56:     {
57:         return [function (Validator $validator): void {
58:             if ($validator->errors()->isNotEmpty()) {
59:                 return;
60:             }
61: 
62:             $coupon = $this->route('coupon');
63:             $type = $this->input('type');
64:             // قيمة غير رقمية (بما فيها null الصريح) تعني «أبقِ الحالية» في
65:             // مسار التعديل — فالفحص على القيمة الفعلية لا المُرسلة
66:             $submitted = $this->input('value');
67:             $effective = is_numeric($submitted) ? (float) $submitted : (float) ($coupon?->value ?? 0);
68: 
69:             if ($type === 'percentage' && $effective > 100) {
70:                 $validator->errors()->add('value', 'نسبة الكوبون لا تتجاوز 100%.');
71:             }
72:         }];
73:     }
74: 
75:     protected function prepareForValidation(): void
76:     {
77:         if (is_string($this->input('code'))) {
78:             $this->merge(['code' => strtoupper(trim($this->input('code')))]);
79:         }
80:     }
