  5: namespace App\Services;
  6: 
  7: use Carbon\CarbonImmutable;
  8: use Illuminate\Database\Query\Builder;
  9: use Illuminate\Support\Facades\DB;
 10: use Illuminate\Validation\ValidationException;
 11: 
 12: /**
 13:  * خدمة التقارير ولوحة معلومات الإدارة (المرحلة 13.2).
 14:  *
 15:  * قاعدة الأداء: كل الأرقام تُحسب باستعلامات تجميعية مباشرة في قاعدة
 16:  * البيانات (SUM/COUNT/GROUP BY/CASE WHEN) — ممنوع جلب سجلات وحسابها
 17:  * في PHP. «طلبات المبيعات» هنا = طلبات بحالات مؤكدة فصاعدًا
 18:  * (confirmed/processing/shipped/delivered) — الملغاة والمنتظرة لا
 19:  * تُحتسب مبيعات.
 20:  */
 21: class ReportService
 22: {
 23:     /** @var list<string> */
 24:     private const SALES_STATUSES = ['confirmed', 'processing', 'shipped', 'delivered'];
 25: 
 26:     /** @return array<string, mixed> */
 27:     public function dashboard(?int $branchId = null): array
 28:     {
 29:         $businessNow = CarbonImmutable::now(config('app.business_timezone', 'Africa/Cairo'));
 30:         [$todayStart, $todayEnd] = $this->periodBounds($businessNow->toDateString(), $businessNow->toDateString());
 31:         $monthStart = $businessNow->startOfMonth()->utc()->toDateTimeString();
 32: 
 33:         $salesByChannel = function (callable $scope) use ($branchId): array {
 34:             $rows = $this->salesEntries($branchId)
 35:                 ->selectRaw('channel, SUM(grand_total) AS total, COALESCE(SUM(sale_count), 0) AS orders_count')
 36:                 ->tap($scope)
 37:                 ->groupBy('channel')
 38:                 ->get();
 39: 
 40:             $byChannel = ['store' => 0.0, 'wholesale' => 0.0, 'pos' => 0.0];
 41:             $total = 0.0;
 42:             foreach ($rows as $row) {
 43:                 $byChannel[$row->channel] = (float) $row->total;
 44:                 $total += (float) $row->total;
 45:             }
 46: 
 47:             return ['total' => $total, 'by_channel' => $byChannel];
 48:         };
 49: 
 50:         $todaySales = $salesByChannel(fn ($q) => $q->where('created_at', '>=', $todayStart)->where('created_at', '<', $todayEnd));
 51:         $monthSales = $salesByChannel(fn ($q) => $q->where('created_at', '>=', $monthStart));
 52: 
 53:         $newOrdersCount = (int) DB::table('orders')->whereNull('return_of_order_id')->when($branchId !== null, fn ($q) => $q->where('allocated_branch_id', $branchId))
 54:             ->where('created_at', '>=', $todayStart)->where('created_at', '<', $todayEnd)->count();
 55: 
 56:         $lowStockCount = (int) DB::table('stock_levels as sl')->when($branchId !== null, fn ($q) => $q->where('sl.branch_id', $branchId))
 57:             ->join('product_variants as pv', 'pv.id', '=', 'sl.product_variant_id')
 58:             ->whereRaw('COALESCE(NULLIF(sl.reorder_level, 0), pv.reorder_level, 0) > 0')
 59:             ->whereRaw('sl.available <= COALESCE(NULLIF(sl.reorder_level, 0), pv.reorder_level, 0)')
 60:             ->count();
 61: 
 62:         $pendingWholesale = $branchId !== null ? 0 : (int) DB::table('customers')
 63:             ->whereIn('type', ['wholesale', 'distributor'])
 64:             ->where('status', 'pending')
 65:             ->count();
 66: 
 67:         $topProducts = DB::table('order_items as oi')->when($branchId !== null, fn ($q) => $q->where('oi.allocated_branch_id', $branchId))
 68:             ->join('orders as o', 'o.id', '=', 'oi.order_id')
 69:             ->leftJoin('product_variants as pv', 'pv.id', '=', 'oi.product_variant_id')
 70:             ->leftJoin('products as p', 'p.id', '=', 'pv.product_id')
 71:             ->selectRaw('oi.product_variant_id, pv.sku, p.name_ar AS product_name, SUM(oi.qty) AS qty_sold, SUM(oi.line_total) AS revenue')
 72:             ->whereIn('o.status', self::SALES_STATUSES)
 73:             ->where('o.created_at', '>=', $monthStart)
 74:             ->groupBy('oi.product_variant_id', 'pv.sku', 'p.name_ar')
 75:             ->orderByDesc('revenue')
 76:             ->limit(5)
 77:             ->get()
 78:             ->map(fn ($row): array => [
 79:                 'product_variant_id' => (int) $row->product_variant_id,
 80:                 'sku' => $row->sku,
 81:                 'product_name' => $row->product_name,
 82:                 'qty_sold' => (float) $row->qty_sold,
 83:                 'revenue' => (float) $row->revenue,
 84:             ])->all();
 85: 
 86:         $topBranches = $this->salesEntries($branchId, 'o')
 87:             ->leftJoin('branches as b', 'b.id', '=', 'o.allocated_branch_id')
 88:             ->selectRaw('o.allocated_branch_id, b.name AS branch_name, COALESCE(SUM(sale_count), 0) AS orders_count, SUM(o.grand_total) AS revenue')
 89:             ->where('o.created_at', '>=', $monthStart)
 90:             ->whereNotNull('o.allocated_branch_id')
 91:             ->groupBy('o.allocated_branch_id', 'b.name')
 92:             ->orderByDesc('revenue')
 93:             ->limit(5)
 94:             ->get()
 95:             ->map(fn ($row): array => [
 96:                 'branch_id' => (int) $row->allocated_branch_id,
 97:                 'branch_name' => $row->branch_name,
 98:                 'orders_count' => (int) $row->orders_count,
 99:                 'revenue' => (float) $row->revenue,
100:             ])->all();
101: 
102:         return [
103:             'today' => [
104:                 'sales_total' => $todaySales['total'],
105:                 'sales_by_channel' => $todaySales['by_channel'],
106:                 'new_orders_count' => $newOrdersCount,
107:             ],
108:             'month' => [
109:                 'sales_total' => $monthSales['total'],
110:                 'sales_by_channel' => $monthSales['by_channel'],
111:             ],
112:             'low_stock_count' => $lowStockCount,
113:             'pending_wholesale_applications' => $pendingWholesale,
114:             'top_products' => $topProducts,
115:             'top_branches' => $topBranches,
116:         ];
117:     }
118: 
119:     /**
120:      * تقرير المبيعات الزمني: تجميع بالفترة (يومي/شهري) وبُعد اختياري
121:      * (فرع/قناة/كاشير/طريقة دفع).
122:      *
123:      * @return array{rows: list<array<string, mixed>>, totals: array<string, mixed>}
124:      */
125:     public function salesReport(string $from, string $to, string $granularity = 'daily', ?string $groupBy = null, ?int $branchId = null): array
126:     {
127: 
128:         [$periodStart, $periodEnd] = $this->periodBounds($from, $to);
129:         $zone = str_replace("'", "''", (string) config('app.business_timezone', 'Africa/Cairo'));
130:         $localCreated = "timezone('{$zone}', o.created_at AT TIME ZONE 'UTC')";
131:         $periodExpr = $granularity === 'monthly'
132:             ? "DATE_TRUNC('month', {$localCreated})::date"
133:             : "DATE({$localCreated})";
134: 
135:         $query = $this->salesEntries($branchId, 'o')
136:             ->where('o.created_at', '>=', $periodStart)->where('o.created_at', '<', $periodEnd);
137: 
138:         $selects = [
139:             "{$periodExpr} AS period",
140:             'COALESCE(SUM(sale_count), 0) AS orders_count',
141:             'COALESCE(SUM(o.subtotal), 0) AS gross_sales',
142:             'COALESCE(SUM(o.discount_amount), 0) AS discounts',
143:             'COALESCE(SUM(o.tax_amount), 0) AS tax',
144:             'COALESCE(SUM(o.shipping_cost), 0) AS shipping',
145:             'COALESCE(SUM(o.grand_total), 0) AS net_sales',
146:         ];
147:         $groups = [$periodExpr];
148: 
149:         if ($groupBy === 'branch') {
150:             $query->leftJoin('branches as b', 'b.id', '=', 'o.allocated_branch_id');
151:             $selects[] = 'o.allocated_branch_id AS group_key';
152:             $selects[] = 'b.name AS group_label';
153:             $groups[] = 'o.allocated_branch_id';
154:             $groups[] = 'b.name';
155:         } elseif ($groupBy === 'channel') {
156:             $selects[] = 'o.channel AS group_key';
157:             $groups[] = 'o.channel';
158:         } elseif ($groupBy === 'payment_method') {
159:             $selects[] = 'o.payment_method AS group_key';
160:             $groups[] = 'o.payment_method';
161:         } elseif ($groupBy === 'cashier') {
162:             $query->join('pos_shifts as ps', 'ps.id', '=', 'o.pos_shift_id')
163:                 ->leftJoin('users as u', 'u.id', '=', 'ps.user_id');
164:             $selects[] = 'ps.user_id AS group_key';
165:             $selects[] = 'u.name AS group_label';
166:             $groups[] = 'ps.user_id';
167:             $groups[] = 'u.name';
168:         }
169: 
170:         $rows = $query
171:             ->selectRaw(implode(', ', $selects))
172:             ->groupByRaw(implode(', ', $groups))
173:             ->orderBy('period')
174:             ->get()
175:             ->map(fn ($row): array => [
176:                 'period' => (string) $row->period,
177:                 'group_key' => $row->group_key ?? null,
178:                 'group_label' => $row->group_label ?? ($row->group_key ?? null),
179:                 'orders_count' => (int) $row->orders_count,
180:                 'gross_sales' => (float) $row->gross_sales,
181:                 'discounts' => (float) $row->discounts,
182:                 'tax' => (float) $row->tax,
183:                 'shipping' => (float) $row->shipping,
184:                 'net_sales' => (float) $row->net_sales,
185:             ])->all();
186: 
187:         $totals = $this->salesEntries($branchId)
188:             ->where('created_at', '>=', $periodStart)->where('created_at', '<', $periodEnd)
189:             ->selectRaw('COALESCE(SUM(sale_count), 0) AS orders_count, COALESCE(SUM(subtotal), 0) AS gross_sales, COALESCE(SUM(discount_amount), 0) AS discounts, COALESCE(SUM(tax_amount), 0) AS tax, COALESCE(SUM(shipping_cost), 0) AS shipping, COALESCE(SUM(grand_total), 0) AS net_sales')
190:             ->first();
191: 
192:         return [
193:             'rows' => $rows,
194:             'totals' => [
195:                 'orders_count' => (int) $totals->orders_count,
196:                 'gross_sales' => (float) $totals->gross_sales,
197:                 'discounts' => (float) $totals->discounts,
198:                 'tax' => (float) $totals->tax,
199:                 'shipping' => (float) $totals->shipping,
200:                 'net_sales' => (float) $totals->net_sales,
201:             ],
202:         ];
203:     }
