205:     /**
206:      * تقييم المخزون لكل فرع (on_hand × cost_price) + الأصناف الراكدة
207:      * (رصيد موجود بلا أي حركة منذ X يوم).
208:      *
209:      * @return array{valuation: list<array<string, mixed>>, total_value: float, dead_stock: list<array<string, mixed>>}
210:      */
211:     public function inventoryReport(int $deadDays = 90, ?int $branchId = null): array
212:     {
213:         $valuation = DB::table('stock_levels as sl')->when($branchId !== null, fn ($q) => $q->where('sl.branch_id', $branchId))
214:             ->join('product_variants as pv', 'pv.id', '=', 'sl.product_variant_id')
215:             ->leftJoin('branches as b', 'b.id', '=', 'sl.branch_id')
216:             ->selectRaw('sl.branch_id, b.name AS branch_name, COUNT(DISTINCT sl.product_variant_id) AS variants_count, COALESCE(SUM(sl.on_hand), 0) AS total_qty, COALESCE(SUM(sl.on_hand * COALESCE(pv.cost_price, 0)), 0) AS total_value')
217:             ->groupBy('sl.branch_id', 'b.name')
218:             ->orderByDesc('total_value')
219:             ->get()
220:             ->map(fn ($row): array => [
221:                 'branch_id' => (int) $row->branch_id,
222:                 'branch_name' => $row->branch_name,
223:                 'variants_count' => (int) $row->variants_count,
224:                 'total_qty' => (float) $row->total_qty,
225:                 'total_value' => (float) $row->total_value,
226:             ])->all();
227: 
228:         $totalValue = (float) (DB::table('stock_levels as sl')->when($branchId !== null, fn ($q) => $q->where('sl.branch_id', $branchId))
229:             ->join('product_variants as pv', 'pv.id', '=', 'sl.product_variant_id')
230:             ->selectRaw('COALESCE(SUM(sl.on_hand * COALESCE(pv.cost_price, 0)), 0) AS v')
231:             ->first()?->v ?? 0);
232: 
233:         $deadStock = DB::table('stock_levels as sl')->when($branchId !== null, fn ($q) => $q->where('sl.branch_id', $branchId))
234:             ->join('product_variants as pv', 'pv.id', '=', 'sl.product_variant_id')
235:             ->leftJoin('products as p', 'p.id', '=', 'pv.product_id')
236:             ->leftJoinSub(
237:                 DB::table('stock_movements')->when($branchId !== null, fn ($q) => $q->where('branch_id', $branchId))
238:                     ->selectRaw('product_variant_id, MAX(created_at) AS last_movement_at')
239:                     ->groupBy('product_variant_id'),
240:                 'lm',
241:                 'lm.product_variant_id',
242:                 '=',
243:                 'sl.product_variant_id',
244:             )
245:             ->selectRaw('sl.product_variant_id, pv.sku, p.name_ar AS product_name, SUM(sl.on_hand) AS on_hand, COALESCE(SUM(sl.on_hand * COALESCE(pv.cost_price, 0)), 0) AS tied_value, lm.last_movement_at')
246:             ->groupBy('sl.product_variant_id', 'pv.sku', 'p.name_ar', 'lm.last_movement_at')
247:             ->havingRaw('SUM(sl.on_hand) > 0')
248:             ->havingRaw('(lm.last_movement_at IS NULL OR lm.last_movement_at < NOW() - (? * INTERVAL \'1 day\'))', [$deadDays])
249:             ->orderByDesc('tied_value')
250:             ->limit(100)
251:             ->get()
252:             ->map(fn ($row): array => [
253:                 'product_variant_id' => (int) $row->product_variant_id,
254:                 'sku' => $row->sku,
255:                 'product_name' => $row->product_name,
256:                 'on_hand' => (float) $row->on_hand,
257:                 'tied_value' => (float) $row->tied_value,
258:                 'last_movement_at' => $row->last_movement_at,
259:             ])->all();
260: 
261:         return [
262:             'valuation' => $valuation,
263:             'total_value' => $totalValue,
264:             'dead_stock' => $deadStock,
265:             'dead_stock_days' => $deadDays,
266:         ];
267:     }
