269:     /**
270:      * مجمل وصافي الربح: صافي إيراد المبيعات − COGS (من حركات البيع في
271:      * الدفتر بتكلفتها المسجلة أو تكلفة المتغير الحالية عند غيابها) −
272:      * المصروفات المسجلة في الفترة.
273:      *
274:      * @return array<string, float>
275:      */
276:     public function profitReport(string $from, string $to, ?int $branchId = null): array
277:     {
278: 
279:         [$periodStart, $periodEnd] = $this->periodBounds($from, $to);
280:         $revenue = (float) $this->salesEntries($branchId)
281:             ->where('created_at', '>=', $periodStart)->where('created_at', '<', $periodEnd)
282:             ->sum('grand_total');
283: 
284:         $cogs = (float) (DB::table('stock_movements as sm')->when($branchId !== null, fn ($q) => $q->where('sm.branch_id', $branchId))
285:             ->join('product_variants as pv', 'pv.id', '=', 'sm.product_variant_id')
286:             ->whereIn('sm.type', ['sale', 'sale_return'])
287:             ->where('sm.created_at', '>=', $periodStart)->where('sm.created_at', '<', $periodEnd)
288:             ->selectRaw('COALESCE(SUM(-sm.quantity * COALESCE(sm.unit_cost, pv.cost_price, 0)), 0) AS c')
289:             ->first()?->c ?? 0);
290: 
291:         $expenses = (float) DB::table('expenses')->when($branchId !== null, fn ($q) => $q->where('branch_id', $branchId))
292:             ->whereNull('voided_at')
293:             ->whereBetween('expense_date', [$from, $to])
294:             ->sum('amount');
295: 
296:         $gross = $revenue - $cogs;
297: 
298:         return [
299:             'net_sales_revenue' => $revenue,
300:             'cogs' => $cogs,
301:             'gross_profit' => $gross,
302:             'total_expenses' => $expenses,
303:             'net_profit' => $gross - $expenses,
304:         ];
305:     }
