307:     /**
308:      * أرصدة الموردين وأعمار ديونهم: لكل مورد رصيده الحالي وإجمالي
309:      * مشترياته (فواتير معتمدة) وتوزيع المستحق غير المسدد على شرائح
310:      * عمرية حسب تاريخ الاستحقاق.
311:      *
312:      * @return list<array<string, mixed>>
313:      */
314:     public function suppliersReport(): array
315:     {
316:         $aging = DB::table('supplier_invoices')
317:             ->selectRaw(implode(', ', [
318:                 'supplier_id',
319:                 'COALESCE(SUM(total_amount), 0) AS total_purchases',
320:                 'COALESCE(SUM(CASE WHEN (total_amount - paid_amount) > 0 AND (due_date IS NULL OR due_date >= CURRENT_DATE) THEN total_amount - paid_amount END), 0) AS not_due',
321:                 "COALESCE(SUM(CASE WHEN (total_amount - paid_amount) > 0 AND due_date < CURRENT_DATE AND due_date >= CURRENT_DATE - INTERVAL '30 days' THEN total_amount - paid_amount END), 0) AS overdue_1_30",
322:                 "COALESCE(SUM(CASE WHEN (total_amount - paid_amount) > 0 AND due_date < CURRENT_DATE - INTERVAL '30 days' AND due_date >= CURRENT_DATE - INTERVAL '60 days' THEN total_amount - paid_amount END), 0) AS overdue_31_60",
323:                 "COALESCE(SUM(CASE WHEN (total_amount - paid_amount) > 0 AND due_date < CURRENT_DATE - INTERVAL '60 days' AND due_date >= CURRENT_DATE - INTERVAL '90 days' THEN total_amount - paid_amount END), 0) AS overdue_61_90",
324:                 "COALESCE(SUM(CASE WHEN (total_amount - paid_amount) > 0 AND due_date < CURRENT_DATE - INTERVAL '90 days' THEN total_amount - paid_amount END), 0) AS overdue_90_plus",
325:             ]))
326:             ->whereIn('status', ['posted', 'partially_paid', 'paid'])
327:             ->groupBy('supplier_id');
328: 
329:         return DB::table('suppliers as s')
330:             ->leftJoinSub($aging, 'ag', 'ag.supplier_id', '=', 's.id')
331:             ->selectRaw('s.id, s.name, s.current_balance, COALESCE(ag.total_purchases, 0) AS total_purchases, COALESCE(ag.not_due, 0) AS not_due, COALESCE(ag.overdue_1_30, 0) AS overdue_1_30, COALESCE(ag.overdue_31_60, 0) AS overdue_31_60, COALESCE(ag.overdue_61_90, 0) AS overdue_61_90, COALESCE(ag.overdue_90_plus, 0) AS overdue_90_plus')
332:             ->orderBy('s.name')
333:             ->get()
334:             ->map(fn ($row): array => [
335:                 'supplier_id' => (int) $row->id,
336:                 'supplier_name' => $row->name,
337:                 'current_balance' => (float) $row->current_balance,
338:                 'total_purchases' => (float) $row->total_purchases,
339:                 'aging' => [
340:                     'not_due' => (float) $row->not_due,
341:                     'overdue_1_30' => (float) $row->overdue_1_30,
342:                     'overdue_31_60' => (float) $row->overdue_31_60,
343:                     'overdue_61_90' => (float) $row->overdue_61_90,
344:                     'overdue_90_plus' => (float) $row->overdue_90_plus,
345:                 ],
346:             ])->all();
347:     }
