349:     /**
350:      * تقرير ورديات الكاشير: أرقام الوردية المالية كما سُجلت عند الإغلاق
351:      * (مبيعات نقدية/شبكة، متوقع/فعلي، فرق) مع إبراز ذوات الفروق.
352:      *
353:      * @return array{rows: list<array<string, mixed>>, totals: array<string, mixed>}
354:      */
355:     public function shiftsReport(string $from, string $to, bool $onlyDifferences = false, ?int $branchId = null): array
356:     {
357: 
358:         [$periodStart, $periodEnd] = $this->periodBounds($from, $to);
359:         $base = fn () => DB::table('pos_shifts as ps')->when($branchId !== null, fn ($q) => $q->where('ps.branch_id', $branchId))
360:             ->leftJoin('users as u', 'u.id', '=', 'ps.user_id')
361:             ->leftJoin('branches as b', 'b.id', '=', 'ps.branch_id')
362:             ->where('ps.opened_at', '>=', $periodStart)->where('ps.opened_at', '<', $periodEnd)
363:             ->when($onlyDifferences, fn ($q) => $q->whereNotNull('ps.cash_difference')->where('ps.cash_difference', '!=', 0));
364: 
365:         $rows = $base()
366:             ->selectRaw('ps.id, ps.shift_number, ps.user_id, u.name AS cashier_name, ps.branch_id, b.name AS branch_name, ps.status, ps.opened_at, ps.closed_at, ps.cash_sales_total, ps.card_sales_total, ps.cash_returns_total, ps.cash_expenses_total, ps.expected_closing_cash, ps.actual_closing_cash, ps.cash_difference')
367:             ->orderByDesc('ps.opened_at')
368:             ->limit(200)
369:             ->get()
370:             ->map(fn ($row): array => [
371:                 'shift_id' => (int) $row->id,
372:                 'shift_number' => $row->shift_number,
373:                 'cashier_id' => (int) $row->user_id,
374:                 'cashier_name' => $row->cashier_name,
375:                 'branch_id' => (int) $row->branch_id,
376:                 'branch_name' => $row->branch_name,
377:                 'status' => $row->status,
378:                 'opened_at' => $row->opened_at,
379:                 'closed_at' => $row->closed_at,
380:                 'cash_sales_total' => (float) $row->cash_sales_total,
381:                 'card_sales_total' => (float) $row->card_sales_total,
382:                 'cash_returns_total' => (float) $row->cash_returns_total,
383:                 'cash_expenses_total' => (float) $row->cash_expenses_total,
384:                 'expected_closing_cash' => (float) $row->expected_closing_cash,
385:                 'actual_closing_cash' => $row->actual_closing_cash !== null ? (float) $row->actual_closing_cash : null,
386:                 'cash_difference' => $row->cash_difference !== null ? (float) $row->cash_difference : null,
387:                 'has_difference' => $row->cash_difference !== null && (float) $row->cash_difference !== 0.0,
388:             ])->all();
389: 
390:         $totals = $base()
391:             ->selectRaw('COUNT(*) AS shifts_count, COALESCE(SUM(ps.cash_sales_total), 0) AS cash_sales, COALESCE(SUM(ps.card_sales_total), 0) AS card_sales, COALESCE(SUM(CASE WHEN ps.cash_difference IS NOT NULL AND ps.cash_difference != 0 THEN 1 ELSE 0 END), 0) AS shifts_with_difference')
392:             ->first();
393: 
394:         return [
395:             'rows' => $rows,
396:             'totals' => [
397:                 'shifts_count' => (int) $totals->shifts_count,
398:                 'cash_sales' => (float) $totals->cash_sales,
399:                 'card_sales' => (float) $totals->card_sales,
400:                 'shifts_with_difference' => (int) $totals->shifts_with_difference,
401:             ],
402:         ];
403:     }
