405:     /** Sales and their reversals stay in the period when each event actually occurred. */
406:     private function salesEntries(?int $branchId, string $alias = 'entries'): Builder
407:     {
408:         $columns = 'o.id, o.channel, o.allocated_branch_id, o.pos_shift_id, o.payment_method, o.created_at, o.subtotal, o.discount_amount, o.tax_amount, o.shipping_cost, o.grand_total, 1 AS sale_count';
409:         $sales = DB::table('orders as o')->whereNull('o.return_of_order_id')
410:             ->whereIn('o.status', [...self::SALES_STATUSES, 'returned'])->selectRaw($columns);
411:         $posReturns = DB::table('orders as o')->whereNotNull('o.return_of_order_id')
412:             ->selectRaw('o.id, o.channel, o.allocated_branch_id, o.pos_shift_id, o.payment_method, o.created_at, -o.subtotal, -o.discount_amount, -o.tax_amount, -o.shipping_cost, -o.grand_total, 0 AS sale_count');
413:         $rmaReturns = DB::table('return_requests as r')->join('orders as o', 'o.id', '=', 'r.order_id')
414:             ->whereIn('r.status', ['received', 'refunded'])->whereNotNull('r.received_at')
415:             ->selectRaw('o.id, o.channel, r.branch_id AS allocated_branch_id, o.pos_shift_id, o.payment_method, r.received_at AS created_at, -r.total_refund_amount AS subtotal, 0 AS discount_amount, 0 AS tax_amount, 0 AS shipping_cost, -r.total_refund_amount AS grand_total, 0 AS sale_count');
416:         $manualReturns = DB::table('orders as o')->where('o.status', 'returned')->whereNull('o.return_of_order_id')
417:             ->whereNotExists(fn ($q) => $q->selectRaw('1')->from('return_requests as r')->whereColumn('r.order_id', 'o.id')->whereIn('r.status', ['received', 'refunded']))
418:             ->selectRaw('o.id, o.channel, o.allocated_branch_id, o.pos_shift_id, o.payment_method, o.updated_at AS created_at, -o.subtotal, -o.discount_amount, -o.tax_amount, -o.shipping_cost, -o.grand_total, 0 AS sale_count');
419: 
420:         return DB::query()->fromSub($sales->unionAll($posReturns)->unionAll($rmaReturns)->unionAll($manualReturns), $alias)
421:             ->when($branchId !== null, fn ($q) => $q->where($alias.'.allocated_branch_id', $branchId));
422:     }
423: 
424:     private function periodBounds(string $from, string $to): array
425:     {
426:         $zone = config('app.business_timezone', 'Africa/Cairo');
427:         $start = CarbonImmutable::parse($from, $zone)->startOfDay();
428:         $end = CarbonImmutable::parse($to, $zone)->startOfDay();
429:         if ($end->lessThan($start) || $start->diffInDays($end) > 365) {
430:             throw ValidationException::withMessages(['to' => 'فترة التقرير يجب ألا تتجاوز 366 يومًا.']);
431:         }
432: 
433:         return [$start->utc()->toDateTimeString(), $end->addDay()->utc()->toDateTimeString()];
434:     }
