 33: class ReturnController extends Controller implements HasMiddleware
 34: {
 35:     public static function middleware(): array
 36:     {
 37:         return [
 38:             new Middleware('can:returns.view', only: ['index', 'show']),
 39:             new Middleware('can:returns.create', only: ['store']),
 40:             new Middleware('can:returns.update', only: ['update']),
 41:             new Middleware('can:returns.approve', only: ['approve']),
 42:             new Middleware('can:returns.receive', only: ['receive']),
 43:             new Middleware('can:returns.refund', only: ['refund']),
 44:             new Middleware('can:returns.delete', only: ['destroy']),
 45:         ];
 46:     }
 47: 
 48:     public function __construct(protected ReturnService $returns) {}
 49: 
 50:     public function index(Request $request): AnonymousResourceCollection
 51:     {
 52:         $validated = $request->validate([
 53:             'status' => ['nullable', Rule::in(array_column(ReturnStatus::cases(), 'value'))],
 54:             'order_id' => ['nullable', 'integer', 'min:1'],
 55:             'customer_id' => ['nullable', 'integer', 'min:1'],
 56:         ]);
 57:         $search = trim((string) $request->query('search', ''));
 58:         $branch = app(BranchAccess::class)->restrictedBranch($request->user());
 59:         $returns = ReturnRequest::query()->when($branch !== null, fn ($q) => $q->where(fn ($q) => $q->where('branch_id', $branch)->orWhere(fn ($q) => $q->whereNull('branch_id')->whereHas('order', fn ($q) => $q->where('allocated_branch_id', $branch)))))
 60:             ->with(['order:id,order_number', 'customer:id,name', 'items.orderItem'])
 61:             ->when($validated['status'] ?? null, fn ($q, $status) => $q->where('status', $status))
 62:             ->when($request->query('order_id'), fn ($q, $orderId) => $q->where('order_id', (int) $orderId))
 63:             ->when($request->query('customer_id'), fn ($q, $customerId) => $q->where('customer_id', (int) $customerId))
 64:             ->when($search !== '', fn ($q) => $q->where(function ($w) use ($search): void {
 65:                 $pattern = SearchTerm::pattern($search);
 66:                 $w->where('return_number', 'ilike', $pattern)
 67:                     ->orWhereHas('order', fn ($o) => $o->where('order_number', 'ilike', $pattern));
 68:             }))
 69:             ->latest('id')
 70:             ->paginate(20);
 71: 
 72:         return ReturnRequestResource::collection($returns);
 73:     }
 74: 
 75:     public function store(StoreReturnRequest $request): JsonResponse
 76:     {
 77:         $order = Order::query()->findOrFail((int) $request->validated('order_id'));
 78:         if ($order->allocated_branch_id !== null) {
 79:             app(BranchAccess::class)->assertBranch($request->user()->id, (int) $order->allocated_branch_id);
 80:         } else {
 81:             app(BranchAccess::class)->assertCentralAccess($request->user());
 82:         }
 83:         $return = $this->returns->createReturnRequest($order, $request->validated());
 84:         $return->load(['items.orderItem', 'order', 'customer']);
 85: 
 86:         return ReturnRequestResource::make($return)->response()->setStatusCode(201);
 87:     }
