139:     public function refund(RefundReturnRequest $request, ReturnRequest $returnRequest): ReturnRequestResource
140:     {
141:         $this->authorizeReturn($request, $returnRequest);
142:         /** @var User $admin */
143:         $admin = $request->user();
144:         $return = $this->returns->refund($returnRequest, $admin, $request->validated());
145:         $return->load(['items.orderItem', 'order', 'customer']);
146: 
147:         return ReturnRequestResource::make($return);
148:     }
149: 
150:     private function authorizeReturn(Request $request, ReturnRequest $returnRequest): void
151:     {
152:         $branch = app(BranchAccess::class)->restrictedBranch($request->user());
153:         if ($branch === null) {
154:             return;
155:         }
156:         $returnRequest->loadMissing('order:id,allocated_branch_id');
157:         $returnBranch = $returnRequest->branch_id !== null ? (int) $returnRequest->branch_id : null;
158:         $orderBranch = $returnRequest->order?->allocated_branch_id !== null ? (int) $returnRequest->order->allocated_branch_id : null;
159:         if (($returnBranch ?? $orderBranch) !== $branch) {
160:             throw new AuthorizationException('لا تملك صلاحية الوصول إلى هذا المرتجع.');
161:         }
162:     }
