 20: class TreasuryController extends Controller implements HasMiddleware
 21: {
 22:     public static function middleware(): array
 23:     {
 24:         return [
 25:             new Middleware('can:treasuries.view', only: ['index', 'show']),
 26:             new Middleware('can:treasuries.create', only: ['store']),
 27:             new Middleware('can:treasuries.update', only: ['update']),
 28:             new Middleware('can:treasuries.delete', only: ['destroy']),
 29:         ];
 30:     }
 31: 
 32:     public function index(Request $request): JsonResponse
 33:     {
 34:         $filters = $request->validate([
 35:             'branch_id' => ['nullable', 'integer', 'min:1'],
 36:             'type' => ['nullable', Rule::in(array_column(TreasuryType::cases(), 'value'))],
 37:             'is_active' => ['nullable', 'boolean'],
 38:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
 39:         ]);
 40: 
 41:         $branch = app(BranchAccess::class)->restrictedBranch($request->user());
 42:         $treasuries = Treasury::query()->when($branch !== null, fn ($q) => $q->where('branch_id', $branch))
 43:             ->with('branch')
 44:             ->when($filters['branch_id'] ?? null, fn ($q, $v) => $q->where('branch_id', $v))
 45:             ->when($filters['type'] ?? null, fn ($q, $v) => $q->where('type', $v))
 46:             ->when(isset($filters['is_active']), fn ($q) => $q->where('is_active', $filters['is_active']))
 47:             ->orderBy('branch_id')
 48:             ->orderBy('id')
 49:             ->paginate($filters['per_page'] ?? 15);
 50: 
 51:         return response()->json($treasuries);
 52:     }
 53: 
 54:     public function store(Request $request): JsonResponse
 55:     {
 56:         $data = $request->validate([
 57:             'name' => ['required', 'string', 'max:191'],
 58:             'code' => ['required', 'string', 'max:50', 'unique:treasuries,code'],
 59:             'branch_id' => ['nullable', 'integer', 'min:1', 'exists:branches,id'],
 60:             'type' => ['required', Rule::in(array_column(TreasuryType::cases(), 'value'))],
 61:             'is_active' => ['nullable', 'boolean'],
 62:         ]);
 63: 
 64:         $this->assertBranch($request, $data['branch_id'] ?? null);
 65:         $treasury = Treasury::create($data + ['current_balance' => 0]);
 66: 
 67:         return response()->json([
 68:             'message' => 'تم إنشاء الخزينة بنجاح.',
 69:             'data' => $this->treasuryData($treasury),
 70:         ], 201);
 71:     }
 72: 
 73:     public function show(Request $request, Treasury $treasury): JsonResponse
 74:     {
 75:         app(BranchAccess::class)->assertTreasury($request->user()->id, $treasury);
 76: 
 77:         return response()->json(['data' => $this->treasuryData($treasury)]);
 78:     }
 79: 
 80:     public function update(Request $request, Treasury $treasury): JsonResponse
 81:     {
 82:         $data = $request->validate([
 83:             'name' => ['sometimes', 'string', 'max:191'],
 84:             'code' => ['sometimes', 'string', 'max:50', Rule::unique('treasuries', 'code')->ignore($treasury->id)],
 85:             'branch_id' => ['nullable', 'integer', 'min:1', 'exists:branches,id'],
 86:             'type' => ['sometimes', Rule::in(array_column(TreasuryType::cases(), 'value'))],
 87:             'is_active' => ['nullable', 'boolean'],
 88:         ]);
 89: 
 90:         app(BranchAccess::class)->assertTreasury($request->user()->id, $treasury);
 91:         if (array_key_exists('branch_id', $data)) {
 92:             $this->assertBranch($request, $data['branch_id']);
 93:         }
 94:         DB::transaction(function () use ($treasury, $data): void {
 95:             $locked = Treasury::query()->lockForUpdate()->findOrFail($treasury->id);
 96:             if (isset($data['type']) && $data['type'] !== $locked->type->value) {
 97:                 throw new BusinessException('نوع الخزينة غير قابل للتغيير.');
 98:             }
 99:             $unsettled = PosShift::query()->where('treasury_id', $locked->id)->whereIn('status', ['open', 'closed_pending_approval'])->exists();
100:             if (($unsettled || bccomp((string) $locked->current_balance, '0', 2) !== 0 || DB::table('treasury_transactions')->where('treasury_id', $locked->id)->exists()) && array_key_exists('branch_id', $data) && $data['branch_id'] != $locked->branch_id) {
101:                 throw new BusinessException('لا يمكن نقل خزينة لها رصيد أو سجل حركات إلى فرع آخر.');
102:             }
103:             if ($unsettled && array_key_exists('is_active', $data) && ! $data['is_active']) {
104:                 throw new BusinessException('لا يمكن تعطيل درج له وردية لم تُسوَّ.');
105:             }
106:             $locked->update($data);
107:         });
108:         $treasury->refresh();
109: 
110:         return response()->json([
111:             'message' => 'تم تحديث الخزينة بنجاح.',
112:             'data' => $this->treasuryData($treasury),
113:         ]);
114:     }
115: 
116:     public function destroy(Request $request, Treasury $treasury): JsonResponse
117:     {
118:         app(BranchAccess::class)->assertTreasury($request->user()->id, $treasury);
119:         DB::transaction(function () use ($treasury): void {
120:             $locked = Treasury::query()->lockForUpdate()->findOrFail($treasury->id);
121:             if (bccomp((string) $locked->current_balance, '0', 2) !== 0 || DB::table('treasury_transactions')->where('treasury_id', $locked->id)->exists()
122:                 || PosShift::query()->where('treasury_id', $locked->id)->exists()) {
123:                 throw new BusinessException('لا يمكن حذف خزينة لها رصيد أو سجل حركات أو ورديات.');
124:             }
125:             $locked->delete();
126:         });
127: 
128:         return response()->json(['message' => 'تم حذف الخزينة.']);
129:     }
130: 
131:     private function assertBranch(Request $request, ?int $branchId): void
132:     {
133:         if ($branchId === null) {
134:             app(BranchAccess::class)->assertCentralAccess($request->user());
135:         } else {
136:             app(BranchAccess::class)->assertBranch($request->user()->id, $branchId);
137:         }
138:     }
139: 
140:     private function treasuryData(Treasury $treasury): Treasury
141:     {
142:         return $treasury->loadMissing('branch');
143:     }
