  5: namespace App\Services;
  6: 
  7: use App\Enums\TreasuryTransactionType;
  8: use App\Enums\TreasuryTransferStatus;
  9: use App\Exceptions\BusinessException;
 10: use App\Models\PosShift;
 11: use App\Models\Treasury;
 12: use App\Models\TreasuryTransaction;
 13: use App\Models\TreasuryTransfer;
 14: use Brick\Math\BigDecimal;
 15: use Brick\Math\RoundingMode;
 16: use Illuminate\Support\Collection;
 17: use Illuminate\Support\Facades\DB;
 18: 
 19: /**
 20:  * خدمة الخزائن — المدخل الوحيد لأي حركة مالية في الخزائن.
 21:  * قاعدة صارمة: ممنوع تعديل current_balance مباشرة من أي مكان آخر.
 22:  * كل قبض أو صرف يمر من هنا: يسجل حركة في treasury_transactions أولًا،
 23:  * ثم يحدث الرصيد — داخل نفس الـ transaction ومع قفل الصف.
 24:  */
 25: class TreasuryService
 26: {
 27:     public function __construct(private readonly SettingService $settings) {}
 28: 
 29:     /**
 30:      * تسجيل حركة مالية في خزينة مع قفل الصف وتحديث الرصيد.
 31:      *
 32:      * @param  array{
 33:      *     treasury_id: int,
 34:      *     shift_id?: int|null,
 35:      *     type: TreasuryTransactionType,
 36:      *     amount: float|string,
 37:      *     reference_type?: string|null,
 38:      *     reference_id?: int|null,
 39:      *     created_by: int,
 40:      *     notes?: string|null,
 41:      * }  $data
 42:      */
 43:     public function record(array $data): TreasuryTransaction
 44:     {
 45:         return DB::transaction(function () use ($data): TreasuryTransaction {
 46:             /** @var Treasury $treasury */
 47:             $treasury = Treasury::query()->lockForUpdate()->findOrFail($data['treasury_id']);
 48: 
 49:             if (! $treasury->is_active) {
 50:                 throw new BusinessException('الخزينة غير نشطة.');
 51:             }
 52: 
 53:             $amount = BigDecimal::of((string) $data['amount'])->toScale(2, RoundingMode::HalfUp);
 54:             $balanceAfter = BigDecimal::of((string) $treasury->current_balance)->plus($amount)->toScale(2);
 55: 
 56:             // منع الرصيد السالب على أدراج نقطة البيع والخزائن الرئيسية
 57:             if ($balanceAfter->isNegative() && $treasury->type->value !== 'bank_account') {
 58:                 throw new BusinessException('رصيد الخزينة غير كافٍ لإتمام العملية.');
 59:             }
 60: 
 61:             $transaction = TreasuryTransaction::create([
 62:                 'treasury_id' => $treasury->id,
 63:                 'shift_id' => $data['shift_id'] ?? null,
 64:                 'type' => $data['type'],
 65:                 'amount' => (string) $amount,
 66:                 'balance_after' => (string) $balanceAfter,
 67:                 'reference_type' => $data['reference_type'] ?? null,
 68:                 'reference_id' => $data['reference_id'] ?? null,
 69:                 'created_by' => $data['created_by'],
 70:                 'notes' => $data['notes'] ?? null,
 71:                 'created_at' => now(),
 72:             ]);
 73: 
 74:             $treasury->current_balance = (string) $balanceAfter;
 75:             $treasury->save();
 76: 
 77:             return $transaction;
 78:         });
 79:     }
 80: 
 81:     /**
 82:      * تحويل مبلغ من خزينة إلى خزينة أخرى بعد الاعتماد.
 83:      */
 84:     public function approveTransfer(TreasuryTransfer $transfer, int $approverId): TreasuryTransfer
 85:     {
 86:         return DB::transaction(function () use ($transfer, $approverId): TreasuryTransfer {
 87:             $transfer = TreasuryTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
 88:             if ($transfer->status !== TreasuryTransferStatus::Pending) {
 89:                 throw new BusinessException('يمكن اعتماد التحويلات المعلقة فقط.');
 90:             }
 91:             if ((int) $transfer->created_by === $approverId) {
 92:                 throw new BusinessException('يجب أن يعتمد تحويل الخزينة موظف آخر غير منشئه.');
 93:             }
 94:             $this->lockTreasuries([$transfer->from_treasury_id, $transfer->to_treasury_id], $approverId);
 95:             $absAmount = (string) BigDecimal::of((string) $transfer->amount)->abs()->toScale(2, RoundingMode::HalfUp);
 96:             // خصم من المصدر
 97:             $this->record([
 98:                 'treasury_id' => $transfer->from_treasury_id,
 99:                 'type' => TreasuryTransactionType::TransferOut,
100:                 'amount' => '-'.$absAmount,
101:                 'reference_type' => TreasuryTransfer::class,
102:                 'reference_id' => $transfer->id,
103:                 'created_by' => $approverId,
104:                 'notes' => "تحويل #{$transfer->transfer_number} صادر",
105:             ]);
106: 
107:             // إضافة إلى الوجهة
108:             $this->record([
109:                 'treasury_id' => $transfer->to_treasury_id,
110:                 'type' => TreasuryTransactionType::TransferIn,
111:                 'amount' => $absAmount,
112:                 'reference_type' => TreasuryTransfer::class,
113:                 'reference_id' => $transfer->id,
114:                 'created_by' => $approverId,
115:                 'notes' => "تحويل #{$transfer->transfer_number} وارد",
116:             ]);
117: 
118:             $transfer->update([
119:                 'status' => TreasuryTransferStatus::Approved,
120:                 'approved_by' => $approverId,
121:             ]);
122: 
123:             return $transfer->fresh();
124:         }, 3);
125:     }
