127:     /**
128:      * ترحيل نقدية الوردية المعتمدة إلى الخزنة الرئيسية للفرع.
129:      */
130:     public function settleShiftToMainSafe(PosShift $shift, int $approverId): void
131:     {
132:         DB::transaction(function () use ($shift, $approverId): void {
133:             // الخزنة الرئيسية للفرع
134:             $mainSafe = Treasury::query()
135:                 ->where('branch_id', $shift->branch_id)
136:                 ->where('type', 'main_safe')
137:                 ->where('is_active', true)
138:                 ->first();
139: 
140:             if ($mainSafe === null) {
141:                 throw new BusinessException('يلزم وجود خزنة رئيسية نشطة لاعتماد الوردية وتسوية رصيد الدرج.');
142:             }
143: 
144:             // الرصيد الفعلي الحالي في الدرج
145:             $locked = $this->lockTreasuries([$shift->treasury_id, $mainSafe->id]);
146:             $drawer = $locked->get($shift->treasury_id);
147:             $amount = (string) BigDecimal::of((string) $shift->actual_closing_cash)->toScale(2, RoundingMode::HalfUp);
148:             $difference = BigDecimal::of((string) $shift->actual_closing_cash)
149:                 ->minus((string) $drawer->current_balance)->toScale(2);
150:             if (! $difference->isZero()) {
151:                 $this->record([
152:                     'treasury_id' => $drawer->id, 'shift_id' => $shift->id,
153:                     'type' => $difference->isNegative() ? TreasuryTransactionType::CashShortage : TreasuryTransactionType::CashOverage,
154:                     'amount' => (string) $difference, 'reference_type' => PosShift::class,
155:                     'reference_id' => $shift->id, 'created_by' => $approverId,
156:                     'notes' => 'تسوية فرق النقدية للوردية '.$shift->shift_number,
157:                 ]);
158:             }
159: 
160:             if (BigDecimal::of($amount)->isLessThanOrEqualTo('0')) {
161:                 return;
162:             }
163: 
164:             // خصم من درج الكاشير
165:             $this->record([
166:                 'treasury_id' => $shift->treasury_id,
167:                 'type' => TreasuryTransactionType::TransferOut,
168:                 'amount' => '-'.$amount,
169:                 'reference_type' => PosShift::class,
170:                 'reference_id' => $shift->id,
171:                 'created_by' => $approverId,
172:                 'notes' => "ترحيل إغلاق وردية #{$shift->shift_number}",
173:             ]);
174: 
175:             // إضافة للخزنة الرئيسية
176:             $this->record([
177:                 'treasury_id' => $mainSafe->id,
178:                 'type' => TreasuryTransactionType::TransferIn,
179:                 'amount' => $amount,
180:                 'reference_type' => PosShift::class,
181:                 'reference_id' => $shift->id,
182:                 'created_by' => $approverId,
183:                 'notes' => "ترحيل إغلاق وردية #{$shift->shift_number}",
184:             ]);
185:         });
186:     }
