188:     /**
189:      * إنشاء تحويل خزينة جديد (معلق حتى الاعتماد).
190:      */
191:     public function createTransfer(array $data, int $userId): TreasuryTransfer
192:     {
193:         foreach (Treasury::query()->whereIn('id', [$data['from_treasury_id'], $data['to_treasury_id']])->get() as $treasury) {
194:             app(BranchAccess::class)->assertTreasury($userId, $treasury);
195:         }
196:         if ($data['from_treasury_id'] === $data['to_treasury_id']) {
197:             throw new BusinessException('لا يمكن التحويل من خزينة إلى نفسها.');
198:         }
199: 
200:         $number = $this->settings->generateNextNumber('treasury_transfer');
201: 
202:         return TreasuryTransfer::create([
203:             'transfer_number' => $number,
204:             'from_treasury_id' => $data['from_treasury_id'],
205:             'to_treasury_id' => $data['to_treasury_id'],
206:             'amount' => $data['amount'],
207:             'status' => TreasuryTransferStatus::Pending,
208:             'created_by' => $userId,
209:             'notes' => $data['notes'] ?? null,
210:         ]);
211:     }
212: 
213:     /**
214:      * رفض تحويل خزينة.
215:      */
216:     public function rejectTransfer(TreasuryTransfer $transfer, int $approverId): TreasuryTransfer
217:     {
218:         return DB::transaction(function () use ($transfer, $approverId): TreasuryTransfer {
219:             $transfer = TreasuryTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
220:             if ($transfer->status !== TreasuryTransferStatus::Pending) {
221:                 throw new BusinessException('يمكن رفض التحويلات المعلقة فقط.');
222:             }
223:             $this->lockTreasuries([$transfer->from_treasury_id, $transfer->to_treasury_id], $approverId);
224:             $transfer->update(['status' => TreasuryTransferStatus::Rejected, 'approved_by' => $approverId]);
225: 
226:             return $transfer->fresh();
227:         }, 3);
228:     }
229: 
230:     public function lockTreasuries(array $ids, ?int $userId = null): Collection
231:     {
232:         $treasuries = Treasury::query()->whereIn('id', $ids)->orderBy('id')->lockForUpdate()->get()->keyBy('id');
233:         if ($userId !== null) {
234:             foreach ($treasuries as $treasury) {
235:                 app(BranchAccess::class)->assertTreasury($userId, $treasury);
236:             }
237:         }
238: 
239:         return $treasuries;
240:     }
