234:     public function test_receive_moves_stock_good_and_damaged_and_computes_refund(): void
235:     {
236:         $variant = $this->purchasableVariant(100);
237:         $level = $this->giveStock($variant, 10);
238:         $customer = Customer::factory()->create();
239:         $order = $this->deliveredOrder($customer, $variant, 3);
240:         $created = $this->storeCreateReturn($customer, $order, $order->items->first()->id, 3)->assertCreated();
241:         $returnId = $created->json('data.id');
242:         $returnItemId = $created->json('data.items.0.id');
243:         $this->assertSame(3, (int) $variant->product->fresh()->sales_count);
244: 
245:         // الاستلام قبل الاعتماد ممنوع
246:         $this->adminPost("/api/v1/admin/returns/{$returnId}/receive", [
247:             'items' => [['id' => $returnItemId, 'received_good_qty' => 1, 'received_damaged_qty' => 0]],
248:         ])->assertUnprocessable();
249: 
250:         $this->adminPost("/api/v1/admin/returns/{$returnId}/approve", [
251:             'branch_id' => $this->branch->id,
252:         ])->assertOk();
253: 
254:         // استلام يتجاوز المعتمد (3) مرفوض
255:         $this->adminPost("/api/v1/admin/returns/{$returnId}/receive", [
256:             'items' => [['id' => $returnItemId, 'received_good_qty' => 3, 'received_damaged_qty' => 1]],
257:         ])->assertUnprocessable();
258: 
259:         $this->adminPost("/api/v1/admin/returns/{$returnId}/receive", [
260:             'items' => [['id' => $returnItemId, 'received_good_qty' => 2, 'received_damaged_qty' => 1]],
261:         ])->assertOk()
262:             ->assertJsonPath('data.status', 'received')
263:             ->assertJsonPath('data.total_refund_amount', '300.00');
264: 
265:         // السليم عاد متاحًا، والتالف محجوز في وعاء التالف، والفعلي زاد بالكل
266:         $branchLevel = $this->branchLevel($variant);
267:         $this->assertNotNull($branchLevel);
268:         $this->assertSame('3.0000', (string) $branchLevel->on_hand);
269:         $this->assertSame('1.0000', (string) $branchLevel->damaged);
270:         $this->assertEquals(2.0, (float) $branchLevel->available);
271:         // مستوى موقع البيع الأصلي لم يتغير بالاستلام
272:         $this->assertSame('7.0000', (string) $level->fresh()->on_hand);
273: 
274:         // الحركات: sale_return للسليم + sale_return وdamage للتالف — كلها بمرجع المرتجع
275:         $movements = StockMovement::query()->where('reference_type', 'return_request')->where('reference_id', $returnId)->get();
276:         $this->assertSame(3, $movements->count());
277:         $this->assertSame(2, $movements->where('type', 'sale_return')->count());
278:         $this->assertSame(1, $movements->where('type', 'damage')->count());
279:         // عدّاد المبيعات تراجع بالكمية المستلمة كلها
280:         $this->assertSame(0, (int) $variant->product->fresh()->sales_count);
281:     }
