312:         $this->assertFalse((bool) $order->requires_refund);
313:         // وبلا إعادة مخزون ثانية: رصيد ما بعد الرد يساوي رصيد ما بعد الاستلام
314:         $this->assertSame($stockAfterReceive, (string) $this->branchLevel($variant)->on_hand);
315:         $this->assertSame(1, StockMovement::query()->where('reference_type', 'return_request')->where('type', 'sale_return')->count());
316:     }
