 37:     public function recordMovement(array $data, ?StockLevel $prelockedLevel = null): StockMovement
 38:     {
 39:         $apply = function () use ($data, $prelockedLevel): StockMovement {
 40:             $rawQty = $data['quantity'];
 41:             if (! is_numeric($rawQty) || ! is_finite((float) $rawQty) || abs((float) $rawQty) > 99999999.9999) {
 42:                 throw new BusinessException('كمية الحركة غير صالحة.');
 43:             }
 44:             // Work in ten-thousandths to avoid floating point residues at zero.
 45:             $units = (int) round((float) $rawQty * 10000);
 46:             $qty = $units / 10000;
 47: 
 48:             if ($units === 0) {
 49:                 throw new BusinessException('كمية الحركة يجب ألا تساوي صفرًا.');
 50:             }
 51: 
 52:             $type = $data['type'] instanceof StockMovementType ? $data['type'] : StockMovementType::from($data['type']);
 53:             $bucket = $data['affected_bucket'] instanceof StockBucket ? $data['affected_bucket'] : StockBucket::from($data['affected_bucket']);
 54:             $this->assertValidMovementSemantics($type, $bucket, $units);
 55:             $locationId = $data['location_id'] ?? null;
 56: 
 57:             // صف مقفول مسبقًا من المستدعي (lockLevels): لا إعادة قفل ولا فحص موقع —
 58:             // المستدعي ضمن الصف والموقع عند القفل. خلاف ذلك نقفل هنا ونتحقق.
 59:             if ($prelockedLevel !== null) {
 60:                 if ((int) $prelockedLevel->product_variant_id !== (int) $data['product_variant_id']
 61:                     || (int) $prelockedLevel->branch_id !== (int) $data['branch_id']
 62:                     || ($prelockedLevel->location_id === null ? null : (int) $prelockedLevel->location_id) !== ($locationId === null ? null : (int) $locationId)) {
 63:                     throw new \LogicException('الصف المقفول مسبقًا لا يطابق مفتاح الحركة.');
 64:                 }
 65:                 $stock = $prelockedLevel;
 66:             } else {
 67:                 if ($locationId !== null && ! Location::query()->whereKey($locationId)->where('branch_id', $data['branch_id'])->exists()) {
 68:                     throw new BusinessException('الموقع لا يتبع الفرع المحدد.');
 69:                 }
 70: 
 71:                 $stock = $this->lockLevels([[
 72:                     'product_variant_id' => $data['product_variant_id'],
 73:                     'branch_id' => $data['branch_id'],
