129:             $referenceType = $data['reference_type'] ?? null;
130:             if (is_string($referenceType) && class_exists($referenceType)) {
131:                 $referenceType = (new $referenceType)->getMorphClass();
132:             }
133: 
134:             // 4. تسجيل الحركة في دفتر الأستاذ (Ledger)
135:             $movement = StockMovement::query()->create([
