137:                 'product_variant_id' => $data['product_variant_id'],
138:                 'branch_id' => $data['branch_id'],
139:                 'location_id' => $locationId,
140:                 'type' => $type,
141:                 'affected_bucket' => $bucket,
142:                 'quantity' => $qty,
143:                 'balance_before' => $before,
144:                 'balance_after' => $after,
145:                 'unit_cost' => $data['unit_cost'] ?? null,
146:                 'reference_type' => $referenceType,
147:                 'reference_id' => $data['reference_id'] ?? null,
148:                 'created_by' => $createdBy,
149:                 'notes' => $data['notes'] ?? null,
150:             ]);
151: 
152:             // 5. تحديث جدول الأرصدة من واقع الحركة
153:             $stock->{$bucketKey} = $after;
