220:     /**
221:      * تسوية يدوية متعددة العناصر داخل transaction واحدة (أي فشل يلغي الكل).
222:      *
223:      * مع مفتاح عدم تكرار (Idempotency-Key): يُدرج المفتاح داخل نفس الـ transaction،
224:      * فالتكرار المتزامن يصطدم بالقيد الفريد بعد commit الأول ويعيد الحركات المحفوظة،
225:      * ونفس المفتاح بحمولة مختلفة يُرفض 409، وفشل الطلب يلغي المفتاح معه.
226:      *
227:      * @param  array{branch_id: int, location_id?: int|null, items: list<array{product_variant_id: int, adjustment_type: string, quantity: float|int|string, reason?: string|null}>}  $payload
228:      * @return list<StockMovement>
229:      */
230:     public function applyAdjustments(array $payload, int $userId, ?string $idempotencyKey = null): array
231:     {
232:         app(BranchAccess::class)->assertBranch($userId, (int) $payload['branch_id']);
233:         if ($idempotencyKey === null) {
234:             return $this->executeAdjustments($payload, $userId);
235:         }
236: 
237:         $requestHash = IdempotencyFingerprint::hash($payload);
238: 
239:         try {
240:             return DB::transaction(function () use ($payload, $userId, $idempotencyKey, $requestHash): array {
241:                 $record = InventoryIdempotencyKey::query()->create([
242:                     'user_id' => $userId,
243:                     'key' => $idempotencyKey,
244:                     'request_hash' => $requestHash,
245:                 ]);
246: 
247:                 $movements = $this->executeAdjustments($payload, $userId);
248: 
249:                 $record->update([
250:                     'response' => array_map(fn (StockMovement $movement) => $movement->id, $movements),
251:                     'status_code' => 201,
252:                 ]);
253: 
254:                 return $movements;
255:             });
256:         } catch (UniqueConstraintViolationException $e) {
257:             // الالتقاط خاص بقيد مفتاح عدم التكرار وحده: أي انتهاك فريد آخر داخل
258:             // المعاملة خطأ حقيقي يجب أن يظهر، لا أن يُقنَّع كتعارض مفتاح (L-2).
259:             // L4: اسم القيد من رسالة السائق (errorInfo) لا من نص الاستثناء العام.
260:             $driverMessage = (string) ($e->errorInfo[2] ?? $e->getMessage());
261:             if (! str_contains($driverMessage, 'inventory_idempotency_keys_user_id_key_unique')
262:                 && ! str_contains($e->getMessage(), 'inventory_idempotency_keys_user_id_key_unique')) {
263:                 throw $e;
264:             }
265: 
266:             $record = InventoryIdempotencyKey::query()
267:                 ->where('user_id', $userId)->where('key', $idempotencyKey)->first();
268: 
269:             if ($record === null) {
270:                 throw new BusinessException('تعارض في مفتاح عدم التكرار؛ أعد المحاولة.', [], 409);
271:             }
272: 
273:             if (! hash_equals($record->request_hash, $requestHash)) {
274:                 throw new BusinessException('مفتاح عدم التكرار هذا مستخدم مسبقًا مع بيانات مختلفة.', [], 409);
275:             }
276: 
277:             $ids = $record->response ?? [];
278:             $byId = StockMovement::query()->whereIn('id', $ids)->get()->keyBy('id');
279: 
280:             return array_values(array_filter(array_map(fn ($id) => $byId->get($id), $ids)));
281:         }
282:     }
