284:     /**
285:      * @param  array{branch_id: int, location_id?: int|null, items: list<array{product_variant_id: int, adjustment_type: string, quantity: float|int|string, reason?: string|null}>}  $payload
286:      * @return list<StockMovement>
287:      */
288:     private function executeAdjustments(array $payload, int $userId): array
289:     {
290:         return DB::transaction(function () use ($payload, $userId): array {
291:             app(BranchAccess::class)->assertBranch($userId, (int) $payload['branch_id']);
292: 
293:             // M5: التعطيل لا يحبس الرصيد — عمليات الإخراج (decrease/تالف/شطب) مسموحة على
294:             // متغير/موقع معطّل لتصفية رصيده، والإدخال (increase) وحده يتطلب النشاط.
295:             if (collect($payload['items'])->contains('adjustment_type', 'increase')) {
296:                 $variants = ProductVariant::query()->withTrashed()
297:                     ->whereIn('id', array_column($payload['items'], 'product_variant_id'))
298:                     ->get()->keyBy('id');
299:                 $location = ($payload['location_id'] ?? null) !== null ? Location::query()->find($payload['location_id']) : null;
300: 
301:                 foreach ($payload['items'] as $item) {
302:                     if ($item['adjustment_type'] !== 'increase') {
303:                         continue;
304:                     }
305:                     // المحذوف ناعمًا يعامل كمعطّل للإدخال، لكن إخراجه يظل مسموحًا
306:                     // حتى لا يُحبس رصيده للأبد (M-9).
307:                     $variant = $variants->get($item['product_variant_id']);
308:                     if ($variant === null || $variant->trashed() || ! $variant->is_active) {
309:                         throw new BusinessException('لا يمكن الإدخال على متغير معطّل؛ فعّله أولًا أو استخدم عمليات الإخراج لتصفية رصيده.');
310:                     }
311:                     if ($location !== null && ! $location->is_active) {
312:                         throw new BusinessException('لا يمكن الإدخال إلى موقع معطّل؛ فعّله أولًا.');
313:                     }
314:                 }
315:             }
316:             $levels = $this->lockLevels(array_map(fn ($item) => [
317:                 'product_variant_id' => $item['product_variant_id'],
318:                 'branch_id' => $payload['branch_id'],
319:                 'location_id' => $payload['location_id'] ?? null,
320:             ], $payload['items']));
321:             $movements = [];
322: 
323:             foreach ($payload['items'] as $item) {
324:                 // الصف مقفول مسبقًا أعلاه — تُمرَّر حركتا العنصر عليه مباشرة.
325:                 $level = $levels->get($this->levelKey([
326:                     'product_variant_id' => $item['product_variant_id'],
327:                     'branch_id' => $payload['branch_id'],
328:                     'location_id' => $payload['location_id'] ?? null,
329:                 ]));
330:                 if (in_array($item['adjustment_type'], ['write_off_damaged', 'restore_damaged'], true)) {
331:                     $base = [
332:                         'product_variant_id' => $item['product_variant_id'],
333:                         'branch_id' => $payload['branch_id'], 'location_id' => $payload['location_id'] ?? null,
334:                         'created_by' => $userId, 'notes' => $item['reason'] ?? null,
335:                         'quantity' => -abs((float) $item['quantity']),
336:                     ];
337:                     $movements[] = $this->recordMovement([...$base, 'type' => StockMovementType::DamageRelease, 'affected_bucket' => StockBucket::Damaged], $level);
338:                     if ($item['adjustment_type'] === 'write_off_damaged') {
339:                         $movements[] = $this->recordMovement([...$base, 'type' => StockMovementType::DamageWriteOff, 'affected_bucket' => StockBucket::OnHand], $level);
340:                     }
341: 
342:                     continue;
343:                 }
344:                 [$type, $bucket, $sign] = match ($item['adjustment_type']) {
345:                     'increase' => [StockMovementType::AdjustmentIn, StockBucket::OnHand, 1],
346:                     'decrease' => [StockMovementType::AdjustmentOut, StockBucket::OnHand, -1],
347:                     'mark_damaged' => [StockMovementType::Damage, StockBucket::Damaged, 1],
348:                     default => throw new BusinessException('نوع تسوية غير معروف: '.$item['adjustment_type']),
349:                 };
350: 
351:                 $movements[] = $this->recordMovement([
352:                     'product_variant_id' => $item['product_variant_id'],
353:                     'branch_id' => $payload['branch_id'],
354:                     'location_id' => $payload['location_id'] ?? null,
355:                     'type' => $type,
356:                     'affected_bucket' => $bucket,
357:                     'quantity' => $sign * abs((float) $item['quantity']),
358:                     'created_by' => $userId,
359:                     'notes' => $item['reason'] ?? null,
360:                 ], $level);
361:             }
362: 
363:             return $movements;
364:         });
365:     }
