367:     /** الرصيد الحالي لمتغير في فرع/موقع (للقطات الجرد ونحوها) — قراءة فقط. */
368:     public function levelFor(int $variantId, int $branchId, ?int $locationId): ?StockLevel
369:     {
370:         return StockLevel::query()
371:             ->where('product_variant_id', $variantId)
372:             ->where('branch_id', $branchId)
373:             ->where('location_id', $locationId)
374:             ->first();
375:     }
