377:     /** Acquire every stock key before a multi-item operation, in one global order. */
378:     public function lockLevels(array $keys): Collection
379:     {
380:         if (DB::transactionLevel() === 0) {
381:             throw new \LogicException('Stock locks require an active transaction.');
382:         }
383:         // انتظار محدود للأقفال داخل هذه المعاملة فقط؛ التنافس الطويل يتحول لرفض
384:         // واضح (409) بدل تعليق الطلب حتى مهلة PHP-FPM.
385:         $keys = collect($keys)->unique(fn ($key) => $this->levelKey($key))
386:             ->sortBy(fn ($key) => [(int) $key['branch_id'], (int) ($key['location_id'] ?? 0), (int) $key['product_variant_id']]);
387:         if ($keys->isEmpty()) {
388:             return collect();
389:         }
390:         $now = now();
391:         $previousTimeout = DB::selectOne("SELECT current_setting('lock_timeout') AS value")->value;
392:         DB::statement("SET LOCAL lock_timeout = '5s'");
393: 
394:         try {
395:             // Lock variants before stock rows in every path, including callers
396:             // that prelock a batch of balances before recording movements.
397:             // H1: shared (FOR SHARE) lock — movements only need to block
398:             // concurrent variant edits (which take FOR UPDATE), while shared
399:             // locks don't block each other, so branches run in parallel.
400:             // The real serialization stays on stock_levels (FOR UPDATE below).
401:             $variantIds = $keys->pluck('product_variant_id')->unique()->sort()->values();
402:             $variants = ProductVariant::withTrashed()->whereIn('id', $variantIds)->orderBy('id')->sharedLock()->get();
403:             if ($variants->count() !== $variantIds->count()) {
404:                 throw new BusinessException('أحد المتغيرات لم يعد متاحًا.');
405:             }
406: 
407:             // Aggregate threshold checks must see earlier movements at other
408:             // locations in this branch. Lock only pairs with a branch threshold.
409:             $thresholdIds = $variants->filter(fn ($variant) => (float) $variant->reorder_level > 0)->modelKeys();
410:             $pairs = $keys->filter(fn ($key) => in_array((int) $key['product_variant_id'], $thresholdIds, true))
411:                 ->unique(fn ($key) => $key['branch_id'].':'.$key['product_variant_id'])
412:                 ->sortBy(fn ($key) => [(int) $key['branch_id'], (int) $key['product_variant_id']]);
413:             foreach ($pairs as $key) {
414:                 DB::statement('SELECT pg_advisory_xact_lock(hashtextextended(?, 0))', [
415:                     'stock-threshold:'.$key['branch_id'].':'.$key['product_variant_id'],
416:                 ]);
417:             }
418: 
419:             // M2: batch location→branch ownership check inside the lock path,
420:             // so executeAdjustments cannot plant (branch A, location of branch
421:             // B) rows through the prelocked path. The composite FK migration
422:             // enforces the same invariant at the database level.
423:             $locationIds = $keys->pluck('location_id')->filter(fn ($id) => $id !== null)->unique()->values();
424:             if ($locationIds->isNotEmpty()) {
425:                 $branchByLocation = Location::query()->whereIn('id', $locationIds->all())->pluck('branch_id', 'id');
426:                 foreach ($keys as $key) {
427:                     if (($key['location_id'] ?? null) === null) {
428:                         continue;
429:                     }
430:                     $actual = $branchByLocation->get($key['location_id']);
431:                     if ($actual === null || (int) $actual !== (int) $key['branch_id']) {
432:                         throw new BusinessException('الموقع لا يتبع الفرع المحدد.');
433:                     }
434:                 }
435:             }
436: 
437:             // الإدخال نفسه قد ينتظر قفلًا: ON CONFLICT ينتظر معاملة أخرى أدخلت
438:             // نفس المفتاح ولم تعتمد بعد، فيخضع لنفس lock_timeout — لازم يكون
439:             // جوه الـ try حتى يتحول الانتظار الطويل لـ 409 لا 500 (M-2).
440:             $rows = $keys->map(fn ($key) => [
441:                 'product_variant_id' => $key['product_variant_id'], 'branch_id' => $key['branch_id'],
442:                 'location_id' => $key['location_id'] ?? null, 'created_at' => $now, 'updated_at' => $now,
443:             ])->values();
444:             foreach ($rows->chunk(1000) as $chunk) {
445:                 DB::table('stock_levels')->insertOrIgnore($chunk->all());
446:             }
447: 
448:             $levels = StockLevel::query()->with(['variant:id,product_id,is_active,deleted_at,reorder_level', 'location:id,is_active'])->where(function ($query) use ($keys): void {
449:                 foreach ($keys->groupBy(fn ($key) => $key['branch_id'].':'.($key['location_id'] ?? 0)) as $group) {
450:                     $identity = $group->first();
451:                     $query->orWhere(fn ($scope) => $scope->where('branch_id', $identity['branch_id'])
452:                         ->where('location_id', $identity['location_id'] ?? null)
453:                         ->whereIn('product_variant_id', $group->pluck('product_variant_id')->all()));
454:                 }
455:             })->orderBy('branch_id')->orderByRaw('location_id ASC NULLS FIRST')->orderBy('product_variant_id')
456:                 ->lockForUpdate()->get()->keyBy(fn ($stock) => $this->levelKey($stock->getAttributes()));
457:         } catch (QueryException $e) {
458:             // Keep deadlocks as database exceptions so the outer transaction
459:             // can retry them. The API exception handler returns 409 if exhausted.
460:             if (($e->errorInfo[0] ?? $e->getCode()) === '55P03') {
461:                 throw new BusinessException('المخزون مشغول بعملية أخرى الآن؛ أعد المحاولة بعد لحظات.', [], 409);
462:             }
463: 
464:             throw $e;
465:         } catch (\Throwable $e) {
466:             DB::selectOne("SELECT set_config('lock_timeout', ?, true)", [$previousTimeout]);
467:             throw $e;
468:         }
469: 
470:         // Restore the caller's transaction-local setting, not the session default.
471:         // Failed PostgreSQL transactions must roll back before further SQL.
472:         DB::selectOne("SELECT set_config('lock_timeout', ?, true)", [$previousTimeout]);
473: 
474:         return $levels;
475:     }
