482:     public function receivingLocation(int $branchId, ?int $locationId = null): ?int
483:     {
484:         $query = Location::query()->where('branch_id', $branchId)->where('is_active', true);
485:         if ($locationId !== null) {
486:             if (! $query->whereKey($locationId)->exists()) {
487:                 throw new BusinessException('موقع الاستلام غير نشط أو لا يتبع الفرع.');
488:             }
489: 
490:             return $locationId;
491:         }
492:         $id = $query->orderByRaw("CASE WHEN type = 'receiving' THEN 0 ELSE 1 END")->orderBy('id')->value('id');
493: 
494:         return $id === null ? null : (int) $id;
495:     }
