497:     private function assertValidMovementSemantics(StockMovementType $type, StockBucket $bucket, int $units): void
498:     {
499:         // L4: فرع default حتى لا ينفجر نوع جديد بـ UnhandledMatchError (500).
500:         [$allowed, $positive] = match ($type) {
501:             StockMovementType::ProductionReceipt, StockMovementType::PurchaseReceipt, StockMovementType::SaleReturn,
502:             StockMovementType::AdjustmentIn, StockMovementType::StocktakeGain, StockMovementType::TransferIn => [[StockBucket::OnHand], true],
503:             StockMovementType::Sale, StockMovementType::AdjustmentOut,
504:             StockMovementType::StocktakeLoss, StockMovementType::TransferOut,
505:             StockMovementType::DamageWriteOff => [[StockBucket::OnHand], false],
506:             StockMovementType::Damage => [[StockBucket::Damaged], true],
507:             StockMovementType::DamageRelease => [[StockBucket::Damaged], false],
508:             StockMovementType::Reserve => [[StockBucket::Reserved], true],
509:             StockMovementType::ReleaseReserve => [[StockBucket::Reserved], false],
510:             StockMovementType::TransferInTransit => [[StockBucket::InTransit], true],
511:             StockMovementType::TransferTransitRelease, StockMovementType::TransferShortage => [[StockBucket::InTransit], false],
512:             default => throw new BusinessException('نوع حركة مخزنية غير مدعوم: '.$type->value),
513:         };
514:         if (! in_array($bucket, $allowed, true) || ($units > 0) !== $positive) {
515:             throw new BusinessException('نوع الحركة لا يطابق وعاء المخزون أو اتجاه الكمية.');
516:         }
517:     }
