152:         // وضع Shipped يدويًا يترك الطلب بلا بوليصة فلا يصله ويب هوك تسليم
153:         if (($request->validated()['status'] ?? null) === OrderStatus::Shipped->value) {
154:             throw new BusinessException('حالة الشحن تتم فقط عبر إنشاء بوليصة شحن للطلب.');
