167:     /**
168:      * تحديث حالة الدفع يدويًا (F6): مسار إداري صريح بدل الترقيع عبر تغيير
169:      * الحالة. يُسجّل التغيير في سجل الطلب بالمنفّذ والملاحظة للتدقيق.
170:      */
171:     public function updatePayment(UpdateOrderPaymentRequest $request, Order $order): AdminOrderResource
172:     {
173:         $this->authorizeOrder($request, $order);
174:         $data = $request->validated();
175:         $to = (string) $data['payment_status'];
176: 
177:         // قفل صف + transaction (H4): سباق مع ويب هوك الدفع كان يضيّع تحديث
178:         // أحدهما (lost update)، وآلة انتقالات تمنع الحالات المستحيلة.
179:         $order = DB::transaction(function () use ($order, $to, $data, $request): Order {
180:             $order = Order::query()->lockForUpdate()->findOrFail($order->id);
181:             $from = $order->payment_status;
182: 
183:             if ($from === $to) {
184:                 return $order;
185:             }
186:             if (! in_array($to, self::PAYMENT_TRANSITIONS[$from] ?? [], true)) {
187:                 throw new BusinessException("انتقال حالة دفع غير مسموح: من ({$from}) إلى ({$to}).");
188:             }
189: 
190:             // حالة الاسترداد تتبع حالة الطلب لا القيمة القادمة (H4): دفع على
191:             // طلب ملغى/مرتجع يستلزم استردادًا، والاسترداد يُسقط الالتزام.
192:             // ضبط requires_refund مباشرة من $to كان يمحو الالتزام بصمت.
193:             $requiresRefund = $to === 'paid'
194:                 && in_array($order->status, [OrderStatus::Cancelled, OrderStatus::Returned], true);
195:             if ($to === 'refunded') {
196:                 if (empty($data['refund_reference'])) {
197:                     throw new BusinessException('الانتقال إلى مسترد يتطلب مرجع استرداد (refund_reference).');
198:                 }
199:                 $requiresRefund = false;
200:             }
201: 
202:             $order->update([
203:                 'payment_status' => $to,
204:                 'requires_refund' => $requiresRefund,
205:             ]);
206: 
207:             $actor = $request->user();
208:             $notes = trim("تحديث يدوي لحالة الدفع: {$from} ← {$to}. ".($data['notes'] ?? ''));
209:             $order->statusHistories()->create([
210:                 'from_status' => $order->status,
211:                 'to_status' => $order->status,
212:                 'changed_by_type' => $actor?->getMorphClass(),
213:                 'changed_by_id' => $actor?->getKey(),
214:                 'notes' => mb_substr($notes.($to === 'refunded' ? ' [مرجع الاسترداد: '.($data['refund_reference'] ?? '').']' : ''), 0, 500),
215:             ]);
216: 
217:             return $order;
218:         });
219: 
220:         return $this->orderResource($order);
221:     }
