 19: /**
 20:  * توزيع الطلب على الفروع وحجز مخزونه (reserved) عبر InventoryService حصرًا.
 21:  *
 22:  * الخوارزمية:
 23:  * 1. فرع مُجبر من الأدمن: يُتحقق من تغطيته ويُحجز منه.
 24:  * 2. أول فرع نشط واحد يغطي الطلب كاملًا — أولوية لفرع نفس مدينة العميل.
 25:  * 3. وإلا: كل صنف من الفرع الأعلى رصيدًا متاحًا له (الصنف كاملًا من فرع واحد).
 26:  *
 27:  * داخل الفرع الواحد قد يتوزع الصنف على أكثر من موقع (الأعلى متاحًا أولًا).
 28:  * أي نقص في أي صنف يُلغي العملية كلها (transaction واحدة — لا حجز جزئي يتسرب).
 29:  */
 30: class OrderAllocationService
 31: {
 32:     public function __construct(protected InventoryService $inventoryService) {}
 33: 
 34:     public function allocate(Order $order, ?int $forcedBranchId = null, ?int $performedBy = null): Order
 35:     {
 36:         return DB::transaction(function () use ($order, $forcedBranchId, $performedBy): Order {
 37:             // إعادة قراءة الطلب بقفل صف قبل فحص التوزيع السابق (C1)
 38:             $order = Order::query()->lockForUpdate()->findOrFail($order->id);
 39:             $order->load('items');
 40:             // ترتيب قفل عام ثابت (F-02): البنود بترتيب product_variant_id
 41:             // في كل المسارات حتى لا ينتظر طلبان بعضهما دائريًا (40P01)
 42:             $order->setRelation('items', $order->items
 43:                 ->sortBy(fn (OrderItem $item): int => (int) $item->product_variant_id)
 44:                 ->values());
 45:             $performedBy ??= auth()->id();
 46: 
 47:             if (in_array($order->status, [\App\Enums\OrderStatus::Cancelled, \App\Enums\OrderStatus::Shipped, \App\Enums\OrderStatus::Delivered, \App\Enums\OrderStatus::Returned], true)) {
 48:                 throw new BusinessException('التوزيع غير متاح على هذه الحالة.');
 49:             }
 50: 
 51:             if ($order->allocated_branch_id !== null
 52:                 || $order->items->contains(fn (OrderItem $item): bool => $item->allocated_branch_id !== null)) {
 53:                 throw new BusinessException('الطلب مُوزّع على الفروع من قبل؛ ألغِ التوزيع الحالي أولًا قبل إعادة التوزيع.');
 54:             }
 55: 
 56:             // 1. فرع مُجبر يدويًا
 57:             if ($forcedBranchId !== null) {
 58:                 $branch = Branch::query()->where('is_active', true)->find($forcedBranchId);
 59:                 if ($branch === null) {
 60:                     throw new BusinessException('الفرع المحدد غير موجود أو غير نشط.');
 61:                 }
 62:                 $this->reserveItemsFromBranch($order, $branch->id, $performedBy);
 63:                 $order->update(['allocated_branch_id' => $branch->id]);
 64: 
 65:                 return $order->fresh(['items']);
 66:             }
 67: 
 68:             // خريطة تغطية واحدة مجمّعة لكل الفروع والأصناف (M15) بدل
 69:             // استعلام لكل فرع × صنف — القرارات التالية كلها في الذاكرة
 70:             $coverage = $this->branchAvailabilityMap($order);
 71: 
 72:             // 2. فرع واحد يغطي الطلب كاملًا (أولوية لنفس مدينة العميل:
 73:             // بالمعرّف أولًا ثم بمطابقة الاسم كرجوع — L5)
 74:             $cityName = $order->city?->name_ar;
 75:             $branches = Branch::query()
 76:                 ->where('is_active', true)
 77:                 ->when($order->city_id !== null, fn (Builder $q): Builder => $q->orderByRaw('CASE WHEN city_id = ? THEN 0 ELSE 1 END', [$order->city_id]))
 78:                 // CASE لا «city = ? DESC» (F17): في Postgres ترتيب DESC يضع
 79:                 // NULL أولًا فتتقدّم فروع بلا مدينة معلنة على فرع مدينة العميل
 80:                 ->when($cityName !== null, fn (Builder $q): Builder => $q->orderByRaw('CASE WHEN city = ? THEN 0 ELSE 1 END', [$cityName]))
 81:                 ->orderBy('id')
 82:                 ->get();
 83: 
 84:             $candidateAttempts = 0;
 85:             foreach ($branches as $branch) {
 86:                 if ($this->canBranchFulfillFullOrder($order, $branch->id, $coverage)) {
 87:                     if (++$candidateAttempts > 3) {
 88:                         break;
 89:                     }
 90:                     try {
 91:                         return DB::transaction(function () use ($order, $branch, $performedBy): Order {
 92:                             $this->reserveItemsFromBranch($order, $branch->id, $performedBy);
 93:                             $order->update(['allocated_branch_id' => $branch->id]);
 94: 
 95:                             return $order->fresh(['items']);
 96:                         });
 97:                     } catch (BusinessException $e) {
 98:                         if ($e->errorCode !== 'insufficient_stock') {
 99:                             throw $e;
100:                         }
101:                         $order->load('items');
102:                     }
103:                 }
104:             }
105: 
106:             // A bounded retry recalculates coverage after a competing checkout.
107:             for ($attempt = 0; $attempt < 3; $attempt++) {
108:                 $coverage = $this->branchAvailabilityMap($order);
109:                 $plan = [];
110:                 foreach ($order->items as $item) {
111:                     $branchId = $this->bestBranchForItem($item, $coverage);
112:                     if ($branchId === null) {
113:                         throw new BusinessException("الرصيد المتاح للصنف [{$item->sku_snapshot}] غير كافٍ لإتمام الطلب.");
114:                     }
115:                     $plan[(int) $item->product_variant_id] = $branchId;
116:                 }
117:                 try {
118:                     return DB::transaction(function () use ($order, $plan, $performedBy): Order {
119:                         $levels = $this->lockPlannedLevels($plan);
120:                         foreach ($order->items as $item) {
121:                             $branchId = $plan[(int) $item->product_variant_id];
122:                             $this->reserveItemFromBranch($order, $item, $branchId, $performedBy, $levels);
123:                             $item->update(['allocated_branch_id' => $branchId]);
124:                         }
125: 
126:                         return $order->fresh(['items']);
127:                     });
128:                 } catch (BusinessException $e) {
129:                     if ($e->errorCode !== 'insufficient_stock' || $attempt === 2) {
130:                         throw $e;
131:                     }
132:                     $order->load('items');
133:                 }
134:             }
135:             throw new BusinessException('تغير المخزون أثناء الحجز؛ أعد المحاولة.', [], 409);
136:         });
137:     }
138: 
139:     /**
140:      * فك توزيع الطلب (M5): يُحرّر كل حجوزات الطلب من وعاء reserved ويعيده
141:      * إلى «غير موزّع» — كان endpoint التوزيع يشير لهذه العملية في رسالته
142:      * بينما لا سبيل لتنفيذها. الحجوزات تُقرأ من دفتر الحركات نفسه، فلا يعتمد
143:      * الفك على حالة مشتقة قابلة للانحراف.
144:      */
145:     public function deallocate(Order $order, ?int $performedBy = null): Order
146:     {
147:         return DB::transaction(function () use ($order, $performedBy): Order {
148:             $order = Order::query()->lockForUpdate()->findOrFail($order->id);
149:             $order->load('items');
150:             // ترتيب قفل عام ثابت كالتوزيع (F-02) لتفادي الجمود
151:             $order->setRelation('items', $order->items
152:                 ->sortBy(fn (OrderItem $item): int => (int) $item->product_variant_id)
153:                 ->values());
154:             $performedBy ??= auth()->id();
155: 
156:             if (in_array($order->status, [\App\Enums\OrderStatus::Cancelled, \App\Enums\OrderStatus::Shipped, \App\Enums\OrderStatus::Delivered, \App\Enums\OrderStatus::Returned], true)) {
157:                 throw new BusinessException('فك التوزيع غير متاح على هذه الحالة.');
158:             }
159: 
160:             if (! $this->isAllocated($order)) {
161:                 throw new BusinessException('الطلب غير موزّع على أي فرع؛ لا شيء لفكه.');
162:             }
163: 
164:             // C3: الحجز القائم الصافي لكل مفتاح — لا يُفك أي حجز مرتين
165:             // مهما تكرر allocate/deallocate.
166:             $net = StockMovement::query()
167:                 ->whereIn('reference_type', array_unique([$order->getMorphClass(), Order::class]))
168:                 ->where('reference_id', $order->id)
169:                 ->whereIn('type', [StockMovementType::Reserve->value, StockMovementType::ReleaseReserve->value])
170:                 ->groupBy('product_variant_id', 'branch_id', 'location_id')
171:                 ->selectRaw('product_variant_id, branch_id, location_id, SUM(quantity) AS net_qty')
172:                 ->get()
173:                 ->map(fn ($row): array => [
174:                     'product_variant_id' => (int) $row->product_variant_id,
175:                     'branch_id' => (int) $row->branch_id,
176:                     'location_id' => $row->location_id === null ? null : (int) $row->location_id,
177:                     'net_qty' => (float) $row->net_qty,
178:                 ])
179:                 ->filter(fn (array $row): bool => $row['net_qty'] > 1e-9)
180:                 ->sortBy(fn (array $row): string => $row['branch_id'].':'.$row['location_id'].':'.$row['product_variant_id'])
181:                 ->values();
182: 
183:             $levels = $this->inventoryService->lockLevels($net->map(fn (array $row): array => [
184:                 'product_variant_id' => $row['product_variant_id'],
185:                 'branch_id' => $row['branch_id'],
186:                 'location_id' => $row['location_id'],
187:             ])->all());
188: 
189:             foreach ($net as $row) {
190:                 $this->inventoryService->recordMovement([
191:                     'product_variant_id' => (int) $row['product_variant_id'],
192:                     'branch_id' => (int) $row['branch_id'],
193:                     'location_id' => $row['location_id'],
194:                     'type' => StockMovementType::ReleaseReserve,
195:                     'affected_bucket' => StockBucket::Reserved,
196:                     'quantity' => -1 * (float) $row['net_qty'],
197:                     'reference_type' => Order::class,
198:                     'reference_id' => $order->id,
199:                     'created_by' => $performedBy,
200:                     'notes' => "فك يدوي لتوزيع الطلب رقم {$order->order_number}",
201:                 ], $levels->get($this->inventoryService->levelKey($row)));
202:             }
203: 
204:             $order->items()->update(['allocated_branch_id' => null]);
205:             $order->update(['allocated_branch_id' => null]);
206: 
207:             return $order->fresh(['items']);
208:         });
209:     }
