211:     /** هل الطلب موزّع على أي فرع (على مستوى الطلب أو أي بند)؟ */
212:     public function isAllocated(Order $order): bool
213:     {
214:         return $order->allocated_branch_id !== null
215:             || $order->items->contains(fn (OrderItem $item): bool => $item->allocated_branch_id !== null);
216:     }
217: 
218:     /** Lock only the branch/variant pairs selected by the coverage plan. */
219:     private function lockPlannedLevels(array $plan): Collection
220:     {
221:         if ($plan === []) {
222:             return collect();
223:         }
224:         $rows = StockLevel::query()->where(function ($query) use ($plan): void {
225:             foreach ($plan as $variantId => $branchId) {
226:                 $query->orWhere(fn ($q) => $q->where('product_variant_id', $variantId)->where('branch_id', $branchId));
227:             }
228:         })->where(fn ($q) => $q->whereNull('location_id')->orWhereHas('location', fn ($q) => $q->where('is_active', true)->whereNotIn('type', ['receiving', 'damaged'])))->get();
229: 
230:         return $this->inventoryService->lockLevels($rows->map->getAttributes()->all());
231:     }
232: 
233:     /**
234:      * تغطية الفروع لأصناف الطلب باستعلام واحد مجمّع (M15):
235:      * ‏[branch_id][variant_id] => مجموع المتاح في المواقع النشطة.
236:      *
237:      * @return array<int, array<int, float>>
238:      */
239:     private function branchAvailabilityMap(Order $order): array
240:     {
241:         $variantIds = $order->items
242:             ->map(fn (OrderItem $item): int => (int) $item->product_variant_id)
243:             ->unique()->values()->all();
244: 
245:         $rows = StockLevel::query()
246:             ->whereIn('product_variant_id', $variantIds)
247:             ->whereHas('branch', fn (Builder $q): Builder => $q->where('is_active', true))
248:             ->where(fn (Builder $q): Builder => $q
249:                 ->whereNull('location_id')
250:                 ->orWhereHas('location', fn (Builder $l): Builder => $l->where('is_active', true)->whereNotIn('type', ['receiving', 'damaged'])))
251:             ->groupBy('branch_id', 'product_variant_id')
252:             ->selectRaw('branch_id, product_variant_id, SUM(available) as total_available')
253:             ->get();
254: 
255:         $map = [];
256:         foreach ($rows as $row) {
257:             $map[(int) $row->branch_id][(int) $row->product_variant_id] = (float) $row->total_available;
258:         }
259: 
260:         return $map;
261:     }
