263:     /** @param array<int, array<int, float>> $coverage */
264:     private function canBranchFulfillFullOrder(Order $order, int $branchId, array $coverage): bool
265:     {
266:         foreach ($order->items as $item) {
267:             if (($coverage[$branchId][(int) $item->product_variant_id] ?? 0) < (float) $item->qty) {
268:                 return false;
269:             }
270:         }
271: 
272:         return true;
273:     }
