275:     /** @param array<int, array<int, float>> $coverage */
276:     private function bestBranchForItem(OrderItem $item, array $coverage): ?int
277:     {
278:         $best = null;
279:         $bestAvailable = 0.0;
280:         foreach ($coverage as $branchId => $variants) {
281:             $available = $variants[(int) $item->product_variant_id] ?? 0;
282:             if ($available >= (float) $item->qty && $available > $bestAvailable) {
283:                 $best = $branchId;
284:                 $bestAvailable = $available;
285:             }
286:         }
287: 
288:         return $best;
289:     }
290: 
291:     private function reserveItemsFromBranch(Order $order, int $branchId, ?int $performedBy): void
292:     {
293:         $levels = $this->lockPlannedLevels($order->items->mapWithKeys(fn ($item) => [(int) $item->product_variant_id => $branchId])->all());
294:         foreach ($order->items as $item) {
295:             $this->reserveItemFromBranch($order, $item, $branchId, $performedBy, $levels);
296:             $item->update(['allocated_branch_id' => $branchId]);
297:         }
298:     }
299: 
300:     /**
301:      * حجز كمية الصنف من فرع واحد، موزعة على مواقعه الأعلى متاحًا عند الحاجة.
302:      */
303:     private function reserveItemFromBranch(Order $order, OrderItem $item, int $branchId, ?int $performedBy, Collection $levels): void
304:     {
305:         $remaining = (int) round((float) $item->qty * 10000);
306:         foreach ($levels->where('product_variant_id', $item->product_variant_id)->where('branch_id', $branchId)->sortByDesc('available') as $level) {
307:             $take = min((int) round($level->available * 10000), $remaining);
308:             if ($take <= 0) {
309:                 continue;
310:             }
311:             $this->inventoryService->recordMovement([
312:                 'product_variant_id' => (int) $item->product_variant_id, 'branch_id' => $branchId,
313:                 'location_id' => $level->location_id, 'type' => StockMovementType::Reserve,
314:                 'affected_bucket' => StockBucket::Reserved, 'quantity' => $take / 10000,
315:                 'reference_type' => Order::class, 'reference_id' => $order->id,
316:                 'created_by' => $performedBy, 'notes' => 'حجز للطلب '.$order->order_number,
317:             ], $level);
318:             $remaining -= $take;
319:             if ($remaining === 0) {
320:                 break;
321:             }
322:         }
323:         if ($remaining > 0) {
324:             throw new BusinessException('الرصيد المتاح تغير أثناء الحجز.', errorCode: 'insufficient_stock');
325:         }
326:     }
327: 
328:     /**
329:      * صفوف رصيد قابلة للاستخدام: رصيد الفرع/المتغير في مواقع نشطة
330:      * (أو بلا موقع) — الحجز لا يخرج من موقع معطّل.
331:      *
332:      * @return Builder<StockLevel>
333:      */
334:     private function usableLevels(int $variantId, ?int $branchId = null): Builder
335:     {
336:         return StockLevel::query()
337:             ->where('product_variant_id', $variantId)
338:             ->when($branchId !== null, fn (Builder $q): Builder => $q->where('branch_id', $branchId))
339:             ->where(fn (Builder $q): Builder => $q
340:                 ->whereNull('location_id')
341:                 ->orWhereHas('location', fn (Builder $l): Builder => $l->where('is_active', true)));
342:     }
