 23:   return <ProtectedRoute><AuthenticatedApp /></ProtectedRoute>;
 24: }
 25: 
 26: function AuthenticatedApp() {
 27:   const user = useAuthStore((state) => state.user);
 28:   const logoutRemote = useAuthStore((state) => state.logoutRemote);
 29:   const readRoute = () => window.location.hash.replace(/^#/, '')
 30:     || window.location.pathname + window.location.search;
 31:   const [routeWithQuery, setRouteWithQuery] = useState(readRoute);
 32:   const route = routeWithQuery.split('?')[0];
 33:   const can = useCallback((permission: string) =>
 34:     hasPermission(user?.permissions, permission), [user]);
 35:   const cashierOnly = (user?.roles ?? []).includes('cashier') && ![
 36:     'orders.view', 'treasuries.view', 'expenses.view', 'treasury_transfers.view', 'reports.view',
 37:     'products.view', 'inventory.view', 'users.view', 'customers.view', 'roles.view', 'settings.view',
 38:     'returns.view', 'shipping.view', 'price_lists.view', 'promotions.view', 'pos_shifts.view',
 39:     'quotations.view', 'payment_notices.view',
 40:   ].some(can);
 41: 
 42:   useEffect(() => {
 43:     // Stocktake navigation guards may synchronously restore the accepted hash.
 44:     const changed = () => queueMicrotask(() => setRouteWithQuery(readRoute()));
 45:     window.addEventListener('hashchange', changed);
 46:     window.addEventListener('popstate', changed);
 47:     return () => {
 48:       window.removeEventListener('hashchange', changed);
 49:       window.removeEventListener('popstate', changed);
 50:     };
 51:   }, []);
 52: 
 53:   const opMatch = route.match(/^\/(orders|returns|wholesale|shipping|pricing|promos|brands|suppliers|purchasing|finance|shifts|reports|notifications)(?:\/([^/?#]+))?$/);
 54:   const isOperation = Boolean(opMatch);
 55:   const operationsActive = opMatch ? opMatch[1] : null;
 56:   const operationsId = opMatch ? opMatch[2] : undefined;
 57:   const operationsSub = (() => {
 58:     const raw = routeWithQuery.split('?')[1] ?? '';
 59:     return new URLSearchParams(raw).get('sub') || undefined;
 60:   })();
 61: 
 62:   useEffect(() => {
 63:     const isStore = ['/store', '/banners', '/settings/store', '/settings/banners'].includes(route);
 64:     if (cashierOnly && !['/', '/dashboard', '/pos'].includes(route)) {
 65:       window.location.replace('/dashboard');
 66:     } else if (
 67:       !['/', '/dashboard', '/categories', '/dealers', '/production', '/pos', '/users', '/roles', '/settings'].includes(route) &&
 68:       !isStore &&
 69:       !isOperation &&
 70:       !/^\/products(?:\/(?:new|[0-9]+))?$/.test(route) &&
 71:       !/^\/inventory(?:\/[a-z-]+)?$/.test(route)
 72:     ) {
 73:       window.location.replace('/dashboard');
 74:     }
 75:   }, [cashierOnly, route, isOperation]);
 76: 
 77:   if (cashierOnly && !['/', '/dashboard', '/pos'].includes(route)) return null;
 78:   if (route === '/pos') return <PosPage />;
 79: 
 80:   const categoriesActive = route === '/categories';
 81:   const inventoryActive = route === '/inventory' || route.startsWith('/inventory/');
 82:   const isStoreRoute = route === '/store' || route === '/banners' || route === '/settings/store' || route === '/settings/banners';
 83:   const adminActive = route === '/users' ? 'users' : route === '/roles' ? 'roles' : (route === '/settings' || isStoreRoute) ? 'settings' : null;
 84:   const catalogActive = isOperation
 85:     ? operationsActive
 86:     : inventoryActive
 87:     ? 'inventory'
 88:     : route.startsWith('/products')
 89:     ? 'products'
 90:     : route === '/dealers'
 91:     ? 'dealers'
 92:     : route === '/production'
 93:     ? 'production'
 94:     : adminActive;
 95: 
 96:   return <FinancialDashboard
 97:     onLogout={logoutRemote}
 98:     catalogActive={catalogActive}
 99:     catalogPage={
100:       isOperation && operationsActive ? (
101:         !canViewOperation(operationsActive, can) ? (
102:           <div dir="rtl" className="p-6">ليس لديك صلاحية عرض هذه الصفحة.</div>
103:         ) : (
104:         <OperationsMockPage
105:           key={`${operationsActive}-${operationsId || ''}-${operationsSub || ''}`}
106:           page={operationsActive}
107:           id={operationsId}
108:           sub={operationsSub}
109:           can={can}
110:         />
111:         )
112:       ) : inventoryActive ? (
113:         can('inventory.view') ? (
114:           <Suspense fallback={<div dir="rtl" className="p-6">جارٍ تحميل المخزون…</div>}>
115:             <InventoryPage can={can}/>
116:           </Suspense>
117:         ) : (
118:           <div dir="rtl" className="p-6">ليس لديك صلاحية عرض المخزون.</div>
119:         )
120:       ) : adminActive ? (
121:         <AdminMockPage
122:           key={adminActive}
123:           page={adminActive}
124:           can={can}
125:           initialTab={isStoreRoute ? 'store' : undefined}
126:         />
127:       ) : (
128:         catalogActive && <CatalogMockPage key={catalogActive} can={can} page={catalogActive} />
129:       )
130:     }
131:     catalogNav={!cashierOnly ? [
132:       { id: 'orders', label: 'الطلبات', onOpen: () => { window.location.hash = '/orders'; } },
133:       ...(can('inventory.view') ? [{ id: 'inventory', label: 'المخزون', onOpen: () => { window.location.hash = '/inventory/stock'; } }] : []),
134:       ...(can('products.view') ? [{ id: 'products', label: 'المنتجات', onOpen: () => { window.location.hash = '/products'; } }] : []),
135:       ...(can('customers.view') ? [{ id: 'dealers', label: 'التجار والموزعون', onOpen: () => { window.location.hash = '/dealers'; } }] : []),
136:       ...(can('inventory.view') ? [{ id: 'production', label: 'استلام الإنتاج', onOpen: () => { window.location.hash = '/production'; } }] : []),
137:       ...(canViewOperation('finance', can) ? [{ id: 'finance', label: 'المالية', onOpen: () => { window.location.hash = '/finance'; } }] : []),
138:       ...(can('reports.view') ? [{ id: 'reports', label: 'التقارير', onOpen: () => { window.location.hash = '/reports'; } }] : []),
139:       ...((can('users.view') || can('users.manage')) ? [{ id: 'users', label: 'المستخدمون', onOpen: () => { window.location.hash = '/users'; } }] : []),
140:       ...((can('roles.view') || can('roles.manage')) ? [{ id: 'roles', label: 'الأدوار', onOpen: () => { window.location.hash = '/roles'; } }] : []),
141:       ...((can('settings.view') || can('settings.manage')) ? [{ id: 'settings', label: 'الإعدادات', onOpen: () => { window.location.hash = '/settings'; } }] : []),
142:     ] : []}
143:     onCloseCatalog={() => { window.location.hash = '/dashboard'; }}
144:     onOpenNotifications={() => { window.location.hash = '/notifications'; }}
145:     categoriesActive={categoriesActive}
146:     categoriesPage={<CategoriesMockPage can={can} embedded />}
147:     onOpenCategories={!cashierOnly && can('categories.view')
148:       ? () => { window.location.hash = '/categories'; }
149:       : undefined}
150:     onCloseCategories={() => { window.location.hash = '/dashboard'; }}
151:   />;
152: }
